INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(1328, 1, 1, 'koKR', '무엇을 찾으십니까, $g선생님:아가씨;'),
(3626, 1, 1, 'koKR', '무엇을 찾으십니까, $g선생님:아가씨;'),
(3976, 3, 0, 'koKR', '내 아버지의 검을 들고 있구나, $n. 내 병사들을 지휘할 권한을 주겠다, 나의 $g군주:여군주;. 데려가라... 이끌어라... 불순한 자들은 제거해야 한다. 그 오염을 깨끗이 씻어내야 한다.'),
(6244, 4, 0, 'koKR', '그리고 두 연인이 숨을 거둔 곳에 나무 한 그루가 자랐소. 엘프들은 그 나무를 사랑나무라고 부르지. 분명 그대의 목적에 도움이 될 것이오.'),
(10262, 0, 5, 'koKR', '키블러는 G.E.T.A.의 조사를 받고 있어요.'),
(14721, 0, 0, 'koKR', '얼라이언스 시민들이여, 검은바위의 군주가 쓰러졌다! 네파리안은 $N와 $G그의:그녀의; 동료들이 힘을 합쳐 굴복시켰다!'),
(14721, 1, 0, 'koKR', '기세를 올려라! 너희 용사를 중심으로 집결하고, $G그의:그녀의; 영광을 만끽하라! 용 사냥꾼의 함성을 함께 외쳐라!'),
(28576, 1, 0, 'koKR', '자비를 베풀어주십시오, $g선생님:부인;!'),
(28577, 1, 0, 'koKR', '자비를 베풀어주십시오, $g선생님:부인;!'),
(32906, 11, 0, 'koKR', '프레이야가 |cFF00FF00강화된 무쇠 뿌리|r를 시전합니다!');
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(733, 'koKR', '여기선 발밑 조심해, $G젊은이:아가씨;. 우리 패거리가 아니라고 봐주는 건 아니야. 선 넘으면 지팡이 맛 좀 보여줄 테니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7833, 'koKR', '장담하건대 곧 있을 안퀴라즈 전쟁에 필요한 물자를 만드는 데 갈래물풀만큼 유용한 것도 드물 겁니다! 뜨거운 실리더스의 태양이 내리쬐는 무더운 날에 아이스크림을 만들고, 일부 식물의 역겨운 냄새를 없애 주고, 물속에서 숨을 쉴 수 있게 해 주고, 피부를 단단하게 해 주고, 동작을 민첩하게 해 주고, 마력을 보충해 주는 등등... 용도가 하도 많아 일일이 기억하기도 힘들어요! 제가 아이스크림도 만들 수 있다고 말했나요?$B$B어쨌든 제가 모은 것은 대략 $2047w개인데, 총 $2048w개가 필요해요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(10315, 'koKR', '자네가 저주의 제단에서 무릎을 꿇고 기도하는 저주받은 자의 영혼들을 보고 있을 때 자네 눈에 보이지 않는 게 바로 나일세. 난 굴단의 옆에 서 있었지.$B$B<고개를 끄덕이는 오로노크>$B$B나는 여러 가지 일을 했었다고 말한 적이 있지 않았나? 그 \'일\' 중 하나가 굴단의 부관이었지.$B$B끔찍한 짓을 수없이 저질렀어. 남자, 여자, 심지어 아이들까지 가리지 않고 무참히 학살했지. 무고한 드레나이들의 피를 늘 손에 묻히고 살았지... 하지만...$B$B<오로노크가 말을 잇지 못합니다.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(12052, 'koKR', NULL, '자신이 좀 멋지다고 생각하죠. 안 그래요, 풋내기씨? 투기장에서 실력을 발휘했다면 제가 드릴 게 좀 있죠. 좋은 물건이고 말고요, 크릭셀씨 물건하고는 차원이 다르단 말이에요. 크릭셀씨 물건은 한물갔다는 거, 알고 있죠?$B$B아, 어쨌든 좋은 하루 보내시라는 말이에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13005, 'koKR', '제가 도와드릴까요? $g선생님:부인;?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13092, 'koKR', '뭘 내려다보는 거죠?$B$B우리 페스텔포트 가문으로 말할 것 같으면, 갈고 빻기로 오랜 세월 이름을 떨친 뼈대 있는 집안이란 말입니다.$B$B그래요, 세계 제일이라 이 말이죠!$B$B그 방면에서는 아제로스, 아니 세상 어디를 뒤져도 우리 식구들보다 훌륭한 연금술사는 못 찾을 겁니다. 장담하지요!$B$B내 비록 지금 수습생 딱지를 달고 있기는 하지만, 기술만큼은 누구에게도 뒤지지 않아요! 인생에서 성공하려면 이러한 굴욕은 누구나 겪게 되는 법이에요.$B$B그건 그렇고, 혹시 절 도와주러 오신 건가요?$B$B<작은 노움이 오만하게 히죽 웃는다.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES
(15, 'koKR', '잘 지내십니까, 모건 형님.\r\n\r\n이곳 골드샤이어에서는 사업이 아주 번창하고 있습니다. 너무 사업이 잘 되다 보니 형님께 짐을 보낼 시간조차 없었네요.\r\n\r\n사람을 시켜 이 쪽지와 함께 대형 밀랍 양초 한 짐을 보냅니다. 코볼트들이 모자에 달고 다니는 바로 그 양초지요.\r\n\r\n짐을 가져가는 이에게 감사 인사와 함께 적당히 사례해 주셨으면 합니다.'),
(16, 'koKR', '존경하는 크릴리안 교장님께,\r\n\r\n최근 이 제자가 어떤 일을 하고 있는지 궁금하실 것 같아 편지를 드립니다. 스승님의 조언대로 저는 정든 스톰윈드를 떠나 여행하면서 지식과 지혜를 쌓기 위해 노력하고 있습니다. 많은 곳을 여행한 끝에 결국 이곳 아름다운 문브룩 마을에 정착하기로 결심했습니다. 서부 몰락지대 주변의 들녘은 추수기가 다가오면서 정말 아름다운 자태를 드러내고 있습니다.'),
(17, 'koKR', '이곳에 온 지 며칠 안 돼 저는 근처 농장의 아이들을 가르치기 시작했습니다. 수업이 잘 진행되자 마을의 시장님께서는 제게 학교 운영을 맡기셨고 새로운 학교를 건설하기 시작했습니다! 은빛소나무 숲에서 스톰윈드, 그리고 이제 문브룩에 이르기까지, 제가 이렇게 아제로스 곳곳을 여행하게 될 줄 누가 알았겠습니까!\r\n\r\n부디 건강히 지내십시오.\r\n\r\n스탈반 미스트맨틀 올림'),
(18, 'koKR', '친애하는 귀족 나리께,\r\n\r\n귀하의 자녀를 가르칠 가정 교사를 구하신다는 소식이 이곳 골드샤이어에 있는 저에게까지 전해졌습니다. 저는 이곳의 사자무리 여관에 임시로 묵고 있습니다. 이 지역에 닥친 불행한 사태로 인해 저는 문브룩 학교의 교장 직책을 버릴 수밖에 없었습니다. 부디 귀댁 자제의 가정 교사로 채용해 주시기 바랍니다. 필요하다면 크릴리안 교장님께서 제 능력에 대해 보증해 주실 것입니다.'),
(19, 'koKR', '겨울비가 그치고 다시 도로 상황이 좋아지면 제가 직접 찾아 뵙도록 하겠습니다.\r\n\r\n그때까지 안녕히 계십시오.\r\n\r\n은빛소나무의 스탈반 미스트맨틀 올림.'),
(22, 'koKR', '. . .이제 그녀도 나와 같은 마음이라는 걸 확신한다. 오늘 아침에는 내 손 위에 자기 손을 얹기까지 했다. 그녀가 미소 지으면 눈이 반짝이는 다이아몬드처럼 빛난다. 우리 사이에는 말없는 말이 오간다. 두근거리는 가슴과 뜨겁게 달아오른 혈관 속에서 그녀가 느껴진다.'),
(25, 'koKR', '사랑하는 토미 조,\r\n매 순간 당신이 곁에 없다는 사실로 내 심장은 시들어 가고 있답니다. 아, 당신 가족과 우리 가족이 서로에게 했던 어리석은 죄를 넘어설 수 있다면... 진정한 죄악이 바로 증오라는 것을 깨닫게 된다면 더 바랄 것이 없겠어요. 이런 암울한 시기에 당신과 나의 가족들뿐만 아니라 더 많은 이들이 증오에 사로잡히게 될까봐 두려워요. 그들 모두 이런 사실을 깨닫게 된다면, 마침내 우리도 함께할 수 있게 될 텐데... 저는 그날을 꿈꾸며, 그날을 위해 살겠어요.\r\n당신의 사랑, 메이벨'),
(26, 'koKR', '잘 지내시는가, 윌리엄.\r\n\r\n우리가 얼굴을 맞대고 얘기해 본 지도 벌써 여러 해가 됐지만, 자네 형제가 잘 지내고 있을 뿐만 아니라 하고 있는 연금술 사업이 날로 번창하고 있으리라 믿고 있네.\r\n\r\n윌리엄, 자네에게 부탁이 한 가지 있다네. 간단히 말해서, 내 손자 토미 조가 아름다운 메이벨 맥클루어에게 마음을 뺏기고 말았네. 하지만 아무리 서로 사랑한다 하더라도 우리 양가는 수년 동안 서로 앙숙으로 지내 오고 있으니...'),
(27, 'koKR', '잘 지내시는가, 윌리엄.\r\n\r\n우리가 얼굴을 맞대고 얘기해 본 지도 벌써 여러 해가 됐지만, 자네 형제가 잘 지내고 있을 뿐만 아니라 하고 있는 연금술 사업이 날로 번창하고 있으리라 믿고 있네.\r\n\r\n윌리엄, 자네에게 부탁이 한 가지 있다네. 간단히 말해서, 내 손자 토미 조가 아름다운 메이벨 맥클루어에게 마음을 뺏기고 말았네. 하지만 아무리 서로 사랑한다 하더라도 우리 양가는 수년 동안 서로 앙숙으로 지내 오고 있으니...'),
(28, 'koKR', '아거스,\r\n\r\n자네도 알다시피 나는 군대의 수리 요청으로 눈코 뜰 새 없다네. 일이 많다고 불평할 순 없는 거지만 이제는 철마저 거의 바닥나서 말 편자에 사용할 철이 부족하네.\r\n\r\n자네는 항상 많은 철을 확보하고 있다고 알고 있네. 그러니 내가 다음번 철괴 상자를 받게 될 때까지 편자 50개를 빌려 준다면 정말 고맙겠네.\r\n\r\n- 베르너'),
(29, 'koKR', '상자에 다음과 같은 내용의 쪽지가 붙어 있습니다.\r\n\r\n\"베르너 - 붉은마루 산맥에서 그런 문제가 발생했다니 정말 유감일세. 자네가 부탁한 편자를 보내네. 곧 자네 사정이 허락하는 대로 1골드 지급해 주기 바라네.\"\r\n\r\n\"원한다면 얇은 새끼용 비늘로 지급해줘도 상관없네. 붉은마루 산맥에는 새끼용이 흔하다고 들었네. 우린 친구 사이이니 특별히 비늘 6개만 받겠네. 그럼 이만.\r\n-- 아거스\"'),
(30, 'koKR', '장군,\r\n\r\n전쟁이 일어났습니다. 우리의 멸망이 눈앞에 다가온 것입니다.\r\n\r\n국왕 폐하의 최동부 영토에서 진행되고 있는 최근 군사 활동을 보고하는 것이 레이크샤이어의 집정관으로서의 제 임무입니다. 이 보고서에는 붉은마루 산맥에 자리 잡은 레이크샤이어의 현재 상황에 대한 설명이 포함되어 있습니다.'),
(35, 'koKR', '이미 악의 온상이 되어 버린 북부 지역에서 더 크고 심각한 악의 세력이 자라나고 있을까 우려됩니다. 우리 모두가 희생되거나 적의 노예가 되지 않으려면 반드시 우리 스톰윈드 왕국이 행동을 취해야 합니다.\r\n\r\n서명\r\n스톰윈드 왕국\r\n레이크샤이어 마을\r\n집정관 솔로몬'),
(36, 'koKR', '집정관 솔로몬 귀하.\r\n\r\n죽은 이들에 대해 심심한 조의를 표하는 바이네. 국왕 폐하께서 이러한 상황을 파악하고 계신지 직접 알아보도록 하겠네. 그리고 레이크샤이어에 증원군을 보낼 수 있게 되기를 진심으로 바라고 있네. 귀하를 믿고 하는 이야기지만, 폐하는 요즘 뵙기 어려울 뿐 아니라 좀 이상한 행동을 보이고 계시네.\r\n\r\n다시 소식 전할 때까지 부디 안녕히.\r\n\r\n스톰윈드 왕국 장군\r\n마커스 조나단'),
(37, 'koKR', '집정관 솔로몬 귀하.\r\n\r\n죽은 이들에 대해 심심한 조의를 표하는 바이네. 국왕 폐하께서 이러한 상황을 파악하고 계신지 직접 알아보도록 하겠네. 그리고 레이크샤이어에 증원군을 보낼 수 있게 되기를 진심으로 바라고 있네. 귀하를 믿고 하는 이야기지만, 폐하는 요즘 뵙기 어려울 뿐 아니라 좀 이상한 행동을 보이고 계시네.\r\n\r\n다시 소식 전할 때까지 부디 안녕히.\r\n\r\n스톰윈드 왕국 장군\r\n마커스 조나단'),
(38, 'koKR', '스타우트맨틀 경 -\r\n데피아즈단 문제를 논의하는데 어떻게 생판 모르는 자를 보낼 수 있습니까? 경은 이전에 제 생명을 구해 놓고는 이제 와서 큰 위험에 빠뜨리는군요. 어쨌든 당신에게 빚이 있으니 도와드리도록 하겠습니다. 데피아즈단은 생각보다 훨씬 거대한 조직입니다. 서부 몰락지대에서 엘윈 숲에 이르는 모든 광산이 놈들의 수중에 들어갔습니다. 게다가 코볼트와 놀들이 놈들의 더러운 일에 동참하고 있습니다. 또한 지역 주민들의 미신을 없애기 위해 고블린을 시켜서 금속 괴물을 만들어 서부 몰락지대 들판에 갖다 놓도록 하고 있습니다.'),
(39, 'koKR', '놈들은 경이 알고 있는 것보다 훨씬 큰 규모의 거대 지하 망을 구축했습니다. 이 지하 망은 무법항에서 곧장 스톰윈드 왕궁까지 연결됩니다. 경이 놈들을 지하에 몰아넣으면 그만이라고 생각한다면 용감한 성기사에서 둘도 없는 바보가 될 겁니다. 또한 놈들은 대량 살상 무기까지 만들고 있습니다. 아무튼 석공들이 아는 거라곤 뭐든 크게 만드는 것뿐이니까... 설마 이제 이걸 호박 농장이나 포도밭에서 생기는 하찮은 문제라 생각하지는 않겠지요? 경에게 진 빚은 갚았으니, 이제 그만 날 내버려 둬 주세요!\r\n- 와일리'),
(40, 'koKR', '놈들은 경이 알고 있는 것보다 훨씬 큰 규모의 거대 지하 망을 구축했습니다. 이 지하 망은 무법항에서 곧장 스톰윈드 왕궁까지 연결됩니다. 경이 놈들을 지하에 몰아넣으면 그만이라고 생각한다면 용감한 성기사에서 둘도 없는 바보가 될 겁니다. 또한 놈들은 대량 살상 무기까지 만들고 있습니다. 아무튼 석공들이 아는 거라곤 뭐든 크게 만드는 것뿐이니까... 설마 이제 이걸 호박 농장이나 포도밭에서 생기는 하찮은 문제라 생각하지는 않겠지요? 경에게 진 빚은 갚았으니, 이제 그만 날 내버려 둬 주세요!\r\n- 와일리'),
(41, 'koKR', '스타우트맨틀 경 -\r\n\r\n에드윈 밴클리프가 이끄는 석공 길드는 인간 최고의 건축가들로 구성되어 있었습니다. 이 석공들은 첫 번째 전쟁 동안 오크들에 의해 파괴된 스톰윈드의 도시 재건을 도왔습니다. 밴클리프와 그의 숙련공들은 비길 데 없는 건축가들이며 그들의 기술과 예술성은 빛의 대성당과 스톰윈드 왕국 건축물만 봐도 여실히 확인할 수 있습니다.'),
(43, 'koKR', '평생 동안 에드윈 밴클리프와 개인적인 친분이 있는 사람으로서, 감히 말씀드리건대 그를 적으로 돌리는 것은 위험천만한 일입니다. 아시다시피, 그는 제 죽마고우로 언젠가 저와 함께 일하게 될 것이라 생각해서 제가 직접 남모르게 그를 훈련시켰습니다. 밴클리프가 데피아즈단을 이끌게 된다면 신께서 우리에게 자비를 베푸시기를 바랄 수밖에 없습니다.\r\n\r\n스톰윈드 암살단 길드\r\n단장 마티아스 쇼'),
(44, 'koKR', '평생 동안 에드윈 밴클리프와 개인적인 친분이 있는 사람으로서, 감히 말씀드리건대 그를 적으로 돌리는 것은 위험천만한 일입니다. 아시다시피, 그는 제 죽마고우로 언젠가 저와 함께 일하게 될 것이라 생각해서 제가 직접 남모르게 그를 훈련시켰습니다. 밴클리프가 데피아즈단을 이끌게 된다면 신께서 우리에게 자비를 베푸시기를 바랄 수밖에 없습니다.\r\n\r\n스톰윈드 암살단 길드\r\n단장 마티아스 쇼'),
(45, 'koKR', '제법이군 그래, 친구! 이제 정동 쪽을 향해 갈 차례요. 동쪽 절벽 위의 길을 따라 동쪽으로 가시오. 길가에서 낡은 굴뚝의 잔해를 발견하게 되면 다음 단서가 들어 있는 낡은 통을 발견하게 될 것이오.'),
(48, 'koKR', '검은발톱에게\r\n\r\n바다가 우리를 기다리고 있다. 우리는 북쪽에서 보내 오는 그대들의 보급품이 필요하다. 모든 철로와 물통 등 모든 걸 약탈하도록 하라. 우리는 금속이 필요하다. 무법항에서 물자가 오기로 했으나 이미 오랫동안 지체되고 있다. 검은발톱이여, 나를 위해 힘을 내라. 이번에는 보급품을 창고로 직접 보내도록 하라. 지체할 시간이 없다.\r\n\r\n- 밴클리프'),
(49, 'koKR', '스타우트맨틀 경 귀하\r\n\r\n레이크샤이어는 정중히 귀하의 민병대에 지원을 요청하는 바입니다. 이 글을 쓰고 있는 지금 우리는 검은바위부족 오크와 모건스의 잿빛가죽놀에게 포위되어 있습니다. 이 정도로 상황이 심각하지 않았다면 이런 청을 드리지 않았을 것입니다. 현재 스톰윈드로부터의 증원군을 기다리고 있기는 하지만 증원군이 도착할 때까지 힘을 빌려 주시기 바랍니다. 왕국이 침략당한다면 모든 인간들이 위험에 빠지게 됩니다.\r\n\r\n집정관 솔로몬\r\n'),
(52, 'koKR', '존경하는 집정관 귀하\r\n\r\n현재 어둠의 순찰대는 다크샤이어의 위수 지역을 이탈할 수 없음을 전해 드리게 되어 유감입니다. 스톰윈드가 더 이상 이 지역에 군사 지원을 하지 않는다는 사실을 모르고 계신 것 같습니다. 어둠의 순찰대는 스톰윈드가 철수한 다크샤이어를 방어하기 위해 순수하게 그늘숲 주민들로 조직되고 훈련된 부대입니다. 어둠의 순찰대가 자리를 비우게 되면 마을은 파괴될 것입니다. 귀하가 계신 곳의 상황이 좋아지기를 바랍니다.\r\n\r\n- 엘로 이본로크 경'),
(53, 'koKR', '이 쪽지의 글자들이 표면 위에서 깜박이며 춤추는 것처럼 보입니다. 글자에서 뜻을 읽어내는 것은 불가능합니다...'),
(55, 'koKR', '이것은 서부 몰락지대 내의 토지에 대한 등기 권리증입니다. 이 증서는 아래에 명시된 이들에게 지정된 지역과 지역 경계 내에서 생산되는 모든 재화와 건축된 모든 구조물에 대한 소유권을 부여합니다.\r\n\r\n서명인: 시어도어 펄브로우, 베르나 펄브로우'),
(56, 'koKR', '[증서의 뒷면에 아래 내용이 급히 휘갈겨 쓰여 있습니다.]\r\n\r\n우리는 펄브로우를 위협해 놈에게서 땅문서를 받아 냈다. 이곳 땅 중 일부를 손에 넣으려면 이 방법이 가장 편리할 거라 생각됐다. 펄브로우 가족은 더 이상 우리에게 문제를 일으키지 않을 것이다. 마지막으로 그들을 본 게 서부 몰락지대를 떠나는 길에 마차가 고장 나 꼼짝 못하고 있는 모습이었다.'),
(58, 'koKR', '골짜기의 달은 밝게 빛나리\r\n조국과 신성한 영토를 수호하라는 부름에\r\n귀 기울이는 자랑스러운 전사들이 있는\r\n정글 위를 밝게 비추고 있나니\r\n골짜기의 달은 밝게 빛나리\r\n저 높은 곳에서\r\n적과 아군이 함께 피 흘리는\r\n전투의 울음소리를 비추고 있나니'),
(59, 'koKR', '그리고 우리 형제들이\r\n미지의 땅을 지날 때\r\n골짜기 아래 깊은 곳에서\r\n그들의 영혼이 강건해지리\r\n\r\n그리고 우리 형제들이\r\n산맥의 신전을 지날 때\r\n우리는 신성한 파란 수정 속에 깃든\r\n그들의 영원한 영혼을 지켜야 하리\r\n\r\n그리고 우리 형제들이 지날 때\r\n골짜기의 달은 밝게 빛나리'),
(61, 'koKR', '그리고 우리 형제들이\r\n미지의 땅을 지날 때\r\n골짜기 아래 깊은 곳에서\r\n그들의 영혼이 강건해지리\r\n\r\n그리고 우리 형제들이\r\n산맥의 신전을 지날 때\r\n우리는 신성한 파란 수정 속에 깃든\r\n그들의 영원한 영혼을 지켜야 하리\r\n\r\n그리고 우리 형제들이 지날 때\r\n골짜기의 달은 밝게 빛나리'),
(62, 'koKR', '달과 불로,\r\n살과 뼈로,\r\n피로 쓰고,\r\n돌에 새길지니.\r\n이 땅을 떠나거나\r\n너의 운명을 맞으라\r\n너의 죽음으로\r\n제왕의 무덤을 지키리라.'),
(64, 'koKR', '모건 래디모어는 선량한 사람들과 가난한 자들, 그리고 고통 받는 이들을 보호하기 위해 싸웠던 위대하고 고귀한 기사였다. 여러 해 동안 그는 아제로스 외곽 지역에서 열심히 싸우며 고통받는 자들의 짐을 덜어 주고 악한 자들에게는 신속히 정의의 심판을 내렸다.\r\n\r\n그는 18세 되던 해 여름, 리스라는 어린 소녀와 결혼했다. 그들은 서로 깊이 사랑했으며 아들 하나와 딸 둘, 모두 세 아이를 낳았다.'),
(65, 'koKR', '로데론에서 전쟁이 발발하던 당시 모건은 32세였다. 모건은 전설적인 성기사인 빛의 수호자 우서 경의 부름을 받아 그와 함께 오크와 언데드에 맞서 싸웠다. 아내와 아이들을 안전한 집에 남겨두고 모건은 전쟁터로 향했다.\r\n\r\n전쟁은 몇 해가 흐르도록 계속되었고, 모건은 은빛 성기사단의 해체, 우서의 죽음, 역병의 확산과 같은 많은 끔찍한 일들을 겪었다. 그가 온전한 정신을 유지할 수 있었던 것은 오직 언젠가 아내와 아이들을 다시 만나게 되리라는 희망 때문이었다.'),
(66, 'koKR', '마침내 모건은 고향으로 돌아왔지만 그가 기억하는 고향과는 전혀 다른 모습뿐이었다. 울창했던 숲은 오염되어 언데드와 다른 악의 세력이 창궐해 있었다. 어딜 가나 파괴된 집과 농장이 즐비했고, 까마귀 언덕 근처의 공동 묘지가 이제 지역의 대부분을 차지하고 있었다. 놀라고 당황한 모건은 집으로 향했으나 그곳엔 폐허만이 있을 뿐이었다.'),
(69, 'koKR', '모건은 그 중 가장 큰 묘비의 먼지를 쓸어내고 묘비에 쓰인 이름을 확인했다. 무덤 위에 단출하게 새겨져 있는 다음과 같은 글자는 그의 끔찍한 공포를 현실로 확인시켜 주었다.\r\n리스 래디모어\r\n한 남자의 사랑스런 아내이자 아이들의 어머니, 여기 잠들다\r\n모건의 불안은 경악으로 바뀌었고, 그리고 다시 그것은 깊은 슬픔이 되었다. 그는 무릎을 꿇고 앉아 눈물을 흘리기 시작했다. 여러 시간 동안 그 무덤을 바라보며 차가운 묘비에 흐느껴 울며 용서를 빌었다.'),
(74, 'koKR', '첫째 날\r\n수습생과 나는 오늘 눈마루 골짜기에 도착했다. 동굴을 통해 여행하는 동안에는 거의 아무 일도 없었다. 트롤이 모여 있다는 동굴에서 적당히 떨어진 곳에 야영지를 설치했다.\r\n둘째 날\r\n그 괴로운 늑대 울음소리 때문에 거의 한숨도 자지 못했다. 며칠 내에 새로운 늑대 가죽 옷을 얻게 될 것이다. 오늘 수습생이 트로그와 맞붙어 용감히 싸웠다.'),
(77, 'koKR', '첫째 날\r\n수습생과 나는 오늘 눈마루 골짜기에 도착했다. 동굴을 통해 여행하는 동안에는 거의 아무 일도 없었다. 트롤이 모여 있다는 동굴에서 적당히 떨어진 곳에 야영지를 설치했다.\r\n둘째 날\r\n그 괴로운 늑대 울음소리 때문에 거의 한숨도 자지 못했다. 며칠 내에 새로운 늑대 가죽 옷을 얻게 될 것이다. 오늘 수습생이 트로그와 맞붙어 용감히 싸웠다.'),
(79, 'koKR', '아래 내용은 엘윈의 광산들에서 서부 몰락지대의 우리 본부까지 데피아즈단이 황금을 징수하는 과정과 일정이다.\r\n \r\n징수 일정:\r\n\r\n일요일 오후 12시 30분\r\n\r\n수요일 오후 12시 30분\r\n\r\n각 지정일까지 엘윈의 광산에서 채굴된 황금을 브랙웰 호박밭으로 수거한다. 수거 담당자인 `징세관`은 문자가 새겨진 반지로 확인할 수 있다. 그 반지는 내가 그에게 준 것이다.'),
(80, 'koKR', '그렐린,\r\n\r\n난 앞으로 살아갈 날이 얼마 남지 않았고 많은 골칫거리들이 내 수명을 재촉하고 있군그래. 부디 트롤에 대한 자네의 조사만은 순조롭게 진행되길 바라네. 트롤을 상대하는 데 필요하다면 언제든지 내 권위를 사용할 수 있도록 허락하지. 그렇게 해서 적절한 해결책을 찾을 수 있다면 말일세.\r\n\r\n마그니 브론즈비어드'),
(81, 'koKR', '간신히 그 추한 짐승들을 물리쳤지만 팔에 심한 상처를 입고 지금 치료 중이다. 한동안은 자잘한 일들을 내가 직접 해야 할 것 같다.\r\n셋째 날\r\n춥다. 정오 무렵에 눈이 조금 내렸다.\r\n넷째 날\r\n오늘 수습생이 다시 원기를 회복했고, 우리는 처음으로 트롤들을 살펴보았다. 몸에 있는 반점과 몸에 걸친 여러 가지 장신구들 때문에 나는 그들을 서리갈기트롤이라 부르기로 했다.'),
(82, 'koKR', '다섯째 날\r\n수습생에게 야영지를 지키도록 하고 나는 몰래 동굴로 숨어 들어가 주변을 살펴보았다. 트롤의 수는 다소 우려될 정도였다. 동굴을 점령하고 있는 트롤을 모두 몰아내려면 산악경비대를 대거 소집해야 할 것 같다.\r\n한동안 트로그에 대해서는 언급하지 않은 것 같다. 이 지역에 출몰하는 트로그의 수는 트롤보다 많지만 너무 미개하여 그다지 큰 위협이 되지는 않는다. 내 판단이 옳은지는 좀 더 두고봐야 할 것이다.'),
(83, 'koKR', '그리고 거의 일주일 동안 에일 맥주는 한 방울도 입에 대지 못했다.\r\n여섯째 날\r\n오늘도 춥고 눈이 내린다. 트롤을 봤고 에일 맥주는 마시지 못했다.\r\n일곱째 날\r\n눈이 새하얗게 쌓였다. 하늘이 정말 파랗다. 밤에는 늑대가 또 울부짖을 것이다. 그리고 여전히 맥주는 입에 대지도 못했다.'),
(84, 'koKR', '여덟째 날\r\n우리가 처음에 생각했던 것처럼 트롤들이 큰 문제가 되지 않을지도 모르겠다. 그 수는 상당하지만 무기가 형편 없고 조직적이지도 못하다. 적은 수의 병력으로도 충분히 놈들을 상대할 수 있을 것이다.'),
(85, 'koKR', '내 일지\r\n\r\n지난 몇 주 동안의 공포는 참기 힘든 것이었다. 이렇게 일지를 기록하면서 미치지 않고 버틸 수 있게 되는 이유는 무엇일까? 마치 아무 말도 하지 않는 동료에게 죄를 고백하는 것이 마음 속의 괴로운 생각들을 종이 위에 풀어놓고 덮어두는 것과 마찬가지이기 때문일지도 모르겠다. 전에도 일지를 썼었지만 그 일지는 내가 돌아갈 수 없는 곳에 남겨져 있다. 그래서 새로 일지를 작성하는 것이다. 하지만 이번에는 진정 처음부터 시작하리라.'),
(86, 'koKR', '눈마루 골짜기 전역의 서리갈기트롤에 대한 보고서\r\n\r\n작성: 그렐린 화이트비어드, 원로원 특사\r\n\r\n그 동안 눈마루 골짜기 지역에서 서리갈기트롤들의 동태를 조사한 결과, 이들이 해당 지역에 거주하는 드워프의 안전에 큰 위협은 되지 않는다는 결론에 이르렀습니다. 또한 이들은 소수의 군병력만 추가로 지원된다면 제거할 수 있을 정도로 그리 위협적이지는 않습니다.'),
(87, 'koKR', '이미 눈마루 골짜기에 배치된 산악경비대와 용병들의 지원으로 문제가 신속히 해결될 것이라 믿고 있습니다. 이들은 제가 파견하기 전 원로원에서 배정한 예산으로 고용되었습니다.\r\n\r\n이 조치는 브론즈비어드 폐하께서 제게 부여하신 권한에 의거해 실행되었습니다.'),
(88, 'koKR', '던 모로 전역의 서리갈기트롤에 대한 보고서\r\n\r\n던 모로의 트롤들은 서쪽 변방의 산속 동굴인 서리갈기 소굴에 대거 집결해 있습니다. 그들의 수는 우려가 될 만큼 많지만 동굴에서 나올 생각은 없는 듯합니다. 또 다시 드워프의 분노를 자극해 몰살당하는 일이 없도록 하려는 것임이 분명합니다. 그들의 활동은 대체로 지역적으로 제한돼 있다고 볼 수 있으며'),
(89, 'koKR', '우리가 그들의 영역을 침범하지 않는 한 우리에게 큰 위협이 되지는 않을 것이라 판단됩니다. 이것이 드워프 주민들에게는 별 상관없는 상황이겠지만, 병력이 분산되어 있다는 점을 감안할 때 트롤을 전멸시키는 문제의 중요성은 조금 낮추고 트로그와 검은무쇠 드워프의 위협에 계속 초점을 맞추는 것이 현명할 것입니다.\r\n제 동생인 그렐린이 앤빌마에 대해 쓴 보고서 한 부를 동봉합니다.\r\n\r\n서명: 세니르 화이트비어드'),
(90, 'koKR', '눈마루 골짜기 전역의 서리갈기트롤에 대한 보고서\r\n\r\n작성: 그렐린 화이트비어드, 원로원 특사\r\n\r\n그 동안 눈마루 골짜기 지역에서 서리갈기트롤들의 동태를 조사한 결과, 이들이 해당 지역에 거주하는 드워프의 안전에 큰 위협은 되지 않는다는 결론에 이르렀습니다. 또한 이들은 소수의 군병력만 추가로 지원된다면 제거할 수 있을 정도의 위협입니다. 이미 눈마루 골짜기에 배치된 산악경비대와'),
(91, 'koKR', '용병들의 지원으로 문제가 신속히 해결될 것이라 믿고 있습니다. 이들은 제가 파견되기 전에 원로원에서 배정한 예산으로 고용되었습니다.\r\n\r\n이 조치는 브론즈비어드 폐하께서 제게 부여하신 권한에 의해 실행되었습니다.'),
(92, 'koKR', '사랑하는 타렐에게\r\n서둘러 답장을 써서 미안해요. 하지만 지금 이곳에서는 시간이 넉넉지 않답니다.\r\n\r\n발굴단은 상당한 진척을 이루어 중요한 티탄 유물들을 발굴해 냈어요. 그런데 추가로 커다란 뼈와 같은 다른 고대 유물들도 발견되기 시작했어요.'),
(94, 'koKR', '지금은 안전한 동굴에 피신해 있어요. 별다른 위험은 없을 것 같아 보이지만 랩터를 처리할 병력이 투입될 때까지 우린 꼼짝없이 갇히게 됐어요. 웰가르님은 작업을 계속하려고 하시지만 아직도 많이 겁을 먹고 계신 것 같아 보여요. 지금 우리는 이런 상황이에요, 타렐. 즉시 구조 병력을 보내도록 롱브레이드님을 설득해 주세요.\r\n\r\n이런 절박한 상황에서도 당신을 향한 제 사랑은 너무나 강하답니다.\r\n\r\n- 당신의 아내 메린'),
(102, 'koKR', '바닐이 한 발짝 발을 헛디디자 얼가딘 경은 그 큰 손으로 바닐의 어깨를 잡았다. 아제크와 나는 그가 다만 부주의한 바닐에게 꼭 필요한 따끔한 질책을 하는 거라고 생각하며 별생각 없이 쳐다보았다. 하지만 얼가딘 경은 머리로 천천히 근처에 쓰러져 있는 나무를 가리켰다. 거기엔 면도날 같이 날카로운 송곳니 바로 위로 두 개의 검은 눈이 뚫어질 듯 무섭게 우릴 쏘아보고 있었다.\r\n'),
(108, 'koKR', '오늘은 새로운 퓨마 흔적을 쫓아 남쪽으로 사냥을 나갔다. 출발한 지 얼마되지 않아 우리는 밧줄로 만들어진 멋진 다리가 놓인 계곡에 이르렀다. 기술이 낳은 이 경이로운 다리를 보는 순간 나는 이 지역을 묘사한 브란의 글을 떠올리지 않을 수 없었다. 종종 트롤 원주민은 원시적이고 교육 받지 못한 종족이라 생각했지만, 뛰어난 기술로 만들어진 다리를 올려다 보면서 나는 이 불가능해 보이는 일을 이뤄낸 트롤 건축가들의 솜씨를 인정하게 되었다.'),
(114, 'koKR', '우리는 해가 뜨자마자 트카시 폐허를 지나 남쪽을 향해 출발했다. 바닐은 붉은머리부족과 마주치게 되지 않을까 걱정했다. 나는 바닐에게 붉은머리부족은 그들 일족의 숙적인 백골가루부족을 처치하는 데 여념이 없을 거라고 상기시켜 주었다. 물론 바닐은 전혀 안심하지 않았지만, 나는 장전된 총, 화약을 가득 담은 가방, 그리고 세 명의 뛰어난 사냥꾼이 있어 어떤 적이 습격해 온다 해도 걱정이 없었다.'),
(119, 'koKR', '나는 해안가에 랩터로부터 숨을 곳이 있기를 바라면서 동료들을 바다 쪽으로 안내했다. 그런데 서둘러 도망쳐 오는 바람에 북쪽으로 너무 멀리 도망쳐 와 위태로운 고지까지 오고 말았다. 이미 실수는 저질러졌고 그건 모두 내 잘못이었다. 우리는 깎아지른 절벽 끝에 멈춰 섰고, 랩터들은 겨우 몇 발자국 뒤에 있었다.'),
(125, 'koKR', '첫째 날은 보통 그렇듯이 순조롭게 지나갔다. 우리는 기지 구축을 위해 필요한 준비를 하는 데 대부분의 시간을 보냈다. 나는 담수가 흘러드는 강어귀 가에서 이상적인 장소를 찾아 냈다. 근처에 낡고 버려진 부두가 있는걸로 보아 이곳은 예전에 어떤 종족이 거주하던 곳인 것 같다. 그러나 원래 누가 살던 땅이었는지는 시간이 흘러야만 알 수 있을 것이다.'),
(127, 'koKR', 'S. J. 얼가딘 경은 인간 귀족 출신입니다. 그의 아버지인 얼가딘 백작은 관대함으로 유명했습니다. 제2차 대전쟁 후 스톰윈드 복구 과정에서 석공 조합의 근무 환경 개선을 위해 적극적으로 노력한 사람이 바로 얼가딘 백작이었습니다.'),
(134, 'koKR', '놈의 죽음으로 원정대는 축제 분위기에 휩싸였다. 바닐은 모두가 즐길 수 있도록 벌꿀술을 따라 주었으나 축제는 오래가지 못했다. 시체를 다시 기지로 보내기 위해 준비하느라 모두 방심하고 있던 중에 끔찍한 으르렁거리는 소리가 들려 온 것이었다. 내 생애에서 피가 얼어 붙는 것처럼 그렇게 섬뜩한 소리는 다시 들어 보지 못했다.'),
(136, 'koKR', '나는 대원들에게 다음 날은 아제로스 전역에서 모피 수요가 대단히 높은 표범을 사냥할 것이라 약속했다. 얼라이언스를 위해 용감하게 자신의 삶을 희생하고 있는 모든 전문 사냥꾼, 덫사냥꾼, 가죽 상인들을 생각한다면 이런 수요는 당연한 보상이라 할 수 있다.'),
(153, 'koKR', '첫째 날은 보통 그렇듯이 순조롭게 지나갔다. 우리는 기지 구축을 위해 필요한 준비를 하는 데 대부분의 시간을 보냈다. 나는 담수가 흘러드는 강어귀 가에서 이상적인 장소를 찾아 냈다. 근처에 낡고 버려진 부두가 있는걸로 보아 이곳은 예전에 어떤 종족이 거주하던 곳인 것 같다. 그러나 원래 누가 살던 땅이었는지는 시간이 흘러야만 알 수 있을 것이다.'),
(155, 'koKR', 'S. J. 얼가딘 경은 인간 귀족 출신입니다. 그의 아버지인 얼가딘 백작은 관대함으로 유명했습니다. 제2차 대전쟁 후 스톰윈드 복구 과정에서 석공 조합의 근무 환경 개선을 위해 적극적으로 노력한 사람이 바로 얼가딘 백작이었습니다.'),
(162, 'koKR', '놈의 죽음으로 원정대는 축제 분위기에 휩싸였다. 바닐은 모두가 즐길 수 있도록 벌꿀술을 따라 주었으나 축제는 오래가지 못했다. 시체를 다시 기지로 보내기 위해 준비하느라 모두 방심하고 있던 중에 끔찍한 으르렁거리는 소리가 들려 온 것이었다. 내 생애에서 피가 얼어 붙는 것처럼 그렇게 섬뜩한 소리는 다시 들어 보지 못했다.'),
(164, 'koKR', '나는 대원들에게 다음 날은 아제로스 전역에서 모피 수요가 대단히 높은 표범을 사냥할 것이라 약속했다. 얼라이언스를 위해 용감하게 자신의 삶을 희생하고 있는 모든 전문 사냥꾼, 덫사냥꾼, 가죽 상인들을 생각한다면 이런 수요는 당연한 보상이라 할 수 있다.'),
(177, 'koKR', '나는 해안가에 랩터로부터 숨을 곳이 있기를 바라면서 동료들을 바다 쪽으로 안내했다. 그런데 서둘러 도망쳐 오는 바람에 북쪽으로 너무 멀리 도망쳐 와 위태로운 고지까지 오고 말았다. 이미 실수는 저질러졌고 그건 모두 내 잘못이었다. 우리는 깎아지른 절벽 끝에 멈춰 섰고, 랩터들은 겨우 몇 발자국 뒤에 있었다.'),
(180, 'koKR', '그때 기적 같은 일이 일어났다. 옆쪽 멀리서 거대한 흰 호랑이의 또렷하고 무시무시한 포효가 들려왔다. 숫자가 많았음에도 랩터들은 몸을 돌려 사방으로 흩어졌다. 호랑이가 우리 곁을 스쳐 지나가 랩터 한 마리를 덮치는 순간, 하얀 섬광만이 언뜻 보였다. 명령은 필요하지 않았다. 일행 넷 모두 이제 달아날 때임을 알았다.'),
(182, 'koKR', '자랑스런 동료와 진실의 탐구자들에게\r\n\r\n현장 발굴 작업은 계속되고 있지만 지난 보고서에서도 언급했던 트로그 놈들 때문에 작업이 지연되고 있소. 이 트로그 중 일부는 보통 때보다 더 공격적이긴 하지만 난 놈들을 처치할 방법이 있으리라 확신하오. 최근 유물이 많이 발굴되고 있지만 한 가지를 제외하고는 그 가치에 있어서 이전 것과 별반 다를 게 없소. 대단한 것은 아니지만 흥미로운 사실이오. 이 건에 관해서는 아래에 자세히 설명하도록 하겠소.'),
(183, 'koKR', '한 가지 예외가 있었소. 최근 발견된 독특하게 조각된 조각상들이 현장에 있는 트로그들에게 영향을 미치는 것 같소. 놈들은 이 돌 조각상들에 이끌리고 있으며, 일부 트로그들은 돌 조각상의 영향으로 광포해지기까지 하오! 지난 번 보고서에 이 조각상들에 대한 간략한 설명이 포함되어 있소.\r\n\r\n이 조각상들에 대해 어떤 결론을 내리기 위해서는 더 면밀한 조사가 필요하겠지만, 아무튼 난 이 조각상들이 트로그와 티탄 간의 관계를 밝혀 줄 것으로 기대하고 있소.'),
(184, 'koKR', '끝으로, 다시 한번 강조하지만 우린 화약이 필요하오. 현재 보급품이 거의 바닥나 발굴 작업에 큰 지장을 주고 있소. 곧 다시 화약이 보급될 것이라고 들었지만 아직까지 받지 못했소.\r\n\r\n혹 무슨 일이 있는 것인지, 지연되고 있는 이유가 궁금하오.\r\n\r\n그럼 이만 줄이겠소.\r\n발굴조사단장 다테우스 아이언밴드'),
(185, 'koKR', '모든 것은 롤랜드 광산에서 그 저주받은 낫을 발견하면서 시작됐다. 낫을 발견하기 전까지 이곳은 노스샤이어 계곡만큼이나 평온한 곳이었다.\r\n\r\n정말 후회스럽게도 내가 광산의 돌 무더기 사이에서 튀어나와 있던 낫의 자루를 발견하고 그걸 잡아 꺼내면서부터 롤랜드 광산은 비참한 죽음의 장소가 되어 버렸다.'),
(186, 'koKR', '모든 것은 롤랜드 광산에서 그 저주받은 낫을 발견하면서 시작됐다. 낫을 발견하기 전까지 이곳은 노스샤이어 계곡 만큼이나 평온한 곳이었다.\r\n\r\n정말 후회스럽게도 내가 광산의 돌 무더기 사이에서 튀어나와 있던 낫의 자루를 발견하고 그걸 잡아 꺼내면서부터 롤랜드 광산은 비참한 죽음의 장소가 되어 버렸다.'),
(187, 'koKR', '무슨 일이 일어날지 진작 알았더라면 룬문자가 새겨진 그 낫 자루를 잡지 못하게 내 손을 잘라 버리기라도 했을 것이다. 이 얼마나 후회스러운 일인가! 후회란 세상을 등지기 전 노인들만 하는 것이라고 생각했었는데... 후회란 노인이 아니라 절망에 빠진 자의 것이란 걸 깨달았다. 후회하는 사람은 외투를 뒤집어쓰고 불행한 운명에 굴복하여 벗을 수도 없고 벗으려는 의지도 없는 자들이다.\r\n\r\n감상적인 시인들이나 할 법한 얘기는 이쯤에서 그쳐야겠다. 내가 겪은 일들을 계속 기록해야 하니까...'),
(188, 'koKR', '그 낫이 세상에 모습을 드러낸 이후 광산에 변화의 물결이 일었다. 희미한 횃불에서 나오던 빛이 휘어지고, 우리는 목소리 크기를 스스로 제어할 수 없게 되었다. 어떤 때는 한 사람이 속삭이는 소리가 손으로 귀를 틀어막아야만 할 정도로 굴 속 전체에 크게 울려 퍼지기도 하고, 또 어떤 때는 고함 소리가 채 몇 발자국 거리도 못 가 바람에 묻혀 희미하게 사라져 버리기도 했다.\r\n\r\n물론 우린 당황했지만 이 이상한 현상에 대한 궁금증은 곧 풀렸다. 그것은 우리를 광산에서 내쫓은 늑대인간의 출현을 알리는 전조였을 뿐이었다.'),
(189, 'koKR', '놈들이 사방에서 공격해 왔다. 우리 발 아래 숨겨진 구덩이에서 튀어나오기도 하고, 머리 위에서 조용히 떨어져 내리기도 했다. 이렇게 끔찍한 상황이 시작되고 몇 분이 지나지 않아 반이 당하고 말았다. 나를 포함한 나머지 생존자는 필사적으로 도망쳤다. 나는 달려가면서 많은 형제들이 놈들의 이빨과 발톱에 당하는 걸 목격했고, 비명 소리가 짧게 사라지거나 헐떡이다 끊어져 버리는 것을 수없이 들었다.\r\n\r\n난 그곳을 탈출한 유일한 인간이었던 것이다.'),
(190, 'koKR', '내가 그날 밤 어떻게 살아남을 수 있었는지 정확히는 모르겠지만 아마도 경계를 늦추지 않고 공격이나 위험으로부터 재빨리 빠져나왔기 때문일 것이다. 내 별명도 이런 성격 탓에 붙여진 것이니 붙여졌다. 이런 나의 조심스러운 성격이 날 구한 것이 아니었을까...?\r\n\r\n아니면 내가 돌 무더기에서 잡아 꺼낸 낫 때문이었을 수도... 정신없이 도망치는 동안 그 낫을 잃어버렸으니깐 그것도 아닐 것이다. 하지만 어쨌든 나 때문에 늑대인간이 그늘숲에 나타난 것이니 늑대인간 놈들도 내게 일종의 예의를 차린 것 아니었을까? 저주받을 놈들!'),
(191, 'koKR', '아니면 내가 그늘숲에 초래한 변화의 목격자가 되는 비참한 운명을 타고난 것인가? 아마도 늑대인간이 이 땅을 짓밟고 그 사악함으로 세상을 끝없이 더럽히는 것을 지켜보는 것이 내 운명일지도...\r\n\r\n진정 그것이 내 운명이라면, 나에게 닥친 시련은 그것뿐만이 아닐 것이다. 그늘숲을 차지하려는 세력은 늑대인간만이 아니다. 죽음의 고개에서 나타난 악귀들도 이 땅을 노리고 있는 것이다.\r\n\r\n그들에 대해서는 다음 장에서 쓰도록 하겠다. 그리고 이 땅을 노리는 자들이 그들이 마지막이 되길 바랄 뿐이다...'),
(192, 'koKR', '롤랜드 광산에서 무사히 도망친 후, 나는 스벤이라는 자의 헛간에 숨었다. 그 헛간에서 며칠을 지냈지만 계속 공포에 휩싸여 있었기 때문에 스벤이나 그의 가족이 보지 못하게 숨어있었다. 하지만 숨어서 지켜보니 농부가족인 이들은 매우 좋은 사람들이었다. 그때 내가 헛간에서 나갔다면 그들이 안전하게 나를 숨겨 줬었겠지만, 당시 누군가를 믿는다는 건 내게 너무 어려운 일이었다. 광산에서 그 충격적인 일을 겪은 후로는 더욱 그랬다. 그래서 나는 숨어 있었고 그것이 나를 살렸다.'),
(193, 'koKR', '내가 헛간에 숨어 지낸 지 며칠이 지난 후, 스벤은 다크샤이어로 떠나기 위해 농장을 나섰다. 그는 아내에게 작별의 입을 맞추고 아이들에게 미소를 지어 보이고는, 곧 장난감과 과자를 사 가지고 돌아오겠다는 약속과 함께 길을 나섰다. 불쌍한 사람, 그것이 가족들의 모습을 본 마지막이었다. 그래도 그들은 마지막 순간에 행복하게 헤어질 수 있지 않았는가. 또 그의 아내가 먼저 죽었으니 아이들의 처참한 죽음을 목격하고 피눈물을 흘리는 일은 피할 수 있지 않았던가. 하지만, 내게는 이런 작은 자비도 허락되지 않았다. 난 모든 걸 목격했고, 그 모습은 악몽으로 나타나 영원히 나를 괴롭힐 것이다.'),
(194, 'koKR', '스벤이 떠나고 집에 남아 있던 그의 가족이 흑기사의 습격을 당하던 그날 밤의 악몽이 생생히 떠올라 내 손이 떨리면서 또다시 후회가 밀려온다. 내가 뛰쳐나가 죽음의 고개에서 온 저 악귀들과 맞서 싸웠어야 하는데... 이미 되돌릴 수 없는 후회일 뿐이다. 참사에서 살아남은 생존자라면 누구나 이러한 후회에 시달리게 된다. 설령 내가 숨어 있던 곳에서 뛰쳐나갔다 하더라도 나 역시 죽임을 당하고, 내 시체가 조각조각 찢겨 사방으로 흩어져서 형체도 알아볼 수 없게 되었으리란 걸 잘 알고 있다.'),
(196, 'koKR', '\"엘룬의 낫.\" 흑기사 중 하나가 마치 돌에 도끼를 가는 듯한 거칠고 날카로운 목소리로 소리쳤다. 그리고 말이 끝날 때쯤에는 - 엘룬 - 이라고 목이 멘 듯 쉰 목소리가 났다.\r\n\r\n그 목소리는 공포 그 자체였다. 소리가 무시무시하기도 했었지만... 나는 그들이 얘기하는 낫이 무엇인지 알고 있었기 때문이었다. 그것은 며칠 전 내가 롤랜드 광산의 돌 더미에서 꺼낸 그 저주받은 물건을 말하는 것이 분명했다. 그게 흑기사들이 찾고 있는 물건이었다니! 그리고 그때문에 스벤의 가족이 죽임을 당하다니...'),
(197, 'koKR', '항상 남편이나 아이들에게 스벤의 아내의 호칭은 \"여보\", \"내 사랑\", \"엄마\" 등이었기 때문에 난 그녀의 이름을 알지 못했다. 그녀의 이름을 알았더라면 좋았을 텐데... 난 그날 그녀의 마지막 모습을 기억하고 있는 유일한 사람이고, 비록 일개 농부의 아내일 뿐이었지만 지금까지 내가 봐 온 어떤 사람보다도 용감한 사람이었다.\r\n\r\n물론 그녀는 낫에 대해 모르고 있었지만 흑기사가 그걸 찾고 있다는 사실을 눈치채고 곧 작전을 생각해 냈다. 정말 대담하고도 영리한 작전이었다. 성공했더라면 정말 좋았을 것을...'),
(198, 'koKR', '\"낫이라고요?\" 조용한 목소리로 그녀가 대답했다. \"물론 알고 있죠. 이곳에 사는 사람 중에 그 낫을 모르는 사람이 있겠어요?\" 그녀는 흔들림 없이 흑기사를 쳐다봤다. 만약 내가 진실을 모르고 있었다면 나조차도 그녀가 사실을 말할 것이라고 믿었을 것이다. 그녀가 낫에 대해 알리는 없었던 것이다.\r\n하지만 그녀의 거짓말이 효과를 발휘했다. 조금 전 질문을 했던 흑기사가 그녀를 향해 고개를 약간 숙이고는 외쳤다. \"어디에 있지?\" \"내가 데려다 주겠어요, 당신들 모두.\" 그녀가 대답했다. 그녀의 눈 속에 작은 희망이 희미하게 빛나는 것을 볼 수 있었다.'),
(199, 'koKR', '\"하지만 가는 길이 멀고 아이들은 방해만 될 테니까 여기 두고 가요.\" 그녀의 속임수는 단순했지만, 원래 단순한 속임수가 가장 잘 먹히는 법이다. 성공했더라면 흑기사들을 농장에서 멀리 데려갈 수 있었을 것이다. 그러면 그녀 자신은 살아남지 못하더라도 아이들만은 살릴 수 있었을 것이다. 그리고 흑기사가 그녀의 지혜로운 거짓말을 믿기만 했더라면 성공했을 것이다. 난 신을 믿은 적이 없었지만, 저 끔찍한 흑기사와 맞서고 있는 스벤의 아내를 위해 열심히 기도했다.\r\n\r\n\"제발... 놈들이 믿도록 해 주십시오.\"'),
(201, 'koKR', '스벤의 아내는 판자처럼 굳은 채로 서 있었고 눈동자는 커졌다. 비명을 지르기 위해 입을 벌렸지만 어떤 소리도 들리지 않았다. 이 끔찍한 순간이 몇 분 동안 계속된 후 그 손은 그녀를 놓아 주었고 그녀는 바닥에 쓰러졌다. 그리고는 보석을 가진 흑기사가 말 안장에 올라타더니 커다란 목소리가 뿜어져 나왔다.\r\n\r\n\"이 여자는 거짓말을 하고 있다.\" 이 목소리는 그 후 내가 꾸는 악몽에 계속 나타나고 있다. \"이 여자는 낫을 본 적도 없어.\"'),
(202, 'koKR', '그러고 나서 그 흑기사는 몸 속의 영혼이 빠져 나가기라도 한 듯 어깨를 약간 굽혔다. 그리고 마지막으로 전과 같이 늙고 날카로운 목소리로 이렇게 외쳤다.\r\n\r\n\"주인께서 명하셨다. 모두 죽여라!\"\r\n\r\n그 뒤에 일어난 일은 설명할 수가 없다. 기억에 또렷이 남아 있긴 하지만 내 비열한 영혼조차도 차마 그 후의 끔찍했던 몇 분 동안 일어난 일들을 종이 위에 옮기지는 못하겠다.'),
(203, 'koKR', '그저 스벤의 가족이 모두 죽었다는 것만 말할 수 있다. 그리고 얼마 지나지 않아 스벤이 이 끔찍한 죽음의 현장으로 돌아왔다. 나는 그의 깊은 슬픔 앞에 내 모습을 나타내기가 두려웠다. 그리곤 그가 나를 발견하게 될까 두려운 나머지 숨어 있던 헛간에서 도망쳐 나왔다. 나는 지금 스벤이 어디에 있는지 모르지만 그가 언젠가 평온을 되찾게 되기를 빈다.\r\n\r\n그 후 몇 주 동안 이곳 저곳으로 피해 다녔다. 흑기사에 대한 두려움 때문에 어디에서도 지체할 수가 없었다.'),
(204, 'koKR', '그저 스벤의 가족이 모두 죽었다는 것만 말할 수 있다. 그리고 얼마 지나지 않아 스벤이 이 끔찍한 죽음의 현장으로 돌아왔다. 나는 그의 깊은 슬픔 앞에 내 모습을 나타내기가 두려웠다. 그리곤 그가 나를 발견하게 될까 두려운 나머지 숨어 있던 헛간에서 도망쳐 나왔다. 나는 지금 스벤이 어디에 있는지 모르지만 그가 언젠가 평온을 되찾게 되기를 빈다.\r\n\r\n그 후 몇 주 동안 이곳 저곳으로 피해 다녔다. 흑기사에 대한 두려움 때문에 어디에서도 지체할 수가 없었다.'),
(205, 'koKR', '그 낫이 세상에 모습을 드러낸 이후, 놈들이 사방에서 공격해 왔다. 우리 발 아래 숨겨진 구덩이에서 튀어나오기도 하고, 머리 위에서 조용히 떨어져 내리기도 했다. 이렇게 끔찍한 상황이 시작되고 몇 분이 지나지 않아 반이 당하고 말았다. 나를 포함한 나머지 생존자는 필사적으로 도망쳤다. 나는 달려가면서 많은 형제들이 놈들의 이빨과 발톱에 당하는 걸 목격했고, 비명 소리가 짧게 사라지거나 헐떡이다 끊어져 버리는 것을 수없이 들었다.'),
(206, 'koKR', '내가 그날 밤 어떻게 살아남을 수 있었는지 정확히는 모르겠지만 아마도 경계를 늦추지 않고 공격이나 위험으로부터 재빨리 빠져나왔기 때문일 것이다. 내 별명도 이런 성격 탓에 붙여졌다. 이런 나의 조심스러운 성격이 날 구한 것이 아니었을까...?\r\n\r\n아니면 내가 돌 무더기에서 잡아 꺼낸 낫 때문이었을 수도... 정신없이 도망치는 동안 그 낫을 잃어버렸으니깐 그것도 아닐 것이다. 하지만 어쨌든 나 때문에 늑대인간이 그늘숲에 나타난 것이니 늑대인간 놈들도 내게 일종의 예의를 차린 것 아니었을까? 저주받을 놈들!'),
(207, 'koKR', '롤랜드 광산에서 무사히 도망친 후, 나는 스벤이라는 자의 헛간에 숨었다. 그 헛간에서 며칠을 지냈지만 계속 공포에 휩싸여 있었기 때문에 스벤이나 그의 가족이 보지 못하게 숨어있었다. 하지만 숨어서 지켜보니 농부가족인 이들은 매우 좋은 사람들이었다. 그때 내가 헛간에서 나갔다면 그들이 안전하게 나를 숨겨 줬었겠지만, 당시 누군가를 믿는다는 건 내게 너무 어려운 일이었다. 광산에서 그 충격적인 일을 겪은 후로는 더욱 그랬다.\r\n\r\n그래서 나는 계속 숨어 있었다.'),
(209, 'koKR', '보고서: 코볼트\r\n\r\n노스샤이어 계곡 주변 지역에서 코볼트의 활동이 증가하고 있습니다. 노스샤이어 수도원 북쪽에 있는 메아리 광산 안에는 상당한 수의 코볼트가 집결해 있는 것으로 밝혀졌습니다. 이에 코볼트 섬멸을 도울 성기사와 전사, 지역 주민들을 소집 중입니다. 현재까지는 순조롭게 진행되고 있으며 필요하면 인원을 더 충원할 계획입니다.'),
(210, 'koKR', '보고서: 도적 무리\r\n\r\n노스샤이어 계곡에 코볼트보다 위험한 인간 도적 떼가 나타났습니다. 그들은 붉은 복면을 하고 자신들을 결사단이라 칭하고 있습니다. 이 정도 규모의 조직이라면 노스샤이어를 비롯한 엘윈 숲 전역에 문제를 일으킬 수 있습니다. 놈들의 지휘관 중 한 명인 개릭 패드풋이란 자의 신원을 확인하고 현재 놈을 처치하기 위해 노력하고 있습니다.'),
(211, 'koKR', '보고서: 늑대\r\n\r\n노스샤이어에서 야생동물들의 습격이 증가하고 있습니다. 이건의 말로는 그늘숲에서 늑대들이 이곳으로 쫓겨왔다고 합니다. 늑대들이 인간을 공격하는 일은 극히 드물지만 놈들의 수가 증가하면서 농부들이 피해를 입고 있으며 가축을 많이 잃고 있습니다.'),
(212, 'koKR', '추천서:\r\n\r\n이 문서를 지닌 이는 열정과 뛰어난 능력으로 노스샤이어를 위해 봉사한 공로를 인정받아 스톰윈드 군대에서 부관 대리의 지위를 수여받았습니다. 이 사람은 엘윈 숲을 위해서도 필요한 사람이라 확신합니다.\r\n\r\n서명: 노스샤이어 스톰윈드 군대\r\n치안대장 더글라스 맥브라이드'),
(213, 'koKR', '서부정통 스튜 조리법\r\n\r\n재료:\r\n식인독수리 고기 3덩이\r\n뿔엄니멧돼지 주둥이 3개\r\n멀록 눈알 3개\r\n오크라 3개\r\n\r\n위의 재료를 함께 넣고 적어도 두 시간 이상 푹 끓인 후 그릇에 담아낸다.'),
(214, 'koKR', '사랑하는 이베트\r\n\r\n이 편지를 가장 빠른 전령에게 맡기도록 하겠소. 전령이 우리를 포위하고 있는 적진을 뚫고 무사히 빠져나가기를 기원하오. 그리고 내가 전하는 마지막 소식이 될 이 편지를 당신이 읽을 수 있기를 간절히 바라오이다.\r\n\r\n그래도 이 암울한 시기에 당신만은 무사하다는 사실이 내게 유일한 위안이라오.'),
(217, 'koKR', '사랑하는 이베트\r\n\r\n이 편지를 가장 빠른 전령에게 맡기도록 하겠소. 전령이 우리를 포위하고 있는 적진을 뚫고 무사히 빠져나가기를 기원하오. 그리고 내가 전하는 마지막 소식이 될 이 편지를 당신이 읽을 수 있기를 간절히 바라오이다.\r\n\r\n그래도 이 암울한 시기에 당신만은 무사하다는 사실이 내게 유일한 위안이라오.'),
(218, 'koKR', '스톤필드 일가와 맥클루어 일가 간의 전쟁으로 토미 조가 죽임을 당해, 꽃을 피우고 있는 메이벨의 사랑이 슬픈 결말을 맞이하게 되지 않을까 걱정이라네. 난 전쟁으로 어두운 소식과 소문이 끊이지 않고 있는 이런 시기에는 젊음과 사랑이 더욱 활짝 꽃펴야 한다고 생각한다네.\r\n그래서 부탁인데, 자네의 능력을 발휘하여 이 두 젊은이가 사랑을 이룰 수 있도록 물약이나 비약을 만들어 줬으면 하네. 고맙네, 윌리엄. 바쁘지 않으면 한번 들리게나. 옛 이야기나 나누게 말이야.\r\n\r\n밀드레드 스톤필드'),
(223, 'koKR', '필요할 경우 이 정보를 전하도록 하라.\r\n\r\n\r\n티리스팔 지역 사령부\r\n\r\n대장 멜로즈\r\n\r\n대장 바콘\r\n\r\n대장 페린\r\n\r\n\r\n대영주 지령 사항\r\n\r\n\r\n대장 페린, 지시에 따라 현재 주둔 중인 남서쪽 감시탑의 경계를 더욱 강화하라. 추가 보급품은 후일 공급될 것이니 그동안 주변 농장에서 구할 수 있는 대로 물품을 조달하도록 하라.\r\n'),
(224, 'koKR', '브릴 지역의 언데드 조직에 대해 보다 자세한 정찰 및 정보 수집 활동을 펼치도록 하라.\r\n\r\n\r\n대장 바콘, 북쪽 탑 근처에서 언데드의 움직임이 증가하고 있는 것으로 보인다. 신속히 진압하라.\r\n\r\n\r\n대장 멜로즈, 역병지대 변방에서 활동 중인 언데드 조직의 규모에 대한 우려의 목소리가 있다. 몇 주 내에 증원 병력을 그곳으로 보내도록 하겠다.\r\n\r\n\r\n정의의 편에 영광 있으라.\r\n'),
(229, 'koKR', '첫째 날\r\n\r\n전차가 고장 났지만 이 언덕 어딘가에 키론 광석이 있을 것이다. 해머풋에게 전차를 떠나지 말고 잘 지키라고 이르고 나는 혼자 정찰을 계속했다. 전차를 수리하지 못하면 이 일지는 내 마지막 유언이 될 것이다.\r\n\r\n- 조종사 버론 힐델브, 아이언포지 전차 부대'),
(230, 'koKR', '둘째 날\r\n\r\n정찰을 계속했지만 광석을 찾지는 못했다. 스톤기어가 농담으로 그 광석에 대한 소문을 지어낸 건 아닌지 모르겠다. 흠, 만약 정말 그랬다면 스틸그릴의 정비소로 돌아가는 대로 그의 머리를 부숴 버릴 것이다!\r\n\r\n오늘 밤 야영을 준비하면서 협곡에 메아리치는 짐승의 울음소리를 들었다.\r\n\r\n늑대는 아니고, 혹시 곰일지도 모르겠다.'),
(231, 'koKR', '셋째 날\r\n\r\n짐승의 울음소리가 밤새 계속됐고 오늘도 하루 종일 나를 따라다니며 광석 찾는 일을 방해했다. 아무래도 나를 쫓아다니는 곰이 있는 것 같다.\r\n\r\n가까이 오기만 해라. 머리에 정을 박아 줄 테니까!'),
(232, 'koKR', '넷째 날\r\n\r\n가지고 온 물품이 다 떨어져 간다. 식량은 아직 충분하지만, 이렇게 오랫동안 전차 밖의 야외에서 지낼 생각은 아니었기 때문에 에일 맥주를 두 통밖에 가져오지 않은 것이다.\r\n\r\n지난 이틀 동안 밤새도록 잠을 이루지 못했다. 바로 그 망할 놈의 울음소리 때문이다. 그리고 맥주가 거의 바닥났다.\r\n\r\n내일 해머풋과 우리의 증기 전차가 있는 곳으로 돌아가야 할 것 같다. 맥주 없이 이곳에서 길을 잃고 싶은 생각은 추호도 없으니까.'),
(233, 'koKR', '다섯째 날\r\n\r\n그 망할 놈의 곰이 나를 덮쳤다. 한낮에 내 뒤에서 으르렁거리며 달려들어 공격해 왔다.\r\n\r\n놈이 바람을 등지고 공격해 왔더라면 놈이 다가오는 것을 냄새로 알 수 있었을 것이다. 놈의 냄새는 정말 고약했다. 지저분한 털과 썩은 숨결에서 풍기는 악취만으로도 어지러울 지경이었다.\r\n\r\n놈을 물리치긴 했지만 다리를 심하게 물렸다. 지금은 움직일 수도 없고, 에일 맥주도 바닥이 난 데다, 광석은 하나도 찾지 못했다. 제길!'),
(234, 'koKR', '여섯째 날\r\n\r\n아직까지 곰은 다시 나타나지 않았다. 내 공격으로 꽤 큰 타격을 입은 모양이다. 하지만 여전히 놈의 울음소리는 들린다. 놈은 내가 죽기를 기다리는 것 같다.\r\n\r\n이 책을 발견하는 이에게. 당신에게 한 가지 부탁이 있습니다. 저 지저분한 곰을 처치해 주십시오. 놈을 처치하고 이 책을 내 친구 해머풋에게 돌려주시기 바랍니다. 그가 무슨 일이 일어난 것인지 궁금해 할 테니까요. 그리고 내 갑옷은 당신이 가지시기 바랍니다. 늙은 썩은발톱을 상대하려면 필요할 겁니다!'),
(235, 'koKR', '다크샤이어 시장 엘로 이본로크 보시오. 귀하의 마을에 대해 좋지 않은 소식을 전하게 되어 유감이군. 나는 무에서 유를 창조하는 자요. 이 편지를 전하는 이를 속여 끔찍한 피조물을 만드는 걸 돕도록 했소. 바로 살과 뼈, 그리고 저주받은 금속으로 만들어진 악귀지. 당신이 이 편지를 읽는 지금 이 순간, 그 피조물은 내 초라한 집 밖에서 이를 갈며 내 학살 명령을 기다리고 있을 것이오.\r\n무슨 말인지 곧 알게 될 거요.\r\n\r\n-장의사'),
(244, 'koKR', '베소르 아이스샤드 경\r\n\r\n\r\n경의 뜻에 따라 요청하신 요원을 보냅니다. 바로 이 명령서를 가져가는 이가 적임자입니다.\r\n\r\n\r\n이 자는 믿을 만하고 충분히 명령을 수행할 능력이 있음을 보여 주었습니다. 스컬지 군대를 상대로 능력을 입증해 보인 자이니만큼 경의 임무에 적격일 거라고 생각합니다.\r\n\r\n\r\n여왕 폐하의 영광이 있기를...\r\n\r\n- 집정관 세브렌 올림\r\n'),
(245, 'koKR', '실종된 하사관 키샨을 찾습니다.\r\n\r\n돌망루 요새에서 있었던 혈투에서 마지막으로 목격된 것으로 확인되었으며, 검은바위부족 오크들에 의해 끌려갔다는 보고가 있었습니다.\r\n\r\n레이크샤이어 북쪽, 불타는 평원으로 가는 길 바로 서쪽에 위치한 검은바위부족의 주둔지에 전쟁 포로로 잡혀 있을 것으로 추정됩니다.\r\n\r\n집정관 솔로몬의 명으로, 하사관 키샨을 구출하는 데 도움을 주는 이에게는 치안대장 매리스가 보상할 것입니다.'),
(246, 'koKR', '지금 나는 언제나 그랬던 것처럼 까마귀 언덕의 버려진 마을에 숨어 있다. 놈들이 스벤의 아내에게 사용했던 그 힘이 무엇이든 나는 그 힘을 감당할 수가 없다. 그리고 놈들이 아직까지도 그 낫을 찾기 위해 그늘숲을 수색하고 있다는 사실을 알고 있다. 그 낫이 지금 내 손에 없다는 것에 대해 신께 감사한다. 만약 내가 지금까지 그걸 가지고 있었더라면 이미 놈들에게 발각됐을 것이다. 지금도 마음 속으로는 언젠가 놈들이 나를 발견할 것이라는 것을 알고 있다.\r\n\r\n난 너무 지쳤다.'),
(247, 'koKR', '지금 나는 언제나 그랬던 것처럼 까마귀 언덕의 버려진 마을에 숨어 있다. 놈들이 스벤의 아내에게 사용했던 그 힘이 무엇이든 나는 그 힘을 감당할 수가 없다. 그리고 놈들이 아직까지도 그 낫을 찾기 위해 그늘숲을 수색하고 있다는 사실을 알고 있다. 그 낫이 지금 내 손에 없다는 것에 대해 신께 감사한다. 만약 내가 지금까지 그걸 가지고 있었더라면 이미 놈들에게 발각됐을 것이다. 지금도 마음 속으로는 언젠가 놈들이 나를 발견할 것이라는 것을 알고 있다.\r\n\r\n난 너무 지쳤다.'),
(250, 'koKR', '데피아즈단 본부에서 파견된 이들이 징세관과 접촉할 것이다. 그 후 징세관이 수집된 황금을 이송한다.\r\n\r\n이 과정을 수행함에 있어 실패란 있을 수 없으며 신중히 처리되어야 함을 명심하기 바란다. 황금 수송에 대한 책임은 징세관에게 있지만, 질서 있고 주의 깊게 자신의 역할이 수행되도록 하는 것은 궁극적으로 데피아즈단 구성원 각자의 책임이다.'),
(251, 'koKR', '형제들이여, 우리는 한때 자부심 있는 장인이었다는 사실을 기억하기 바란다. 우리는 예전에 우리가 장인이었을 때와 마찬가지로 지금 우리에게 주어진 임무를 정확하게 수행해 낼 것이다.\r\n\r\n-EVC'),
(252, 'koKR', '아버지께서 남아 우리 가족을 지키기로 결정하신 것이 큰 실수가 아니었는지 걱정스럽소. 스컬지 군대가 티리스팔 숲을 통해 무서운 기세로 진격하고 있고, 우리가 만반의 방어 태세를 갖췄다고 해도 내 형제 데블린의 배반 이후에 우리는 놈들의 계속되는 공격에 저항할 힘과 병력이 부족한 실정이오.\r\n\r\n이베트, 이 편지를 받으면 데블린이 배반자라는 사실을 꼭 알아 두기 바라오.'),
(253, 'koKR', '데블린은 실의에 빠져 불운 속에서 빠져나올 탈출구를 찾고 있었고 그러던 중 스컬지와 계약을 맺게 된 것이오. 어떤 보상을 약속받았기에 배신을 한 것인지는 모르지만, 내 생각엔 그럴듯한 거짓말일 것이 자명하오.\r\n\r\n그를 보게 되면 도망치도록 하시오. 그는 이제 악귀일 뿐이니까 말이오. 며칠 전 밤 그는 우리 경비병 둘을 살해하고 소규모 스컬지 부대를 잠입시켜 다수의 아군이 취침하고 있는 곳으로 데려왔었소.'),
(254, 'koKR', '놈들의 매복 공격은 잔인했소. 우리는 미처 반격하기도 전에 삼분의 일이 희생됐소. 이제 변경을 지킬 경비병도 부족할 실정이오. 우리의 빈약한 방어선이 무너지고 스컬지가 공격해 오는 건 이제 시간 문제일 뿐이오.\r\n\r\n그 저주받은 밤에 절망적인 얼굴의 사람들과 음산한 얼굴의 스컬지들 사이에서 데블린의 얼굴을 봤지만 그는 내가 붙잡기 전에 사라져 버렸소. 아마 벌써 죽었거나 아니면 아직도 스컬지의 앞잡이로 살고 있겠지.\r\n\r\n어쨌든, 그는 이제 괴물이오.'),
(255, 'koKR', '데블린은 우리가 스컬지에 대항하려 하면 비참한 최후를 맞게 될 거라고 경고했었소. 그들이 티리스팔 숲에 처음 발을 들여놓았을 때 우리에게 그런 얘길 했었지. 우리를 포위하기 훨씬 전에 말이오. 아마 그는 우리가 떠나기를 간절히 바랬던 것이거나, 아니면 회심의 미소를 짓고 있었던 것일지도 모르지.\r\n\r\n데블린은 언제나 진의를 파악하기 힘든 자였소. 그는 어렸을 때부터 우리에게 수수께끼 같은 존재였지.'),
(256, 'koKR', '하지만 결국 그가 옳았고 우리는 비참한 최후를 맞았소. 아가만드 가문은 이제 여기서 끝나는가 보오. 아직은 살아 있지만 나도 곧 죽게 되리라는 것을 알고 있소.\r\n\r\n난 두렵지 않고 내 가족과 함께 남아 있었던 것에 대해 일말의 후회도 없소. 하지만 결국 마지막에 떠오르는 건 당신이구려.\r\n\r\n사랑하는 이베트, 당신은 반드시 살아 남아야 하오. 내가 편히 눈감을 수 있도록.\r\n- 투르만'),
(266, 'koKR', '소규모의 언데드 무리의 우두머리인 케간 다크마르란 자가 우리와 그들의 관계에도 자신들의 동지들로부터 은신할 곳을 찾아 우리에게 왔다. 그의 피부는 썩고 있었고 피가 오랫동안 통하지 않은 것 같았지만, 그의 행동은 매우 위엄 있고 자신보다는 동료의 안전을 더 걱정하는 것 같았다. 사실 그는 내 주위의 인간들에게도 찾아보기 힘든 인간애를 소유하고 있었다.'),
(267, 'koKR', '그런데 내가 이런 사실을 언급하는 이유는 무엇일까? 바로 지금부터 써 나갈 내용에 신빙성을 부여하기 위함이다. 왜냐하면 이 내용은 케간의 입에서 나온 것이고, 내 동료들이 이 일지를 읽고 내가 그의 말을 믿게 된 이유를 알아주길 바라기 때문이다.\r\n\r\n\"고대 신들 중에서 살아남은 자들이 아직 이 세계 깊은 곳에 남아 있다. 새로운 세력이 이 고대의 힘을 이용하기 위해 혈안이 되어 있으며, 성공하는 자는 적에 대항할 강력한 무기를 손에 넣게 될 것이다.\"'),
(268, 'koKR', '이것이 바로 케간이 내게 그의 혈석 펜던트를 주며 한 말이다. 그때 그의 눈은 공포와 함께 경의의 빛이 빛나고 있는 것 같았다. 그리고 내 손에 닿은 그의 손의 느낌으로 볼 때 내게 펜던트를 넘겨주는 것이 썩 내키지 않는 것 같았다. 뭔가 좋지 않은 기분이 날 엄습했는데, 지금까지도 그게 그의 죽은 살갗이 닿았기 때문이었는지, 아니면 펜던트가 내 피부를 스멀거리게 한 것이었는지 모르겠다.\r\n\r\n나는 펜던트에 담겨 있는 어떤 힘을 느꼈다. 깊고, 숨겨져 있는, 뭔가에 굶주려 있는 힘. 그리고 해방을 갈망하는 힘.'),
(269, 'koKR', '달라란에 있는 내 동료들은 케간과 그의 부하들이 가져온 혈석에 대한 연구를 놓고 망설이며, 대신 이 네 명의 도망자를 격리하고 그들과 함께 혈석을 그대로 놔두었지만, 나는 그의 혈석 펜던트를 연구해 주기를 바라는 케간의 진심을 외면할 수 없었다.'),
(270, 'koKR', '나는 이런 종류의 돌이 마법 특성을 가질 수 있으며, 언젠가는 우리의 적이 혈석을 이용해 우리를 공격하게 될지도 모르기 때문에, 우리 달라란 마술사들이 혈석의 힘을 이용하고 싶지 않더라도 최소한 그 특성은 알아 두어야 한다는 것을 밝혀 보이고 싶었다.\r\n\r\n그렇게 내 연구가 시작된 것이다.'),
(271, 'koKR', '나는 혈석이 석영이나 흑요석과 같은 암석의 일종이라는 가정 하에 실험을 시작했다. 따라서 이를 확인할 일련의 처리 과정에 착수했다. 혈석에 포함된 광물의 종류, 혈석의 색과 경도를 만들어낸 힘의 정체, 그리고 암석 및 광석의 공통적인 기타 특성... 하지만 실망스럽게도 혈석 펜던트는 처리 과정에서 일반 광석과는 다른 반응을 보였다.'),
(272, 'koKR', '사실, 기대했던 것과는 정반대의 반응을 보이는 경우가 많았다. 펜던트가 일부러 내 실험을 망치려 들기라도 하듯 말이다.\r\n\r\n마치 스스로 생각하고 살아 있는 것처럼...\r\n\r\n나는 화가 나긴 했지만 희망을 잃지는 않았다. 그리고 이제 펜던트를 움직이지 않는 암석 조각이 아니라 살아 있는 생명체로 여기기로 했다.\r\n\r\n하지만 나는 또다시 실패하고 말았다.'),
(273, 'koKR', '내가 실시한 새로운 실험 중 그 어떤 것으로도 혈석의 기원을 밝힐 수 없었다. 그때까지 내가 푼 유일한 수수께끼라고는 혈석이 살아 있는 것도, 그렇다고 죽은 것도 아니라는 사실뿐이었다.\r\n\r\n하지만 바로 그때, 실패 직전에 돌파구가 마련됐다. 가장 최근의 실험에 사용된 유리 비커는 이가 빠져서 가장자리를 따라 작은 홈들이 생겨 있었다. 실험이 다시 아무 소득 없이 끝나자 나는 작업대를 청소하다가 비커에 손을 베었다.'),
(274, 'koKR', '상처는 깊지 않았지만 피가 많이 났다. 상처 입은 손가락에 붕대를 감기 전에 상당량의 피가 작업대 위에 흘러 있었다.\r\n\r\n피 때문에 다시 엉망이 되어 버린 작업대를 닦다가 나는 참으로 기이한 현상을 목격했다.'),
(275, 'koKR', '혈석 펜던트 근처에 떨어진 피가 마치 중력에 이끌리기라도 하는 것처럼 그 보석을 향해 서서히 움직이고 있는 것이었다. 펜던트에 닿은 피는 사라져 버린 것처럼 보였고, 더 많은 피를 흡수할수록 혈석의 붉은색은 진해져 갔다.'),
(276, 'koKR', '이 광경을 본 후, 머리가 가벼워졌다. 아마 방금 입은 상처 탓이거나(그 정도로 많은 피를 흘렸다고 생각하지는 않지만), 아니면 그토록 많은 좌절을 겪은 후 마침내 혈석의 특성 중 하나를 밝혀 냈기 때문이리라. 나는 뒤에 있는 작업용 의자를 끌어다 앉아 생각에 잠겼다. 머릿속에 수많은 생각과 의문들이 빠르게 오가면서 혼란과 압박감으로 쓰러질 것 같았다.\r\n\r\n혈석이 피를 마시는 건가? 피를 원하고 있는 건가? 피를 빨아들이는 건가?'),
(277, 'koKR', '아니면 혈석 자체가 피로 만들어진 것인가? 만약 그렇다면 누구의 피로 만들어진 것인가? 내 피? 아니면 다른 인간의 피? 동물의 피?\r\n\r\n그것도 아니라면 혈석은 알려지지 않은 어떤 존재의 피란 말인가? 케간이 내게 펜던트를 건네 줄 때 두려워하면서도 경의를 표했던 바로 그 존재.\r\n\r\n그것은 반드시 답을 찾아야 할 중요한 의문이다. 이것이 바로 수수께끼의 열쇠인 것이다.'),
(278, 'koKR', '내 안에서 다시 뜨거운 열의가 타올랐고 다시 실험에 착수했다. 이번에는 어떠한 가정도 하지 않고 내가 할 수 있는 모든 실험을 꼼꼼하게 실행했다. 때문에 전보다 엄청나게 많은 노력이 필요했지만 그 정도는 기꺼이 감수할 만큼 나는 해답을 발견하기를 원하고 있었다.\r\n\r\n그리고, 비록 나의 연구실은 작고 도와줄 조수도 없지만 나는 혈석의 또 다른 흥미로운 성질을 발견해 냈다.'),
(279, 'koKR', '피뿐만 아니라 혈석에는 정령의 힘들이 깃들여 있었다. 불, 물, 천둥, 그리고 바위가 피(과연 누구의 피란 말인가?)와 섞여 있으며, 이 혼합물은 겉보기에 움직임이 없어 보이지만 내부적으로는 이 모든 힘들이 서로 격렬히 충돌하고 있는 것 같았다. 이제 이 놀랍고도 불길한 예감이 드는 물질에 대해 더 많은 의문이 생겨났다.'),
(281, 'koKR', '이러한 실험의 결과를 기다리는 동안 나는 케간과 이야기를 나눴다. 혈석에 대해 아는 것을 말해 달라고 끈질기게 부탁했지만 그는 펜던트를 주던 날 했던 말 외에는 절대 입을 열지 않았다. 그리고 자신이 \"포세이큰\" (그는 자신의 언데드 일족을 이렇게 불렀다.)이라는 집단에 몸담고 있을 때의 이야기도 잘 하지 않았다.'),
(282, 'koKR', '하지만 케간은 다른 주제에 관해서는 이야기하기를 매우 좋아했다. 특히, 자신이 멸망 전의 로데론에서 자라던 시절의 이야기를 자주 했다.\r\n\r\n이미 폐허가 되어 사멸했지만 그는 아직도 그 사라진 왕국에 대해 큰 애정이 있었다.\r\n\r\n난 점점 더 케간을 좋아하게 되었고 덕분에 인내심을 가지고 실험 결과를 기다릴 수 있었다.'),
(283, 'koKR', '하지만 아무 소식도 없이 몇 주가 지나자 내 인내심도 흔들리기 시작했다. 그래서 달라란에 자세히 문의해 본 결과, 혈석이 내 동료들에게 전달되지 않았다는 사실을 알게 되었다. 내가 보낸 급사가 혈석 펜던트와 함께 도중에 실종돼 버린 것이다!\r\n\r\n이건 심각한 사태다. 케간과 그의 부하들에게 실험에 사용할 수 있는 혈석 견본이 아직 남아 있기는 하지만, 펜던트가 불미스러운 자의 손에 들어가게 될까 봐 걱정이다.'),
(284, 'koKR', '나는 다른 전령을 달라란으로 보냈고, 아직도 보호 지역 밖의 폐허에서 펜던트를 찾고 있다는 소식을 전해 듣고 있다.\r\n\r\n너무 늦기 전에 되찾게 되기만을 바랄 뿐이다.'),
(285, 'koKR', '방랑자 그리렉의 이야기\r\n\r\n[...서판의 첫 부분은 닳아 지워졌지만 마지막 부분은 알아볼 수 있습니다...]\r\n\r\n그리렉은 정글을 짓밟아 버렸다. 그의 눈은 분노로 불타고 가슴은 우레와 같이 뛰고 있었다. 허공을 향해 분노로 울부짖은 그는 팔을 쳐들었다.\r\n\r\n오른쪽 팔을 잃고 나머지 한 쪽 팔만으로 이어온 사냥을 통해 그의 왼쪽 팔은 강하고 튼튼하게 단련되어 있었다.'),
(286, 'koKR', '트롤의 전설, 제 3권 해일의 돌\r\n\r\n저자: 대마법사 앤자이럼 룬위버\r\n\r\n달라란\r\n\r\n서문\r\n\r\n고대 구루바시 제국은 매우 매혹적이고 흥미로운 전설의 근원이다. 이 전설은 그들의 주변 환경에 대한 신념과 사회적 규범에 대한 고찰로 자연을 향한 위대한 숭배 정신에 초점을 맞추고 있다. 본 연구의 이전 부분에서는 그들의 뱀 숭배의 여러 가지 측면에 대해 자세히 살펴봤다.\r\n'),
(287, 'koKR', '쿠르트란 와일드해머\r\n\r\n저명한 용기사이자 맹금의 봉우리의 그리핀 조련사. 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대 소속 그리핀 비행사단의 사령관. 사망한 것으로 추정.\r\n\r\n바람 소리에 창공의 리의 울음소리가 들리면 산봉우리에 부딪혀 울리는 그대의 우렁찬 망치 소리가 들릴 겁니다. 형제여, 저 세상에서도 힘차게 나아가십시오. 조상들의 전당에서 편히 쉬시기를...\r\n\r\n- 맹금의 봉우리의 군주, 폴스타드 와일드해머'),
(288, 'koKR', '순찰대장 알레리아 윈드러너\r\n\r\n쿠엘탈라스의 저명한 트롤 사냥꾼. 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대에서 정찰대 및 첩보부대를 지휘. 사망한 것으로 추정.\r\n\r\n바람을 가르는 화살만큼이나 곧은 마음의 소유자여. 그대는 우리 순찰대의 가장 빛나는 존재였으며 우리 종족이 가장 사랑했던 이였습니다.\r\n\r\n- 쿠엘탈라스의 순찰대 사령관, 실바나스 윈드러너'),
(289, 'koKR', '키린 토의 대마법사 카드가\r\n\r\n메디브의 전 제자이자 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대의 총사령관. 사망한 것으로 추정.\r\n\r\n그 누구도 그대처럼 헌신적인 자세로 마법과 전쟁의 어두운 소용돌이 속을 뛰어든 자는 없었으니... 지혜로운 방랑자여, 당신이 어디에 있든지 평안을 빕니다\r\n\t\t\t\t\r\n- 달라란의 대마법사, 안토니다스'),
(290, 'koKR', '투랄리온 장군\r\n\r\n전직 안두인 로서 경의 부관. 은빛 성기사단원. 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대의 장성. 사망한 것으로 추정.\r\n\r\n에사루스 다르 노 `다라도르` - 피와 명예로 기립니다.\r\n친구여, 자네는 정의와 미덕의 오른손이었네. 자네 이름은 우리의 전당에서 영원히 기려질 것일세.\r\n\r\n- 은빛 성기사단, 빛의 수호자 우서 경'),
(291, 'koKR', '다나스 트롤베인\r\n\r\n스트롬가드의 민병대 사령관. 장군 투랄리온의 전술 조언가이자 오크족의 본거지인 드레노어로 진격한 얼라이언스 원정대의 군단장. 사망한 것으로 추정.\r\n\r\n사랑하는 조카야, 너에 대한 기억을 잊지 않을 것이며 너의 희생에 경의를 표하는 바이다. 우리의 영광스러운 제국을 건설한 이후에도 너와 같은 영웅이 용맹한 전사의 길을 피로 적셔 왔단다.\r\n\r\n- 스트롬가드의 군주, 토라스 트롤베인'),
(292, 'koKR', '최초의 성기사이며 은빛 성기사단의 설립자\r\n빛의 수호자 우서 여기 잠들다.\r\n\r\n우서 경은 로데론 왕국 수호를 위해 평생을 바치다 숨을 거두었다. 비록 자신이 가장 아끼던 제자에게 배신을 당했으나 우리는 그의 영혼이 여전히 살아 있다고 믿는다. 우리의 황폐해진 땅 가까이에 어둠이 손을 뻗쳐올 때에도 그는 계속 우리를 지켜보고 있으니... 그의 빛은 전 인류의 빛. 그가 보여준 정신을 따르는 한 그 빛은 절대 꺼지지 않을 것이다.\r\n\t\t\t\t\t\t\t\t\t- 무명'),
(293, 'koKR', '지금부터는 트롤과 바다의 흥미롭고 독특한 관계에 대해 알아보고자 한다.\r\n\r\n대해\r\n\r\n구루바시 제국은 삼면이 바다로 둘러싸여 있었기 때문에 그들의 사회에서 물이 중요한 의미가 있었던 것은 너무나 당연한 일이라 할 수 있다. 트롤은 그들의 정글 제국을 누비며 광활한 영토를 지배했지만 바다는 쉽게 그들에게 정복되지 않았다. 바다는 광대하고 무한했으며, 강력한 트롤들조차 쩔쩔매게 하는 이웃이었다.\r\n'),
(294, 'koKR', '최근 밝혀진 사실들로 미루어 볼 때 트롤들은 대해 너머의 땅을 탐험하는 데는 거의 관심이 없었던 것 같다. 트롤 종족은 아제로스, 카즈 모단, 그리고 로데론에 이르는 광활한 지역에서 만날 수 있지만, 새롭게 발견된 칼림도어의 땅이나 남쪽 바다의 섬에서는 그들 문명의 흔적이 거의 발견되지 않았다. 이러한 사실이 트롤이 그들의 대륙 영토에만 머물고 더 멀리까지는 진출하려 하지 않았음을 나타내는 것인지,\r\n'),
(295, 'koKR', '아니면 대양을 항해하기 위해 필요한 기술을 개발하는 데 실패했음을 의미하는 것인지를 밝히기 위해서는 본 글의 범위를 넘어서는, 더욱 심도 있는 조사와 분석이 이루어져야 할 것이다.\r\n\r\n하지만 누구도 그 거대한 문명의 존재를 부정할 수 없거니와, 가시덤불 골짜기의 광활한 트롤 폐허에서 새로 발견된 자료들은 이전에는 알려지지 않았거나 문헌에 기록되지 않았던 트롤과 바다의 관계를 보여 주고 있다.\r\n'),
(296, 'koKR', '해일의 돌\r\n\r\n가시덤불 골짜기의 트롤 폐허에 대한 조사를 통해 최근 새로 발견된 자료들은 \"해일의 돌\"이라 알려진 유물에 대해 언급하고 있다. 트롤 전설의 여러 부분들을 조합해 보면 해일의 돌과 이 돌이 고대 구루바시 제국이 갖는 중요성에 대해 좀 더 전체적으로 파악할 수 있을 것이다.\r\n\r\n해일의 돌은 그것을 지니고 있는 자에게 여러 형태의 물, 강, 비, 조류 등을 제어할 수 있는 능력을 부여했던 것으로 보인다. 해일의 돌의 사용과 관련된 여러 이야기들로 미루어\r\n'),
(297, 'koKR', '나는 그것이 실제로 강력한 바다 정령인 바다제왕의 힘을 물리적으로 형상화한 것이라고 추측해 왔다. 그런 물건이 어떻게, 그리고 왜 바다제왕의 통제에서 벗어나 트롤의 손에 들어갔느냐 하는 것은 나로서는 알 수 없는 또 다른 의문점이다.\r\n\r\n해일의 운반자\r\n\r\n그 이름의 기원이 된 조류가 넘실대듯 해일의 돌은 트롤과 함께하다가 이들을 떠났으며, 한 번에 한 세대 이상 오랜 기간 동안 꾸준히 트롤이 소유했던 적은 없었다.\r\n'),
(298, 'koKR', '트롤 전설에 따르면 해일의 돌은 가시덤불 골짜기 해안을 따라 여행하던 한 트롤 전사에 의해 발견되어 처음으로 구루바시 제국에 들어가게 되었다고 한다. 트롤 전사는 내부에 우유처럼 흰 가닥들이 떠서 흘러 다니는 신비한 푸른 돌을 우연히 발견했다. 돌에 흥미를 느낀 전사는 돌을 가지고 여행을 계속했다.\r\n\r\n몇 주 그리고 몇 달의 시간이 흐르면서 전사는 그 돌이 자신에게 물을 제어할 수 있는 능력을 주었다는 사실을 알게 되었다. 그는 물의 정령과,\r\n'),
(299, 'koKR', '완전히 물로만 이루어진 생명체를 불러낼 수 있었다. 그것은 키린 토의 강력한 마법사들만이 행할 수 있는 마법에 해당하는 것이었다.\r\n\r\n전사는 새로 발견한 능력을 황제에게 보이기 위해 제국의 수도인 줄구룹으로 향했다. 그가 제국 수도의 중심부에서 그 힘을 선보이자 쉽게 왕궁의 주목을 받게 되었다. 그 힘에 크게 놀란 구루바시 황제는 즉시 전사에게 왕궁의 명예로운 지위를 주고 \"해일의 운반자\"라는 이름을 하사하여 옛 이름 대신 사용하도록 했다.\r\n'),
(300, 'koKR', '해일의 운반자는 전투에서 그의 명령에 따르는 물의 정령을 불러내고 가시덤불 골짜기의 물이 제국에 유리한 방향으로 흐르도록 조작하며 여러 해 동안 구루바시 제국을 위해 일했다. 하지만 세월이 흐르면서 해일의 운반자는 점점 더 은둔 생활에 빠져들어 왕궁을 떠나 지내는 시간이 길어졌다.\r\n\r\n해일의 운반자는 왕궁의 감시의 눈길을 피해 한 가지 비밀을 숨기고 있었다. 해일의 돌은 그에게 그러한 능력과 함께 저주를 내렸던 것이다. 몇 해가 지나면서\r\n'),
(301, 'koKR', '해일의 운반자는 서서히 모습을 감췄다. 죽음을 맞이할 때까지 밀물과 썰물이 반복될 때마다 해일의 운반자는 그 존재가 사라졌다가 나타나기를 반복하면서 점점 몸의 형태를 잃고 사라져갔다. 결국 마지막에는 그가 맨 처음 해일의 돌을 발견했던 해변으로 돌아가서는 바다로 걸어 들어가 영원히 사라져 버렸다.\r\n\r\n수세대가 지난 후, 해일의 돌은 가시덤불 골짜기 해변으로 휩쓸려왔고 또 다른 해일의 운반자가 선택되어 그 트롤이 해일의 돌을 다시\r\n'),
(302, 'koKR', '줄구룹으로 가져왔다. 이런 식으로 수세대 동안 해일의 돌은 조류와 함께 모습을 나타냈다가 다시 해일 속으로 해일의 운반자와 함께 사라지기를 반복했다.\r\n\r\n오늘날 곳곳에서 해일의 돌에 대한 이야기들이 전해지지만, 왜 그런 힘을 가진 물건이 그토록 규칙적으로 나타나며, 과연 누가 그렇게 만든 것인가 하는 것은 여전히 수수께끼로 남아 있다.\r\n'),
(303, 'koKR', '붉은해적단의 명령서\r\n\r\n이것이 무법항에서 우리에게 주어진 마지막 기회이므로 동지들은 이 명령서를 주의 깊게 읽도록 하라.\r\n\r\n나는 올 던큰을 북쪽으로 정찰을 보내 신호를 기다리라고 지시했다.\r\n\r\n담셀의 행운호는 보급품을 싣기 위해 남쪽 곶에 닻을 내릴 것이다. 난쟁이 스틸워터 선장은 선원들과 함께 물에 빠진 약탈물을 따라 항해할 준비를 하고 있다. 그 멍청이 브루터스가 모든 것을 손에 넣게 되는 것이다.'),
(305, 'koKR', '붉은해적단의 명령서\r\n\r\n이것이 무법항에서 우리에게 주어진 마지막 기회이므로 동지들은 이 명령서를 주의 깊게 읽도록 하라.\r\n\r\n나는 올 던큰을 북쪽으로 정찰을 보내 신호를 기다리라고 지시했다.\r\n\r\n담셀의 행운호는 보급품을 싣기 위해 남쪽 곶에 닻을 내릴 것이다. 난쟁이 스틸워터 선장은 선원들과 함께 물에 빠진 약탈물을 따라 항해할 준비를 하고 있다. 그 멍청이 브루터스가 모든 것을 손에 넣게 되는 것이다.'),
(306, 'koKR', '킬하울 선장은 립타이드호를 남동쪽으로부터 해안으로 이동시키도록 하라. 신호가 있으면 그의 선원들이 배에서 내려 육지로 들어가도록 할 것이다.\r\n\r\n거대한 몸집의 살트후프는 사람들을 들고 흔들어 해치울 수 있을 정도의 힘을 가졌다. 레빌가즈와 시혼 앞에 지옥을 선사하도록 하라. 그들을 바다 밑바닥에 가라앉혀도 상관없다.\r\n\r\n함장들은 죽음의 폐광에서 밴클리프와 함께 진행하는 작은 계획에 유용할 것이라고 생각되는 것은 무엇이든 책임지고 회수해 오도록 하라.'),
(307, 'koKR', '내가 아이언패치에게 사격 명령을 내리겠다. 포격 지원을 통해 어떤 검은바다 해적단의 선박도 항구를 떠나거나 들어오지 못하도록 하라.\r\n\r\n크림슨 베일호에서 포탄을 모두 빼낸 후 립타이드호와 함께 이동시켜 지원과 필요한 만큼의 예비 병력을 제공받도록 하겠다.\r\n\r\n살트후프와 그의 부하들이 마을을 불태우고 모든 선원들이 갑판에 오르고 나면 출항하여 폭풍 해안에서 무법항에 한 번 더 추가 포격을 가할 것이다.\r\n\r\n- 함장 피랠론'),
(308, 'koKR', '당시에는 잔질을 피해 그 썩어가는 배에서 도망가는 것이 현명하다고 생각했지만 갑자기 그대로 죽는 편이 더 나을지도 모른다는 생각이 들기 시작했다.\r\n\r\n우리 조상들의 가호로 살아남을 수 있었다고 생각했다. 하지만 지금은 평생 갇혀 살아야 한다면 무엇이 현명한 길인지 의문이 든다.\r\n'),
(309, 'koKR', '이 섬을 지배하는 저 괴물은 끔찍하리 만큼 강하다. 다른 모든 생물들은 하늘갈기고릴라와 긴발톱 흑표범 앞에서 무릎을 꿇는다. 지금까지도 놈의 울음소리가 들리는 듯하여 소름이 끼친다.\r\n\r\n놈들은 이 섬에 오는 모든 이를 해칠 것이다. 선조들의 가호를 믿을 수밖에...'),
(310, 'koKR', '우리 일족과 집이 그립다. 이 정글의 열기 대신 넓은 평야에 부는 바람을 느끼고 썬더 블러프 너머로 지는 석양을 바라볼 수만 있다면 더할 나위 없을 것이다.\r\n\r\n멀지 않은 곳에 바다가 있지만 내 몸과 화를 식혀 주지는 못한다. 갇혀 있었던 시절만 환기시킬 뿐이다.'),
(316, 'koKR', '못난 바보들!\r\n\r\n내 계획은 두 다리를 동시에 파괴하는 것이었다. 그런데 어리석은 네놈들은 어떻게 했느냐? 다리는 하나밖에 파괴하지 못했고 동맹 전체에 우리 계획만 알리는 꼴만 되지 않았느냐. 바보 같은 놈들!\r\n\r\n네 놈들의 실수를 만회할 마지막 기회를 주겠다. 예비 폭탄을 아라시 고원의 다리에서 그리 멀지 않은 곳에 숨겨 두었다.\r\n\r\n네 놈들의 임무를 완수하고 살아 있을 가치가 있다는 걸 증명하라!\r\n\r\n- 캄 딥퓨리'),
(336, 'koKR', '슈나이더 일가 귀중,\r\n\r\n안녕하시오. 운하 지역에서의 사업은 잘 되고 있으리라 믿소. 이곳 상업 지구는 급속히 번창하여 지금 편물 옷감 재고가 바닥난 상태라오. 그러니 가능한 한 빨리 통상적인 양의 옷감을 보내 주기 바라오.\r\n\r\n행운을 비오. 그리고 당신네 아들 투르만의 공부도 잘 진척되길 바라오.\r\n\r\n- 할란 바글리'),
(337, 'koKR', '쿨 티라스 함대 공식 명령서\r\n\r\n나 프라우드무어 함장은 칼림도어 해안의 최초 상륙 작전을 직접 지휘하겠다.\r\n\r\n내가 부재 중일 경우에는 부대장 베네딕트가 지휘권을 일임 받는다. 타이라가드 요새에서 12개월 동안 내 소식을 듣지 못할 경우 부대장 베네딕트가 해당 지역을 확보하기 위한 두 번째 작전을 지휘한다.'),
(338, 'koKR', '그 동안 부관 알베롤드를 보내 칼림도어 대륙의 탐험 임무를 수행하도록 하겠다. 그의 부대는 임무를 완수한 다음 타이라가드 요새의 아군과 합류한다.\r\n\r\n부관 알베롤드의 임무는 상당한 시간이 소요될 것으로 예상된다. 새로운 땅은 광활하고 위험할 것이다. 그러나 나와 부대장 베네딕트에게 불운이 닥칠 경우 알베롤드의 부대가 요새를 맡도록 한다.\r\n\r\n저 요새가 우리 수중에 들어올 때까지 우리는 멈추지 않을 것이다.\r\n\r\n- 함장 프라우드무어'),
(339, 'koKR', '그 동안 부관 알베롤드를 보내 칼림도어 대륙의 탐험 임무를 수행하도록 하겠다. 그의 부대는 임무를 완수한 다음 타이라가드 요새의 아군과 합류한다.\r\n\r\n부관 알베롤드의 임무는 상당한 시간이 소요될 것으로 예상된다. 새로운 땅은 광활하고 위험할 것이다. 그러나 나와 부대장 베네딕트에게 불운이 닥칠 경우 알베롤드의 부대가 요새를 맡도록 한다.\r\n\r\n저 요새가 우리 수중에 들어올 때까지 우리는 멈추지 않을 것이다.\r\n\r\n- 함장 프라우드무어'),
(342, 'koKR', '바엘 모단 발굴\r\n\r\n애초에 탐험가 연맹에서 파견한 조사단이 발견했던 내용이 옳았다. 이곳 땅에는 우리 종족에게 무한한 가치를 갖는 유물들이 묻혀 있다. 바엘 모단의 모래와 바위 아래에서 지식을 구한다면 틀림없이 많은 해답을 얻게 될 것이다.\r\n\r\n하지만 이 지역의 지질학적 특성 때문에 극단적인 수단을 사용해야 한다. 혹독한 조건과 변화하는 기후로 인해 많은 모래 더미가 단단하게 굳어 버린 것이다.'),
(343, 'koKR', '그러나 해결 방법은 매우 간단하다. 나무 펄프를 흡수제로 사용하면 미량의 니트로글리세린을 질산나트륨과 섞어 강력한 폭발물을 만들 수 있는데, 이렇게 하면 아무리 밀도 높은 덩어리라도 뚫을 수 있다.\r\n\r\n시끄럽고 파괴적인 작업이 되겠지만 인근 주민들의 안락함보다는 우리의 조사가 훨씬 더 중요하다. 사실, 벌써 이 주변에서 알짱대며 성가시게 굴던 황소 인간 무리를 몰아낼 수밖에 없었다.'),
(344, 'koKR', '이곳에는 다양한 악당들이 돌아다니고 있어 이에 대처하려면 왕국 군대의 지원이 필요할 것 같다. 발굴 작업에만 군사 지원이 필요한 것이 아니라 이곳에 온 지 얼마 안 된 내가 보기에 현재 폭발 직전인 세계 정치 상황을 감안할 때 바엘 모단은 위치상 얼라이언스에 전략적 가치가 있을 것으로 보인다.\r\n\r\n이런, 주제에서 벗어난 이야기를 하고 말았다. 바위 밑에서 해야 할 일이 잔뜩 있는데도 글 쓰는 데 너무 많은 시간을 보내느라 발굴을 충분히 하지 못했다...'),
(349, 'koKR', '이곳에는 다양한 악당들이 돌아다니고 있어 이에 대처하려면 왕국 군대의 지원이 필요할 것 같다. 발굴 작업에만 군사 지원이 필요한 것이 아니라 이곳에 온 지 얼마 안 된 내가 보기에 현재 폭발 직전인 세계 정치 상황을 감안할 때 바엘 모단은 위치상 얼라이언스에 전략적 가치가 있을 것으로 보인다.\r\n\r\n이런, 주제에서 벗어난 이야기를 하고 말았다. 바위 밑에서 해야 할 일이 잔뜩 있는데도 글 쓰는 데 너무 많은 시간을 보내느라 발굴을 충분히 하지 못했다...'),
(350, 'koKR', '사모플랜지 제어장치는 연료, 가스 및 액체의 흐름과 관련 기계를 자동으로 제어합니다. 초기 설정을 완료한 다음에는 특별한 유지관리 없이도 문제 없이 작동합니다.\r\n\r\n제어장치 구성요소의 개요(왼쪽에서 오른쪽으로)\r\n\r\nI. 주동력 레버가 사용 위치에 있으면 사모플랜지가 활성화됩니다. 레버를 꺼짐 위치에 두어도 제어 과정이 자동으로 해제되지 않습니다.'),
(352, 'koKR', '감독관 피즈스프로켓 귀하. 사장 라즈덩크의 승인 하에 귀하가 요청한 설비 목록을 동봉합니다.\r\n\r\n사장님께서는 칼림도어 전역으로 사업을 확장하는 일에 투자개발회사가 큰 관심을 보인다는 점을 귀하께 반드시 상기시켜 드리라고 하셨습니다. 불모의 땅에 있는 우리 굴착 현장 역시 수익이 높고 효율적이라는 사실이 입증되긴 했지만 여전히 귀하의 관할인 멀고어에서 충분한 물건들을 제공받길 기다리고 있습니다.'),
(353, 'koKR', '자문 위원회는 타우렌 본거지와 그렇게 가까운 곳에서 대규모 설비를 운영하는 데 수반되는 어려움은 이해하고 있지만, 자신들이 지역 내에서 우리의 전체적인 사업 계획에 큰 장애가 되고 있다는 사실은 자각하지 못하고 있습니다.\r\n\r\n광물이 풍부한 멀고어의 평원에서 채굴 작업이 시작되었다는 소식을 듣게 되어 기쁩니다. 그 덕분에 위원회가 귀하의 설비 요청을 승인해 준 것입니다.'),
(355, 'koKR', '이는 냉각 프로세스를 시작할 뿐이며 장치를 끄는 데는 상황에 따라 약 1~2분이 걸립니다.\r\n\r\n주의: 주동력 레버는 실제 기계에 있는 제어 밸브 3개를 해제한 경우에만 조작이 가능합니다. 이 밸브들은 순서에 관계 없이 잠글 수 있습니다.\r\n\r\n첫 번째는 대형 수직 연통의 하부에 있는 주 제어 밸브입니다. 다음은 연료 제어 밸브로, 연료 탱크(3개가 있음)에서 연통으로 이어져 있는'),
(356, 'koKR', '대형 파이프에 설치되어 있습니다. 마지막은 연통으로 이어지는 2개의 대형 원통형 탱크 하부에 설치된 압력 조절 밸브입니다.\r\n\r\nII. 연료 계기\r\n\r\n첫 번째, 두 번째 및 세 번째 연료 탱크 내부의 현재 압력을 표시합니다.\r\n\r\nIll. 유속 계기\r\n\r\n시스템 내부의 현재 유속을 표시합니다.'),
(357, 'koKR', 'IV. 유속 제어장치\r\n\r\n유속을 높이거나 낮춥니다. 사모플랜지 컨트롤 메커니즘에 의해 자동으로 제어됩니다.\r\n\r\nV. 온도 계기\r\n\r\n일반적인 시스템 작동 온도를 표시합니다.'),
(359, 'koKR', '땅이 흔들리며 마법에 걸린 숲의 오래된 나무들이 송두리째 뽑히고 쓰러져 갔다. 세나리우스의 후예들이 돌보던 숲과, 별들의 후예들의 돌탑이 흔들리는 땅 위로 쓰러졌다. 전투의 혼란 속에서도, 절망적인 상황 속에서도 밝게 빛나는 우리의 여왕님이 계셨다. 마법이 풀리면서 마법에 걸렸던 하늘의 색이 바뀌었고, 폭발로 인해 온 세상이 갈가리 찢어질 것만 같았다.\r\n\r\n형제가... 형제와 싸웠다. 선택받은 자가 축복받은 자와 싸웠다.'),
(361, 'koKR', '존경하는 스승이신 델그렌님,\r\n걱정하시던 대로였습니다. 알살락스의 탑에 대한 스승님의 이론이 사실로 증명되었습니다. 한 이교도 집단이 탑에 모여 있었는데, 그 중에는 많은 마법사들이 포함되어 있고 심지어 사악한 사티로스까지 있었습니다. 그들은 스스로를 암흑이교도라 칭하고 있습니다. 그들이 어떤 사악한 목적을 위해 모였는지는 알 수 없지만 우려가 됩니다.\r\n편지를 이렇게 짧게 줄이는 것을 부디 용서해 주십시오. 하지만 지금 제 주위의 숲에는 위험이 도사리고 있으며 상황 설명을 위해 길게 말씀 드릴 수가 없습니다.'),
(364, 'koKR', '호숫가에는 이미 많은 마을과 집이 지어져 있었지만 태고적부터 칼도레이의 사랑받는 여왕인 아즈샤라의 축복을 받은 아메스아란과 바샬아란이 가장 훌륭했다. 여왕은 총애하는 신하인 귀족들을 이 쌍둥이 마을에서 살게 하였고, 그 마을들을 통치하기 위해 여왕이 애스리쿠스 나라신을 보내었다. 하지만 그는 하루의 대부분을 마을에서 꽤 떨어진 알살락스의 탑에서 보냈다.'),
(365, 'koKR', '그의 보좌관이자, 육체적인 능력만큼 뛰어난 마법 솜씨를 발휘하던 아스테리온은 바샬아란의 주민들과 함께 살며 아메스아란으로 여러 번 건너가 그곳의 주민들에게 필요한 것을 살폈다.\r\n\r\n그리하여 별 아래의 세계가 천천히 광란에 접어드는 동안 이 쌍둥이 마을은 영원의 샘 연안에서 날로 번창해 갔다.'),
(366, 'koKR', '싸운 자들 모두가 귀족은 아니었다. 일부는 이 광란이 자신들을 집어삼킬 때까지 그냥 서 있기만 했다. 강대한 도시나 초라한 마을 할 것 없이 모두 쓰러져 갔다.\r\n\r\n아메스아란에서는 모든 것이 폐허로 변해 버렸고, 주민들은 마치 그것만 붙잡으면 이 모든 파괴 속에서 살아남을 수 있기라도 한 것처럼 땅을 붙들고 놓지 않았다. 바로 그때 아즈샤라의 총애를 받는 애스리쿠스 나라신이 나타나 그들을 안전한 곳으로 인도했다.\r\n\r\n그는 단 하나의 마법 주문으로도 그들을 보호할 수 있다고 말했지만 주변에서는 형제, 자매, 아버지와 어머니가 쓰러져 갔다.'),
(372, 'koKR', '실예의 별\r\n\r\n욕심쟁이 그렐볼그가 실예의 별을 가지고 있습니다. 그는 알터랙 산의 알터랙 폐허에서 싸구려 물건을 찾아 헤매고 있는 탐욕스러운 오우거입니다. 그의 수집품 대부분은 쓸모없는 것이지만 실예의 별 하나만은 가치가 대단합니다.'),
(373, 'koKR', '다군의 손\r\n\r\n고대 문서에 의하면 다군의 발톱은 먹잇감을 죽이는 데 사용하는 것이 아니라 고대 종족 중 하나로 변형시키는 독을 분비한다고 합니다. 그 가치가 굉장하다는 사실은 의심의 여지가 없습니다.\r\n\r\n다군은 깊은 바다에 살지만 주기적으로 먼지진흙 습지대의 진흙아가미멀록 일족이 수면으로 유인해냅니다. 이들 멀록 점쟁이들은 마법의 해조를 사용하여 다군을 불러냅니다. 점쟁이들을 처치하다 보면 그 해조를 손에 넣을 수 있을 것입니다. 그 해조를 멀록 제단에 놓으면 다군이 나타날 것입니다.'),
(374, 'koKR', '고대의 심장\r\n\r\n불사신 모그는 가시덤불 골짜기에 살고 있는 트롤 의술사입니다. 그리고 그는 갖고 있는 고대의 심장의 비밀을 풀면 죽음을 피하는 능력을 얻을 수 있다고 합니다. 줄맘웨의 폐허에서 모그를 찾을 수 있으니 그를 물리치고 고대의 심장을 가져오십시오.'),
(375, 'koKR', '내게 실예의 별, 다군의 손, 그리고 고대의 심장, 이 세 가지를 가져오십시오. 그러면 야그인의 법전을 주겠습니다.\r\n\r\n- 게릭 본그립'),
(376, 'koKR', '실예의 별.\r\n\r\n알터랙의 오우거, 욕심쟁이 그렐볼그가 이 보석을 마지막으로 가지고 있었다고 하오. 그는 이 보석을 소유한 자에게는 다른 세계와 교신할 수 있는 능력이 주어진다는 것에 현혹되어 있소. 정보에 따르면 그렐볼그는 더 많은 유물을 찾기 위해 알터랙 산의 알터랙 폐허에서 잡석과 파편들을 뒤지고 다니고 있다고 하오.'),
(377, 'koKR', '다군의 손.\r\n\r\n다군은 먼지진흙 습지대의 멀록들이 숭배하는, 깊은 물속에 사는 생물이오. 멀록은 주술사의 마법이 걸린 특수한 해조를 사용하여 다군을 수면으로 유인하시오. 멀록을 처치하고 그들의 마법 해조를 모아 멀록 제단에 가져다 놓도록 하시오. 기다리고 있으면 다군이 나타날 것이오.\r\n\r\n그 손을 내게 가져오면 되오.'),
(378, 'koKR', '고대의 심장.\r\n\r\n고대 문서에 따르면 고대의 심장을 소유한 자는 죽음의 공포에서 벗어날 수 있다고 하오. 고대의 심장을 가지고 있는 트롤 모그가 `불사신 모그`라고 알려진 것을 보면 이 말이 사실일지도 모르오. 백골가루부족 의술사인 모그는 가시덤불 골짜기의 줄맘웨의 폐허에 살고 있소.'),
(379, 'koKR', '내게 실예의 별, 다군의 손, 그리고 고대의 심장, 이 세 가지를 가져오시오. 그러면 야그인의 법전을 주겠소.\r\n\r\n- 관리인 벨두거'),
(387, 'koKR', '그는 팔을 찾아 헤맸지만 잃어버린 팔을 찾을 수는 없었다. 그는 그렇게 저주를 퍼붓고 울부짖으며 돌아다녔다.\r\n\r\n하지만 그리렉은 오래전부터 정령들에게 귀를 기울이지 않았고 화가 난 정령들은 그의 저주를 아랑곳하지 않았다.\r\n\r\n비참한 운명의 그리렉. 그는 팔 없이 헤매야 할 운명을 맞은 것이었다.'),
(393, 'koKR', '그는 팔을 찾아 헤맸지만 잃어버린 팔을 찾을 수는 없었다. 그는 그렇게 저주를 퍼붓고 울부짖으며 돌아다녔다.\r\n\r\n하지만 그리렉은 오래전부터 정령들에게 귀를 기울이지 않았고 화가 난 정령들은 그의 저주를 아랑곳하지 않았다.\r\n\r\n비참한 운명의 그리렉. 그는 팔 없이 헤매야 할 운명을 맞은 것이었다.'),
(403, 'koKR', '잿빛 골짜기를 위한 내 임무 수행을 기록하기 위해 이 일지를 쓰기 시작했다. 최근 발생한 사건들 중 일부에 대해 의혹이 제기되고 있다. 내가 이 사건들을 해결하여 다른 이들을 도울 수 있기를 바란다.\r\n\r\n후에 잊지 않도록 있었던 사실들을 기록하도록 하겠다.\r\n\r\n최근 나는 마법사 다르톨의 계획에 대한 소문의 진상을 알아냈다.'),
(404, 'koKR', '인간이 우리 땅에 와서 우리의 지식을 배운다는 것은 있을 수도 없는 일이라 생각했건만, 이 사악한 인간 마법사는 이곳에 와서 살아남았을 뿐 아니라 우리의 지식도 어느 정도 습득했다. 어떻게 그럴 수 있었는지 아직도 이해가 되지 않는다. 내가 실시하고 있는 조사를 통해 그의 목표가 무엇인지는 밝히지 못했지만 그의 계획은 간단해 보였다. 드루이드의 마법을 사용하여 펄볼그를 자기 편으로 끌어들여 조종하려는 것이었다. 만약 우리 종족을 해치려고 하는 것이거나 다른 악의적인 의도가 있는 것이라면 나의 조사가 끝나기 전에 알아내게 되기를 바란다.'),
(405, 'koKR', '어쨌든, 그는 외견상 자신의 계획을 실행에 옮기는 데 어느 정도 성공한 것 같았다. 그의 음모를 우리 주민에게 실행하기 전에 먼저 펄볼그에게 시험해 보려 한 것일까? 아니면 펄볼그들이 그가 탐내는 무언가를 지니고 있는 건가? 알 수가 없다. 그는 그가 만든 물건, 일종의 마법봉 또는 마법 지팡이를 이용해서 잿빛 골짜기의 펄볼그 종족에게 숨어 들어가려고 했었다. 어느 시점에서 그는 펄볼그들이 서로 적대시하도록 조종하려 하다가 그들에게 발각되고 말았다. 이 당시에 대해서는 지금도 다수의 상세한 내용이 명확히 알려져 있지 않다.'),
(406, 'koKR', '아마 엘프들이라도 그랬겠지만, 펄볼그들은 분노했고 훨씬 더 거센 반응을 보이며 결국 다르톨을 처치했다.\r\n\r\n적어도 이 당시의 펄볼그는 그 이후처럼 타락한 짐승이 아니었다. 그들은 아직 이성적이며 지적이었다. 그리고 우리 종족과의 관계도 우호적이었다.\r\n\r\n내가 셸드린이라는 드리아드의 도움을 받아 그 마법봉을 다시 만들 수만 있다면 그 힘을 이용해 우리 종족과... 펄볼그들까지도 구할 수 있을 텐데...'),
(407, 'koKR', '모든 펄볼그들이 타락한 것은 아니었다. 일부는 아직 살아 남아 숲을 보호하려 하고 있다. 그들이 타락할 당시, 일부 펄볼그는 달아났고, 많은 수가 희생당했으며, 나머지는 그들 일족으로부터 쫓겨났다.\r\n\r\n나는 미스트랄 호수 위쪽에 살고 있는 크롤그라는 훌륭한 썩은나무일족 펄볼그를 만나게 되었다.\r\n\r\n며칠 동안 그를 지켜본 결과, 내가 펄볼그로 위장해 그에게 접근한다면 그를 도와 두 종족간의 우호적인 관계를 회복할 수 있을 것이라는 생각이 들었다.'),
(408, 'koKR', '다르톨을 처치하면서, 펄볼그는 다시는 마법봉이 자신들에게 사용되지 못하도록 이를 세 조각으로 나눠 버렸다. 어려운 일이긴 했지만, 나는 그 세 조각이 모두 어디에 있는지 알아냈다.\r\n\r\n보석\r\n마법봉의 첫 번째 조각인 빛나는 보석은 잿빛 골짜기 북서쪽의 제단에 숨겨져 있었다. 현재 팔라딤 호수 중앙에 있는 폐허가 바로 이 제단이라 생각된다. 센티널에서는 지금 그곳에 멀록들이 살고 있다고 내게 일러 주었다.'),
(409, 'koKR', '내가 제단에 숨겨진 보석을 찾을 수 없다면 분명 멀록의 손에 들어간 것이다.\r\n\r\n자루 부분\r\n이 마법봉 조각은 현재 악령의 숲이라 불리는 곳 가까이에 있는 나무정령들의 손에 들어갔다. 펄볼그나 우리 종족은 이 위대한 종족이 이 땅을 덮친 타락의 나락에 떨어졌으리라고는 상상도 하지 못했다. 조사를 통해 이 수호정령들이 이 마법봉 조각을 상자 안에 넣고 잠궈 작은 습지에 보관하고 있다는 사실을 밝혀냈다. 더 자세한 내용을 알아내기 위해서는 셸드린과 얘기해 봐야 할 것이다.'),
(411, 'koKR', '셸드린은 아이리스 호수 북동쪽의 달샘을 보호하는 드리아드이다. 그녀는 숲을 떠나거나 숲이 오염되도록 내버려 두려고 하지 않는다. 나는 그녀가 마법봉을 고칠 수 있는 힘과 지식을 지니고 있거나, 적어도 내가 직접 고칠 수 있는 방법을 알려 줄 수 있다는 것을 알고 있다.\r\n\r\n자루 끝\r\n마법봉의 자루 끝 부분은 도르다닐의 드루이드들의 손에 들어갔다. 하지만 여기에는 한 가지 큰 문제가 있다. 그 드루이드들이 이미 죽었다는 것이다. 그들의 영혼은 지금도 그 지역에 남아 있지만 더 이상 우호적이지는 않다.'),
(412, 'koKR', '여기에 대해서는 조사가 더 필요할 것 같다. 내게 도르다닐의 깊은 곳까지 철저히 조사하여 자루 끝을 찾아내는 것은 고사하고... 죽은 일족의 영혼과 싸울 힘이라도 있을지 자신이 없다.\r\n\r\n참고: 아스트라나르에서 채비를 하는 동안, 최근에 잿빛 골짜기에서 오랫동안 우리 종족을 도와 온 드워프 종족 사냥꾼을 만났다. 그는 스톰윈드라는 곳에서 온 자이다.\r\n\r\n어느 날 밤, 우리는 에일 맥주를 몇 잔 하며 이야기를 나눴는데, 그의 이야기는 내게 자루 끝 부분을 찾을 수 있으리라는 새로운 희망을 안겨 주었다.'),
(413, 'koKR', '그는 도르다닐 전역을 여행했지만 자루 끝 부분이 보관되어 있을 만한 상자나 다른 용기는 보지 못했다고 했다.\r\n\r\n그리고 그 지역엔 썩어가는 진흙괴물이 사는 곳으로 그들은 자신들보다 작은 건 뭐든 먹어 치운다고 했다. 그는 그들이 탁자, 조각품, 곰, 심지어는 노움까지 \"먹어 치우는\" 걸 봤다고 한다!\r\n\r\n진흙괴물들은 마법의 힘이 있는 사물에서 많은 양의 양분을 얻는 것 같다. 만약 자루 끝 부분이 보관된 상자에 마법이 걸려 있다면 진흙괴물들이 먹어 버렸을지도 모른다.'),
(414, 'koKR', '도박이긴 하지만 지금으로서는 다른 단서가 없으니...\r\n\r\n무언가 더 찾아내게 되면 여기에 상세히 적을 것이다. 하지만 그때까지 마법봉 조각들을 찾아 잿빛 골짜기를 돕는 데 전력을 다해야 한다.'),
(415, 'koKR', '진질에게\r\n이미 오랜 시간이 흘렀지만 붉은깃털일족의 마지막 생존자가 죽었다는 사실을 알고 싶어할 것 같군. 이 편지를 자네에게 전하는 사람이 한 일이니 내게 감사할 필요는 없네. 자네가 원한다면 불모의 땅에서 짐마차의 순회가 끝나는 대로 그녀의 머리를 자네에게 보내 주겠네. 자네의 부두 마법을 사용하기 위해서는 그게 필요하다는 사실을 알고 있으니 말이야.\r\n잘 지내게, 내 오랜 벗이여\r\n\r\n-달소크 스위프트대거'),
(436, 'koKR', '주문 번호: 45TK-3\r\n구매자: 크레이블 콜비어드\r\n\r\n구매서:\r\n\r\n수력래칫 (3)\r\n연발볼트 (50)\r\n30\" 20눈금 구리관 (12)\r\n딥퓨리제 코담배 (1)\r\n최상급 삼각결정(3)'),
(437, 'koKR', '이 전갈을 제가 직접 전해드리고 싶지만 중요한 사건을 놓치게 될 것 같아 이곳을 떠날 수가 없습니다.\r\n\r\n알살락스의 탑에 대한 제 조사 내용을 더 자세히 알고 싶어하실지 몰라, 이 편지를 전하는 이가 제게 큰 도움을 주었으며 믿을 만한 자임을 말씀 드립니다.\r\n\r\n긴급히,\r\n발툴 섀도스트라이크'),
(441, 'koKR', '친애하는 마르텍,\r\n\r\n나는 지금 곤경에 빠져 자네 도움이 필요하다네. 우리 형제가 경주용 자동차를 제작하고 있는데 튼튼한 피스톤이 필요하네. 여러 가지를 시도해 봤지만 그 어느 것도 강도가 충분치 못하더군. 우리가 만든 새 자동차의 속도를 견뎌 낼 수 있는 게 하나도 없어. 그래서 계속 엔진 고장을 일으키고 있네!\r\n\r\n자네가 금속 가공에는 전문가이니 꼭 도와주기 바라네. 자네만이 할 수 있는 일일세.'),
(442, 'koKR', '서리갈기 설인을 상대하려면 먼저 녀석이 가장 좋아하는 먹이의 고기로 유인해야 하오.\r\n아제로스에 있는 알터랙 산맥으로 가서 덩치큰 산사자를 한 마리 잡아 죽인 후, 그 시체를 서리갈기 설인이 성스럽게 여기는 우젤 동굴로 가져가시오.\r\n우젤의 불꽃에 그 시체를 올려 놓으면 동굴에서 불에 타는 고기 냄새가 흘러나가게 될 거요.\r\n그러면 서리갈기 설인이 나타날 것이오.'),
(443, 'koKR', '사람들을 자신의 의지 앞에 굴복시키는 데는 증오만큼 쉬운 수단이 없다는 사실에 항상 놀라곤 한다. 그 중에서도 오크와 트롤이 가장 쉬운 대상이다. 얼라이언스에 대한 증오로 그들은 암흑이교도의 말에 기꺼이 귀 기울이는 충성스러운 백성이 되었다. 자신들이 섬기는 더 큰 힘에 대해 조금이라도 알고 있을까? 격분한 성기사 수호자 델그렌이 잿빛 골짜기 숲에서의 우리 일을 캐고 다니고 있고, 그의 부하 발툴은 내가 그의 존재를 모른다고 생각하며 우리 탑을 염탐하고 있다. 델그렌은 우리를 대수롭지 않게 생각하고 있다.'),
(444, 'koKR', '아마 또 다른 죽음의 이교도 집단쯤으로 여기고 있을 것이다. 그는 우리가... 어둠의 의회의 이교도 중 하나에 불과하다는 사실을 거의 모르고 있다.\r\n\r\n내가 어린 아이였을 때, 겨우 알아볼 정도의 작은 점 크기의 파리처럼 보이지만 물리면 바로 죽을 수도 있는 곤충에 대한 이야기를 들은 적이 있다. 하지만 그 곤충은 물리면 살이 썩어 들어가며 매우 치명적인 해를 입힐 수 있으므로 박멸해야 한다.'),
(447, 'koKR', '나는 그동안 위상과 그들의 창조자 티탄에 대해 많은 조사를 해 왔다. 한 인간이 전 생애에 걸쳐 할 수 있는 최대한의 노력을 한 것이라고 생각한다. 티탄들은 이 세상을 떠나면서 이 세상에 5개의 위상을 남겼는데, 이들은 아제로스 세계를 수호하는 임무를 맡은 강력한 용이었다. 그 꼬리는 거대하고 다양한 모양을 하고 있으며, 충분히 많은 정보를 수집하고 난 지금도 이 엄청난 생물에 대해 알아내야 할 것이 훨씬 더 많다고 느끼고 있다.'),
(448, 'koKR', '연금술사 라이던,\r\n\r\n이 편지가 빨리 당신에게 전해지기를, 또한 이 편지를 전하는 이가 무사하기를 바라오. 멀리 칼림도어에서 당신의 능력을 필요로 하게 될 것 같은 일이 발생했소. 간단히 설명하도록 하겠소이다.\r\n우리의 동맹 타우렌의 고향인 멀고어에서 멀지 않은 돌발톱 산맥에 위기가 닥쳤소. 고블린이 운영하는 투자개발회사가 이 산맥에서 마구잡이로 채굴과 벌목을 강행해 산의 정령들이 격노하고 있소이다.'),
(449, 'koKR', '이 정령들이 타우렌 주술사와 드루이드의 비호 아래서 여러 방법으로 일으킨 소란이 놈들을 혼란케 하는 것 같소. 타우렌들은 돌발톱 산맥의 투자개발회사를 심각한 위협으로 간주하고 있소. 그들이 위협 요소이든 그렇지 않든, 우린 우리의 동맹을 도와야 하오.\r\n라이던, 당신은 독약에 대해 너무나 잘 알고 있지 않소? 돌발톱 산맥의 고블린들을 전염시킬 수 있는 독약을 만들어 줄 수 있겠지?\r\n\r\n당신의 학식을 존경하는 P. 자마'),
(450, 'koKR', '지금 내가 가진 지식 중 상당량은 나 혼자의 힘으로는 결코 알아낼 수 없었을 것이며, 이 점에 대해 나이트 엘프들에게 크게 감사한다. 그들의 도움이 있었기에 이토록 자세한 정보를 확보할 수 있었던 것이다. 그들과 교류하면서 그들의 시초가 내가 처음 생각했던 것보다 훨씬 더 깊이 위상과 관련되어 있는 것 같다는 느낌이 들었다. 하지만 그들은 나조차도 확실히 알 수 없도록 비밀을 철저히 숨기고 있다.'),
(452, 'koKR', '알렉스트라자:\r\n알렉스트라자는 고룡의 강력한 여왕으로 티탄들은 그녀를 생명의 어머니라고 불렀다. 티탄들이 떠나면서 이 세상을 지키게 할 목적으로 만든 첫 번째 피조물이 바로 그녀였다. 알렉스트라자는 아제로스 대륙에서 모든 종족의 탄생을 목격했다고 전해진다. 훌륭한 품행으로 널리 알려진 그녀의 붉은용 군단은 한때 다른 모든 용족을 지배했다.'),
(453, 'koKR', '나이트 엘프들 사이에 떠도는 소문에 의하면 알렉스트라자와 반신 세나리우스는 절친한 친구였다고 하며, 불타는 군단이 처음으로 침략했을 때 그녀를 부른 것도 세나리우스였다고 한다.'),
(454, 'koKR', '이세라:\r\n꿈의 여왕 이세라는 모든 종족들의 잠재 의식을 관장하며 에메랄드의 꿈을 수호한다. 그녀는 종족들의 상상력과 창조의 진정한 가치를 이해하고 그들의 야심을 인정하지만, 그녀와 그녀의 용군단은 현실이 한낱 환상일 뿐이라고 여긴다. 이세라는 모든 종족들이 가장 고귀하고 강하다고 여기는 존재 중 하나이다.'),
(455, 'koKR', '말리고스:\r\n말리고스는 마법의 청지기 또는 마법의 지배자라고 알려져 있다. 그의 타고난 외모는 여느 용과는 다르며 자신의 의지에 따라 모습을 바꿀 수 있다고 전해진다. 북쪽으로 멀리 달아난 후 거의 모습을 드러내지 않으며, 보통 때는 곤충과 같은 모습을 하고 있지만, 용의 모습을 드러냈을 때 그와 그의 용군단은 여러 가지 푸른 빛을 띤다.'),
(456, 'koKR', '노즈도르무:\r\n노즈도르무는 시간의 지배자 또는 시간을 초월한 자로 알려져 있다. 그와 그의 용군단은 청동색을 띠고 있으며 다방면에서 뛰어난 솜씨를 보여 준다. 노즈도르무의 관심은 언제나 과거의 유물을 수집하는 데 집중돼 있으며 종족간 분쟁이나 동료 위상들의 현안들에는 별로 관심이 없다. 하지만 정치에 무관심하다고 해서 세상 일에 전혀 관심을 두지 않는 것은 아니다.'),
(458, 'koKR', '넬타리온:\r\n창조되었을 당시 대지의 수호자로 불렸던 넬타리온은 다른 어떤 위상보다도 강한 충성심으로 아제로스를 수호하려 애썼다. 그의 검은용군단은 산맥들과, 대륙 안에서 종족들간 경계지역을 비롯한 기타 지형의 형성을 담당했다. 그가 타락하게 된 원인은 아직 밝혀지지 않고 있다. 외부에서 영향을 받았는지 아니면 내적으로 부패한 것인지 알 수 없다. 고대 신들이 이 거대한 검은용의 타락과 관련이 있는 것은 아닐지 의문스럽다.'),
(459, 'koKR', '검은용 넬타리온은 완전한 변형을 거쳤고 결국 이전과는 전혀 다른 존재가 되었다. 그는 악의와 증오의 창조자 데스윙이 되었다. 하이 엘프와 같은 종족에게 더 이상 대지의 수호자는 없게 되었다. 그는 타이탄이 붙여 주었던 이름 대신 죽음의 위상, 그리고 삭사스라는 새로운 이름으로 불렸다. 데스윙은 혼돈과 악의 화신이며, 항상 파괴에 굶주려 있다. 아마도 그는 고대 신들의 추방 이후 아제로스에 나타난 첫 번째 악일 것이다.'),
(467, 'koKR', '축하 드립니다!\r\n\r\n이제 당신은 땅다람쥐의 자랑스러운 새 주인이 되셨습니다! 땅다람쥐는 다소 낯을 가리기는 하지만 보송보송한 털과 귀여운 용모에다 후각 기관이 매우 발달해 있어 분명히 마음에 드실 것입니다.\r\n\r\n다음 페이지에는 땅다람쥐에 대한 정보가 수록되어 있습니다.\r\n1. 먹이 및 관리법\r\n2. 엉뚱하면서도 귀여운 행동\r\n3. 특허를 받은 땅다람쥐 지휘봉의 사용법\r\n\r\n땅다람쥐의 주인이 되신 것을 다시 한번 축하 드리며, 결코 후회 없는 선택이 되리라고 확신합니다.\r\n-땅다람쥐 회사 사장, 마르위그 러스트볼트'),
(528, 'koKR', '요르겐,\r\n내가 두려워하던 일이 현실로 드러났네. 그것도 내가 전혀 생각지도 못했던 방식으로 말일세. 놈들이 이렇게 가까이 다가올 줄은 생각도 못했었네.\r\n이 편지를 전하는 이를 도와주도록 하고 그를 `그`에게 보내게. 솔직히 말해, 내 생각에는 이번 일이 워낙 심각한 만큼 그가 우릴 도와줄 것 같네. 만약 다른 위협이었다면 그가 우리와 우리 도시의 문제를 계속 무시해 버리겠지만 말이야. 고맙네, 이 어부 친구야. 언제나 자네에게 신세만 지는구먼.\r\n자네의 친구, 드라베이'),
(547, 'koKR', '요르겐,\r\n내가 두려워하던 일이 현실로 드러났네. 그것도 내가 전혀 생각지도 못했던 방식으로 말일세. 놈들이 이렇게 가까이 다가올 줄은 생각도 못했었네.\r\n이 편지를 전하는 이를 도와주도록 하고 그를 `그`에게 보내게. 솔직히 말해, 내 생각에는 이번 일이 워낙 심각한 만큼 그가 우릴 도와줄 것 같네. 만약 다른 위협이었다면 그가 우리와 우리 도시의 문제를 계속 무시해 버리겠지만 말이야. 고맙네, 이 어부 친구야. 언제나 자네에게 신세만 지는구먼.\r\n자네의 친구, 드라베이'),
(575, 'koKR', '아무도 우주의 기원에 대해 정확히 알지 못한다. 어떤 이들은 엄청난 대폭발이 거대한 암흑 속으로 무한한 공간들을 방출시켜서 현재와 같이 되었고, 그 안에 형성된 세계들이 놀랍게도 다양한 생명을 잉태하게 되었다는 가설을 내세운다. 또 다른 이들은 무한한 힘을 가지고 있는 전능한 존재에 의해 지금의 우주가 창조되었다고 믿는다.\r\n'),
(576, 'koKR', '비록 이 무질서한 우주의 정확한 기원은 불명확하지만, 어떤 강력한 종족이 혼돈 상태였던 세계를 체계화하고 후손들이 안전하게 그들의 발자취를 따를 수 있도록 미래를 확보해 놓았다는 것은 확실하다.\r\n\r\n우주 먼 곳으로부터 온, 금속의 피부를 가진 거대한 신, 티탄들이 나타나 세계에 힘을 불어 넣었다. 그들은 거대한 산맥을 일으키고 광활한 바다를 만들어 세계의 형태를 다듬었다.\r\n'),
(577, 'koKR', '티탄들은 숨을 불어넣어 하늘을 만들고 대기를 채웠다. 먼 미래를 내다본 그들의 헤아릴 수 없는 계획에 따라 혼돈에서 질서가 창조되었다. 그들은 원시 종족들에게 힘을 부여하여 자신들의 일을 돕고 각각의 세계를 완전한 상태로 유지하도록 했다.\r\n\r\n티탄들의 세계의 정권은 최상위 집단 판테온이 잡고 있었으며, 첫 번째 창조 시대 동안 끝없는 어둠 너머 곳곳에 흩어져 있는 수억 개의 세계에 질서를 확립시켰다.\r\n'),
(578, 'koKR', '자비로운 판테온은 뒤틀린 황천이라는 다른 차원에서 온 사악한 존재들의 공격으로부터 그들이 창조한 세계를 안전하게 지키기 위해 경계를 늦추지 않았다. 혼란스러운 마법으로 가득한 천상계인 황천은 우주의 무수한 세계와 연결되어 있으며, 생명을 파괴하고 우주의 생명 에너지를 삼켜 버리는 데만 혈안이 되어 있는 악의 무리들에게 고향과 같은 곳이다.\r\n'),
(607, 'koKR', '존경하는 롱비어드씨\r\n\r\n아시는 바와 같이, 우리 스톰파이크 일가는 명품을 볼 줄 아는 눈이 있습니다. 그래서 당신이 만드는 방패가 얼마나 품질이 좋은지도 잘 알고 있습니다.\r\n그래서 그런 방패를 좀 주문했으면 합니다. 주문 내역은 다음 페이지에 나와 있습니다.'),
(626, 'koKR', '존경하는 롱비어드씨\r\n\r\n아시는 바와 같이, 우리 스톰파이크 일가는 명품을 볼 줄 아는 눈이 있습니다. 그래서 당신이 만드는 방패가 얼마나 품질이 좋은지도 잘 알고 있습니다.\r\n그래서 그런 방패를 좀 주문했으면 합니다. 주문 내역은 다음 페이지에 나와 있습니다.'),
(627, 'koKR', '오크 호드와 끔찍한 2차 대전쟁으로 인해 로데론의 얼라이언스는 충격과 혼란에 빠지게 되었다. 강력한 대족장 오그림 둠해머가 이끄는 피에 굶주린 오크족은 드워프들이 점령하고 있는 카즈 모단으로 공격하여 쳐 부셨을 뿐 아니라 로데론의 중심 지역도 다수 손에 넣었다.\r\n냉혹한 오크들은 심지어 머나먼 엘프의 왕국 쿠엘탈라스까지 진격한 후에야 그 난폭한 공격을 멈추게 되었다.'),
(628, 'koKR', '안두인 로서 경과 빛의 수호자 우서 경과 댈린 프라우드무어 제독이 이끄는 얼라이언스 부대는 오크족을 남쪽으로 황폐해져 버린 아제로스까지 밀고 나아갔다. 오크족의 잔혹한 살육에 처음으로 쓰러진 왕국은 아제로스였다.\r\n\r\n로서 경이 이끄는 얼라이언스 부대는 가까스로 둠해머의 부족을 로데론에서 오크가 점령한 아제로스로 다시 밀어냈다. 로서의 군대는 오크족의 화산 요새인 검은바위 첨탑을 포위하고 공성전을 벌였다.'),
(630, 'koKR', '로서가 가장 신뢰하는 부관 투랄리온이 로서의 피 묻은 방패를 다시 집어 들고 슬픔에 잠긴 동료들을 규합하여 맹렬한 반격을 가했다. 짓밟힌 로데론과 아제로스 양국의 깃발 아래, 투랄리온의 부대는 둠해머의 마지막 잔병들을 해치우고 영광스럽지만 끔찍한 승리를 거두었다.'),
(631, 'koKR', '겨우 살아남은 오크 생존자들은 오크족의 최후의 보루, 어둠의 문으로 도망칠 수밖에 없었다.\r\n\r\n투랄리온과 그의 전사들이 오염된 슬픔의 늪을 지나 어둠의 문이 우뚝 서 있는 타락한 저주받은 땅으로 오크족의 잔병들을 추격했고, 그 거대한 문 아래에서 호드의 잔병들과 만신창이가 된 얼라이언스 부대가 2차 대전쟁의 마지막 대혈전을 벌였다.'),
(632, 'koKR', '수적으로 열세인데다가 피를 향한 욕망의 저주에 미쳐 버린 오크들은 얼라이언스 부대의 분노 앞에 결국 쓰러져 버렸다. 둠해머는 체포되어 로데론으로 이송되었고 나머지 부족들도 얼라이언스 부대가 모아 북쪽, 로데론으로 이송했다.'),
(633, 'koKR', '네더가드가 완성된 지 얼마 되지 않아 어둠의 문의 힘이 형상화되어 드레노어로 연결되는 새로운 문이 열렸고, 장로 주술사인 넬쥴이 이끄는 나머지 오크 부족들은 다시 한번 아제로스로 진격했다. 오크들은 넬쥴의 힘을 배가할 마법 유물들을 훔쳐 드레노어에서 새로운 문을 열어 이 멸망해 가는 붉은 세계에서 영원히 탈출하고자 했다.'),
(634, 'koKR', '넬쥴이 얼라이언스에게 공격을 감행할 작정이라고 생각한 로데론의 국왕 테레나스는 드레노어로 군대를 파견해 오크의 위협을 완전히 제거하게 했다. 카드가와 장군 투랄리온이 이끄는 이 얼라이언스 부대는 불타는 평원을 가로지르며 오크족과 싸우게 되었다. 순찰대장 알레리아, 드워프 쿠르트란, 그리고 노병 다나스의 도움까지 받았지만 결국 카드가는 넬쥴이 다른 세계로 연결되는 문을 여는 것을 막아내지 못했다.'),
(635, 'koKR', '두 문이 하나로 합쳐지면서 생긴 격렬한 마법력의 태풍이 황폐한 세계를 뒤흔들기 시작했다. 넬쥴은 자신이 가장 신뢰하는 신하들만 데리고 두 문 중 하나로 빠져나갔고, 카드가는 아제로스에 있는 동료들에게 되돌아 가기 위해 혼신의 힘을 다해 싸웠다. 곧 파멸할 세계에 갇혀 버릴 것이라는 것을 깨달은 카드가와 그의 동지들은 아제로스가 드레노어의 격렬한 파괴로 인해 피해를 입지 않도록 헌신적으로 어둠의 문을 파괴하기로 결정했다.'),
(637, 'koKR', '오크족과 인간이 1차 대전쟁에서 맞붙기 1만 년 전에 아제로스의 세계는 하나의 거대한 대륙으로, 끝없고 거친 바다에 둘러싸여 있었다. 칼림도어라 불리는 이 땅덩어리는 막 태어나고 있던 세계의 거친 자연 속에서 살아남기 위해 서로 다투는 절박한 종족과 짐승들의 고향이었다. 이 어두운 대륙의 중심부에는 하얗게 빛나는 힘을 내뿜는 신비한 호수가 있었다.'),
(638, 'koKR', '훗날에 영원의 샘이라고 불린 이 호수는 이 세계의 마법과 자연력의 태고의 근원이었다. 이 호수는 이 세계 너머의 끝없는 대 암흑으로부터 힘을 빨아들여 전 세계로 보내 다양한 생명을 놀라운 형태로 무럭무럭 자라나도록 하는 신비한 샘이었다.\r\n\r\n시간이 흘러 인간의 모습을 한 원시적인 야행성 부족이 조심스레 이 매혹적인 마법의 호숫가로 모여들었다.'),
(641, 'koKR', '이들 중 그들이 가장 흥미롭게 여긴 것은 아주 오래되고 강력한 용들이었다.\r\n뱀 모양을 한 이 짐승들은 종종 은둔을 하지만 알려진 대륙을 잠재적인 위협으로부터 보호하기 위해 많은 활동을 했고, 나이트 엘프들은 용들이 이 세계의 수호자일 것이니 그들의 비밀을 캐내지 않는 것이 좋다고 믿었다.'),
(642, 'koKR', '나이트 엘프의 끝없는 호기심은 결국 여러 강한 존재들을 만나 친분을 쌓게 하였는데, 이 중에서도 주목할 만한 존재는 원시 삼림지의 강대한 반신인 세나리우스였다. 마음이 넓은 세나리우스는 호기심이 강한 나이트 엘프에게 정이 들었고 많은 시간을 할애하여 그들에게 자연의 세계에 대해 가르쳐 주었다. 차분한 종족인 칼도레이는 칼림도어의 살아 있는 숲에 강한 유대를 만들어 나갔고 조화로운 자연의 균형을 즐기며 살았다.'),
(643, 'koKR', '하지만 끝이 없을 것 같은 긴 시간이 흐르면서 나이트 엘프의 도시는 점차 커져나갔고, 문명도 번창하였으며 그들의 사원, 길, 그리고 주거지가 대륙의 양쪽 끝으로 뻗어나갔다. 나이트 엘프의 아름답고 축복받은 아즈샤라 여왕은 샘 근처에 거대하고 호화로운 궁전을 지어 자신이 가장 신뢰하는 신하들에게 나눠 주고 온갖 금은보석으로 수놓은 전당에서 살도록 했다.'),
(644, 'koKR', '그녀가 귀족이라는 뜻으로 쿠엘도레이라 부르던 이 신하들은 그녀의 모든 명령에 맹목적으로 복종하며 자신들이 다른 모든 나이트 엘프들보다 더 위대하다고 믿었다. 모두 주민이 똑같이 아즈샤라 여왕을 사랑했지만 질투심을 느낀 다수의 군중들은 은밀히 귀족들을 미워했다.\r\n\r\n영원의 샘에 대한 호기심으로 가득했던 사제들처럼 아즈샤라 여왕은 지식이 풍부한 귀족에게 샘의 비밀을 캐내어 세계의 진정한 목적을 찾아내도록 지시를 내렸다.'),
(646, 'koKR', '마법은 무책임하게 다룰 경우 본질적으로 위험한 것이라는 데에는 모두 동의했음에도 불구하고 아즈샤라 여왕과 귀족들은 마법을 남용했다. 세나리우스와 여러 나이트 엘프 학자들이 명백하게 위험의 여지가 남아있는 마법을 남용하면 대재난이 일어나게 될 것이라고 경고했지만, 아즈샤라와 그녀의 신하들은 자신들의 고집대로 점점 커져 가고 있는 그들의 힘을 더욱 확장해 나갔다.'),
(649, 'koKR', '완전 원형으로 주먹과 팔꿈치 사이에 장착할 수 있어 함.\r\n가장자리에 은으로 만든 징이 박혀 있어야 함.\r\n중앙에 손가락 세 개 정도 길이의 큰 징이 하나 박혀 있어야 함.\r\n재질은 참나무로 만들어지고 철로 보강해야 함.\r\n맨 위쪽 테두리에 그링거 스톰파이크라는 이름이 새겨져야 함.'),
(650, 'koKR', '대금은 통상적인 경로를 통해 지급해 드리도록 하겠습니다. 그리고 이 주문서를 전달하는 이에게 관례적인 배달료를 지불해 주시기 바랍니다. 그 비용은 방패 대금에 포함시켜 주시면 됩니다.\r\n\r\n\r\n감사합니다.\r\n- 그링거 스톰파이크'),
(689, 'koKR', '대금은 통상적인 경로를 통해 지급해 드리도록 하겠습니다. 그리고 이 주문서를 전달하는 이에게 관례적인 배달료를 지불해 주시기 바랍니다. 그 비용은 방패 대금에 포함시켜 주시면 됩니다.\r\n\r\n\r\n감사합니다.\r\n- 그링거 스톰파이크'),
(690, 'koKR', '`배신자`라고 조악하게 긁어 써 놓은 아래에 다음과 같은 비문이 정교하게 새겨져 있습니다.\r\n\r\n가족에게 자상한 아버지이자,\r\n자상한 남편이며,\r\n강인한 성기사였던,\r\n유리브 여기 잠들다.\r\n그의 아이들이 빛에 대한 그의 헌신을 증언하리라.\r\n그는 스스로 하지 않을 일은 결코 다른 이에게 부탁하는 일이 없었다.'),
(695, 'koKR', '`배신자`라고 조악하게 긁어 써 놓은 아래에 다음과 같은 비문이 정교하게 새겨져 있습니다.\r\n\r\n가족에게 자상한 아버지이자,\r\n자상한 남편이며,\r\n강인한 성기사였던,\r\n유리브 여기 잠들다.\r\n그의 아이들이 빛에 대한 그의 헌신을 증언하리라.\r\n그는 스스로 하지 않을 일은 결코 다른 이에게 부탁하는 일이 없었다.'),
(697, 'koKR', '일기 - 512일째 바나나들이 내게 말을 걸기 시작했고, 나는 그들의 문화에 대해 많은 것을 배웠다. 나는 그들의 보금자리를 무분별하게 파괴하고 어린것들을 먹어 치우는 짓을 그만두었다. 내가 파괴하고 있던 위대한 문명을 그때는 얼마나 몰랐던가. 그건 그렇고 병과 종이가 떨어져 가는 모양이다. 처음 해변에 떠밀려 온 거대한 종이 더미를 보았을 때는 영영 바닥나지 않을 줄 알았는데. 슬프게도 내 일기는 곧 끝나야 할 것 같다.'),
(751, 'koKR', '다음은 피스톤의 사양입니다.\r\n\r\n길이: 32 WW\r\n너비: 12WW\r\n무게: 23.5 IBG~25.5 IBG\r\n전도율: 70 TC\r\n전단력: 98 이상\r\n결합 강도: `엄청 튼튼` 이상\r\n노움의 측정 단위를 잊으셨다면 다음을 참고하세요.\r\nWW = `수염 너비`\r\nIBG = `아주 조금` 그램\r\nTC = `발가락 털 길이`'),
(771, 'koKR', '먹이 및 관리법:\r\n\r\n저희 땅다람쥐 회사에서는 귀하의 다람쥐를 위한 모든 것을 제공하기 위해 최선의 노력을 다하고 있습니다. 저희 고객은 땅다람쥐 회사에 수준 높은 서비스를 기대하고 있으며 이 점은 저희도 환영하는 바입니다!\r\n\r\n저희는 작은 구멍이 뚫린 땅다람쥐 상자를 설계하여 빛이 잘 비치지 않는 곳에서도 땅다람쥐를 안전하게 보호할 수 있도록 하고 있습니다.\r\n\r\n상자 안에는 땅다람쥐가 제일 좋아하는 간식인 청엽수 줄기 냄새가 나는 그릇도 달려 있습니다!'),
(855, 'koKR', '아래에 위대한 사이클로니안을 소환하는 마법 주문에 필요한 것들을 적어 놓았네. 행운이 함께하길 빌겠네.\r\n\r\n- 바람의감시자 바스라'),
(856, 'koKR', '생명의 뿌리:\r\n\r\n이것은 황무지에서 구할 수도 있고 먼지진흙 습지대에 사는 시든덩굴괴물들에게서 얻을 수도 있네. 이 생명의 뿌리는 사이클로니안의 생명의 정수를 이 세계로 가져오는 데 필요할 걸세.'),
(857, 'koKR', '붉은머리부족의 어금니:\r\n\r\n가시덤불 골짜기에 사는 붉은머리부족은 아주 희귀한 성질을 지니고 있지. 붉은머리부족의 사악한 힘은 어금니에 집중되어 있기 때문에 어금니를 가루로 빻으면 사악한 힘이 풀려 나올 걸세.'),
(858, 'koKR', '떠도는 정령의 정수:\r\n\r\n이 정수는 아라시 고원에 사는 떠도는 정령들의 세 가지 부적을 한데 합쳐서 만들어진 것이네. 이 정령들에게서 천둥 부적, 불타는 부적, 용마루장식 부적을 모아서 각각 여덟 개씩 내 가마솥에 넣게. \r\n\r\n그러면 떠도는 정령의 정수가 만들어질 걸세.'),
(871, 'koKR', '친애하는 $N,\r\n먼저 제 아내와 저를 위해 베풀어 주신 모든 일에 대해 다시 한번 감사 드립니다. 아내의 생명을 구해 주신 은혜는 제가 백 번을 다시 산다고 해도 다 갚지 못할 것입니다. 아내는 제 인생의 전부입니다. 아내가 죽었더라면... 글쎄요, 제가 무슨 짓을 저질렀을지 모르겠군요.\r\n\r\n보답으로 여기에 적어놓은 재료를 찾아오시면 당신께 성스러운 무기를 만들어 드리겠습니다. 제가 생각하기에 가장 찾기 쉬운 것부터 어려운 것 순으로 적어 놓았습니다. 도움이 되었으면 좋겠군요.'),
(872, 'koKR', '쓸만한 흰돌참나무 약간 - 서부몰락지대가 정복 당하기 전만 해도 문브룩 지하 폐광에는 목재가 아주 많았습니다. 열과 압력에도 잘 견디기 때문에 단단한 격자나 도구를 제작하는 데 쓰였죠.\r\n\r\n목재는 바다 건너 어딘가에서 가져와 그곳으로 운반되었습니다. 당신의 무기를 제조하는 데 쓸 수 있을 정도로 아주 튼튼하지만 매우 희귀한 목재죠. 폐광에 아직 남아 있다면 아마 고블린 나무꾼들이 갖고 있을 겁니다.'),
(873, 'koKR', '제련된 광석 - 텔사마에 베일러 스톤핸드라는 드워프 대장장이가 있는데, 한동안 제게 기술을 가르쳐 주셨던 분입니다. 그분은 아주 특수한 합금을 만드는 데 당신의 새 무기에 딱 맞을 것 같군요. 제가 아이언포지에 있는 동안 합금이 도착할 줄 알았는데 아직 아무 소식이 없습니다.\r\n\r\n그분을 찾아서 합금을 보냈는지 확인해 주세요. 만약 모단 호수에서 계시지 않는다면... 옛 스승에게 무슨 일이 일어난 것이 분명합니다.'),
(874, 'koKR', '대장장이 망치 - 역병이 퍼지고 아서스 왕자의 배반이 있기 전, 저는 아름다운 은빛소나무 숲 깊은 곳에 있는 장작나무라는 마을에 살았습니다. 하지만 이제 예전의 아름다운 모습은 사라지고, 제가 강철의 비밀을 배우던 성채도 사악한 무리들에게 침략당해 타락과 부패로 물든지 오랩니다.\r\n\r\n이제는 그림자송곳니 성채라 불리고 있지요. 그곳을 아내와 함께 탈출할 때 가장 아끼던 물건들을 놓고 나왔습니다.'),
(875, 'koKR', '그 중 한 가지가 아버지께서 물려주신 대장장이 망치입니다. 어렸을 때는 그 망치에 마법이 깃들었다는 아버지의 말씀을 믿지 않았었는데... 그 망치는 스컬지에게 당해 돌아가시기 전 아버지의 손때가 묻은 유일한 물건입니다.\r\n\r\n제 열정을 되돌릴 수 있도록 그 망치를 가져다 주세요. 정말로 마법이 깃든 망치라면 우리 모두에게 도움이 될 거예요.\r\n\r\n망치는 성채의 넓은 안마당에 있는 마구간에 두었습니다. 괴물들이 직접 망치질을 하지 않는다면 아직 그곳에 있을 겁니다.'),
(876, 'koKR', '코르석 - 제가 들은 이야기에 의하면 마법을 사용하는 이들은 이 보석에 마법의 힘을 모아서 훨씬 강하게 만들었다고 합니다. 한때 제가 도움을 줬던 툰드리스 윈드위버라는 나이트엘프에게 제 얘기를 하면 자세히 얘기해 줄 겁니다. 당신의 무기를 만드는 데 그 보석에 담긴 힘을 쓸 수 있는 게 있을 겁니다.\r\n\r\n저와 마지막으로 얘기를 나눴을 때 툰드리스는 어둠의 해안 깊은 곳에 있는 아우버다인이라는 마을에 있었습니다. 그 타락한 숲은 이제는 음산한 그늘이 져 버린 나이트엘프들의 고향으로, 해안에 점점이 흩어져 있죠.'),
(930, 'koKR', '비취를 구하세요. 비취는 다양한 여러 장소에 숨겨져 있을 겁니다. 비취는 매우 희귀해서 구하기 어렵지만 대장 기술이나 기계 공학을 익힌 자들에게 물어보면 한두 개 얻을 수도 있을 겁니다.'),
(931, 'koKR', '아래의 물건들이 갑옷 제작에 필요한 재료들이오.\r\n\r\n돌발톱 산맥의 칼바람 광산에 있는 칼바람 코볼트에게서 연기나는 철제 주괴.\r\n\r\n힐스브래드에 있는 힐스브래드 광부에게서 아주라이트 가루.\r\n\r\n채광을 익힌 자나 당신이 채광을 익혔다면 철 광맥에서 철 주괴.\r\n\r\n가시덩굴 우리에 있는 루구그라는 가시멧돼지에게서 연소 약병.'),
(950, 'koKR', '아래의 물건들이 갑옷 제작에 필요한 재료들이오.\r\n\r\n돌발톱 산맥의 칼바람 광산에 있는 칼바람 코볼트에게서 연기나는 철제 주괴.\r\n\r\n힐스브래드에 있는 힐스브래드 광부에게서 아주라이트 가루.\r\n\r\n채광을 익힌 자나 당신이 채광을 익혔다면 철 광맥에서 철 주괴.\r\n\r\n가시덩굴 우리에 있는 루구그라는 가시멧돼지에게서 연소 약병.'),
(951, 'koKR', '(얼룩에 가려 일지의 일부만을 읽을 수 있습니다.)\r\n울다만, 셋째 날\r\n\r\n내가 그렇게 바보스러웠다는 게 믿기지 않는다. 그 역겨운 검은무쇠 드워프들에게 약점을 찔리다니 초보자나 하는 실수였다. 상처가 아무는 속도를 보면 중독된 것이 분명하다. 기운이 점점 빠져나가는 것 같다. 그렇지만 정찰은 해야 한다...\r\n\r\n...엎친 데 덮친 격으로 노움이 만들어 준 목걸이가 산산조각 나 버렸다! 박혀 있던 보석 중 가장 큰 세 개가 없어졌다. 반드시 찾아야 한다. 그게 없으면 목걸이는 아무 힘도 발휘하지 못한다...'),
(971, 'koKR', '울다만, 넷째 날...\r\n\r\n...첫 번째 단서가 울다만의 깊은 곳에서 그 모습을 드러냈다. 지금까지 본 것 중 가장 포악한 트로그가 커다란 사파이어 하나를 휘둘러대고 있었다. 틀림없이 내 목걸이에 딱 맞는 크기일 것이다. 난 우연히 검은무쇠 드워프가 그 괴물같은 놈을 그림로크라고 부르는 것을 들었다. 하지만 놈이 데리고 있는 경비병들은...'),
(972, 'koKR', '울다만, 다섯째 날\r\n\r\n트로그를... 그리고 죽음을 당한 `형제들`의 토파즈를 빼앗아 전당 앞쪽에 있는 옆 동굴로 들어간 다음...\r\n\r\n...방 뒷편의 크고 눈에 띄인 항아리에 재빨리 집어넣고...\r\n\r\n...하필이면 드워프라니! 그것도 세 놈씩이나 되는데 지금 트로그에게 막혀 있다. 힘이 약해진 상태에서는 역겨운 트로그 녀석들에게 당할지도 모르니 녀석들을 부르는 것은 자살행위나 마찬가지였다. 하지만 세 번째 보석을 알게 되면 나는...'),
(973, 'koKR', '울다만, 여섯째 날\r\n\r\n...너무 배고프다. 식량이 다 떨어져 이제는 곰팡이 핀 빵이라도 진수성찬으로 보일 정도다... 내 눈 바로 앞에 있는 트로그의 머리가 맛있는 스테이크로 보일 지경이다...'),
(974, 'koKR', '울다만, 일곱째 날\r\n\r\n...내 실수를 만회할 마지막 기회다. 루비는 드워프가 트로그를 막기 위해 쳐 놓은 최후의 방어진 내에 있는 것으로 보인다. 그들의 전투는 유적지의 유물이나 보석을 차지하기 위해 벌어지고 있는 것이 확실해 보였고 날이 갈수록 치열해지고 있다. 그런 곳에 보석을 숨겨놓다니 사악한 드워프답다. 사정이야 어쨌든 나도 움직여야 한다. 어쩌면 이곳을 미친 듯이 뛰쳐나가는 것이 최선일지도...'),
(1011, 'koKR', '내가 카즈뮬의 방으로 들어가는 방법을 알아냈다!\r\n\r\n나의 궤짝에서 그니키브의 메달을 습득한다.\r\n\r\n지도실 앞방에 있는 레벨로쉬라는 트로그를 처치하고 티솔의 자루를 회수한다.\r\n\r\n메달과 자루를 합쳐 잃어버린 역사의 지팡이를 만든다.\r\n\r\n지도실에서 지팡이를 사용해 카즈뮬의 방으로 통하는 문을 연다.\r\n\r\n그러면 그 방 안에 있는 것은 모두 당신의 것이다!\r\n\r\n-밸로그'),
(1051, 'koKR', '이 탑의 경비병들은 내 공격에 유독 약한 듯하다. 내가 탑의 뒤편을 조사하던 중, 정찰병 하나가 나를 보고 공격을 했는데 때를 맞춰 후려치고 목을 졸라 아주 손쉽게 처치할 수 있었다.\r\n\r\n나는 이 정찰병의 동료가 소동이 나는 소리를 듣고 조사하러 오기를 숨어서 기다렸다. 그는 내가 시체를 끌고 간 덤불로 가서 조사하기 시작했다. 내가 매복하고 있는 것이 발각되지 않도록 나는 천천히, 조심스럽게 그의 뒤로 다가갔다.'),
(1052, 'koKR', '적절한 기회가 포착되자 나는 녀석의 등에 내 단검을 찔러넣었다! 내 공격에 그는 허파가 터져 쿵하고 둔탁한 소리를 내며 쓰러졌다.\r\n\r\n워낙 빠르고 맹렬한 기습이어서 녀석은 고통으로 비명을 지를 틈조차 없었다. 이상하게도 내가 그의 등에서 칼을 뽑자 그 정찰병에게서 악취가 나기 시작했다.'),
(1053, 'koKR', '클레븐이 궤짝에 숨겨 놓은 것이 탑의 주민들에게 나쁜 영향을 끼치고 있는 것 같았다. 다른 경비병들도 비슷한 약점들을 가지고 있을 듯하고, 어쩌면 클레븐 자신도 그 폐기물로 인해 피해를 입었을지 모른다.\r\n\r\n첩보원 앰버 켈넌\r\nSI:7 지상 행동 요원, R8'),
(1090, 'koKR', '클레븐이 궤짝에 숨겨 놓은 것이 탑의 주민들에게 나쁜 영향을 끼치고 있는 것 같았다. 다른 경비병들도 비슷한 약점들을 가지고 있을 듯하고, 어쩌면 클레븐 자신도 그 폐기물로 인해 피해를 입었을지 모른다.\r\n\r\n첩보원 앰버 켈넌\r\nSI:7 지상 행동 요원, R8'),
(1091, 'koKR', '줄파락의 나무망치\r\n\r\n1. 줄파락의 나무망치를 만들려면 우선 동부 내륙지에 있는 줄의 제단으로 가서 트롤 문지기를 처치하여 신성한 나무망치를 얻는다.\r\n\r\n2. 이 신성한 망치를 진타알로라는 트롤 도시 꼭대기에 있는 제단으로 가지고 간다.\r\n\r\n3. 제단에서 신성한 나무망치를 사용하면 마력이 부여되면서 줄파락의 나무망치로 변한다.'),
(1131, 'koKR', '일급 기밀 3중 암호화 데이터 카드\r\n\r\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111'),
(1150, 'koKR', '일급 기밀 3중 암호화 데이터 카드\r\n\r\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111'),
(1191, 'koKR', '일급 데이터! 보안 등급 5122!\r\n\r\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101'),
(1192, 'koKR', '절대 이 정보가 적의 손에 들어가는 일이 없도록 하십시오!\r\n\r\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010'),
(1193, 'koKR', '보안 등급 10^10000 일급 기밀 데이터!\r\n\r\n01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001'),
(1194, 'koKR', '이 정보의 보안 등급이 매우 높아 이를 표현하기 위한 새로운 숫자 개발을 보류 중입니다!\r\n'),
(1211, 'koKR', '땅다람쥐 수색\r\n\r\n땅다람쥐는 구석지고 어두운 곳을 좋아하며 낯을 매우 가리는 편입니다.\r\n\r\n땅다람쥐에게 수색을 시키려면 땅다람쥐가 집처럼 편안하게 생각할 수 있는 곳을 찾아야 합니다. 그리고 반드시 땅다람쥐가 가장 좋아하는 음식인 청엽수 줄기가 있는 곳으로 데리고 가야 합니다.\r\n\r\n이러한 장소 중 가장 가까운 곳은 가시덩굴 우리입니다. 그곳에서 구멍 난 상자를 열면 땅다람쥐가 근처에 있는 청엽수 줄기의 냄새를 맡고 상자 밖으로 나와 당신을 따를 것입니다.'),
(1212, 'koKR', '땅다람쥐 지휘봉\r\n\r\n땅다람쥐는 놀라운 동물입니다. 성질이 아주 고약한 초원타조에게서도 사랑과 보살핌을 받을 수 있을 뿐만 아니라, 최대 50미터 정도 떨어진 곳에 묻혀 있는 청엽수 줄기의 냄새를 맡을 수도 있습니다!\r\n\r\n땅다람쥐를 시켜 청엽수 줄기를 찾으려면 별도 판매되는 저희 회사의 특허 제품인 땅다람쥐 지휘봉을 사용하시기 바랍니다.\r\n\r\n사용법은 다음 장에 이어집니다.'),
(1213, 'koKR', '고도의 훈련을 받은 땅다람쥐는 지휘봉을 흔들기만 해도 수색 태세를 취할 것입니다. 이때 청엽수 줄기의 냄새를 맡기 시작하며, 발견 즉시 달려가서 땅을 파기 시작합니다.\r\n\r\n만약 땅다람쥐가 청엽수 줄기를 찾는 동안 지휘봉을 다시 흔들면 땅다람쥐는 수색을 즉시 중단하고 주인의 곁으로 돌아옵니다.\r\n\r\n땅다람쥐는 손에 쥐었을 때 아주 부드러울 뿐 아니라 훈련이 잘되어 있고, 쓸모가 많기 때문에 여러분의 파티에 큰 도움이 될 것이라 자부합니다!'),
(1214, 'koKR', '저희 코담배 회사에서는 일부 욕심 많은 청엽수 줄기 채집꾼들이 우리의 사랑스러운 땅다람쥐들을 어둡고 위험한 곳으로 보내 노역을 시켰다는 보고를 받았습니다. 무척 가슴 아픈 사실이 아닐 수 없습니다.\r\n\r\n저희는 그러한 무책임한 행동을 묵과하지는 않을 것입니다. 그러나 고객 만족 정책의 하나로 저희가 판매하는 모든 땅다람쥐에는 품질보증서를 붙여서 땅다람쥐가 죽는 불상사가 발생해도 고객은 돌아가서 땅다람쥐를 새로 얻을 수 있습니다.\r\n\r\n그럼, 즐거운 채집되십시오!'),
(1311, 'koKR', '쪽지를 주은 자에게\r\n\r\n이 쪽지를 읽고 있다면 당신은 다음 두 장소 중 하나에 있는 것이다.\r\n\r\n1. 아즈샤라의 남부 반도.\r\n\r\n2. 절벽거인의 뱃속\r\n\r\n둘 다 편히 쉴만한 곳은 못 된다.\r\n\r\n나도 한때 남부 반도에도 있어 보았고 지금은 뱃속에 앉아 이 쪽지를 쓰고 있다.'),
(1312, 'koKR', '거인의 뱃속에 있으면 생각할 시간이 생기게 된다.\r\n\r\n내 몸이 결정화되어 가면서 나도 어쩌면 아직도 이 세상에 많은 영웅 중 하나가 나를 구할 수 있을지도 모른다는 희망을 품게 되었다. 내 어떻게든 이 곤경을 벗어나게 되면 그 유령 같은 오크 녀석의 목을 졸라 버리고 싶다!\r\n\r\n- 윈던 셰이'),
(1313, 'koKR', '내가 지금 무슨 생각을 하고 있는 것일까?\r\n\r\n좀 더 나은 질문이 되려면 이렇게 물어야 할 것이다. 거인의 뱃속에 들어앉아서 쪽지나 쓰고 있다니 이게 무슨 짓일까?\r\n\r\n둘 다 내가 지금 당장 답할 수 없는 질문들이다...\r\n\r\n사실, 내가 여기로 오게 된 이유 자체부터 어리석었다. 아즈샤라 남부에서만 나는 수정, 아즈샤리트를 찾아 온 것이다. 아, 그것만 손에 넣었다면 엄청난 부자가 되었을 것을!\r\n\r\n나, 참! 지금 내 꼴을 보라고...'),
(1314, 'koKR', '이성적인 존재가 이 쪽지를 발견한다면 스스로에게 질문을 던져 봐야 할 것이다. \"키가 10미터나 되는 난폭한 거인들이 마구 돌아다니는 곳에서 대체 지금 뭘 하고 있는 거지?\"라고.\r\n\r\n- 무크'),
(1330, 'koKR', '이성적인 존재가 이 쪽지를 발견한다면 스스로에게 질문을 던져 봐야 할 것이다. \"키가 10미터나 되는 난폭한 거인들이 마구 돌아다니는 곳에서 대체 지금 뭘 하고 있는 거지?\"라고.\r\n\r\n- 무크'),
(1392, 'koKR', '닐스 수사님,\r\n\r\n제 포도는 무사합니다! 이 포도 수확 목록을 지니고 있는 $n씨가 용감하게도 악당들이 득실거리는 제 포도밭에 들어가 제가 가져오지 못한 포도를 가져와주었답니다. 강 건너편에서는 아직도 데피아즈단이 어슬렁거리고 있지만 제 포도는 거의 다 구했습니다. 수사님의 저장고에 포도를 한 부대 더 두셔도 좋습니다.\r\n\r\n성스러운 빛의 가호가 함께 하길.\r\n\r\n-밀리 오스워드 올림'),
(1433, 'koKR', '우그젤 해머핸드\r\n\r\n우그젤은 솜씨 좋고 진지한 조각가로, 암흑의 열쇠라는 짐을 지고 있지 않을 때에는 그의 손에서 장인의 전당에 있는 걸작들이 만들어진다.'),
(1435, 'koKR', '오프구트 스톤피스트\r\n\r\n암흑의 문지기 오프구트의 망치 아래 쓰러진 자들의 수는 헤아릴 수 없을 정도다.\r\n\r\n서부 주둔지 병사들은 그가 지날 때 허리 굽혀 인사하며 경의를 표한다. 오프구트의 눈 속에서 암흑의 열쇠가 속삭이는 비밀을 볼 수 있는 자가 그 중 누구란 말인가?'),
(1436, 'koKR', '펠베르 딥스톰프\r\n\r\n암흑의 문지기 펠베르는 가장 영광된 제자이다. 그 누구보다도 암흑의 열쇠를 오래 지니고 있었으며 그로 인해 엄청난 대가를 치렀다. 그가 암흑의 열쇠를 위해 부름을 받으면 거주지에서 그는 보호를 받는다.\r\n\r\n암흑이 그를 지배하게 되더라도... 그의 희생은 언제까지나 우리의 마음 속에 소중하게 기억될 것이다.'),
(1471, 'koKR', '솔로몬,$B$B이 명령서를 지닌 자는 스톰윈드의 부관 대리로 공식 임명되었노라. 그러니 이 자를 보내 검은용군단이 검은바위부족 오크와 연루되어 있다는 증거를 찾도록 하라. 증거를 찾거든 이 부관이 스톰윈드에 있는 내게 그 증거를 보낼 것이다. 그 증거를 받으면 레이크샤이어에 지원 병력을 투입하는 명령을 허가하겠노라.$B$B대영주 볼바르 폴드라곤'),
(1551, 'koKR', '안녕하세요. 모험가 여러분!\r\n\r\n저, 크린클 굿스틸은 험난한 임무를 수행하기 위해 기꺼이 위험을 무릅쓸 뜻이 있는 분들을 찾고 있습니다. 제가 책임지고 있는 임무와 작업량이 너무 많은 이유로 이 목록에 적힌 물건들을 제게 무사히 가지고 오시는 분에게는 후한 사례를 하겠습니다.\r\n\r\n물건 목록은 다음 페이지에 있습니다...'),
(1552, 'koKR', '단단한 수정 다리 마디 -\r\n\r\n믿을 수 없겠지만 불타는 골짜기에 서식하는 유리그물거미는 수정 같은 물질로 이루어져 있습니다. 이 거미들을 처치할 때 다리가 손상되지 않게 해서 가지고 오시면 제 동료들의 기계 공학 실험에 아주 우수한 도체로 사용할 수 있을 겁니다.\r\n\r\n실험해 볼 다리가 좀 필요한데 거미에게는 다리가 8개나 있으니까 강인한 전사나 솜씨 좋은 마법사에게는 문제가 되지 않을 것입니다.'),
(1553, 'koKR', '부쳐지지 않은 소포 -\r\n\r\n믿을 만하다고 생각한 조종사 하나를 고용해 테라모어에서 소포 하나를 가져오게 했었는데 생각보다 실력이 아주 형편없었습니다. 그 조종사가 살아서 자초지종을 듣긴 했지만 자기 목숨 건지려고 비행선과 화물을 몽땅 버려두고 와버렸지 뭡니까.\r\n\r\n그 소포가 필요합니다. 비질 말로는 그 자가 먼지진흙 습지대 만의 바로 서쪽에 추락했다고 해요. 물가에 있는 언덕을 넘자마자 바로 추락했다더군요.\r\n\r\n음... 그런데 추락한 원인은 말해주지 않았습니다.'),
(1554, 'koKR', '균형 잡힌 굿스틸의 플랑베르주 -\r\n\r\n마지막으로 찾아야 할 물건은 제가 지금까지 대장장이로 살면서 만든 물건 중 가장 우수한 것입니다. 이 플랑베르주는 믿을 수 없을 만큼 훌륭한 검이었는데, 저는 이 검을 명예롭고 위대한 전사라고 생각된 자에게 주었습니다. 그런데 그만 그 전사가 자르콰이인가 하는 멀록에게 당하고 말았지요.\r\n\r\n그 전사는 슬픔의 늪 해안을 따라가던 중 멀록을 공격했었습니다. 하지만 멀록에게 당한 전사는 도망을 치다 그 검을 버렸고 결국 멀록이 가져가 버렸습니다.'),
(1555, 'koKR', '균형 잡힌 굿스틸의 플랑베르주 -\r\n\r\n마지막으로 찾아야 할 물건은 제가 지금까지 대장장이로 살면서 만든 물건 중 가장 우수한 것입니다. 이 플랑베르주는 믿을 수 없을 만큼 훌륭한 검이었는데, 저는 이 검을 명예롭고 위대한 전사라고 생각된 자에게 주었습니다. 그런데 그만 그 전사가 자르콰이인가 하는 멀록에게 당하고 말았지요.\r\n\r\n그 전사는 슬픔의 늪 해안을 따라가던 중 멀록을 공격했었습니다. 하지만 멀록에게 당한 전사는 도망을 치다 그 검을 버렸고 결국 멀록이 가져가 버렸습니다.'),
(1590, 'koKR', '이 물건들을 찾아 이 장부와 함께 모두 가젯잔으로 돌아오시오. 그러면 보상을 하겠소.'),
(1611, 'koKR', '<페이지마다 고대 엘프의 룬문자가 가득합니다.>\r\n\r\n본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 경험을 담고 있다.\r\n\r\n부디 이 책이 적들의 손에 들어가지 않기를.\r\n\r\n부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.\r\n\r\n부디 캘타스님의 은총 속에서 숨을 거두기를.\r\n\r\n부디 일리단님의 영광을 위해 살생을 하기를.\r\n\r\n-카리엘 윈탈루스'),
(1631, 'koKR', '<페이지마다 고대 엘프의 룬문자가 가득합니다.>\r\n\r\n본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.\r\n\r\n부디 이 책이 적들의 손에 들어가지 않기를.\r\n\r\n부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.\r\n\r\n부디 캘타스님의 은총 속에서 숨을 거두기를.\r\n\r\n부디 일리단님의 영광을 위해 살생도 불사하기를.\r\n\r\n-카리엘 윈탈루스'),
(1632, 'koKR', '<책장이 고대 엘프 룬 문자로 뒤덮여 있다.>\n\n이 책에는 하급 마법약을 제작하는 데 필요한 재료들을 모으고 만들어내는 과정에서 일어난 사건들의 기록이 담겨 있다.\n\n우리의 적들이 이 책에 결코 접근하지 못하게 하소서. \n\n쿠엘탈라스에 다시 한번 창백한 달빛이 비치는 것을 볼 수 있게 하소서.\n\n켈타스의 은총이 아니었다면 죽음을 맞이했을 것입니다.\n\n일리단의 영광을 위해 적을 처치할 수 있게 하소서.\n\n-카리엘 윈탈루스 님'),
(1633, 'koKR', '<페이지마다 고대 엘프의 룬문자가 가득합니다.>\r\n\r\n본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.\r\n\r\n부디 이 책이 적들의 손에 들어가지 않기를.\r\n\r\n부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.\r\n\r\n부디 캘타스님의 은총 속에서 숨을 거두기를.\r\n\r\n부디 일리단님의 영광을 위해 살생도 불사하기를.\r\n\r\n-카리엘 윈탈루스'),
(1634, 'koKR', '<책장이 고대 엘프 룬 문자로 뒤덮여 있다.>$B$B이 책에는 하급 마법약을 제작하는 데 필요한 재료들을 모으고 만들어내는 과정에서 일어난 사건들의 기록이 담겨 있다.$B$B우리의 적들이 이 책에 결코 접근하지 못하게 하소서. $B$B쿠엘탈라스에 다시 한번 창백한 달빛이 비치는 것을 볼 수 있게 하소서.$B$B켈타스의 은총이 아니었다면 저는 죽었을 것입니다.$B$B일리단의 영광을 위해 저는 적을 처치할 것입니다.$B$B-카리엘 윈탈루스 님'),
(1691, 'koKR', '안녕, 펠녹!$B$B불타는 초원에서의 내 연구는 아주 순조롭게 진행되고 있어. 그리고 $N의 도움 덕분에 정말 큰 은혜를 입었지! 연구를 계속하려면 다음 재료들이 필요해:$B$B스틸코일 범퍼비첼$B17게이지 아이스 스패너$B오리 깃털 12파운드$B네가 만든 접착제 한 병$B$B정말 고마워, 펠녹. 다음에 또 만나면 네 부츠에 석탄을 넣지 말라고 꼭 말해줘!$B$B-팅키'),
(1711, 'koKR', '절벽파수꾼 롱혼에게 보내는 긴급 전갈$B$B에톡 야영지의 켄타우로스 군대가 대규모로 공격하여 보급품 짐마차 중 한 대를 습격. 짐마차에 타고 있던 자들과 보급품 실종 및 분실. 지금까지의 켄타우로스 공격과는 달리 매우 과감한 공격으로, 앞으로 추가 공격이 우려됨.'),
(1731, 'koKR', '로데론 최후의 진정한 국왕 테레나스 메네실 2세, 여기 잠들다.\r\n\r\n그의 업적은 위대했고, 그의 통치는 오랜 세월 이어졌으나, 그의 죽음은 상상도 하지 못한 것이로다.\r\n\r\n         \"부디 그 아버지가 아들의 행동으로 비난받지 않기를.\r\n         부디 그 피 묻은 왕관이 영원히 돌아오지 않고 잊혀지기를.\"'),
(1756, 'koKR', '이 프테라돈 뼈는 운고로 분화구 외딴곳에서 회수한 것으로, 골격 구조가 온전한 걸 보아 아무도 이 뼈를 발견하지 못했던 게 분명하다. 이 뼈는 발견되지 않았더라도 운고로 분화구의 비옥한 토양 아래 몇 세기든 온전하게 보존될 수 있었을 것이다.'),
(1757, 'koKR', '수사마르의 해저 유적에서 찾은 이 아스트롤라베는 거의 2만년 전 귀족의 나이트 엘프들이 제작한 것으로 아직도 작동이 가능하다. 마법, 비술, 천문학에 유난히 집착이 강했던 명가의 엘프들은 갖가지 훌륭한 도구들을 개발했다. 이 장치는 고대 나이트 엘프들의 과학적 수준을 엿볼 수 있는 아주 중요한 물건이다.'),
(1781, 'koKR', '한때 숭고했던 가슴이 타락으로 찌들면서 살게라스가 지닌 티탄의 모습도 변형되기 시작했다. 눈과 머리카락, 수염에서는 불길이 치솟고 청동 피부는 갈라져 끝없이 타오르는 증오를 드러냈다.'),
(1783, 'koKR', '그 중 하나인 책략가 킬제덴은 우주에서 가장 사악한 종족들을 찾아내 살게라스의 수하로 데려오는 일을 맡았고, 다른 하나인 파멸자 아키몬드는 살게라스의 강대한 군대를 이끌고 어둠의 티탄에게 거역하는 자들을 가차없이 처단하는 임무를 맡았다.'),
(1787, 'koKR', '피조물을 다시 무로 돌리려는 살게라스의 사명을 알지 못한 채, 티탄들은 계속해서 이 세계에서 저 세계로 옮겨가며 자신들이 적합하다고 생각하는 대로 세계를 꾸미고 질서를 세워 갔다. 후에 거주자들이 아제로스라고 부르게 되는 작은 세계에 도달하게 된 티탄들은'),
(1788, 'koKR', '이 세계의 혼돈스럽고 원시적인 땅을 지나다가 몇몇 사나운 정령들을 만나게 되었다. 고대 신들이라고만 알려진, 알 수 없는 악의 존재들을 섬기는 이 정령들은 티탄들을 몰아내고 이 침입자들의 철의 손길로부터 자신들의 세계를 지킬 것을 맹세했다.'),
(1789, 'koKR', '악행을 취미로 삼는 고대 신들을 염려한 판테온은 정령들과 그들의 사악한 지배자에 맞서 전쟁을 치렀다. 고대 신들의 군대는 가장 뛰어난 정령 부관들이라고 할 수 있는 불의 군주 라그나로스, 돌의 어머니 테라제인, 바람의 군주 알아키르, 바다의 사냥꾼 넵튤론이 이끌었다.'),
(1792, 'koKR', '티탄은 세계를 가꾸는 일을 도울 종족을 창조했다. 땅 아래 끝없이 깊은 동굴을 파내기 위해 생명이 깃든 마법의 돌로 난쟁이처럼 생긴 토석인을 창조했고, 바다를 고르고 해양 바닥에서 땅을 들어올리기 위해 거대하지만 온순한 바다 거인을 창조했다. 오랜 세월 동안 티탄은 열심히 땅을 가꾸었고 마침내 하나의 완벽한 대륙만이 남게 되었다.'),
(1793, 'koKR', '티탄은 이 대륙의 중심에 반짝이는 에너지가 깃든 호수를 만들어 영원의 샘이라 불렀고 이 세계의 생명의 원천으로 삼았다. 이 호수의 강렬한 에너지는 세계의 뼈대에 영양분을 공급했으며 생명체를 창조해 이 세계의 비옥한 땅에 정착하도록 했다. 시간이 흘러 각종 식물과 나무, 괴물, 생명체들이 이 원시 대륙에서 번성하기 시작했다.'),
(1794, 'koKR', '일을 끝낸 마지막 날 해질 무렵, 티탄들은 이 대륙에 `영원한 별빛의 땅`이란 뜻의 칼림도어라는 이름을 지어 주었다.'),
(1798, 'koKR', '모든 생명의 수호자인 티탄, 이오나는 자신이 가진 힘의 일부를 거대한 붉은용인 알렉스트라자에게 주었다. 그 후 알렉스트라자는 생명의 어머니로 불리며 아제로스 세계의 모든 생명체를 보호하는 데 힘썼다. 알렉스트라자는 탁월한 지혜와 모든 생명체에 대한 끝없는 연민으로 용의 여왕이 되어 붉은용혈족을 다스리게 되었다.'),
(1801, 'koKR', '만물을 빚어내고 창조한 조물주 티탄중 하나인 카즈고로스는 자신의 광활한 힘의 일부를 강대한 검은용 넬타리온에게 주었다. 후에 대지의 수호자로 불린 넓은 마음의 소유자, 넬타리온은 세계의 대지와 지하 세계를 지배하게 되었다. 세계의 힘을 부여 받은 넬타리온은 알렉스트라자의 가장 든든한 힘이 돼 주었다.'),
(1808, 'koKR', '극악무도한 흑마법사들은 칼림도어의 우아한 사원에 마치 지옥의 운석이 떨어지듯 불타는 지옥불정령을 불러냈으며, 피를 뿌리며 다니는 불타는 살인마 집단인 파멸의수호병은 칼림도어의 평원을 지나면서 눈에 보이는 자들을 닥치는 대로 살해했다. 거칠고 흉포한 지옥사냥개 무리조차 도시 주변을 휘젓고 다니며 모든 것을 파괴했다. 칼도레이의 용감한 전사들이 유서 깊은 고향을 지키기 위해 돌격했지만 불타는 군단의 맹공격 앞에서 점차 무릎을 꿇을 수밖에 없었다.'),
(1809, 'koKR', '이제 위기에 처한 동족을 구해내는 것은 말퓨리온 스톰레이지의 손에 달려 있었다. 마법을 사용하는 귀족인 일리단의 친형, 말퓨리온은 귀족 계급의 부패가 심각해져 가는 데 몹시 화가 나 있었다. 일리단에게 위험한 집착을 버리도록 설득한 말퓨리온은 세나리우스를 찾아 저항 세력을 모으기 위해 길을 나섰다.'),
(1812, 'koKR', '머나먼 하이잘 산맥의 성스러운 달의 숲에서 살고 있었던 세나리우스는 말퓨리온과 일리단, 티란데가 고대의 용을 찾아 도움을 받을 수 있도록 힘을 써주기로 했다. 그리하여 거대한 붉은용 알렉스트라자가 이끄는 붉은용족은 강대한 용군단을 보내 나이트 엘프의 땅을 침략한 악마와 그 군주에 대항하기로 했다.'),
(1814, 'koKR', '아즈샤라의 수도에서 대접전이 벌어지는 동안, 살게라스의 힘에 현혹된 아즈샤라 여왕은 살게라스가 도착하기만을 기다리고 있었다. 한편 불타는 군단의 군주는 영원의 샘을 지나서 이 파괴의 세계로 들어오려 하고 있었다. 믿을 수 없을 정도로 거대한 살게라스의 그림자가 소용돌이 치는 샘의 표면에 가까워지자 아즈샤라는 귀족 추종자 중 가장 강한 자들을 모았다. 그들의 마법을 연결해 하나의 집중된 주문을 사용해야만 살게라스가 들어올 수 있을 만큼 커다란 문을 만들 수 있었기 때문이었다.'),
(1817, 'koKR', '말퓨리온은 영원의 샘이 악마와 이 세계를 밀접하게 연결해주는 고리 역할을 한다고 확신하여 샘을 파괴해야 한다고 주장했다. 그의 동료들은 영원의 샘이 나이트 엘프에게 불멸성과 힘을 주는 근원이라는 것을 알고 있었기에 그 무모한 주장에 충격을 감추지 못했다. 하지만, 티란데는 그의 생각이 현명하다고 판단하여 아즈샤라의 사원에 쳐들어가 영원의 샘을 완전히 봉쇄해야 한다고 세나리우스와 동료들을 설득했다.'),
(1828, 'koKR', '끔찍한 폭발 속에서 살아남은 나이트 엘프들은 함께 뗏목을 타고 눈에 보이는 유일한 땅덩어리로 천천히 나아갔다. 말퓨리온과 티란데, 세나리우스는 엘룬의 은총으로 대재앙에서 살아남을 수 있었다. 지칠 대로 지친 영웅들은 살아남은 동료들을 이끌고 새로운 터전을 일구기로 했다.'),
(1832, 'koKR', '한편, 일리단도 대재앙에서 살아 남아 말퓨리온과 나이트 엘프들이 도착하기 훨씬 전에 하이잘 산의 정상에 다다랐다. 일리단은 이 세상에 마법의 힘을 계속 유지시켜야 한다는 잘못된 생각으로 물병에 담아온 영원의 샘의 고귀한 물을 산의 호수에 부었다.'),
(1837, 'koKR', '붉은용 알렉스트라스자와 녹색용 이세라, 청동용 노즈도르무는 드루이드의 고요한 숲으로 내려와 나이트 엘프들의 노력이 맺은 결실을 살펴보았다. 강력한 힘을 지닌 대드루이드가 된 말퓨리온은 강대한 용들을 맞이하며 새로운 영원의 샘이 만들어진 배경에 대해 얘기해 주었다.'),
(1840, 'koKR', '이 거대한 나무는 나이트 엘프와 자연의 결속을 나타내는 영원한 상징물로, 생명을 불어넣는 나무의 힘은 곳곳으로 뻗어나가 점차 세계를 치유하게 될 것이었다. 나이트 엘프들은 이 세계수의 이름을 그들의 언어로 \"천상의 왕관\"이라는 뜻인 놀드랏실로 정했다.'),
(1844, 'koKR', '수 세기가 지나면서 나이트 엘프의 새로운 사회는 점점 강해서 그들이 잿빛 골짜기라고 부르게 된 숲 전체로 확대되었다. 펄볼그나 가시멧돼지처럼 대재앙 이전에 많았던 생물과 종족이 다시 나타나 번성하기 시작했고 드루이드의 인자한 통치 아래 나이트 엘프는 별빛 아래서 전례 없는 평화와 고요를 누리게 되었다.\r\n'),
(1845, 'koKR', '하지만 원래 귀족이었던 생존자들은 불안해하기 시작했다. 그들은 일리단과 마찬가지로 아끼던 마법을 잃어 고통스러워 하던 터라 영원의 샘의 힘을 끌어내 마법을 사용하는 기쁨을 맛보고 싶어했다. 성급하고 솔직했던 귀족 지도자 다트리마는 마법의 주인은 원래 자신들이었다고 주장했고 마법을 사용하지 못하게 하는 드루이드에게 불만을 품어 그들을 겁장이라며 비난하기 시작했다.\r\n'),
(1846, 'koKR', '말퓨리온과 드루이드들은 다트리마의 비난을 넘겨 듣고 귀족들에게 마법을 사용하게 되면 사형에 처할 것이라 경고했다. 하지만 다트리마와 그의 추종자들은 드루이드에게 법을 폐지할 것을 납득시키려는 거만하고도 불행한 의도로 잿빛 골짜기에 끔찍한 마법 폭풍을 일으켰다.\r\n'),
(1847, 'koKR', '그 많은 동족을 모두 사형에 처할 수 없었던 드루이드들은 이 무모한 귀족들을 자신들의 땅에서 추방하기로 결정했다. 다트리마와 그의 추종자들은 마침내 보수적인 동족들과 떨어지게 된 것을 기뻐하며 특별히 제작한 배에 올라 항해를 시작했다. 격돌하는 혼돈의 소용돌이 너머에 무엇이 있는지 아무도 몰랐지만 그들은 아무런 처벌도 받지 않고 마법을 자유롭게 사용할 수 있는 자신들만의 터전을 만들기를 간절히 바랬다.\r\n'),
(1848, 'koKR', '과거에 아즈샤라가 \"쿠엘도레이\"라 이름을 지어주었던 이 귀족들은 마침내 인간이 로데론이라고 부르게 될 동쪽 땅의 해안에 다다랐다. 그들은 자신들만의 마법 왕국인 쿠엘탈라스를 세우기로 하고 달을 숭배하고 밤에만 활동하는 나이트 엘프의 규율을 저버렸다. 그 후 이들은 태양을 받아들이고 \"하이 엘프\"라고만 불리게 되었다.\r\n'),
(1868, 'koKR', '트롤 전투부대는 물론이고 필요한 경우 은둔해 있는 엘프와도 싸워 이길 자신이 있었던 아라시 족장들은 로데론의 남부 지역에 강력한 요새 도시를 건설하기로 결정했다. 스트롬이라는 이름의 이 도시국가는 아라시인들의 국가, 아라소르의 수도가 되었다. 아라소르가 번성하자 대륙 각지에서 인간들이 스트롬의 보호와 안전을 찾아 남쪽으로 몰려들었다.'),
(1893, 'koKR', '세계가 영원의 샘의 내파로 인해 갈라지면서 토석인은 깊은 영향을 받게 되었다. 토석인은 대지 자체의 고통과 함께 휘청거리다 정체성의 대부분을 상실하고 자신들이 처음 창조되었던 석실에 스스로를 봉인해버렸다. 울다만, 울둠, 울두아, 이는 토석인이 처음으로 태어난 고대 티탄 도시의 이름들이다. 토석인은 땅 속 깊은 곳에 묻힌 채 거의 8천년간을 평화롭게 쉬고 있었다.'),
(1898, 'koKR', '스트롬은 계속해서 아라소르의 중심지로 남아 있었지만 달라란처럼 로데론 대륙의 각지에서 많은 도시국가들이 생겨났다. 새로 생긴 첫 도시국가들로는 길니아스, 알터랙, 그리고 쿨 티라스가 있었다. 이 도시들은 각각 고유한 관습과 상업 정책에 따라 운영되었지만 스트롬의 통일된 권한에 속해 있었다.'),
(1899, 'koKR', '달라란은 티리스팔 의회의 철저한 감독 하에 세계 각지에서 온 마법사들의 배움의 장으로 자리잡았다. 달라란을 지배하는 마법지배층은 키린 토라는 전문 분파를 결성하고 당시 인류에게 알려진 모든 주문과 유물, 마법 물품을 수록하고 조사하는 일을 담당하게 되었다.'),
(1915, 'koKR', '마도란 브론즈비어드 호족이 이끄는 브론즈비어드 일족은 대왕과 긴밀한 관계를 유지하며 아이언포지 산맥의 전통적인 수호자로 일어섰고, 카드로스 와일드해머가 이끄는 와일드해머 일족은 산기슭 주변의 바위산과 구릉지대에 살며 도시 내에서 세력을 확장하려고 노력했다.'),
(1916, 'koKR', '세 번째 당파인 검은무쇠단은 타우릿산이라는 마법사 족장을 지도자로 두었는데, 이 부족은 산 아래 깊은 그늘 속에서 브론즈비어드 부족과 와일드해머 부족을 몰아내기 위한 음모를 꾸미고 있었다.'),
(1919, 'koKR', '시간이 흐르면서 도시는 번창했지만 검은무쇠단 부족의 증오는 사라지지 않았다. 타우릿산과 그의 아내, 여마법사 모드구드는 아이언포지와 그림 바톨 양쪽 모두에 각각 공격을 감행했다. 검은무쇠단은 카즈 모단 전역을 손에 넣기 위해 혈안이 되어 있었다.'),
(1924, 'koKR', '이 세계가 태어난 지 얼마 되지 않던 시절 티탄에게 추방당한 불의 군주, 불의 정령들의 영원한 군주인 라그나로스가 다시 깨어났다. 그가 이제 타우릿산의 소환으로 다시 깨어나게 된 것이다. 아제로스에서 일어난 대재앙, 라그나로스의 환생으로 붉은마루 산맥이 파괴되고 그 파괴의 중심에 격렬한 화산이 만들어졌다.'),
(1925, 'koKR', '검은바위 첨탑이라고 하는 이 화산은 북쪽으로 이글거리는 협곡, 남쪽으로 불타는 평원과 닿아 있다. 타우릿산은 자신이 푼 마력에 죽고 말았지만 살아남은 그의 동족들은 결국 라그나로스와 그의 정령들에게 노예로 잡히고 말았다. 그들은 오늘날까지도 검은바위 첨탑 속에 남아있다.'),
(1928, 'koKR', '사랑하는 고향 땅을 잃게 된 와일드해머 부족은 가슴이 아팠다. 이에 브론즈비어드 왕이 와일드해머 부족에게 아이언포지에서 살 곳을 마련해주려 했지만 와일드해머 부족은 단호히 거절했다. 카드로스는 부족을 이끌고 북쪽의 로데론으로 향했다. 동부 내륙지의 푸른 숲에 정착한 와일드해머 부족은 맹금의 봉우리라는 도시를 세우고, 그곳에서 자연과 더욱 가까워지며 그 지역의 강대한 그리핀과도 유대 관계를 갖게 되었다.'),
(1942, 'koKR', '아제로스에서 메디브가 태어날 즈음, 책략가 킬제덴은 뒤틀린 황천에서 자신의 추종자들에 둘러싸여 골똘히 생각에 잠겨 있었다. 그가 주인으로 섬기는 살게라스로부터 명령을 받은 이 교활한 악마 군주는 아제로스에 대한 불타는 군단의 2차 공격을 계획하고 있었다.'),
(1952, 'koKR', '서리늑대부족의 듀로탄 족장이 그 중 하나로, 그는 오크족이 증오와 분노에 굴복하는 것에 대해 경고했다. 하지만 전쟁노래부족의 그롬 헬스크림과 같이 전쟁과 정복의 새로운 시대를 주도하고자 하는 더욱 강력한 족장들이 등장하면서 듀로탄의 경고는 무시되고 말았다.'),
(1955, 'koKR', '새로운 피의 욕망에 사로잡힌 오크족은 자신들의 길을 가로막는 자에게 그 분노를 폭발했다. 굴단은 때가 된 것을 느끼고 전쟁을 벌이고 있는 부족들을 통일해 단 하나의 멈출 수 없는 군단, 호드를 만들었다.'),
(1959, 'koKR', '킬제덴이 호드의 아제로스 침공을 준비하는 동안 메디브는 살게라스로부터 자신의 영혼을 지키기 위해 힘겨운 싸움을 계속하고 있었다. 스톰윈드의 고귀한 군주, 레인 국왕은 자신의 옛 친구의 영혼을 타락시키는 듯한 어둠을 점점 더 경계하게 되었다.'),
(1960, 'koKR', '레인 국왕은 전투 부관으로 임명된, 아라시 혈통의 마지막 자손인 안두인 로서와 근심을 나누었다. 하지만 서서히 광기에 빠져들고 있는 메디브가 가져오게 될 재앙에 대해서는 어느 누구도 예상하지 못했다.'),
(1963, 'koKR', '메디브와 어둠의 의회 흑마법사들은 힘을 모아 어둠의 문이라고 하는, 차원을 넘나들 수 있는 통로를 열었다. 아제로스와 드레노어 사이의 먼 차원을 연결해 주는 이 문은 군대가 지날 수 있을 정도로 큰 크기였다. 굴단은 오크 정찰병을 어둠의 문 반대편으로 보내 자신들이 정복할 땅에 대해 조사하도록 했다. 돌아온 정찰병들은 아제로스 세계를 정복할 적당한 때가 되었다고 어둠의 의회에 자신 있게 보고했다.'),
(1967, 'koKR', '몇 년 후, 대다수의 오크 호드가 아제로스로 건너왔고 굴단은 인간에게 첫 공격을 감행할 때가 왔다고 판단했다. 호드는 아무 것도 눈치 채지 못하고 있는 스톰윈드 왕국을 전력을 다해 공격하기 시작했다.'),
(1969, 'koKR', '자신의 본능을 따르기로 한 로서는 메디브의 젊은 수습생, 카드가의 도움으로 메디브의 탑 요새 카라잔을 급습했다. 카드가와 로서는 이번 충돌의 근본 원인으로 확인된 악마에 홀린 수호자 메디브를 처치하는 데 성공했다.'),
(1972, 'koKR', '그의 오랜 동지인 듀로탄은 유배에서 돌아와 굴단의 배반에 대해 다시 한번 경고해 주었다. 그러나 굴단은 즉시 자객들을 보내어 듀로탄과 그의 가족을 모두 살해하여 보복을 했고 오직 듀로탄의 젖먹이 아들만이 살아남게 되었다. 둠해머는 애델라스 블랙무어라는 인간 장교가 듀로탄의 젖먹이 아들을 발견하여 노예로 삼은 사실을 알지 못했다.\r\n\r\n바로 그 젖먹이 오크가 훗날 오크족 역사상 가장 위대한 지도자로 등장하게 된다.'),
(1973, 'koKR', '듀로탄의 죽음에 분개한 오그림은 악마의 타락으로부터 호드를 구하기 위해 나섰고 마침내 굴단의 타락한 꼭두각시, 블랙핸드를 처치하고 호드 대족장의 자리에 올랐다. 그의 과감한 지도력 아래, 냉혹한 호드는 마침내 스톰윈드 요새를 포위 공격했다.'),
(1974, 'koKR', '호드의 힘을 지나치게 과소평가했던 레인 국왕은 자신의 왕국이 녹색 피부를 가진 침략자들의 발 아래 무너지는 것을 가만히 지켜봐야만 했다. 결국 레인 국왕은 어둠의 의회 최고의 암살자 중 하나인 반오크, 가로나의 손에 암살되고 말았다.'),
(1978, 'koKR', '또한 로서는 빛의 수호자 우서와 댈린 프라우드무어 제독, 투랄리온과 같은 부관들의 도움으로 눈 앞에 닥친 위협에 대해 로데론의 반인 종족을 설득할 수 있었다. 얼라이언스는 아이언포지의 무뚝뚝한 드워프족과 쿠엘탈라스의 소수의 하이 엘프들의 지원을 얻는 데 성공했다.'),
(1981, 'koKR', '2차 대전쟁의 장대한 전투는 대규모 해전에서 대규모 공중 혼전까지 그 범위가 실로 넓었다. 우여곡절 끝에 호드는 악마의 영혼이라 불리는 강력한 유물을 발굴했고 그것을 이용해 고대의 용, 여왕 알렉스트라스자를 노예로 만들었다. 호드는 그녀의 소중한 알을 파괴해 버리겠다고 위협하며 알렉스트라스자에게 그녀의 자식들인 성체가 된 용들을 전쟁에 내보낼 것을 강요했고 숭고한 붉은용들은 어쩔 수 없이 호드를 위해 싸워야만 했다. 아주 치열하게...'),
(1982, 'koKR', '이 전쟁은 카즈 모단과 로데론, 아제로스 대륙 전체를 휩쓸었다. 호드는 북방 전쟁의 일환으로 경계지인 쿠엘탈라스를 불질러 파괴하는 데 성공했으며 이로 인해 엘프들은 결정적으로 얼라이언스의 대의에 대한 헌신을 다짐하게 되었다. 이 전투로 로데론의 보다 큰 도시와 마을들이 남김 없이 파괴되었다. 증원군도 없이 압도적인 수적 열세 상황에서 싸웠음에도 불구하고 로서와 그의 동맹군은 적을 더 이상 접근하지 못하도록 하는 데 성공했다.'),
(1983, 'koKR', '하지만, 2차 대전쟁 말, 얼라이언스에 대한 호드의 승리가 거의 확실시 되었을 무렵 아제로스에서는 가장 강력한 두 오크 부족 간에 격렬한 싸움이 일어났다. 둠해머가 얼라이언스의 나머지 병사들을 쳐부수기 위해 수도인 로데론에 대한 마지막 공격을 준비하고 있을 때, 굴단과 그의 추종자들은 각자의 임무를 뒤로 한 채 바다로 향했다.'),
(2005, 'koKR', '넬쥴의 무력한 영혼을 사로 잡고 있던 킬제덴은 그에게 불타는 군단을 섬길 것인가 아니면 영원한 고통에 시달릴 것인가에 대한 마지막 선택권을 주었다. 무모하게도, 넬쥴은 다시 한번 이 악마의 서약에 동의했다. 넬쥴의 영혼은 뒤틀린 황천의 깊숙한 곳에서 가져온, 특별히 만들어진 다이아몬드처럼 단단한 얼음 덩어리 속에 안치되었다.'),
(2006, 'koKR', '넬쥴은 이 얼음 속에 갇힌 채 자신의 의식이 만 배나 확장되는 것을 느꼈다. 악마의 혼돈 마력으로 뒤틀린 넬쥴은 헤아릴 수 없는 힘을 가진 유령과 같은 존재로 변했다. 바로 그 순간, 넬쥴이라는 이름의 오크는 영원히 사라지고 리치 왕이 탄생한 것이다.'),
(2008, 'koKR', '때가 됐을 때, 킬제덴은 리치 왕이 어떤 임무를 수행하기 위해 창조되었는지를 설명해주었다. 넬쥴의 임무는 아제로스 전역에 죽음과 공포의 역병을 퍼뜨려 인간 문명을 영원히 말살시키는 것이었다. 이 끔찍한 역병으로 죽은 이들은 언데드로 환생하게 되었고 그들의 영혼은 넬쥴의 철통 같은 의지에 영원히 묶이게 될 것이었다.'),
(2012, 'koKR', '킬제덴은 넬쥴이 든 얼음 수정을 아제로스의 세계로 내던졌다. 단단한 수정은 밤하늘을 가르며 날아가 북극의 황량한 대륙, 노스렌드에 떨어져 얼음왕관 빙하 속 깊숙이 묻혔다. 떨어질 때의 심한 충격으로 모양이 일그러지고 손상된 이 얼어붙은 수정은 왕좌의 모양을 띠게 되었고 곧 그 속에서 복수심에 불타는 넬쥴의 영혼이 움직이고 있었다.'),
(2017, 'koKR', '그 후 몇 달 동안 넬쥴은 계속해서 불사의 역병을 시험하며 노스렌드에 거주하는 모든 인간들을 정복했고, 날마다 늘어나는 언데드 군단을 보며 진정한 시험의 때가 다가오고 있다는 것을 알았다.'),
(2021, 'koKR', '분노한 알렉스트라자의 용들은 그림 바톨을 파괴하고 붉은용부족의 절반 이상을 태워 없애버렸다. 네크로스가 계획한 오크의 재통일이라는 원대한 꿈은 얼라이언스 군대가 나머지 오크 생존자들을 붙잡아 수용소에 가둬버림으로써 물거품으로 사라졌다. 붉은용부족의 패배는 호드의 종말, 그칠 줄 모르는 오크의 피를 향한 열망에 대한 종말을 알린 것이었다.'),
(2027, 'koKR', '그는 오크들이 아제로스에 처음 침입하기 전부터 이미 이 힘에 타락되어 있었을 것이라고 주장했다. 그러면서 악마들이 오크의 피에 마력을 불어넣어 야만적인 오크의 힘과 체력, 공격성이 비정상적으로 향상된 것이라고 추측했다.'),
(2029, 'koKR', '증세가 분명했지만 안토니다스는 오크의 무기력증을 치유할 방법을 찾지 못했다. 그때도 마찬가지로, 많은 동료 마법사들을 비롯하여 몇몇 이름 있는 얼라이언스 지도자들도 오크를 위해 치료법을 찾는다는 것은 신중하지 못한 행동이라고 비난했다. 수수께끼 같은 오크의 상태를 두고 고심하던 안토니다스는 영적인 방법으로만 오크를 치유할 수 있다는 결론을 내렸다.'),
(2030, 'koKR', '수용소 최고 교도소장인 애델라스 블랙무어는 그의 감옥 요새 던홀드에서 오크 포로들을 감시하고 있었다. 그 중 한 오크가 항상 그의 주의를 끌었는데, 그는 바로 자신이 약 18년 전에 주워 기른 고아 젖먹이였다. 블랙무어는 이 어린 오크 아이를 자신이 가장 총애하는 노예로 키우며 `스랄`이라는 이름을 지어 주었다. 블랙무어는 이 오크에게 전술과 철학, 전투에 대해 가르쳤고 투사로서의 훈련도 시켰다. 여기에는 이 오크를 하나의 무기로 만들어 내려는 타락한 교도소장의 속셈이 있었다.'),
(2037, 'koKR', '동족의 부활을 상징하기 위해 스랄은 던홀드 요새로 되돌아가 수용소를 공격함으로써 한 때 주인이었던 블랙무어의 계획을 과감히 무산시켜 버렸다. 하지만 대가 없는 승리란 없는 법, 수용소의 동족들을 구하던 중 둠해머가 전장에서 죽음을 맞이하였다.'),
(2040, 'koKR', '극악한 인간 거미 종족이 건설한 고대 지하 왕국, 아즈졸네룹이 정예 경비병을 보내 얼음왕관을 공격하고 권세를 거머쥐려는 리치 왕의 미친 시도를 끝장내려 한 것이었다. 넬쥴은 이 사악한 네룹인들이 역병뿐만 아니라 자신의 정신적 지배에도 면역성이 있는 것을 알고는 좌절했다.'),
(2042, 'koKR', '네룹인들은 역병에 대해 면역성이 있었지만 점점 커가는 강령술의 힘을 빌려 넬쥴은 이 거미 전사들의 시체를 환생시키고 자신의 뜻에 굴복시킬 수 있었다. 그들의 끈기와 대담함에 대한 증언으로, 넬쥴은 네룹인들의 특이한 건축 스타일을 도입해 자신의 요새와 건물에 사용했다.'),
(2048, 'koKR', '거친 북극 황무지를 몇 달 동안 오래 돌아다닌 켈투자드는 마침내 암흑 빙하, 얼음왕관에 도달했다. 그는 넬쥴의 암흑 요새에 당당히 다가갔다. 그런데 마치 그를 기다리고 있기라도 한 듯 언데드 경비병들이 아무 말 없이 그를 지나가게 해주었고 켈투자드는 이에 놀랐다.'),
(2049, 'koKR', '켈투자드는 차가운 땅 속으로 깊숙이 내려가 빙하 바닥에 이르렀다. 그곳, 끝없는 얼음 동굴과 암흑 속에서, 그는 얼음 왕좌 앞에 엎드려 자신의 영혼을 죽은 자들의 어둠의 지배자에게 바쳤다.'),
(2051, 'koKR', '이 대마법사가 임무를 완수하는 것을 도와주기 위해 넬쥴은 켈투자드의 인간성을 그대로 두었다. 나이가 들었어도 아직 강한 카리스마를 갖고 있던 켈투자드는 환각 능력과 설득력을 이용해 로데론에서 시민 자격을 박탈 당하고 학대 받는 무리들에게 신뢰감을 심어 주라는 지시를 받았다. 일단 그들의 주목을 받게 된 후, 사회에 대한 새로운 이상과 그들의 왕이라 부를 새로운 인물을 제시하게 될 것이었다.'),
(2054, 'koKR', '로데론에서 있었던 켈투자드의 성공으로 리치 왕은 인간 문명에 대한 공격을 감행하기 위한 마지막 준비를 마쳤다. 그의 역병의 힘을 역병 가마솥이라는 이동 가능한 용기 여러 개에 담은 후, 넬쥴은 켈투자드에게 이 가마솥들을 로데론으로 수송하라고 명령했다. 그리고 그곳에서 이교도 집단이 장악한 여러 마을 안에 가마솥들을 숨겨 놓을 계획이었다.'),
(2056, 'koKR', '리치 왕의 계획은 완벽하게 성공하여 로데론 북부 마을들 중 다수가 거의 즉시 오염되었다. 노스렌드에서와 마찬가지로, 역병에 걸린 주민들은 죽음을 맞았고 그 후 리치 왕의 자발적인 노예로 되살아났다.'),
(2066, 'koKR', '아서스의 두려움과 결의는 점점 파멸로 이어졌다. 그는 역병의 위협을 영원히 제거하기 위해 노스렌드까지 역병의 근원을 추적했다. 하지만 오히려, 아서스 왕자는 결국 리치 왕의 엄청난 힘 앞에 무릎을 꿇고 말았다. 아서스는 그의 백성을 구하는 길이라 생각하고 저주 받은 룬문자 검, 서리한을 집어들었다.'),
(2068, 'koKR', '아서스는 자신이 적으로 생각한 모든 이들을 물리쳤지만 그 후에도 계속해서 켈투자드의 유령에게 시달렸다. 켈투자드의 유령은 리치 왕이 세운 계획의 다음 단계를 실행하기 위해서는 자신이 환생해야 한다고 얘기했다. 아서스는 그를 환생시키기 위해서 하이 엘프의 영원한 왕국, 쿠엘탈라스 안에 숨겨져 있는 신비한 태양샘으로 켈투자드의 시체를 가져가야만 했다.'),
(2073, 'koKR', '1만 년이 지난 후 강력한 악마 아키몬드와 그의 수하들이 다시 한번 아제로스 세계에 들어왔지만 그들의 최종 목적지는 달라란이 아니었다. 킬제덴의 직속 수하에 있는 아키몬드와 그의 부하 악마들은 언데드 스컬지를 따라 칼림도어로 향했다. 세계수, 놀드랏실을 파괴하러 가는 것이었다.'),
(2075, 'koKR', '하지만 수세대에 걸쳐 쌓인 서로 간의 증오때문에 오크와 인간의 동맹은 결코 이루어질 수 없었다. 메디브는 하는 수 없이 각 종족을 개별적으로 상대해 예언과 속임수를 써서 그들을 바다 건너에 있는 전설의 대륙, 칼림도어로 인도했다. 곧 오크와 인간들은 오랜 세월 동안 숨겨져 있던 칼도레이 문명을 마주하게 되었다.'),
(2078, 'koKR', '결국, 헬스크림은 스랄을 도와 맨 처음 자신의 증오와 분노의 혈통으로 오크족에게 저주를 내렸던 악마 군주 만노로스를 물리침으로써 스스로를 구원했고  만노로스의 죽음으로 오크의 피의 저주는 마침내 종결되었다.'),
(2093, 'koKR', '이 즈음, 언데드 스컬지는 로데론과 쿠엘탈라스를 유독한 역병지대로 본질적으로 변형시켜 버렸다. 그곳에는 아주 소수의 얼라이언스 저항 세력만이 남아 있었다. 그 중 하나는 주로 하이 엘프들로 이루어진 무리로, 선스트라이더 왕조의 마지막 후손인 캘타스 왕자가 이끌고 있었다.'),
(2097, 'koKR', '리치 왕, 넬쥴은 자신의 시간이 얼마 남지 않았다는 것을 알았다. 얼음 왕좌 안에 갇힌 그는 킬제덴이 첩자를 보내 자신을 파멸시킬 것이라 생각했다. 얼음 왕좌는 일리단의 마법 주문의 영향을 받아 손상되었고 이에 따라 리치 왕은 날마다 그 힘을 잃어 가고 있었다. 스스로 자신을 구하기를 간절히 원하던 그는 가장 아끼는 필멸의 신하, 죽음의 기사 아서스 왕자를 곁에 불러들였다.'),
(2098, 'koKR', '리치 왕이 쇠약해짐에 따라 그 자신의 힘도 약해진 아서스는 로데론에서 내란을 수습하고 있었다. 언데드 군대 중 절반이 밴시 실바나스 윈드러너의 지휘 아래 언데드 제국을 장악하기 위한 쿠데타를 일으킨 것이었다. 리치 왕의 부름을 받은 아서스는 역병지대 전역에서 전쟁의 물결이 거세어져 가는 와중에 스컬지를 자신의 부관, 켈투자드의 손에 맡기고 떠나야만 했다.'),
(2099, 'koKR', '결국, 실바나스와 포세이큰이라 불리는 그녀의 언데드 반란군은 폐허가 되어 버린 로데론의 수도를 점령했다. 허물어진 이 도시 밑에 자신들의 보루를 건설한 포세이큰은 스컬지를 물리치고 이 땅에서 켈투자드와 그의 졸개들을 몰아낼 것을 맹세했다.'),
(2101, 'koKR', '비록 쇠약해진 상태였지만 아서스는 결국 일리단을 제치고 얼음 왕좌에 도착했다. 아서스는 자신의 룬문자 검, 서리한으로 리치 왕의 얼음 감옥을 부수고 넬쥴의 마법 투구와 흉갑을 꺼냈다.'),
(2102, 'koKR', '상상을 초월할 정도로 강력한 투구를 머리에 쓴 아서스는 스스로 새로운 리치 왕이 되었다. 넬쥴이 계속 계획해 왔던 대로 넬쥴과 아서스의 영혼은 한데 어우러져 하나의 강력한 존재가 되었다. 아서스는 세계 역사상 가장 강력한 존재 중 하나가 된 반면, 일리단과 그의 군대는 치욕스럽게도 바깥땅으로 도망치듯 후퇴할 수밖에 없었다.'),
(2103, 'koKR', '현재 소문에 의하면, 새로운 불멸의 리치 왕 아서스는 노스렌드에 거처하며 얼음왕관 요새를 재건하고 있다고 한다. 그가 신뢰하는 부관 켈투자드는 역병지대에서 스컬지를 지휘하고 있고, 실바나스와 그녀의 포세이큰 반란군은 전쟁으로 파괴된 왕국의 작은 부분인 티리스팔 숲만을 차지하고 있다.'),
(2104, 'koKR', '필멸의 종족들은 비록 승리는 했지만 전쟁으로 갈갈이 찢긴 세계에 남아 있는 자신들을 발견했다. 스컬지와 불타는 군단은 로데론 문명을 거의 남김없이 파괴해 버렸고 칼림도어에서도 사정은 거의 마찬가지였다. 치유해야 할 숲과 묻어 두어야 할 원한, 그리고 정착해야 할 고향 땅이 있었다. 전쟁은 각 종족에게 깊은 상처를 남겼지만 모두 사심을 버리고 힘을 합쳐 새로운 시작을 도모했다. 이러한 노력은 얼라이언스와 호드 사이의 불편한 휴전 협정으로 시작되었다.'),
(2106, 'koKR', '악마의 저주가 끝난 지금, 한때 호전적인 파괴자였던 호드 무리는 너그러운 상태로 변했다. 이제는 정복보다는 생존과 번영에 주력하게 된 것이다. 고귀한 타우렌과 머리 좋은 검은창 부족 트롤의 도움으로 스랄과 그의 오크들은 새로운 고향 땅에서 평화의 새 시대를 기대하고 있었다.'),
(2109, 'koKR', '프라우드무어의 대규모 함단은 그 지역의 안정에 심각한 위협을 불러왔고 2차 대전쟁에서 영웅으로 명성을 얻은 제이나의 아버지는 호드의 강한 적으로, 오크들이 다시 땅에 발붙이기 전에 듀로타를 파괴해 버리려 했다.'),
(2110, 'koKR', '총사령관 프라우드무어는 제이나에게 끔찍한 결정을 내리도록 했다. 그것은 그녀의 새로운 동족들을 배신하고 오크와의 전쟁에서 아버지를 돕느냐, 아니면 스랄과 오크족의 편에서 겨우 이루어 낸 얼라이언스와 호드 간의 깨지기 쉬운 평화를 지키기 위해 아버지와 싸우냐 하는 것이었다. 심사숙고 끝에 제이나는 후자를 선택했고 미쳐 버린 자신의 아버지를 물리치기 위해 스랄을 도왔다.'),
(2111, 'koKR', '불행히도, 제이나가 아버지와 화해하거나 오크족이 더 이상 피에 굶주린 괴물이 아니라는 것을 증명해 보이기도 전에 프라우드무어 제독은 전장에서 숨을 거두었다. 그녀의 신의를 확인한 오크들은 제이나의 군대가 고향인 테라모어로 무사히 돌아갈 수 있도록 해 주었다.'),
(2151, 'koKR', '아렐라스 파이어리프\r\n붉은십자군의 고위 마법사\r\n쿠엘탈라스 시민\r\n강령술사 디샐븐과의 영원한 전투 속에 갇힘'),
(2174, 'koKR', '홀리아 선쉴드\r\n붉은십자군의 수호자\r\n공포의 군주 벨테리스를 처치하는 도중 전사함'),
(2176, 'koKR', '스트롬가드의 오르만\r\n붉은십자군의 초대 총지휘관\r\n스트롬가드 시민\r\n얼음왕관 빙하 입구에서 실종됨'),
(2178, 'koKR', '야나 블러드스피어\r\n붉은십자군의 암살부단장\r\n달라란 시민\r\n티리스팔 숲에서 실종됨'),
(2191, 'koKR', '나이트 엘프가 불타는 군단의 분노를 불러내는 어리석은 짓을 범하기 훨씬 전인 16,000여 년 전, 트롤 종족은 당시 하나의 대륙이었던 칼림도어의 많은 부분을 지배했다. 그러다 쌍둥이 제국이 일어서게 되었으니, 남동부 밀림의 구루바시 제국과 중앙 산림지대의 아마니 제국이 그것이었다.'),
(2192, 'koKR', '북쪽 멀리, 지금의 노스렌드로 알려진 지역에는 작은 부족들이 살았다. 이 부족들은 군드라크라는 작은 국가를 세웠지만 남부 제국들만큼 영토를 확장하거나 번성하지는 못하였다.'),
(2193, 'koKR', '구루바시 제국과 아마니 제국은 서로를 미워했지만 전쟁을 치르는 일은 거의 없었다. 당시 두 제국에게 아즈아퀴르 제국이라는 커다란 공동의 적이 있었다. 아퀴르는 지능이 발달한 곤충들로서 머나먼 서쪽 지방을 지배했는데, 이들은 확장 능력이 엄청난데다 믿을 수 없을 만큼 사악했다. 아퀴르는 칼림도어 대륙에서 곤충이 아닌 생명체를 완전히 말살하겠다는 생각에 사로잡혀 있었다.'),
(2195, 'koKR', '이로 인해 두 개의 아퀴르 도시국가가 일어섰으니, 북부 황무지의 아즈졸네룹과 남부 사막의 안퀴라즈가 그것이다. 트롤은 칼림도어 땅 속에 다른 아퀴르 거주지가 있을 것이라 추측했지만 확인되지는 않았다.'),
(2197, 'koKR', '이 용감한 개척자들은 그곳에서 무한한 영원의 샘을 발견했고, 이 영원의 샘 덕분에 엄청난 힘을 가진 종족으로 변하게 되었다. 이 모험심 강한 트롤이 나이트 엘프의 근원이었다는 얘기도 전해지지만 입증된 바는 없다.'),
(2198, 'koKR', '나이트 엘프의 근원은 불분명하지만, 나이트 엘프가 힘을 갖게 된 것이 영원의 샘을 발견한 직후라는 사실은 확실하다. 트롤은 나이트 엘프의 영토 확장을 막아보려고 했으나 나이트 엘프는 강대한 제국을 건설하고 원시 칼림도어 대륙을 빠르게 점령해 나갔다. 미신을 믿는 트롤이 일찍이 상상하지도 못한 강한 마법을 휘두르던 나이트 엘프는 사악한 아퀴르마저 이루지 못한 일을 쉽게 이루고야 말았다. 바로 거대한 쌍둥이 제국을 무너뜨린 것이었다.'),
(2199, 'koKR', '나이트 엘프는 트롤의 방어선과 보급망을 조직적으로 붕괴시켜 나갔다. 나이트 엘프의 파괴적인 마법에 맞설 수 없었던 트롤은 결국 나이트 엘프의 학살에 굴복하고 말았다. 나이트 엘프는 야만적인 트롤만큼이나 교활하고 잔인하다는 것이 입증되었으며, 이로써 트롤의 영원한 증오와 경멸을 사게 되었다. 구루바시 제국과 아마니 제국은 불과 몇 년 만에 산산조각나고 만 것이다.'),
(2202, 'koKR', '이렇게 해서 아마니 제국과 구루바시 제국의 상당 부분이 오늘날의 쿠엘탈라스와 가시덤불 골짜기에 각각 남게 되었다. 아즈아퀴르 왕국인 아즈졸네룹과 안퀴라즈도 오늘날의 노스렌드와 타나리스에 각각 생존해 있다.\r\n\r\n두 트롤 문명은 그들이 알았던 원시 세계의 엄청난 파괴로 인해 그 세력은 약해졌지만 불굴의 트롤은 자신들의 파괴된 도시를 재건하고 예전의 권력을 되찾으려 했다.'),
(2204, 'koKR', '영혼의 약탈자 학카르는 사악하고 피에 굶주린 영혼으로, 트롤의 부름을 듣고 그들을 도와주기로 하였다. 학카르는 피의 비밀을 구루바시 트롤에게 전해주고 가시덤불 골짜기와 남해의 일부 섬까지 그들의 문명을 확장할 수 있도록 도와주었다. 학카르는 구루바시 트롤들에게 큰 힘을 안겨주었지만 그 대가로 점점 더 많은 것을 요구하기 시작했다.'),
(2207, 'koKR', '아탈라이 사제들도 결국 수도인 줄구룹에서 쫓겨나 지도에도 없는 북쪽 늪지대에서 살아갈 수 밖에 없게 되었다. 그들은 이 늪지대에서 자신들의 몰락한 신, 아탈학카르에게 신전을 지어바치고 그 주인의 임무를 계속해 나갔다.'),
(2208, 'koKR', '나머지 구루바시 부족은 큰 내전으로 폐허가 되어버린 땅을 떠나 각자 자신들의 길을 갔다. 백골가루부족, 붉은머리부족, 검은창부족은 가시덤불 골짜기에서 각자의 땅을 차지했다. 파괴된 제국에는 불안한 평화가 찾아왔지만 어떤 이들은 학카르가 다시 이 세상에 태어날 것이며, 그날이 오면 학카르가 이 세계를 통째로 집어삼킬 것이라는 예언에 대해 말하기도 했다.'),
(2211, 'koKR', '전쟁노래부족 족장 그롬마쉬 헬스크림, 여기 잠들다.\r\n\r\n우리 부족의 저주는 그에게서 시작되어 그에게서 끝났도다.\r\n그의 이름은 우리의 고대 언어로 \"거인의 가슴\"이라는 뜻이니라.\r\n만노로스 앞에 홀로 서서 자신의 피로써 우리의 자유를 산 그는 이 이름을 수백 번 받아 마땅하도다.\r\n\r\n록타 오그아르, 내 형제여. 전쟁노래가 영원히 그치지 않기를.\r\n\r\n-호드 대족장, 스랄'),
(2216, 'koKR', '행운을 빌겠소. 그리고 우로크의 졸개들을 처치할 때 도움이 될만한 정보를 하나 알려주리다.$B$B오모크가 오우거를 처치할 때 사용하는 마법은 당신이 오모크를 죽이고 나서도 효력이 지속될 수 있소. 우로크의 졸개들과 싸울 때 오모크의 머리에 담긴 마력을 불러내야 하는데, 운이 좋으면 오모크가 우로크의 졸개들을 내리칠 수도 있소!$B$B상황에 딱 맞는 아이러니라고 생각하오.'),
(2271, 'koKR', '나타카, 버섯구름 봉우리에선 모두 무사하오. 켄타우로스가 가끔씩 공격을 해와 성가시긴 하지만 실제로 위협적인 것은 아니고 말 그대로 성가신 것 뿐이오. 하지만 켄타우로스 부족이 결합하고 있다는 소문이 들리는 듯하오.\r\n\r\n\r\n우리는 항상 켄타우로스처럼 무자비한 종족이 단결하면 어떤 위협이 될까 궁금했는데... 그런 생각은 될 수 있으면 하고 싶지 않소. 알다시피 그 어떤 것도 녀석들이 가진 순수한 증오를 뚫을 수는 없소. 서로에 대한 증오까지도 말이오.\r\n\r\n\r\n- 절벽파수꾼 롱혼\r\n'),
(2291, 'koKR', '대주교 알론수스 파올\r\n\r\n빛의 교회의 인자한 수호 성인.\r\n\r\n그는 로데론의 스트라솔름에서 자선 행위를 시작했으며 과거에도 스톰윈드 주민들의 좋은 친구였다. 2차 대전쟁 후의 암울한 시대에는 노스샤이어의 결사단의 개혁을 돕고 스톰윈드를 다시 건설하는데 필요한 막대한 자금을 모금했다.\r\n\r\n이 대성당은 성스러운 빛의 보루일 뿐만 아니라 한 인간의 고귀한 영혼과 아량에 대한 영구불변의 증거인 것이다.'),
(2292, 'koKR', '린 가문의 국왕 레인 1세\r\n\r\n스톰윈드의 군주\r\n\r\n아제로스의 수호자'),
(2293, 'koKR', '얼라이언스 함대의 사령관\r\n\r\n스톰윈드의 친구'),
(2294, 'koKR', '여군주 마라 포드래곤\r\n\r\n스톰윈드의 고위성직자\r\n\r\n1차 대전쟁 후에 로데론으로 피난간 사람들의 수호 성인.\r\n\r\n그녀는 미래의 현명한 어머니상이었다. 성스러운 빛의 품에서 편히 쉬기를.'),
(2304, 'koKR', '여군주 마라 포드래곤\r\n\r\n스톰윈드의 고위성직자\r\n\r\n1차 대전쟁 후에 로데론으로 피난간 사람들의 수호 성인.\r\n\r\n그녀는 미래의 현명한 어머니상이었다. 성스러운 빛의 품에서 편히 쉬기를.'),
(2377, 'koKR', '다로우샤이어 연대기\r\n\r\n서쪽의 다로미어 호수에서 그 이름이 유래한 다로우샤이어는 로데론의 남쪽 구릉지 안쪽에 위치한 마을이다. 다로우샤이어는 보잘것없지만 주민들이 근면하기로 소문이 자자하며 2차 대전쟁 이전에는 로데론 역사의 뒷전에 머물러 왔을 뿐이다.\r\n\r\n그 전쟁 중 많은 영웅들이 탄생했고 사라져 갔다.'),
(2378, 'koKR', '다로우샤이어 전투\r\n\r\n다로우샤이어 전투는 스컬지 병력이 로데론을 쑥대밭으로 만든 2차 대전쟁이 한창 벌어지고 있던 도중 일어났다. 다로우샤이어는 대부분의 얼라이언스 병력과 단절되었지만 은빛 성기사단의 파견대와 경비대장 조셉 레드패스가 이끄는 든든한 민병대원이 마을을 지켜 주었다.'),
(2379, 'koKR', '스컬지는 다로우샤이어에 산발적인 첫 공격을 시작했다. 소규모의 해골 부대와 좀비들이 습격하며 마을 외곽을 배회하다 격퇴되었다.\r\n\r\n그러나 스컬지는 병사들의 완강한 저항에도 주저하지 않고 첫 번째 공격을 한 지 얼마 지나지 않아 두 번째 공격을 해왔다. 놀 군주 호르구스의 부하인 놀 용사들이 소리를 지르며 언덕을 내려와 포위된 다로우샤이어의 병사들과 격돌했다.'),
(2380, 'koKR', '민병대원들은 약해졌지만 은빛 성기사단의 성기사들이 구원이 되었다. 다로우샤이어 출신인 그들의 지도자 다빌 크록포드가 임박한 공격 소식에 추종자들을 데려와 병사들과 함께 호르구스의 부하들을 저지했다.\r\n\r\n마침내 호르구스가 직접 전투에 참가했을 때 그는 다빌과 맞닥뜨렸다. 장시간의 격투 끝에 마침내 다빌이 승리를 거두었지만 치명적인 부상을 입어 놀 군주를 굴복시킨 후 곧 죽음을 맞이하게 되었다.'),
(2381, 'koKR', '전투는 계속되었고 경비대장 조셉 레드패스는 그의 민병대를 용감하게 이끌었다. 죽음의 기사 검은 마르두크가 경비대장을 타락시키지 않았더라면 전쟁에서 승리했을지도 모른다.\r\n\r\n격투 중 마르두크가 말을 타고 레드패스에게 접근하여 흑마법으로 레드패스의 영혼을 끌어내서 용감한 경비대장을 사악한 어둠의 존재로 만들었다.'),
(2382, 'koKR', '타락한 경비대장 레드패스는 타락한 영혼을 다로우샤이어의 병사들에게 퍼뜨려 동지들을 배신하고 학살하게 만들었다.  그 후 그들은 집에 숨어 있던 다로우샤이어 주민들을 모두 학살했다.\r\n\r\n남은 스컬지 군대는 타락한 경비대장 레드패스의 영혼과 함께 참혹하게 유린된 다로우샤이어 마을을 떠난 후 로데론으로 쳐들어가 2차 대전쟁에 더 많은 고통과 죽음을 안겨 주었다.'),
(2383, 'koKR', '약탈자 호르구스의 운명\r\n\r\n약탈자 호르구스는 다로우샤이어 전투에서 패배했지만 그가 지니고 있던 사악함은 완전히 사라지지 않았다. 승리한 스컬지 병력은 다로우샤이어의 전쟁터에서 그의 머리를 가져다가 살아있는 자들과 마주칠 때마다 그들에게 공포감을 심어 주었다.\r\n\r\n며칠 후 호르구스의 머리를 가지고 있던 스컬지 일당은 은빛 성기사단에 패배했고 호르구스의 머리는 검은나무 호수에 버려졌다.'),
(2384, 'koKR', '검은 마르두크의 운명\r\n\r\n마르두크는 2차 대전쟁에서 살아남아 룬이 박힌 사악한 검으로 많은 이들을 고통과 죽음으로 내몰았다. 마르덕은 여전히 살아 있지만 코린 삼거리 근처에서 일어난 전투에서 그 검을 잃게 되었다. 드워프 대장이 마법의 방패로 그의 검을 산산조각내어 마르두크를 몰아냈고 결국 얼라이언스에게 승리를 안겨 주었다.\r\n\r\n마르두크의 검은 땅 밑으로 가라앉아 협곡을 빨아들이며 대지를 오염시켰고 현재의 오염의 흉터가 생기게 되었다.'),
(2385, 'koKR', '다빌 라이트포지의 운명\r\n\r\n다빌 라이트포지는 다로우샤이어 전투에서 사망했지만 그의 용기는 전쟁기간 동안 얼라이언스를 고무시키기에 충분했다.\r\n\r\n한편 그가 쓴 책인 성기사의 성서가 붉은십자군에 의해 발견되었다. 현재 붉은십자군이 지배하는 하스글렌의 마을 회관에 보관되어 있으며 다빌의 힘을 본받으려는 십자군들이 종종 이 책을 읽기도 한다.'),
(2386, 'koKR', '조셉 레드패스의 운명\r\n\r\n조셉 레드패스는 다로우샤이어 전투에서 사망했다. 그의 영혼은 타락하여 새로운 모습으로 태어났고 로데론에 가공할 악을 퍼뜨렸다.\r\n\r\n타락한 레드패스는 안돌할의 동쪽에 있는 가론의 흉가에서 마침내 얼라이언스에 패배했다. 그의 방패는 아직도 역병 걸린 농장에 있으며 스컬지의 앞잡이들은 여전히 그의 사악함에 대한 기억에 이끌리곤 한다.'),
(2390, 'koKR', '조셉 레드패스의 운명\r\n\r\n조셉 레드패스는 다로우샤이어 전투에서 사망했다. 그의 영혼은 타락하여 새로운 모습으로 태어났고 로데론에 가공할 악을 퍼뜨렸다.\r\n\r\n타락한 레드패스는 안돌할의 동쪽에 있는 가론의 흉가에서 마침내 얼라이언스에 패배했다. 그의 방패는 아직도 역병 걸린 농장에 있으며 스컬지의 앞잡이들은 여전히 그의 사악함에 대한 기억에 이끌리곤 한다.'),
(2391, 'koKR', '카를린 레드패스의 운명\r\n\r\n경비대장 조셉 레드패스의 형제인 카를린은 다로우샤이어 전투에서 패배했다. 카를린은 심한 부상을 입었지만 죽지는 않았다.\r\n\r\n전투가 끝나고 며칠 후 은빛 여명회의 대원들이 코린 삼거리 근처에서 갈증과 열병으로 약해진 채 방황하고 있던 카를린을 발견하여 카를린을 치료하고 희망의 빛 예배당으로 데려갔다.\r\n\r\n그들의 자비에 감사하며 카를린은 은빛 여명회에 합류했고 이제 스컬지에 대항해 복수의 전투를 치르고 있다.'),
(2410, 'koKR', '카를린 레드패스의 운명\r\n\r\n경비대장 조셉 레드패스의 형제인 카를린은 다로우샤이어 전투에서 패배했다. 카를린은 심한 부상을 입었지만 죽지는 않았다.\r\n\r\n전투가 끝나고 며칠 후 은빛 여명회의 대원들이 코린 삼거리 근처에서 갈증과 열병으로 약해진 채 방황하고 있던 카를린을 발견하여 카를린을 치료하고 희망의 빛 예배당으로 데려갔다.\r\n\r\n그들의 자비에 감사하며 카를린은 은빛 여명회에 합류했고 이제 스컬지에 대항해 복수의 전투를 치르고 있다.'),
(2437, 'koKR', '샤엘라, 친구. 이 도장을 찾았기를 바라오. 난 당신을 도와주라는 부탁을 받았소. 나도 알드랏실의 세계수에 있는 그늘 협곡에 있으니 훈련을 받고 싶으면 날 찾아오면 된다는 걸 알려 주려고 이 도장을 만들었소. $B$B지금 같은 어려운 시기에 은신술을 구사하는 이들이 서로 가까이 지내는 것이 현명하다고 생각하오. 그렇지 않으면 어떻게 텔드랏실과 우리 방식을 지키겠소?$B$B시간이 나면 날 찾아오시오.$B$B-상급 도적, 프라훈 섀이드위스퍼'),
(2438, 'koKR', '안녕하시오. 검은손 도적단의 안부 인사를 전하면서 시험의 골짜기가 당신의 솜씨를 발휘하기에 좋은 곳이 되길 바라오. 이제 당신은 시험을 치러야 할 때요. 보이지 않는 누군가가 끊임없이 당신을 지켜보고 있다는 것을 잊지 마시오.\r\n\r\n내 임무는 당신의 실력을 평가하면서 큰 일을 할 실력을 갖추었다 싶을 때 검은손 도적단에 보고하는 것이오.\r\n\r\n준비가 되면 동굴 막사 깊은 곳으로 날 찾아오시오. 기다리고 있겠소.\r\n\r\n- 상급 도적, 르와그\r\n'),
(2441, 'koKR', '많은 부족들이 마법을 사용하거나 우리 선조의 영혼과 대화를 할 수 있는 것을 타고난 재능 있다고 하지만 자네 역시 그들에 못지 않는 재능이 있다는 것을 알아야 하네. 어떤 이들은 강한 무기를 휘두를 수 있는 힘이 없고, 어떤 이들은 암살자의 공격을 막아낼 기술이 없거나, 마법 시전자에게서 입은 육체적인 고통을 견뎌내지도 못한다네. 하지만 자네는 할 수 있지. 자네는 강해. 내가 더 강해지도록 도와주겠네. 나라체 야영지로 날 찾아오게.\r\n\r\n-상급 전사, 하루트 썬더혼'),
(2442, 'koKR', '마그니 폐하의 턱수염만큼이나 당신과 의논할 게 많은데 시간이 너무 부족하군. 가능한 한 빨리 눈마루 골짜기 위의 앤빌마로 날 찾아오시오. 당장 시작해야 하오.\r\n\r\n당신을 제대로 된 전사로 만들기 위해서 배울 것이 무척이나 많지만 지금은... 모두 필요 없는 일들이지. 당신이 중점적으로 익혀야 할 것은 무기를 제대로 쥐는 법, 방어구의 무게감, 그리고 적과 싸울 때 이마에 흘러내리는 땀 냄새 같은 것들이오. 그런 것들부터 차근차근 익히도록 합시다.\r\n\r\n- 스란 코르만, 상급 전사'),
(2445, 'koKR', '마법사의 길을 걷기 시작한 당신을 환영하오.$B$B앞으로 당신이 배워나가게 될 마법에는 다음과 같은 네 가지 규칙이 있소.$B$B   마법은 강력하다.$B   마법은 타락하게 한다.$B   마법은 중독성이 있다.$B   마법은 뒤틀린 황천에 사는 생물들을 시전자에게로 끌어 모은다.$B$B이 규칙들은 언제나 틀림없이 적용되는 것이오. 마법사로서의 길을 계속 걸어나가기로 했다면 이 규칙들이 당신의 운명을 지배하게 될 것이오.$B$B당신이 이 경고를 무시할 만큼 어리석다면 노스샤이어 수도원의 서재로 날 찾아오시오. 위층에서 당신을 기다리고 있겠소.$B$B- 상급 마법사, 켈덴 브레멘'),
(2449, 'koKR', '성스러운 빛의 추종자와 같은 사람들은 진정한 힘에 관심을 가지는 자들에게 어떤 형태의 비전술이든 연구해서는 안 된다는 생각을 심어 주는 사람들이 너무 많소. 하지만 이 세계 외부에서 온 것이라고 해서 모두 악한 것은 아니오. 모든 존재가 다른 이들을 제압하고 복종시키려고 애쓰는 것은 아니란 말이라오. 자신이 충분히 강하다면 바로 그런 존재들이 따르게 되어 있는 것이지.\r\n\r\n이에 대해 당신과 더 깊은 얘기를 나누고 싶소. 수도원 오른쪽 옆에 있는 묘지로 날 찾아오시오.\r\n\r\n- 상급 흑마법사, 드루실라 라 살르'),
(2455, 'koKR', '동물 조련사에, 일급 사격수에, 그리고 인정받는 추적자에, 또 뭐가 되고 싶은 것이오? 모두 상당한 지혜와 엄청난 끈기가 필요한 일들이지.$B$B사냥꾼의 길은 결코 쉽지 않소. 우리 말단 소총병 실력만큼이라도 되려면 많은 훈련이 필요할 거요. 내가 여기 있는 이유도 다 그때문이지.$B$B눈마루 골짜기가 내려다 보이는 앤빌마에서 기다리고 있겠소.$B$B- 상급 사냥꾼, 토르가스 그림슨'),
(2458, 'koKR', '지난 밤 꿈에 영혼들이 내게 나타나 당신이 올 것이며 당신을 돕는 것이 내 임무라고 말해 주었소. 자연, 영혼들, 대지모신, 그리고 심지어는 나이트 엘프까지, 우리가 함께할 짧은 시간 동안 의논해야 할 게 무척 많소이다. 하지만 이런 교훈들은 당신이 올 때까지 접어두도록 하지. 그리고 당신 앞에 놓인 난관에 대한 준비는 내가 전력을 다해 도와 주겠소.\r\n\r\n지혜가 당신을 인도하기를 바라오. 당신을 기다리고 있겠소.\r\n\r\n- 상급 두루이드, 가트 미스트러너'),
(2459, 'koKR', '당신이 준비가 되었다는 소식을 듣자마자 이 도장을 보냈소. 세나리우스의 모든 드루이드들이 새로운 드루이드가 늘어나고 있다는 것에 대단히 만족하고 있소. 정령들마저도 강화된 우리를 보고 더 강해진 것 같소. 때가 될 때까지 참을성 있게 기다린다면 우리의 힘도 예전의 위대함을 되찾게 될 것이오. 준비가 되면 알드랏실 꼭대기 근처에 날 찾아오시오. 당신이 그늘 협곡에서 지내는 동안은 내가 안내자가 되어 주겠소이다.$B$B-상급 드루이드, 마르단트 스트롱오크'),
(2460, 'koKR', '안녕하시오, 젊은 $c|1이여;여;. 바람이 당신이 올 거라는 소식을 전해 주었소. 대지는 당신의 강인함을 칭찬하더니 이제는 고대 영혼들이 당신이 이룰 업적에 대해 속삭이는군. 우리 타우렌들은 언제나 현명하고 위대한 지도자를 필요로 한다오. 지도자들은 종종 그 두 가지 미덕을 우리에게서 찾으려고 하지. 원한다면 주술사의 길을 더 가르쳐 주겠소.\r\n\r\n붉은구름 고원에 있는 나라체 야영지로 찾아오면 그때 더 얘기하기로 하겠소.\r\n\r\n-상급 주술사, 밀라 던스트라이더'),
(2462, 'koKR', '안녕, $g형제:자매;여. 정령들이 네가 우리 동맹을 도울 준비가 되었다고 하네. 넌 정령들과 깊은 유대감을 가지고 있고, 나와 처음 수련을 시작했을 때보다 훨씬 더 강력해졌지. 이제$B$B널 시련의 계곡에 있는 오크 주술사 훈련관 시크릭에게 보내겠다. 그녀는 네가 자기에게 배우러 올 거라는 걸 이미 알고 있어. 우리 조상들을 자랑스럽게 만들어주도록. 다시 만날 때까지, 불꽃이 너를 따뜻하게 해주고 바람이 네 등 뒤에서 불어오길.$B$B이시요'),
(2464, 'koKR', '어떤 이들은 우리를 용보다 더 두려워하고, 또 어떤 이들은 최고의 실력을 자랑하는 대장장이보다도 우리를 부러워하지. 또 어떤 이들은 전투에서 우리가 보여주는 힘을 칭송하기도 하고, 어떤 이들은 우리의 신념을 매우 높이 평가하오. 심지어는 우리가 술을 더 잘 마신다고 질투하는 이들도 있소! 하지만 $c|1이여;여;, 이것만은 알아두시오. 당신은 아제로스의 최정예 수호자 중 하나요. 우리가 수호하는 성스러운 빛이 우리에게 힘을 주고 있지.$B$B이 땅에 대해 조금 더 알게 되면 그때 더 자세히 얘기해 주겠소. 눈마루 골짜기 위에 있는 앤빌마로 날 찾아 오시오.$B$B-상급 성기사, 브로모스 그럼너'),
(2465, 'koKR', '훌륭한 사제가 되려면 이 세상과 교감하는 것이 상당히 중요합니다. 지혜와 연민의 감정을 가지면 도움이 절실하게 필요한 이들을 도울 수 있습니다. 지나친 열의와 현명하지 못한 결단은 다른 이들이 강해지는 것을 방해하거나 심지어 해를 끼칠 뿐입니다.\r\n\r\n내 말을 이해할 수 있는 단계에 이르렀으니 도움이 되는 새로운 능력과 마법을 배워야 합니다. 당신을 가르치는 것이 내 역할입니다. 준비가 되면 노스샤이어 수도원의 서재로 나를 찾아오십시오.\r\n\r\n-상급 여사제, 아네타'),
(2466, 'koKR', '성스러운 빛이 우리를 환하게 비추고 매일같이 새로운 발견이 이루어지고 있으니, 지금이야말로 아이언포지의 자랑스러운 일원이 되기에 아주 적절한 때입니다. 탐험가 연맹에서는 아주 오래전에 잃어버린 수수께끼의 해답을 찾기 위해 날마다 노력하고 있습니다. 이제 당신도 우리의 일원이 되었으니 접경 지역을 위협하는 트로그와 다른 존재들에 맞서 함께 싸웁시다.$B$B시간이 날 때 찾아오십시오. 언덕 바로 위에 있는 앤빌마에 있겠습니다.$B$B- 상급 사제, 브란스토크 칼더'),
(2467, 'koKR', '자네의 영혼이 황천에서 풀려나지 않은 것을 축복으로 여기게. 내가 자네를 이 두루마리를 받을 만한 가치가 있는 자로 평가했다는 사실을 더 큰 축복으로 여기게나.\r\n\r\n\r\n자네가 한때 알았고 또 아꼈던 자들은 이제 모두 존재하지 않네! 앞으로 지금과 같은 부자연스러운 삶을 살기 위해서는 그런 사실을 수용하는 법도 배워야 하지. 먼저 그런 사실들을 극복하는 법부터 배우길 바라네.\r\n\r\n\r\n그러다가 이제 시험해 볼 때가 되었다 싶거든 데스넬에 있는 교회로 날 찾아오게나.\r\n\r\n\r\n- 상급 사제, 어둠의사제 듀스텐\r\n'),
(2468, 'koKR', '이 도장을 잊지 않고 확인했길 바랍니다. 그대가 온다는 소식을 정령들에게서 듣고 즉시 전갈을 보내는 것입니다. 당신에게 제 경험을 가르치며 그대가 더 중요한 일을 위해 텔드랏실을 떠날 준비를 할 수 있도록 제가 옆에서 도와드리고 싶습니다.$B$B지난 몇 년 동안 많은 일들이 일어났어요. 아제로스의 많은 종족을 돕기 위해 해야 할 일이 아주 많답니다. 준비가 되면 알드랏실 2층으로 절 찾아오세요.$B$B- 상급 사제, 샨다'),
(2491, 'koKR', '그리쉬-\r\n\r\n\r\n자네의 휴가 신청을 허가한다. 가족과 함께 지내는 동안 자네 위치를 담당할 예비 타우렌 전사를 보낼 테니 일주일 후에 다시 보고하도록 하라!\r\n\r\n\r\n-마그그랜 어스바인더\r\n'),
(2512, 'koKR', '오스릭,\r\n\r\n우리에게 필요한 방어구 목록을 아래에 적어 놓았네.\r\n\r\n사슬 조끼 10개\r\n투구 20개\r\n방어구 키트 30개\r\n쇠사슬 장화 15개\r\n\r\n언제나 그렇듯이 자네에게 신세를 지는군. 서부 몰락지대에서 도적 떼들을 모두 소탕하는 날, 우리 집에 초청해서 한때 그렇게나 유명했던 서부 몰락지대만의 푸짐하고 맛있는 식사를 대접할 수 있게 된다면 내가 마음의 빚을 좀 갚을 수 있을 텐데 말이야.\r\n\r\n감시의 언덕 병참장교, 루이스'),
(2513, 'koKR', '네사, 소식을 듣게 돼서 반갑군요.\r\n\r\n보내 준 뼈와 비늘은 정말 놀라웠습니다. 본토 밖에서 그렇게 큰 물고기는 본 적이 없어요. 루테란 마을의 낚시꾼들은 매일 손쉽게 엄청난 양의 물고기를 잡아들이겠군요!\r\n그렇게 큰 물고기를 잡다니 부러우면서도 조금 걱정이 되네요. 새로운 세계수 때문에 물고기들이 그렇게 커진 것일까요? 만약 그렇다면 새로운 세계수가 또 어떤 다른 영향을 미치게 될까요?\r\n\r\n궁금해 하며, 레어드'),
(2514, 'koKR', '다음은 브록의 채광 및 측량 학부에서 장학생으로 선발되어 명예로운 광부의 곡괭이를 수여 받은 학생들의 목록이다.\r\n\r\n멜리아 스톤쉐이커\r\n바르딘 아이언밴드\r\n우미 토글볼트\r\n루미 토글볼트\r\n보렐 스틸스파이어'),
(2515, 'koKR', '고위집행관 하드렉의 명령으로 공동묘지의 재고를 유지하기 위해 다음과 같은 물품이 필요함을 공포한다.\r\n\r\n장검 12개\r\n단검 9개\r\n원형 방패 8개\r\n도끼 15개\r\n화살 1000개\r\n\r\n본 내용은 어둠의 여왕 폐하께서 직접 내리신 명령으로 간주하여야 할 것이며 이 임무를 담당하는 자와 여왕 폐하의 명을 거역하거나 달리 방해하는 자는 여왕 폐하의 부름을 받게 될 것이다.'),
(2530, 'koKR', '고위집행관 하드렉의 명령으로 공동묘지의 재고를 유지하기 위해 다음과 같은 물품이 필요함을 공포한다.\r\n\r\n장검 12개\r\n단검 9개\r\n원형 방패 8개\r\n도끼 15개\r\n화살 1000개\r\n\r\n본 내용은 어둠의 여왕 폐하께서 직접 내리신 명령으로 간주하여야 할 것이며 이 임무를 담당하는 자와 여왕 폐하의 명을 거역하거나 달리 방해하는 자는 여왕 폐하의 부름을 받게 될 것이다.'),
(2551, 'koKR', '라요,$B$B우린 이 훌륭한 모험가에게 큰 신세를 졌습니다. 이 모험가를 실리더스에 있는 당신을 도울 인력으로 파견합니다. 부디 그곳의 비밀을 밝혀 내려는 당신의 노력에 이런 훌륭한 인력을 잘 활용하기를 바랍니다. 세나리온 의회에서는 일의 진척 상황에 대한 소식을 애타게 기다리고 있습니다.$B$B세나리우스의 가호가 있기를...$B라빈'),
(2571, 'koKR', '겨울맞이 축제$B$B많은 문화권에서는 아제로스 왕국의 겨울을 변화의 시기로 간주하고 있다. 특히 드워프와 타우렌은 천지를 눈으로 뒤덮음으로써 새로운 시작을 알리는 겨울맞이의 전설을 축제의 시기로 여기며 손꼽아 기다린다. 이 전설에 대한 이해는 아제로스 종족마다 크게 다르지 않으나, 이 축제의 시기를 지내는 방법은 종족의 개성만큼이나 다양하다.'),
(2572, 'koKR', '겨울 할아버지의 전설$B$B\"겨울맞이\"라는 말은 많은 문화권에서 겨울 할아버지라 불리는 초자연적 존재를 칭하는 데서 생겨났다고 한다. 그가 얼어붙은 이 땅 위를 걸을 때면 그의 망토는 겨울 그 자체가 되어 휘날렸다. 그가 깨어나면 온 세계가 눈으로 뒤덮이니 이를 일컬어 겨울 할아버지가 겨울의 장막으로 대지를 덮는 것이라 했다. 아제로스의 일부 지역은 만년설에 싸여있다고는 하나 이 시기는 대지에 부활과 재생의 시간이다.'),
(2574, 'koKR', '타우렌$B$B타우렌과 겨울에 대한 그들의 주술신앙적 이해, 그리고 최근 나타나기 시작한 드루이드의 노력은 겨울맞이의 전설과 잘 들어맞는다. 그러나 이들은 전설의 소생적인 측면에만 관심을 기울인 채 전설의 숭배는 그들이 자연과 완벽하게 조화를 이루지 못한다고 보는 종족들에게 맡겨두고 있다. 많은 타우렌은 이 시기를 멀고어에서 새로운 고향의 축복에 대해 감사하는 시기라고 생각한다.'),
(2576, 'koKR', '최근의 동향$B$B다른 문화권에서도 겨울맞이 축제를 커다란 전통으로 인정하기 시작했으나, 똑같은 전설에서 기반이 되었지만 의미가 변질된 의식들도 있었다. 최근에는 축하와 선물 교환 외에는 전통과 전혀 관련이 없는 관습들까지 가세하는 동향을 보이기 시작한 것이다. 심지어는 겨울 할아버지의 사진까지 사용되는데, 초자연적인 티탄의 모습보다는 상업적 영웅이나 선구자의 모습에 더 가깝다.'),
(2591, 'koKR', '뾰족바위 골짜기 깊숙한 곳에 마라우돈의 성전이 있다. 그게 그렇게 큰 죄가 아니라면 내가 왜 켄타우로스가 아닌 자에게 이런 부탁을 하는 것인지 금방 알게 될 것이다.$B$B그 성전은 영혼과 우리의 성스러운 사제만이 거닐 수 있는 곳으로, 그곳에는 이름 없는 예언자라 불리는 자가 있다. 그는 영혼과 관련된 일에 있어서는 최고일 뿐 아니라 모든 일족 중에서 가장 연륜이 높은 자다.'),
(2592, 'koKR', '그 예언자는 강한 힘을 지녔고 우리 선조의 영혼과도 의사소통을 할 수 있다만 그는 바보다! 자신이 지닌 진정한 힘을 전혀 깨닫지 못하고 있지. 그는 영혼의 아뮬렛이라는 걸 지니고 있는데, 그의 힘은 대부분 그 아뮬렛에서 나오는 것이다.\r\n\r\n나는 그 아뮬렛이 강하긴 하지만 불완전하다는 것을 알아냈지.'),
(2593, 'koKR', '그 아뮬렛에는 다섯 가지 보석이 빠져 있는데 그 보석들을 찾아 다시 집어넣으면 지금의 형상이 지니고 있는 힘보다 훨씬 강력한 힘을 발휘할 거다. 내가 그 다섯 개의 보석을 찾긴 했는데 그것들을 모으려면 네 솜씨가 필요하다. 이름 없는 예언자를 처치하는 것도 그의 시체에서 물건을 훔치는 것도 명백한 이단 행동이지만, 내가 지금부터 부탁할 일은 켄타우로스로서 생각만해도 천벌을 받을 만한 일이다.'),
(2594, 'koKR', '그 아뮬렛에는 다섯 가지 보석이 빠져 있는데 그 보석들을 찾아 다시 집어넣으면 지금의 형상이 지니고 있는 힘보다 훨씬 강력한 힘을 발휘할 거다. 내가 그 다섯 개의 보석을 찾긴 했는데 그것들을 모으려면 네 솜씨가 필요하다. 이름 없는 예언자를 처치하는 것도 그의 시체에서 물건을 훔치는 것도 명백한 이단 행동이지만, 내가 지금부터 부탁할 일은 켄타우로스로서 생각만해도 천벌을 받을 만한 일이다.'),
(2595, 'koKR', '마라우돈의 동굴에는 첫번째 칸의 영혼들이 떠돌고 있다. 우리의 창조모와 창조부의 첫 후손들이자 우리의 위대한 지도자이기도 하지. 이름은 각각 겔크, 콜크, 마그라, 마라우도스, 벵이라고 하는데, 바로 이 영혼들이 잃어버린 보석들을 하나씩 지니고 있다.'),
(2596, 'koKR', '영혼의 아뮬렛을 이용해 이 영혼들이 나타나도록 한 다음 그들에게서 보석을 빼앗아 와라! 그런 다음 보석들을 영혼의 아뮬렛에 넣어 내게 가져 오너라. 결속의 아뮬렛을 갖게 되면 나는 모든 일족들을 개혁시킬 수 있을 만큼 강해질 것이고, 그리하면 우리는 마침내 선조들이 바라던 후손이 될 수 있을 것이다.'),
(2610, 'koKR', '영혼의 아뮬렛을 이용해 이 영혼들이 나타나도록 한 다음 그들에게서 보석을 빼앗아 와라! 그런 다음 보석들을 영혼의 아뮬렛에 넣어 내게 가져 오너라. 결속의 아뮬렛을 갖게 되면 나는 모든 일족들을 개혁시킬 수 있을 만큼 강해질 것이고, 그리하면 우리는 마침내 선조들이 바라던 후손이 될 수 있을 것이다.'),
(2631, 'koKR', '<책장이 고대 엘프 룬 문자로 뒤덮여 있다.>$B$B이 책에는 강력한 마법약을 제작하는 데 필요한 재료들을 모으고 만들어내는 과정에서 일어난 사건들의 기록이 담겨 있다.$B$B우리의 적들이 이 책에 결코 접근하지 못하게 하소서. $B$B쿠엘탈라스에 다시 한번 창백한 달빛이 비치는 것을 볼 수 있게 하소서.$B$B켈타스의 은총이 아니었다면 죽음을 맞이했을 것입니다.$B$B일리단의 영광을 위해 적을 죽일 수 있게 하소서.$B$B-카리엘 윈탈루스 님'),
(2634, 'koKR', '<잉크가 페이지 위에서 소용돌이치며 이리저리 움직입니다. 책이 당신을 조롱하고 있다는 느낌이 듭니다.>'),
(2654, 'koKR', '<HTML><BODY><H1 align=\"center\">군 계급에 관한 논문</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src=\"Interface\\PvPRankBadges\\PvPRankAlliance\"/>\r\n<BR/>\r\n<P align=\"right\">얼라이언스와 호드의</P>\r\n\r\n<P align=\"right\">군 계급에 관한</P>\r\n\r\n<P align=\"right\">정보를 소개합니다.</P>\r\n\r\n<P align=\"right\">각각 장교와 일반 병사,</P>\r\n\r\n<P align=\"right\">두 부분으로 나누어져 있으며</P>\r\n\r\n<P align=\"right\">높은 계급에서 낮은 계급 순서로 나열되어 있습니다.</P>\r\n\r\n<P align=\"right\">얼라이언스여, 영원하라!</P></BODY></HTML>'),
(2774, 'koKR', '병사여, 조심하게. 이 두 탑은 모두 철통같이 요새화되어 있고 밴더의 정예 사령관 중 한 명이 다스리고 있네. 아군이 요새를 돌파하면 안에 있는 사령관이... 침묵했는지 반드시 확인하게. 그 또한 스톰파이크를 해체하는 일의 일부가 될 걸세.$B'),
(2916, 'koKR', '바즈루덴에게,\r\n\r\n어둠의 문이 다시 열린 이후 아제로스에서 명예의 요새와 스랄마에 엄청난 규모의 지원군이 도착하고 있다. 그들이 성채를 공격할 계획이며 우리가 불타는 군단과 싸워야만 할 것으로 보인다는 보고서를 받았다. 이건 있을 수 없는 일이다!\r\n\r\n피의 용광로에서의 작전을 위험에 드러낼 수는 없다! 그곳에서 양성 중인 타락한 오크가 우리의 성공을 결정할 열쇠다. 지금 즉시 성벽의 수비를 강화하고 경계 지역에 보초를 늘려라!\r\n\r\n날 믿거라. 내가 찾아가는 일이 생기기를 바라지는 않겠지?\r\n\r\n-- 일리단'),
(2925, 'koKR', '왕초보를 위한 차원의 함선 수리 완전정복, 야무스 카에시 지음\r\n\r\n<이 책의 얇은 페이지는 빛나는 재료로 만들어졌으며 책에는 차원의 함선을 유지 및 보수하는 방법에 대해 매우 전문적인 도형들로 가득합니다. 이 특별한 책은 `백터 코일 누출과 대비책`이라는 장이 펼쳐져 있습니다.>'),
(2936, 'koKR', '다트리마의 제단을 발견했습니다! 좀 더 자세히 조사한 결과 섬을 둘러싸고 있는 이상한 힘이 강력하게 파동치는 것이 느껴집니다. 제단 옆에 서 있으니 마음이 불편하고... 조금 불안해지기까지 합니다.\r\n\r\n제단 측면에 붙어 있는 금으로 된 판에는 다음과 같은 글귀가 적혀 있습니다.\r\n\r\n여기 다트리마의 제단을 세우니 한 고귀한 엘프에게 바치는 존경의 표시이니라. 이 기념물을 보는 모든 이는 우리를 살리기 위해 스컬지와 맞서 싸우다가 희생한 그의 헌신을 기억할지어다. 쿠엘탈라스에 살고 있는 모든 이의 감사를 다트리마에게 전한다.'),
(2976, 'koKR', '(1) 주정뱅이 라리크: 오우거. 결코 술집을 떠나지 않음. 야비함. 못 생겼음. 뚱뚱함. 천박함. 또한 매우 뚱뚱함.\r\n\r\n[다음 페이지]'),
(2977, 'koKR', '(2) 쿠쉬쿠쉬: 이 작고 성가신 장가르 습지대의 버섯 재배인은 장가르 습지대와 테로카르 숲의 경계선에 버섯 농장을 가지고 있음. \"냄새 알아맞추기\" 게임을 해서 살살라빔에게 많은 돈을 잃었음. 굴뚝버섯이라고 하는 쓸모 없는 버섯으로 살살라빔에게 돈을 갚기 위해 노력함. 그게 금만큼 가치가 있는 것이라나! 하!\r\n\r\n[다음 페이지]'),
(2983, 'koKR', '죽은 자들을 보려면 특수한 재료들을 모아야 합니다.\r\n\r\n우선 나그란드 서부에 있는 산악 그론의 눈이 필요합니다. 불타는 군단의 저주받은 괴철로 근처이자 전쟁망치 언덕의 남쪽입니다.\r\n\r\n그리고 나그란드 서부의 거대한 바람올빼미를 처치하고 재료를 구해야 합니다. 표본에는 절대 흠집이 나면 안 됩니다!\r\n\r\n끝으로 나그란드 서쪽과 남서쪽에서 늙은 갈래발굽의 지방덩어리를 찾아오십시오.\r\n\r\n서둘러 이 재료들을 모아서 제게 가져오십시오!\r\n\r\n-니트린'),
(2986, 'koKR', '나니가 나타나자 전사가 곤란하다는 표정을 짓습니다. \"멀록들을 죽인 데 대한 보상을 받으려고 오신 거로군요?\"\r\n\r\n그녀의 시선이 그의 옆에 있는 빛나는 브로드소드로 쏠립니다. \"그건 보상이 뭐냐에 따라 다릅니다, 마커스.\"  그녀는 장난스럽게 머리카락을 꼬면서 자신의 등장으로 그가 얼마나 불편해하는지 눈치채지 못하는 척합니다. \"제가 그걸 원하지 않을 수도 있지요.\"'),
(2987, 'koKR', '두려움과 분노로 가득한 마커스가 그녀에게 다가갑니다. \"보상은 우리 협상의 대상이 될 수 없어요!\" 그는 잠시 멈춰 서서 마음을 추스르더니 그녀의 귀여운 모습에 저항하려 애를 씁니다. 두 사람의 입술이 격렬하게 부딪히더니 뜨거운 공기의 흐름 속에서 냉기 갑옷 마법이 녹아내립니다.\r\n\r\n\"그럼 다음 임무는 뭐죠?\"라고 놀리는 그녀의 눈동자가 흥분으로 반짝입니다.\r\n\r\n<이야기의 진행 없이 이런 내용이 수백 페이지에 걸쳐 이어집니다.>'),
(2988, 'koKR', '이 이상한 물건은 일종의 기계 공학 장치로 보이지만 지금까지 당신이 봐 온 것들과 전혀 다릅니다.\r\n\r\n겉모습을 미루어 볼 때 어떤 용도로 쓰이는 물건인지는 몰라도 이미 사용된 적이 있는 듯합니다.\r\n\r\n그리고 주변에 시체들이 널려 있는 것으로 보아 살상을 목적으로 사용된 것 같습니다.'),
(2996, 'koKR', '면책 동의서.$B$B시험 조종사는 제피리움 캐퍼시토리움(이하 \"장치\") 사용 중 분쇄, 감전, 주요 장기의 둔상, 토착 생물에게 잡아먹힘, 또는 시공간 역설 현상 등의 형태로 부상, 신체 절단 또는 사망 위험이 있음을 충분히 인지하고 인정합니다. 시험 조종사는 자발적으로 장치에 탑승하며 위의 모든 위험을 스스로 감수합니다.$B$B시험 조종사는 탤리 잽내버 및 그 가족을 상대로 한 모든 부상 또는 손해 배상 청구를 포기하고 면책하며, $G그의:그녀의; 사망 시 연구 목적으로 $G그의:그녀의; 유해를 잽내버 가문에 기증하는 데 동의합니다.$B$B서명,$BX:___$n'),
(2999, 'koKR', '안토니비치,\n\n먼저 자네가 최근 보낸 요원 $n|1은;는; $g그의:그녀의; 임무를 아주 만족스럽게 수행했다고 말해두지. 나는 지금 $g그의:그녀의; 육신을 차지했고, 이렇게 $g그의:그녀의; 손으로 직접 글을 쓰고 있다. 참으로 즐겁군. 언젠가는 위대한 연금술사인 자네 몸에도 들어갈 행운이 찾아오길 바라지!\n\n자, 명령한 보고를 하겠다. 지옥불 성채에는 내가 지금껏 만난 어떤 악마보다도 강력한 악마가 도사리고 있다. 제3차 대전쟁으로 유명한 지옥의 군주 만노로스도 비슷한 힘을 지녔을 거라 생각하지만, 그런 존재는 극히 드물지. 그런데 이 악마 주변에는 어딘가 속박된 듯한 기운이 감돈다. 자신의 의지에 반해 움직이고 있거나, 어딘가에 갇혀 있거나, 혹은 더 강대한 힘의 지배를 받고 있다 해도 놀랍지 않을 것이다.\n\n시간이 지나면 알게 되겠지...'),
(3073, 'koKR', '여왕 폐하께,\n달쉼터 정원의 지맥 교차점이 푸른용군단의 제어에서 벗어나 있었다는 사실이 밝혀졌습니다. 그들의 병력은 쇄도 바늘을 사용해 쐐기돌을 파괴했지만, 힘을 마력의 탑으로 되돌리는 대신 일련의 초점을 이용해 지하의 마력을 조잡하게 끌어와 증폭한 뒤 푸른 용의 성소로 보냈습니다.\n말할 것도 없이, 마력이 지면을 뚫고 솟구친 곳마다 끔찍한 결과가 나타났습니다. 숲의 고대정령들과 칼루아크를 비롯해 지역의 여러 생물들이 악영향을 받았습니다. 다행히도 지금 여왕 앞에 서 있는 $r, $N|1이;가; 이 모든 문제를 추적하고 해결하는 데 결정적인 역할을 했습니다.\n제 생각에 $N|1은;는; 현재 사원이 직면한 문제를 해결하는 데 있어 고룡쉼터에 큰 자산이 될 수 있습니다. 제가 더없이 소중한 인재라고 판단한 $g그:그녀;|1을;를; 부디 활용해 주시길 겸허히 청합니다.\n언제나 깊은 존경을 담아,\n모데라\n대마법사이자 육인회의 일원'),
(3074, 'koKR', '여왕님께,\n\n달쉼터 정원의 지맥 교차점이 푸른용군단의 통제를 받지 않고 있었다는 사실을 발견했습니다. 그들의 병력은 쇄도 바늘을 이용해 마개돌을 파괴했으나, 힘을 마력의 탑으로 되돌리는 대신 일련의 초점 장치를 통해 지하의 힘을 어설프게 끌어와 증폭시킨 뒤 청금석 용제단으로 보내고 있었습니다.\n\n말할 것도 없이 마력이 지면을 뚫고 솟은 곳마다 심각한 피해가 발생했습니다. 숲의 고대정령과 칼루아크, 이 지역의 다른 생명체들도 악영향을 받았습니다. 지금 여왕님 앞에 서 있는 $R $N이 이 문제를 추적하고 처리하는 데 큰 도움을 주었습니다.\n\n제 생각에는 $N이 용의 안식처 사원이 현재 겪는 문제를 해결하는 데 유용한 인재가 될 수 있습니다. 제가 충분히 믿을 만하다고 판단한 인재인 만큼 $G그:그녀;를 자산으로 고려해 주시길 겸손히 청합니다.\n\n언제나 존경을 담아,\n\n에이타스 선리버\n대마법사, 6인의 의회 의원'),
(3075, 'koKR', '안녕!$B$B난 편지를 잘 못 써서 보모님이 대신 적는 걸 도와주셨어. 그냥 고맙다고 말하고 싶었어! 당신은 영웅이잖아. 언젠가 나도 당신처럼 사람들을 구할 수 있으면 좋겠어.$B$B이제 놀러 가야 해서 이만 갈게. 착하고 강한 영웅이 되어줘서 다시 한 번 고마워! 게다가 $g잘생기:예쁘;기도 하잖아!$B$B--당신의 비밀스러운 팬'),
(3093, 'koKR', '<HTML>\n<BODY>\n<BR/>\n<P>목소리가 속삭였다. \"내게로 오라.\" 처음부터 나는 꿈속에서 내게 말하는 것이 성스러운 빛임을 알았다. 마침내! 수년간의 기도와 선행 끝에, 아제로스의 땅에서 죽지 못한 자들의 역병을 정화한 끝에. 그 모든 실패와 부활 끝에.</P>\n<BR/>\n<P>마침내!</P>\n</BODY>\n</HTML>\n'),
(3094, 'koKR', '<HTML>\n<BODY>\n<BR/>\n<P>또다시 그 일이 일어났다. \"내게로 오라...\" 빛이 명령했다.</P>\n<BR/>\n<P>이번에는 얼어붙을 듯 추워서 잠에서 깼지만 내 방은 춥지 않았다. 더 열심히 해야 한다! 내일 대수도원장께 기도를 늘려달라고 말씀드리겠다. 이제 어설픈 조치는 없다!</P>\n<BR/>\n<P>성스러운 빛이 우리의 선행을 알아봐 주었다. 느낄 수 있다!</P>\n</BODY>\n</HTML>\n'),
(3188, 'koKR', '이름: 하모니\n상태: 사망\n비고: 이 죽음의 기사는 일반적인 스컬지 법을 위반한 것으로 판명. 리치 왕께서 처치.\n'),
(3501, 'koKR', '- 아군 오발! 자기 자신을 의심하지 마라. 그냥 그 주문을 써! 빗나가도 괜찮다. 비전 미사일이 설마 네 친구를 맞히겠어?$B$B- 일자리를 구해라! 실력을 키우는 훌륭한 방법은 사람들에게 도울 일이 있는지 물어보는 것이다. 괜찮은 마법사를 고용하려는 사람이 얼마나 많은지 놀랄걸! 의외겠지만 단순히 꾸러미 하나를 배달하는 일조차 더 나은 주문 시전자로 만들어줄 수 있다.$B$B- 매일매일 반복 작업! 주문 연습을 위해 아무 생각 없이 몬스터를 반복해서, 보통 여러 마리씩 잡는 마법사 이야기를 들어봤을 것이다. 강해지는 데 분명 합법적이고 효과적인 방법이지만, 너무 오래 계속하면 뇌가 썩는다.$B'),
(3530, 'koKR', '올빼미야수 - 이 깃털 달린 생명체들은 달빛야수, 올빼미곰 등 여러 이름으로 불린다. 이 온순한 거인들은 나이트 엘프와 비슷한 천부적인 드루이드 에너지를 지녔다.$B$B하피 - 깔깔대는 새 여인들은 강력한 원소 폭풍 마법을 다룰 수 있다. 그 힘의 근원은 거의 알려져 있지 않다. 이유는 1) 침입자를 보자마자 공격하고, 2) 그 날카로운 울음에서 뜻을 알아들을 수 있는 사람이 거의 없으며, 3) 둥지 냄새를 견딜 수 있는 사람이 아무도 없기 때문이다.$B'),
(3535, 'koKR', '대영주님께,\n$N은 스컬지홀름의 스컬지를 상대로 한 작전을 성공적으로 이끌어 얼음왕관으로 진군할 수 있는 위치를 확보했습니다.\n석공들은 정의의 성채 건설을 시작하는 데 필요한 물자를 모두 갖췄습니다. 수정노래 숲에서 도와준 $N의 지원에 다시 한 번 감사드립니다.\n이제 마지막 도전 하나만 남았습니다. 성전사의 봉우리를 점령하는 일입니다. 우리가 가장 큰 고통을 겪은 바로 그곳에서 이 마지막 장을 시작하고 싶습니다.\n명령을 기다리겠습니다.\n빛이 함께하시길.\n- 구스타브');
INSERT INTO `pet_name_generation_locale` (`ID`, `Locale`, `Word`, `Entry`, `Half`) VALUES
(18, 'koKR', '조브', 416, 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`) VALUES
(2785, 0, 'koKR', '물러서! 가깝게 오지 마! 가방에 폭약이 가득 들어있고 난 쓸 준비가 되어 있다고! 우리 다 같이 날아가 버릴 거야!$B$B아, 신경 쓰지 말게. 딴 사람인 줄 알았어....');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) VALUES
(81, 'koKR', '그럼, 이 술통에 뭐가 들어 있는지 한번 보자고!$B$B옳지, 옳지. 모두 제대로 들어 있는 것 같군. 자, 값 여기 있네. 수고 많았어. 이 술을 선술집에다 팔 때는 그 값의 다섯 배는 받게 되지! 하하핫!$B$B덤으로 가져온 이 동부내륙지 벌꿀 리플은 특별한 때를 위해 따로 챙겨둬야겠구만. 샴페인과 같이 마시면 좋을 거야. 이름은... 샴페리플이라고 불러야겠어.'),
(90, 'koKR', '정말 잘하셨어요, 손님! 자, 그럼 늑대 양념 케밥이라는 별미를 한번 맛보세요!'),
(206, 'koKR', '하! 해냈군요! 당신은 선을 위한 위대한 힘입니다, $N. 그 힘이 결코 시들지 않기를!$B$B이 마음의 눈을 연구해서 선한 일에 쓸 수 있는지 알아보겠습니다. 그럴 수 없다면... 파괴해야겠지요.'),
(220, 'koKR', '아, 브린이 만든 순수한 물이 담긴 병이군요. 당신이 직접 모아 주셨군요.$B$B당신에게 드릴 정기를 만들 때 이 병에 담긴 물이 꼭 필요할 거예요. 그리고 이 물은 한 가지 다른 일에도 사용될 거예요.$B$B내가 만들어주는 정기를 사용해서 언더시티의 남쪽, 은빛소나무 숲의 신전에 있는 물의 정령을 만나세요. 그 다음 임무는 그러니까... 당신이 준비가 되었다고 생각되면 그때 말해주도록 하죠.$B$B한번 더 여행을 떠날 준비가 되었나요?'),
(226, 'koKR', '수고하셨습니다. 늑대 수가 제법 줄어서 이제 늑대들이 우리를 뒤쫓아 다니지 않겠군요. 이제는 모벤트 팰을 상대하는데 총력을 기울일 수 있게 되었네요.$B$B자, 이 섬광탄 다발을 받으세요. 스벤틀 위해 마을에서 만들어서 기증해 준 것입니다.'),
(289, 'koKR', '고마워, 친구. 저주받은 동료들도 고마워할 거야.'),
(290, 'koKR', '열쇠는 녹이 슬었지만 자물쇠에 꼭 들어맞습니다.'),
(292, 'koKR', '팔레스의 눈이잖아? 놀랍군! 흠... 그런데 뭔가 이상한 것 같은데. 난파선에서 이걸 찾았다고 했나? 그렇다면 이해가 가는군. 하지만 제 3함대의 잔해에 팔레스의 눈이 있었다니...$B$B피츠시몬즈가 악몽을 꿀만도 했군그래. 분명 팔레스의 저주받은 눈은 기분 좋은 물건이 아니니까 말이야.'),
(293, 'koKR', '팔레스의 눈... 하지만 여기엔 비탄이 서려 있군. 분명히 너무나도 끔찍한 비극을 목격한 게야.$B$B내가 정화해 주도록 하겠네. 원래 팔레스의 눈은 밝은 빛을 발하도록 만들어졌지만, 지금처럼 저주로 가득하다면 매우 위험할 수도 있다네.'),
(296, 'koKR', '고맙소. 당신의 노고는 잊지 않겠소이다. 그저 묵묵히 일만 하던 무고한 드워프들이 이곳에서 수도 없이 죽어 갔소. 저 악마 같은 짐승들에게 복수해 주었으니 놈들도 다시는 마그니 폐하의 백성을 함부로 공격하지 못할 거요.'),
(304, 'koKR', '마침내 불한당 발가라스를 처치했군. 비록 녀석이 죽었다고 해서 그동안 녀석의 손에 무고하게 죽어간 드워프의 목숨을 되돌릴 수는 없지만 살아 남은 이들에게 위안은 될 걸세. 발가라스가 죽었으니 남아 있는 검은무쇠단 드워프들을 격퇴하는 건 어렵지 않겠군. 녀석들에게 새 우두머리가 부임해 오기 전에 쓸어 버려야겠네.$B$B아주 잘해 주었네.'),
(339, 'koKR', '드디어 1장이 완성되었습니다!'),
(340, 'koKR', '2장이 마침내 완성되었습니다! 잘하셨습니다!'),
(341, 'koKR', '휴! 정말 잘하셨습니다. 이제 3장을 모두 되찾았군요!'),
(348, 'koKR', '기...기운이 회복되는 것 같아요...$B$B여기는 어디인가요? 무법항? 이런! 정말 이상한 꿈을 꾸었어요.$B$B...아직 몸이 완전히 회복되지는 않은 것 같은데...'),
(376, 'koKR', '재료를 가져다 줘서 고마워요. 이 방어구가 도움이 될 거예요.$B$B이왕이면 지금 입고 계신 것보다는 더 좋은 거였으면 좋을 텐데...'),
(381, 'koKR', '조금만 더 이성적으로 생각해도 대화로 문제를 해결할 수도 있을 텐데 말이야... 안 그런가?$B$B눈먼 바보들 같으니라고!'),
(408, 'koKR', '자네의 활약으로 스컬지가 상당한 피해를 입었네. 이번 공적은 우리 포세이큰에게나 적들에게나 분명히 기억될 것이야.$B$B항상 그렇듯 계속 전력을 다해 분투해 주게. 언젠가 아제로스에서 리치 왕을 쫓아내는 날이 오고야 말 것이야!'),
(425, 'koKR', '고마워요. 정말 감사해요.$B$B상부에 보고할 때 당신에 대한 내용도 포함하겠어요.'),
(429, 'koKR', '<심장을 건네 받는 렌퍼럴>$B$B우리 죽음의추적자들이 임무에 실패했다니 낭패로군. 이런 실패는 두 번 다시 없어야 할 텐데 말이야.$B$B이번엔 물약을 직접 만들어 주겠지만, 내가 조제법을 일러 줄 테니 다음에 또 물약이 필요할 경우에는 자네가 직접 만들어 주도록 하게.'),
(442, 'koKR', '까마귀발톱 쑤울을 죽인 것은 굉장한 성과였네. 렌퍼럴이 말하기를 자네가 쑤울을 처치하는 순간, 공동묘지에서도 그걸 느낄 수 있었다고 하더군.$B$B자네의 활약이 포세이큰 지도부에까지 알려지고 있어. 자네는 점점 더 우리에게 없어서는 안 될 존재가 되어 가고 있네.'),
(449, 'koKR', '은빛소나무 숲에 있는 스컬지들이 어떤 녀석들인지, 그리고 우리 죽음의추적자 정찰병들에게 무슨 문제가 생긴 것인지 알지 못해 답답했었다네.$B$B자네의 도움이 정말 컸네. 상을 받아 마땅해.'),
(458, 'koKR', '용케도 나를 찾아냈군요, 젊은 $R|1이여;여;... 그대를 보낸 걸 보니 멜리타는 현명한 드루이드군요.'),
(459, 'koKR', '그늘 협곡의 생명체들을 위해 애써 준 일은 보상을 받을 만하군요, $N.$B$B하지만 당신 덕분에 제 우려가 사실로 확인되었습니다. 그렐이 악마의 이끼에 오염되었다면, 한때 이곳에 살았던 나무옹이일족 퍼볼그들이 어떻게 되었을지는 상상조차 하기 어렵습니다.$B$B돌라나르에 가게 된다면, 유능한 $c님, 박식한 드루이드 아스리다스 베어맨틀을 찾아가 보세요. 그도 숲의 안녕을 우리처럼 걱정하고 있답니다.'),
(471, 'koKR', '흠, 혹시 제 밑에서 수습생으로 일하지 않겠습니까?$B$B하하! 농담이었습니다. 일을 배우기엔 너무 나이가 많으시니 곤란하겠군요. 게다가 당신의 모습으로 보아 인생에 대한 또 다른 포부가 있을 것 같군요. 그건 그렇고, 구해오신 이 질 좋은 가죽은 잘 쓰겠습니다.'),
(510, 'koKR', '<말레브가 문서를 읽으며>$B$B이건 심각한데... 이 문서의 정보와 최근 비밀결사대의 움직임으로 미루어 볼 때, 이 살인 집단이 사우스쇼어와 전쟁을 벌이려는 게 분명하네.'),
(511, 'koKR', '이게 뭐지요? 잠시만요... 자세히 볼게요. $B$B...$B$B흠, 이런 형태의 암호화는 처음 보는군요, 이 분야에 대한 제 지식이 결코 완벽하지 않다는 것을 인정해야 되겠군요.'),
(517, 'koKR', '오, 드디어! 이제 준비는 다 끝났군!'),
(519, 'koKR', '우리의 멋진 계획이 시작됐다고 역겨운 오우거 머리 냄새가 말해주는군요.$B$B무그톨의 머리카락까지 가져오면 네 개의 머리카락 다발을 창에 묶어 알터랙 산맥 높은 곳에 걸어둬야겠어요. 어둠의 여왕님의 뜻을 거스르는 녀석들에게 좋은 경고가 될 테니까요.'),
(520, 'koKR', '임무를 잘 완수했군요. 나머지 산사태일족 잔당들은 죽음의경비대가 쓸어버릴 겁니다.'),
(522, 'koKR', '<계약서의 내용을 확인하는 집정관 말레브.>$B$B흠, 이제야 놈들이 지난번 사우스쇼어를 공격한 이유를 알겠군. 비밀결사대 놈들이 전임 집정관이 그랬던 것처럼 나를 암살하려는 거야!'),
(544, 'koKR', '포세이큰을 위해 큰 일을 해 주었군. 이 유물들은 매우 귀한 것들이지.$B$B그리고 케간과 다른 배반자들이 정의의 심판을 받게 되었으니 이보다 더 기쁜 일이 어디 있겠소?'),
(547, 'koKR', '찾았군요!$B$B아, 내 일부나 마찬가지인 이 소중한 검을 다시 찾게 되어 얼마나 기쁜지 모릅니다. 정말 고맙습니다!'),
(556, 'koKR', '이거면 충분하겠군요. 징표의 돌이 마법의 힘을 잃은 것 같긴 하지만 보이드글레어님의 실험에는 이런 표본이 오히려 더 낫겠지요. 고맙습니다.'),
(565, 'koKR', '자, 그럼 이 위대한 바르톨로가 귀신같은 솜씨를 한번 부려 볼까나... 잘 보시오. 위대한 바르톨로는 마법사의 지팡이나 마법사의 마법봉 없이도 마술을 부린다오. 바늘과 실만 가지고 말이지!'),
(566, 'koKR', '아주 훌륭한 일을 했군. 바르두스 남작을 처치했으니 비밀결사대 지도자의 수도 줄어든 셈이군. 놈들의 저항과 악행도 곧 끝이 날 거야.'),
(571, 'koKR', '정말 최고의 힘줄을 구해 왔군. 노고에 대한 답례는 곧 하도록 하지.'),
(575, 'koKR', '좋은 가죽이군요. 사실 장화의 안감으로 사용할 거니까 가죽의 질은 그리 중요하지 않지만, 대신 편안해야 하죠.$B$B가죽이 너무 딱딱한 경우에는 호랑이 피로 부드럽게 해 준답니다. 이런 게 바로 장사 수완이란 겁니다요!'),
(577, 'koKR', '오! 내 장화를 보세요. 꼭 소시지 같지 않나요? 보기 좋고, 맛도 좋고. 가장 좋은 재료와 고기로만 만든 한번 맛을 보면 잊을 수 없는 소시지 말입니다요.$B$B안전성이 아주 뛰어나고 기분을 좋게 해 주는 신발입죠. 제 말을 믿으시라고요. 아, 거참... 진짜 재료가 뭔지 너무 꼬치꼬치 묻진 마세요.'),
(604, 'koKR', '멋지게 해냈군. 이제 놈들의 계획을 알았으니 처리하는 것은 시간 문제야.$B$B이 만 바로 앞에 닻을 내렸다니 바보 같은 놈들...'),
(607, 'koKR', '헤헤, 잘했군! 그래, 내장을 보여 줬을 때 그 겁쟁이가 어느 정도로 떨어 댔지? 봤어야 하는 건데!$B$B하! 녀석의 패를 읽는 건 식은 죽 먹기니, 녀석과 카드 게임을 하면 절대 지는 법이 없지. 도와 줘서 고맙소. 자, 이건 당신 몫이라고.'),
(609, 'koKR', '좋아! 이거면 좋은 값을 받을 수 있겠군. 특히 마우리의 의족에 들어 있는 건 값져 보이는데. 대단히 고맙소!$B$B그 세 녀석이 교훈을 얻었다면 좋겠군. 능력이 안 되면 돈을 걸지 말았어야지. 뭐, 이미 녀석에게는 너무 늦었는지 모르겠지만...노름 상대를 잘 골라야 하는 거라고.'),
(614, 'koKR', '찾았군! 오, 이렇게 기쁜 날이! 고맙소, $N. 내 상자를 되찾으니 가슴속의 불길이 조금은 가라앉는구려.$B$B하지만 내 복수는 아직 끝나지 않았소...'),
(619, 'koKR', '뗏목 위에 음식과 마실 것을 쌓아 올립니다...'),
(628, 'koKR', '훌륭해요! 손님 덕분에 리들복스 조합장님께서 주문한 장화를 다음 지하광산행 배에 실어 보낼 수 있겠군요. 예정보다도 빨리 말이죠!$B$B수고해 주신 대가로 손님 장화도 한 켤레 만들어 놓았으니 가져가세요. 이 드리즐릭이 공짜로 드리는 겁니다요.$B$B다만, 드리즐릭의 익셀시어류 만한 장화는 없다는 사실만 기억해 주세요!'),
(639, 'koKR', '잘했군. 시작이 좋아. 트롤베인의 무덤에서 트롤칼라를 빼내려면 인장들을 모두 모아야 해.'),
(643, 'koKR', '기병대장을 잃었으니 스트롬가드 수호병들에게는 큰 타격이겠군. 더 기쁜 건 이제 인장을 하나만 더 확보하면 트롤칼라를 우리가 가질 수 있게 된다는 것일세.'),
(644, 'koKR', '오늘은 아주 기분이 좋은 날이군. 앞으로 트롤베인의 후손이 더 이상 우리를 괴롭히지 못할 것이고, 트롤칼라를 손에 넣기 위해 필요한 인장을 모두 손에 넣었으니 머지 않아 줄구룹이 이끄는 우리의 트롤 적들을 무찌를 수 있게 될 걸세.'),
(658, 'koKR', '훌륭하군요! $B$B자, 어떤 내용인지 한 번 볼까요...'),
(673, 'koKR', '이 수정구를 파괴하면 드디어 발 뻗고 편히 잘 수 있겠군. 고맙네. 헬스크림님께서 그들을 저주에서 벗어나게 해 주기시기 전 악마의 힘에 억눌려 있었던 시절을 기억나게 하는 물건이로군.'),
(680, 'koKR', '정말 큰 일을 해냈군요. 당신 덕분에 내 남편의 목숨과 해머폴의 안녕이 계속 유지될 수 있게 되었습니다. 자, 이건 노력에 대한 대가라 생각하고 받아 주세요.'),
(701, 'koKR', '좋아, 그거면 충분하군. 랩터의 힘과 영혼을 이 수정구 안에 불어 넣겠네. 그러면 이 수정구가 고르멀에게 랩터의 강력한 힘과 지능을 불어넣어 줄 걸세.'),
(702, 'koKR', '이번에는 뭔가 흥미로운 걸 가지고 왔군. 이 물건에서 이상한 힘이 솟아나고 있는데...'),
(727, 'koKR', '아, 안녕하세요, 형제님.$B$B지하의 주민들에게 축복을.'),
(728, 'koKR', '표식은 조심스럽게 사용하시오, $c. 우리의 서약이 정당하다고 믿지 않는 자들이 있소.$B$B그리고 우리의 존재를 안다면 우리가 실패하기를 바라는 자들도 있지.$B$B우리는 항상 조심해야 하오. 경계를 늦추지 말고, 인내해야 하오.'),
(743, 'koKR', '수고했네. 형제는 모험을 계속할 준비가 되어 있는 것 같군. 언제나 자신이 옳다고 생각하는 길로 가길 바라네.'),
(746, 'koKR', '고맙네. 이제 멀고어의 짐승들은 평온해질 걸세. 그리고 드워프들 역시 대지를 파헤치는 것만으론 아무것도 알 수 없다는 걸 배우는 계기가 되었길 바라네.'),
(747, 'koKR', '나라체의 타우렌들이 그대에게 감사하오, $n. 그대는 큰 가능성을 보여 주었소.'),
(750, 'koKR', '나라체의 $R들이 이 식량에 감사하오, $N. 사냥의 도에 능한 그대는 언젠가 반드시 썬더 블러프에서 존경받게 될 것이오.'),
(751, 'koKR', '이건 투자개발회사가 우리의 천연 자원을 훔치려는 것이 사실이라는 것을 말해주는군. 다행히 미리 알았으니, 이제 조치를 취해야 할 것이오.'),
(753, 'koKR', '대모의 뜻에 따라 이 물동이를 가지고 돌아왔군.$B$B타인을 도우려는 그대의 마음과 나라체 야영지의 타우렌을 위해 베푼 노력을 보니, 언젠가 썬더 블러프에서도 그대가 부족의 자랑이 될 것이라 믿소.'),
(756, 'koKR', '고맙소, 형제여. 정화의 토템상을 만드는 데는 짐승을 사냥할 때의 활기찬 기운이 가장 중요하오.$B$B고블린들은 대지와 조화를 이루며 사는 것과 대지에 맞서는 것의 차이를 절대 알지 못할 것이오.'),
(757, 'koKR', '그대는 대지모신의 의식 중 첫 번째 시험을 통과했네. 부족 전체가 그대를 자랑스럽게 여길 것이야.'),
(766, 'koKR', '아, 고맙네. 자네가 구해 온 재료로 치료약을 만들어 독이 퍼지는 걸 막고 상처를 완전히 치료할 수 있을 거야. 덕분에 목숨을 건졌군. 내 생명을 구해줘서 정말 고맙네.$B$B하지만 마즈라나체가 날 공격할 때 냈던 그 날카로운 울음소리와 나를 향해 달려들던 불타는 듯한 부리의 색은 절대 잊지 못할 걸세.$B$B자네도 놈을 조심하길 바라네.'),
(771, 'koKR', '이제 우리의 신성한 땅에서 재료를 구하는 방법을 터득한 것 같군. 이제 예언의 물을 만들어 주도록 하지.'),
(780, 'koKR', '정말 훌륭하군. 당신이 준 재료들로 맛있는 스튜를 만들 수 있을 것이오. 또한 전투멧돼지들의 손실이 사악한 뾰족털일족 놈들에겐 좋은 교훈이 되었을 것이오.'),
(782, 'koKR', '토그룬의 시체는 사막의 바람과 사막의 청소부인 대머리수리가 깨끗이 청소할 것이오. 이제 놈이 죽었으니 오우거들은 혼란에 빠지겠지. 이 작은 승리로 앞으로 더 큰 승리를 얻게 될 것이오.$B$B대지의 봉인을 되찾았으니 레슬로 협곡에 있는 검은 비룡의 감옥을 열 수 있소. 이제 우리는 그들을 끝없는 감옥에서 해방시켜 영원한 안식을 줄 수 있게 되었소.'),
(793, 'koKR', '검은용군단이 우리를 배신한 검은바위부족 오크들과 동맹을 유지하고 있소. 양쪽 모두 교화되거나 제거되어야 할 대상이지. 이제 블랙래쉬와 헤마투스를 처치했으니 우리의 힘을 서쪽의 검은바위 첨탑에 집중할 수 있게 되었소.'),
(794, 'koKR', '찾아왔군요! 수고했어요!$B$B불타는칼날단 소굴에서 보여 준 당신의 활약은 시험의 골짜기에서 저 이교도 집단의 뿌리를 뽑는 데 중요한 열쇠가 될 거예요. 하지만 놈들이 우리 영토에서 또 다른 뭔가를 꾀하고 있는 것은 아닌지 걱정이 되는군요.$B$B아직 완전히 놈들을 섬멸한 건 아니니까요.'),
(822, 'koKR', '하하! $C 당신도 이 맥주 맛을 보고 싶어할 줄 알고 있었소. 더 마시고 싶을 땐 언제든 찾아 오도록 하시오. 내가 말한 재료들만 다시 모아 오면 얼마든지 만들어 줄 테니까!'),
(825, 'koKR', '임무를 성공적으로 완수했군, $C. 이 도구들은 다음번 짐마차에 실어 오그리마로 보내도록 하겠네.$B$B수고했어.'),
(827, 'koKR', '좋아! 이 이글거리는 목걸이에 숨겨진 비밀이 바로 불타는칼날단의 음모를 밝혀낼 열쇠가 될 거요. 내 반드시 밝혀내고야 말 거요...'),
(829, 'koKR', '아, 그래, 이건 어디서 구했나? 칼바위 언덕의 착한 마르고즈가 보냈다고?$B$B그럼, 좀 더 자세히 살펴보자...'),
(830, 'koKR', '이거 좋은 소식은 아니로군. 이런 정보를 내게 갖고 오다니 영리한 친구로군.'),
(855, 'koKR', '아주 잘했네! 살아남은 켄타우로스 놈들도 겁을 먹었을 게 확실해. 생각이 조금이라도 있다면 이제 공격은 그만두고 조용히 숨어 지낼 텐데...$B$B하지만 그럴 것 같지는 않으니 불행한 일이야.$B$B물론 내 말은 그놈들에게 불행한 일이 될 거란 말이지...'),
(861, 'koKR', '스코른 화이트클라우드는 현명한 타우렌이지. 비록 몸은 늙었지만 그는 강한 정신력으로 오랫동안 사냥을 계속해 왔지. 우리 타우렌에 그와 같은 이가 있다는 건 영광이 아닐 수 없소.$B$B스코른이 보냈다면 그대에게도 역시 사냥꾼의 정신이 있겠군. 그리고 모아온 이 발톱들을 보니 기본적인 기술은 있는 것 같군그래.$B$B사냥꾼의 길을 가기 위한 준비는 된 것 같소.'),
(864, 'koKR', '즉시 이 자료를 분석하도록 하겠어요. 어쩌면 키버의 광기 덕에 내가 천재가 되겠군요.$B$B당신은... 내겐 아주 능력있는 일꾼이었어요. 난 언제나 변함없이 내게 도움이 된 자에게는 보상을 아주 후하게 한답니다. 자, 이 돈도 받고 내 감사의 마음도 함께 받으세요.$B$B나중에 가끔 내게 들리도록 하세요. 이번 임무만으로 우리의 관계가 끝나지는 않을 테니까요.'),
(867, 'koKR', '오, 잘했어. 아주 좋아, 정말 잘했어. 앞으로 많은 활약을 기대하지.'),
(868, 'koKR', '알을 채집해 주고 쓰고 난 장갑까지 돌려주어서 정말 고맙소.$B$B자, 이건 수고에 대한 답례요.'),
(876, 'koKR', '오! 훌륭하군! 아주 훌륭해... 처음엔 자네가 이 임무를 잘해낼 수 있을지 확신이 들지 않았는데... 자네의 실력이 충분히 증명되었어. 자, 이건 보상이야. 도움이 되었으면 좋겠군.'),
(891, 'koKR', '아아, 얼라이언스의 정의로운 대포들이 잠들어 버렸군. 그대의 공로에 합당한 보답을 해야겠지.$B$B다음으로는 죽은 자들의 몸을 부활시키는 조금은 섬뜩한 임무를 맡길까 하는데...'),
(893, 'koKR', '훌륭하오, 참으로 훌륭한 물건들이군.$B$B생각보다 가시멧돼지들의 기술은 훨씬 더 진보한 것 같소.$B$B자, 이걸 받고 길을 떠나시오. 난 이 무기들을 좀 더 연구해야겠소. 아마도 적을 과소평가했던 실수가 지금의 참혹한 결과로 나타나는 것이 아닌지 모르겠군.'),
(897, 'koKR', '이 짐승의 특성에 대해서는 전혀 알 수가 없군. 이미 영혼이 육체를 떠났으니 말일세. 하지만 자네의 추측 대로 이건 불모의 땅의 생태계에 속하는 것이 아니야. 우리 타우렌의 어두운 미래를 암시하는 건 아닌가 우려되는군...$B$B하지만 지금은 방비를 해 놓고 기다리는 수밖에 없지. 시간이 지나면 이 생명체의 비밀이 밝혀질 거야.'),
(899, 'koKR', '내 부탁을 들어 주어 고맙소.$B$B아직 복수는 끝나지 않았지만 사악한 가시멧돼지 놈들에게 고통을 안겨 준 것은 내게 큰 위안이 될 것 같군.'),
(908, 'koKR', '바로 내가 필요하던 걸세! 심연의 핵은 믿기 힘든 정보의 샘이라 많은 것을 얻을 수 있을 걸세. 황혼의 망치단이 저 안에서 무슨 짓을 꾸미고 있든 — 좋은 일이 아니라는 건 내 장담하지 — 이제 나와 동료들이 밝혀내겠네.$B$B오늘 그대는 잘해 주었네. 속세의 고리회는 우리를 도운 그대를 따뜻하게 지켜보고 있네. 그대는 호드 전체에도 도움이 되었으니 그 점을 자랑스러워해도 좋네.'),
(909, 'koKR', '이건... 대단한 발견이군, $N.$B$B검은심연에서 군주 아쿠아니스에게서 얻었다고? 군주 아쿠아니스는 오래전부터 타락한 정령의 힘으로 여겨져 왔는데, 이 구체가 그를 정확히 무엇이 타락시켰는지 밝혀 줄 걸세. 황혼의 망치단 짓이라 해도 놀랍지 않겠지만, 우리 연구는 그들이 어떻게 그랬는지도 밝혀 줄 걸세.$B$B이걸 가져온 건 잘한 일이야. 자, 속세의 고리회의 진심 어린 안부와 함께 이것을 받게.'),
(915, 'koKR', '음~~~~~! 딸기 아이스크림 너무 좋아! 티굴이랑 포로르는 아이스크림 하나는 정말 잘 만든다니까!$B$B정말 고마워요, $N — 최고의 간식이에요!'),
(936, 'koKR', '어서 오게. 우리 연구를 돕는 데 관심을 가져 줘서 기쁘구만. 할 일이 많을 뿐더러, 관련 작업들이 위험하지 않다고 하면 거짓말을 하는 게 될 거야. 겁부터 줘서 쫓아버리는 게 되진 않았으면 좋겠구만... 하지만 자네 모습을 보아하니 이전에 이미 위험한 일을 해 본 경험이 있는 것 같은데.'),
(956, 'koKR', '지... 지금 내 손에 들고 있는 것이 그 오랜 시간 날 구속해왔던 봉인이라니... 믿을 수가 없군. 어서 서둘러야겠네. 더 이상 시간을 낭비하고 싶지 않아. 봉인을 파괴하면 나는 이 땅의 숲을 다시 자유롭게 거닐 수 있을 걸세.'),
(962, 'koKR', '아, 훌륭한 표본이군. 수고했소.'),
(963, 'koKR', '고맙소. 내 손으로 그녀를 자유롭게 해 줄 수 있었다면 더 좋았을 테지만 수천 년이 지난 지금도 내가 사랑하는 이를 다치게 할 수는 없었소.$B$B이제 혼자 이 슬픔을 달래고 싶소. 미안하오만 그만 가주시오.'),
(966, 'koKR', '정말 고맙소. 이제 소환사들이 모여든 이유를 밝혀낼 수 있을 것 같소.$B$B흠... 암흑이교도라... 이런 무리에 대해서는 들어 본 적이 없는데... 내가 알고 있는 바가 없으니 그들의 계획이 무언지도 알 수가 없소.$B$B더 이상 지체할 시간이 없소. 당장 델그렌님께 이 사실을 알려 드려야겠소.'),
(971, 'koKR', '초본을 찾았군! 이렇게 기쁜 날이 또 있을까! 우리 형제 자매들에게 로르갈리스의 고대 지식을 전할 수 있게 되다니! 어서 사본을 만들어 배포해야겠네.$B$B자네가 한 일이 얼마나 큰 의미가 있는지 모를 거야. 이 선물이 우리가 전하는 감사의 마음을 제대로 표현해줬으면 좋겠군.'),
(977, 'koKR', '친구들에게 빨리 보여주고 싶군요! 잠깐, 이것들을 여기에 달면...$B$B완벽해!'),
(986, 'koKR', '이거면 훌륭하오. 즉시 망토를 만들도록 하겠소. 조금만 기다려 주시오.$B$B참, 그리고 일단 망토의 마법을 사용하고 나면 다른 이와의 접촉에 제약을 받게 되오. 가능하면 대화 외에는 다른 이들과 부딪히지 않도록 하시오. 그 이상 접촉할 경우 환영이 사라지고 말 테니까...'),
(1001, 'koKR', '트레샤돈의 눈을 안에 넣자 버즈박스가 작동하는 소리가 들립니다. 그리고 곧 익숙한 목소리가 작게 들립니다.$B$B\"햐... 역시 게살 와인이 최고라니까...\" *딸꾹!*$B$B\"어? 벌써 고쳤군요. 정말 빠르네요. 고칠 게 또 있는데 계속 도와줄 수 있나요?\"$B$B술을 따르는 소리와 꿀꺽꿀꺽 목으로 넘기는 소리가 들리는 것 같습니다.'),
(1002, 'koKR', '버즈박스가 갑자기 작동하기 시작하고 감이 먼 음성이 들리기 시작합니다.$B$B\"이번에도 잘 고쳤군요. 정말 훌륭한... 딸꾹... 또 다른 걸 수리할 생각이 없다면 그만 갈 길이나 가 보세요!\"'),
(1003, 'koKR', '\"가죽은 다 집어 힉... 넣으셨어요? 아주 잘했어요... 에? 뭐, 기계 속에 딸꾹... 재료를 넣지 않아도 당신한테 말을 할 수 있다는 걸 딸꾹... 알아차리셨겠군요. 그래도 고장났다고 한 건 힉... 정말이었어요!$B$B버즈박스는 통신 도구일 뿐 아니라 술을 만드는 데도 쓸 수 있거든요. 딸꾹... 속여서 기분 나쁘다면 미안해요. 하지만 나이트 엘프들은 딸꾹... 자기네 마을 안에서 제가 술을 만들어 파는 걸 탐탁지 않게 여겨서요. 수고에 대한 감사의 표시로 이 상자 안에 힉... 뭔가 특별한 걸 넣어 놓았어요. 잘 쓰시라고요!\"'),
(1008, 'koKR', '잘하셨습니다. 조람 해안에서 나가를 상대로 펼친 그대의 활약은 칭송할 만합니다.$B$B그대의 공적이 쉽게 이루어진 게 아니라는 건 잘 알고 있습니다. 나가의 힘과 지략은 나이트 엘프 사이에서도 잘 알려져 있답니다. 우리는 그들과 오랜 역사를 같이해 왔기 때문에 매우 잘 알고 있지요.$B$B다시는 되풀이하고 싶지 않은 역사이지만...'),
(1009, 'koKR', '반지를 찾았구려! 고맙소. 답례로 이걸 받아 주시오. 또한 그대가 해준 일을 영원히 잊지 않을 거란 걸 알아 주시기 바라오.'),
(1010, 'koKR', '아, 배스랜초를 가져왔구려! 이제 아이를 위한 치료제를 만들 수 있겠군. 부디 약효가 있어야 할 텐데...$B$B그런데 배스랜 서식지에 포세이큰들이 있다고 했소? 저런, 큰 문제로군. 참으로 큰 일이오.'),
(1014, 'koKR', '마침내 은빛소나무 숲이 그 비열한 아루갈의 악으로부터 자유로워졌군. 당신은 어둠의 여왕님을 위해 큰 공을 세웠으니 반드시 노고에 대한 보상이 있을 것이오.'),
(1033, 'koKR', '오! 찾아냈군요! 엘룬의 눈물을 스튜에 넣고 이것으로 내 딸의 병이 낫기를 기도해야겠습니다.$B$B고맙습니다! 정말 고맙습니다.'),
(1035, 'koKR', '오! 당신이 내 딸의 목숨을 살렸어요! 월장석의 힘이 딸의 기력을 회복시켜 줄 거예요.$B$B당신이 베풀어 주신 은혜를 어찌 다 갚을 수 있겠습니까만... 이거라도 받아주세요. 이건 제가 렐라라 다음으로 아끼는 물건입니다.'),
(1058, 'koKR', '아, 이 특별한 마법 약으로 이 친구들은 고향에 온 것 같은 기분을 느끼게 될 거야. 이 작은 숲의 요정들이 얼마나 행복해 할까! 하하하!'),
(1126, 'koKR', '도대체 이게... 이게 뭐지?$B$B모양이... 상자 같은데? 뭔가 지독한 것에 뒤덮여 있군. 가만, 이쪽에 덮여 있지 않은 부분이 있군. 이... 끈적끈적한 것에 덮여 있는 것이 책인가?$B$B뭔가 굉장한 걸 찾아온 것 같소. 적어도 그랬으면 좋겠소. 고대 시절에 쓴 일기나 일지 같은 게 이 껍질 속에 보존된 것일지도 모르고 말이오$B$B이게 뭔지 알아낼 방법이 하나 있긴 하지만...'),
(1134, 'koKR', '고맙습니다. 하지만 그 동물들이 적에게 이용 당한 것 뿐인데... 죄 없는 동물들을 처치하라고 명령해야 하는 건 가슴 아픈 일입니다. 얄궂게도 그게 바로 내 임무이니...$B$B그대 역시 가슴이 아프겠지만, 적어도 얼라이언스의 많은 이들이 사자날개 와이번의 독으로부터 안전해졌으니 그것으로 마음의 위안을 삼길 바랍니다.'),
(1135, 'koKR', '와, 아주 독이 넘쳐 흐르는 것들을 가져오셨군요. 이런 것들은 보통 어린 와이번이나 새끼를 잘 낳는 암컷들에게서만 찾을 수 있는데... 마루둥지에서 굉장히 큰 싸움을 벌이셨겠군요!'),
(1150, 'koKR', '그렌카는 트롤의 기준으로 봐도 강력했네. 오늘 이룬 성과를 자랑스럽게 여기게.$B$B믿음의 시험에서는 정신력을 보여 주었고, 이번에는 약탈자 하피들과 싸워 전투에서의 인내심을 증명했네. 하지만 이제 새로운 시험을 치를 때가 왔네.'),
(1151, 'koKR', '이제 용기의 시험이 끝났네. 이 시험을 통해 그대는 힘과 용기를 증명해 보였군그래. 이제 마지막 시험을 통과하면 이 의식이 완료된다네.'),
(1153, 'koKR', '좋은 견본이야. 정말 아주 괜찮은 견본을 가져왔소.$B$B당신이 이 임무를 성공적으로 완수했으니 이제 더 이상 여행자들에게 광석을 팔라고 들볶을 필요는 없군.$B$B즉시 연구를 시작해야겠어. 이 광석이 충분히 강한 것으로 확인되면 이것으로 만든 무기를 대족장님께 바쳐서 우리의 성공을 직접 보여드리겠소.$B$B당신의 도움을 절대 잊지 않겠소, $C 친구.'),
(1154, 'koKR', '그래, 이게 바로 내가 말한 책이야. 내용을 숙지했겠지? 내 질문에 제대로 대답할 수 있길 바라네.$B$B준비가 되면 질문을 하도록 하겠네.'),
(1166, 'koKR', '너 좋은 $r. 나 물건들 많이 그립다. 나 이제 너 좋아한다.'),
(1169, 'koKR', '이 심장과 혀들을 모으는 것은 분명 아주 위험한 일이었을 거다. 우리 옛 고향을 침략한 검은용군단의 근원을 찾기 위해 이 수수께끼를 깊이 탐구해 볼 것이다.'),
(1177, 'koKR', '난 물고기 머리를 좋아해!$B$B지금은 너 잡아먹지 않아.'),
(1182, 'koKR', '오, 설계도를 구해왔군. 복사해서 나도 하나 갖고 있어야겠어. 이제 이 설계도를 포직에게 가져가도록. 후원자 중 한 사람이 완전히 지원을 끊었다고 생각하면 곤란하니까.'),
(1193, 'koKR', '토륨 장치가 수월하게 제자리에 들어가며, 서리 기름을 부어 넣을 관이 만들어집니다. 마지막 기름 방울까지 쏟아붓자 덫이 철컥 하고 자리를 잡습니다.$B$B혹시라도 이곳을 어슬렁거리다 걸려드는 경계심 없는 오우거는 크게 후회하게 될 것입니다!'),
(1200, 'koKR', '켈리스 녀석은 꽤 오랫동안 우리의 추적을 피해 왔소.$B$B이 부근에 모습을 드러내던 사악한 세력들은 모두 켈리스와 끈이 닿아 있었던 모양이오. 한동안 우리는 그가 죽었거나 실종된 줄로만 알았소이다.$B$B이것으로 모든 게 해결되었소. 그의 권세가 끝났으니 무고한 자들의 목숨을 구하게 된 것이오.$B$B한 개인의 이익을 위해 고대 신의 시녀에게 희생 제물을 바치다니, 정말 말도 안 되는 일이지!$B$B아주 훌륭한 일을 해주셨소. 은빛 여명회를 대신해 진심으로 감사하오.'),
(1275, 'koKR', '멀리까지 가서 분명 큰 위험에도 처했을 거요.$B$B당신의 행동은 아주 헌신적이었소. 내 연구를 도와주는 것은 아제로스 전체의 이익을 위한 일이오. 많은 수고를 해주어서 고맙소.$B$B자, 이제 나는 해야 할 일이 많이 있으니 이만 실례하겠소이다.'),
(1430, 'koKR', '아, 이거면 딱 좋겠군. 어서 불 위에서 요리해 맛을 보고 싶군그래. 가는 길에 맛을 보게 몇 개 가져가도록 하시오. 정말로 맛있다오.'),
(1435, 'koKR', '아, 무사히 돌아왔군. 정말 다행이야. 안전한 곳에 보관할 테니 보석을 내게 주시오.$B$B이제 내가 당신에게 맡길 임무는 더 이상 없소. 타카타가 다른 임무를 맡길지도 모르니까 휴식을 좀 취한 뒤 그를 만나 보도록 하시오. 아니면 오그리마로 돌아가 이곳 잊혀진 땅에서의 진척 상황을 켈드란에게 알려 주시오.'),
(1438, 'koKR', '드디어 엘룬께서 도와줄 분을 보내주셨군요. 제발 절 좀 도와주세요, $C님. 티라니스 오빠랑 저는 불타는칼날단에게 붙잡혀 여기로 왔어요. 그들이 저를 그들이 섬기는 악마 군주에게 제물로 바칠 건가 봐요!$B$B전 잊혀진 땅으로 오면 안 되는 걸 알았지만 티라니스 오빠가 요즘 들어 사람들의 기대를 져버리고 신비술에 몰두하기 시작했어요. 오빠는 이 땅에 악마가 득실거린다는 것을 알고도 여기로 온 거예요.$B$B전 오빠가 잘못될까 봐 걱정이에요.'),
(1480, 'koKR', '흠, 이 룬은 일종의 언어, 아주 오래된 언어가 틀림없소. 언뜻 보면 에레둔어와도 유사한 듯하지만 차이가 상당히 크군. 내 생각이 맞다면 일종의 계약서 같은데... 그래, 여기, 여기 이 기호는 제왕 아즈레토크라는 악마의 서명이군.'),
(1481, 'koKR', '그림자추적자들도 당신 적수는 못 됐나 보군. 훌륭해... 정말 훌륭해!$B$B이 가죽이라면 딱이야! 당신이 가죽을 구하러 간 동안 나는 주문에 필요한 재료 몇 가지를 더 구해 두었소.$B$B이제 준비도 거의 끝났으니 나는 주문을 완성하는데 집중해야겠소. 악마 군주의 실체와 그 본거지를 볼 수 있게 해줄 주문을...'),
(1482, 'koKR', '귀하디 귀한 예언의 수정구... 흠집 하나 없고 정말 아름답군.$B$B즉시 시작해야겠소. 악마 군주를 찾아내는 것이 우리의 최우선 과제이고, 그를 처치하기 위해서는 할 수 있는 한 최선을 다해야 하오.$B$B뒤로 한 발 물러서시오, $C. 이제 이 악마가 어떤 모습인지, 그리고 어디에 있는지 한번 봅시다.'),
(1486, 'koKR', '통가죽을 모아 준 당신의 노고는 잊지 않겠소.$B$B정말 감사하오.'),
(1501, 'koKR', '좋소. 그걸 되찾으러 가서 불타는칼날단에게 다른 손실도 좀 입혔기를 바라오.$B$B그들은 대족장께 큰 골칫거리였고, 흑마법사 전체에게도 커다란 오점이었소.'),
(1534, 'koKR', '굉장하네요. 세 가지 견본을 모두 모았으니, 이제 아무도 본 적이 없는 순수한 물을 만들어 드리지요. 이 물은 다음 단계의 통과 의식에 쓰일 거예요.$B$B당신이 우리 일원이라는 게 자랑스럽군요. 당신은 우리 $C 모두의 자랑이에요. 훗날 당신의 위업에 대한 이야기가 널리 퍼져 이곳에서도 듣게 되길 기대하죠.'),
(1536, 'koKR', '좋아, $N. 자네는 맡은 일에 헌신적이고 필요한 것을 찾아낼 능력이 있군.$B$B자네의 사프타에 필요한 시약을 만들려면 표본이 하나만 더 있으면 되네. 이슬렌도 기뻐할 걸세.'),
(1654, 'koKR', '대단합니다! 모두 찾으셨군요.$B$B이거라면 거뜬히 근사한 무기를 만들 수 있겠는데요. 사실 언젠가 꼭 이걸 만들어 보려고 벼르고 있었지만, 재료를 찾으러 다닐 겨를이 없었답니다. 고맙습니다.$B$B아버지의 망치를 다시 쥐게 되다니 감개무량하군요... 이 코르석도 직접 보게 되리라고는 생각지도 못했답니다.'),
(1740, 'koKR', '그나마 다행이군... 수정구가 아주 여러 조각으로 깨진 것은 아니었어. 부탁 드린 조각들을 전부 가져왔군요. 이 조각들을 붙여서 소랜루크의 수정구를 다시 완전한 형태로 만드는 건 간단한 일입니다.$B$B제 평생을 불타는 군단의 수정구를 재생하기 위한 연구에 바쳤습니다. 수정구 조각을 모아 주다니 제 연구에 큰 보탬이 될 거예요. 당신의 은혜에 어떻게 보답해 드려야 할지... 자, 원하시는 형태에 맞게 완전히 복원된 수정구나 지팡이를 드릴 테니 받아 주십시오.'),
(1786, 'koKR', '고맙소, $G형제:자매;여.$B$B생명의 징표를 지는 것을 보니 두소리안이나 가쟁이 보낸 것 같군.$B$B난 가쟁과 함께 데피아즈단의 문서를 빼내오는 도중 마술사 녀석들에게 당했소. 가쟁이 빠져나갈 동안은 버팅 수 있었지만 결국 녀석들의 마법에 당하고 말았지.$B$B하지만 그대가 날 되살려 주었소. 그 생명의 징표는 아무나 쓸 수 있는 게 아니오. 스스로 빛의 힘으로 생명의 징표를 사용할 수 있었다는 건 굉장한 것이오.'),
(1793, 'koKR', '이미 빛의 힘이 자네와 함께한다는 것은 증명되었네. 그러나 세상이 위험해질수록 신체의 힘을 길러 자신을 지키는 것도 중요하네. 악마, 용, 그리고 다른 악이 우리의 땅을 침략해 오면 자네의 용기를 시험하게 될 것이야. 자신이 충분히 강하다고 생각하나?$B$B어떤 상황에서든 빛의 힘과 방어구, 무기처럼 용기도 $C의 일부분일세. 약한 자를 보호하고 정의로운 마음을 잃지 않는 것 역시 빛의 대성당에서 수련하는 동안 배워야 할 가르침일세.'),
(1794, 'koKR', '이미 빛의 힘이 자네와 함께한다는 것은 증명되었네. 그러나 세상이 위험해질수록 신체의 힘을 길러 자신을 지키는 것도 중요하네. 악마, 용, 그리고 다른 악이 우리의 땅을 침략해 오면 자네의 용기를 시험하게 될 것이야. 자신이 충분히 강하다고 생각하나?$B$B어떤 상황에서든 빛의 힘과 방어구, 무기처럼 용기도 $C의 일부분일세. 약한 자를 보호하고 정의로운 마음을 잃지 않는 것 역시 빛의 대성당에서 수련하는 동안 배워야 할 가르침일세.'),
(1796, 'koKR', '이거면 되겠어요.$B$B마법이 담긴 모든 물건은 반드시 품질이 뛰어난 것부터 사용하기 시작해야 해요. 더 많은 노력과 기술을 투자해서 만들수록 그만큼 더 강력한 마법을 갖게 되죠. 희귀하거나 값 비싼 재료들을 사용하면 마력이 더 잘 유지된답니다. 나중에 로브를 받아 보면 방금 수고하신 시간과 노력이 전혀 아깝지 않을 겁니다.'),
(1880, 'koKR', '오, 멋진 날이야! 기즈모니터를 만들었을 때는 이렇게까지 의존하게 될 줄 몰랐거든. 이제 다시 연구를 시작할 수 있겠어!$b$b고맙네, $N! 그리고 여기 — 이건 내가 $c로서 처음 쓰던 도구들이라네. 조금 긁히긴 했지만 충분히 검증된 것들이지. 아무거나 골라 보게 — 둘 다 쓸모가 있을 걸세.'),
(1918, 'koKR', '썩은 물이 든 구슬을 찾았는데 내게 가져오고 싶더란 말인가? 내가 뭐 속세의 고리회 일원이라도 되는 줄 알아?$B$B가만, 그러고 보니... 이건 속세의 고리회에 가져다주는 게 좋겠어. 호수에서 벌어지고 있는 사태를 완전히 수습해 버리는 데 도움이 된다면 난 대찬성이지.$B$B$N, 설마 속세의 고리회의 일원이 누군지 모르고 있는 건 아니겠지?'),
(1920, 'koKR', '정말 잘 했어요! 이 정령들을 연구해봐야겠어요. 연구하다 운이 좋으면 이 세계에 어떻게 들어왔는지 알 수 있겠죠.$B$B마법사 사회에서 당신의 가치가 점점 빛을 발하는군요.'),
(1944, 'koKR', '아, 아주 좋군요. 자비안의 사티로스들이 별로 속을 썩이지 않았길 바랍니다.$B$B고마워요, $N. 이 자비안의 물 표본은 즉시 연구해 보겠습니다.'),
(1998, 'koKR', '잘했네, $N. 자네가 죽음의 추적자들을 위해 많은 일을 해 왔고 그 가치를 증명했으니, 이제 그림자 기술 훈련을 더 진전시킬 때가 되었는지도 모르겠군.'),
(2159, 'koKR', '참, 그렇지. 그늘 협곡에서 약초가 오기로 했었는데... 안 그래도 포르타니우스와 의논할 게 많은데 직접 안 온 게 아쉽군. 어쨌든 약초를 받아서 다행이요. 당신을 만나게 된 것도 기쁜 일이고...$B$B여기 있는 동안 푹 쉬시오. 영웅은 항상 강인한 체력을 유지해야 하니 쉴 수 있을 때 충분히 휴식을 취하면서 피로를 풀어야지. 몸과 마음의 평안을 소홀히 하는 것은 실패의 지름길이니까...$B$B푹 쉬시오.'),
(2202, 'koKR', '수고했네. 다시 한번 자네의 가치를 증명했군! 이 버섯 연구는 틀림없이 아주 흥미로울 걸세.$B$B자, 이제 약속했던 대로 내가 만든 효과가 좋은 복원의 비약을 한 번 맛보게나...$B$B자네가 실력 있는 연금술사라면 앞으로 또 거래를 하게 되겠지. 어쨌든 도와줘서 고마웠네!'),
(2206, 'koKR', '놀랍군... 케린이 마침내 제대로 된 $c의 자질을 갖춘 신병을 찾아냈다니 놀라울 따름이야. 이 칼날을 받게, $N. 언젠가 자네가 다시 SI:7을 위해 일해야 할 날이 올 걸세. 기술을 갈고닦고, 눈을 부릅뜨고, 칼날을 날카롭게 유지하게.$B$B자네는 우리가 오는 걸 보지 못하겠지만, 우리가 도착하면 느끼게 될 걸세...'),
(2258, 'koKR', '아, 수고했네! 당분간은 이걸로 버틸 수 있겠군. 자, 여기 약속한 수고비일세.$B$B관심이 있는지 모르겠지만 아직 필요한 재료가 더 있다네. 그런데 이것들은 울다만 발굴 현장 깊숙한 곳에서만 찾을 수 있지. 구하기가 쉽지는 않을 테지만 날 한번 더 도와준다면 그 대가는 톡톡히 하도록 하지.$B$B어쩌면 반짝이는 동전보다 더 좋은 걸 줄 수도 있고 말이야. 어떤가?'),
(2523, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(2623, 'koKR', '내가 상상했떤 것보다 훨씬 더 심각하군. 그렇게 섣불리 행동하지 않았더라면, 지금 내 부하들 열 아홉은 그 끔찍한 고통을 겪지 않아도 될 텐데...$B$B그들을 도와주시오, $N! 육신이 없는 나는 아무것도 할 수 없소.'),
(2746, 'koKR', '이 정도면 쓸 만하겠어. 수고했소.$B$B나머지 필요한 도구는 내 가방에 들어있지. 재봉사 친구에게 비단 가방을 만들어 달라고 했는데 얼마나 잘한 일인지 모르겠단 말이야. 가방에 도구를 넣을 자리가 부족하던 참이었거든.$B$B자, 첩보로봇이 들어가기 전에 당신이 할 일이 무엇인지 알 수 있도록 정리를 해 보도록 하지.'),
(2749, 'koKR', '평범한 알을 찾아왔다고, $N? 어서 이리 주세요... 이제 잘 되기만을 바랄 수밖에요.$B$B가진 건 별로 없지만 보상을 받아 주세요. 혹시 페랄라스에 다시 가게 되면, 그곳에서 찾은 알을 받아 줄 사람이 여기 항상 있다는 걸 기억하세요.'),
(2757, 'koKR', '블랙후프의 등 털에 맹세코 — 마침내 미스릴 대장조합에 걸맞은 자가 왔군!$B$B'),
(2759, 'koKR', '이런, 맙소사! 드디어 미스릴 대장조합에 들어올 만한 자격이 있는 자가 왔군그래!'),
(2846, 'koKR', '멋지군! 찾았어! 이제 더 이상 욕심쟁이 벨라타가 티아라를 볼 수 없겠지... $N, 평생 다 못 갚을 큰 은혜를 입었군요! 설마 당신도 욕심이 났던 건 아니겠죠?$B$B아, 내 말이 좀... 거슬리나요? 신경 쓸 것 없어요. 내 물건을 훔치지 않은 자들한테는 상냥하다는 걸 알게 될 테니까.'),
(2852, 'koKR', '또다시 흠 하나 없이 완벽하게 지시 사항을 완수했군요. 어쩌면 언젠가 청출어람격으로 내가 당신에게 찾아가 배우게 될지도 모르겠군요. 안 그렇습니까?$B$B자, 다리보호구의 도안과 함께 내 감사의 마음도 함께 받아주십시오. 이 가르침을 깊이 새겨두고 당신이 완성한 제품에 놀라운 솜씨를 담아내도록 하시기 바랍니다.'),
(2860, 'koKR', '아, 장도르가 보낸 거로군요. 내가 가르친 가장 우수한 제자 중 하나가 이제 자신의 제자를 가르치다니 정말 기쁩니다.$B$B장도르의 가죽에 대한 헌신과 재능은 참으로 놀랍지요. 그가 이 편지에서 이토록 당신을 칭찬하다니 이것은 존중의 표시임을 나도 인정하지 않을 수 없군요.$B$B장도르가 야생 가죽의 도를 당신에게 가르친 것 같군요. 이 도안을 당신에게 주어 그 훈련을 마무리 짓도록 하겠습니다. 야생 가죽 망토의 비밀을 아는 이는 이 세계에서 아주 극소수뿐이니 유용하게 쓰도록 하시기 바랍니다.'),
(2878, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(2880, 'koKR', '그렇지, 바로 이거야! 이 목걸이는 자네가 기꺼이 손에 피를 묻힐 의지가 있다는 것을 증명해 주고 있네. 우리 와일드해머는 그런 점을 높이 평가하지.$B$B앞으로도 계속 이런 자세를 보여준다면 우리의 친구가 될 수 있겠는 걸.'),
(2966, 'koKR', '대좌를 건드리자 울다만에서 가져온 소형 원반이 배낭 속에서 웅웅거리며 빛납니다. 익숙한 저린 느낌이 손을 휩쓸며 울둠의 문 앞에 또 다른 바위감시자의 영상이 나타납니다.$B$B\"안녕하십니까. 저는 이 문을 지키는 문지기입니다. 당신이 사용하신 원반 중에 올바른 출입용 원반인 울둠의 원반이 빠져 있습니다. 원반 구조물과 이 원반들을 조립하신 후 다시 한번 출입 절차를 진행해 주시기 바랍니다. 감사합니다.\"'),
(2967, 'koKR', '빠진 원반이 있다고요? 재미있네요. 노르간논의 원반도 어떤 한 세트의 일부인 것 같아요. 열쇠 고리에 달린 여러 개의 열쇠들처럼 말이에요.$B$B울둠의 원반을 찾을 수만 있으면 실제로 울둠 내부에 들어갈 수 있을 거예요. 이 사실에 기뻐해야 할지 두려워해야 할지 모르겠군요.$B$B어쩌면 그 땅의 비밀이 밝혀지면 우리 모두를 파멸시킬 지도 몰라요. 우리의 전부를 걸어서라도 비밀을 지켜야 하는지도...'),
(2990, 'koKR', '아, 그래. 이 깃털은 아주 훌륭한 그리핀의 것이로군. 아주 위대한 일을 하게 될 운명을 지닌... 무사히 성년이 될 때까지 살아남을 수 있다면 말이지만...$B$B그를 찾고 싶은 건가? 그렇다면 내가 하는 말을 귀 기울여 듣게, 용감한 $C 친구...'),
(3099, 'koKR', '주인이 누구던 간에 노예는 노예라고 말했었지. 기억나오? 우리 둘 모두 그러한 지배력이 우리를 움직이는 힘이라는 걸 알고 있소. 우리는 생물들을 다스리려고 하지. 우리는 더 강하기에 지금보다 더 많은 존경을 받을 자격이 있다는 사실도 알고 있소. 이제 그 존경을 받을 때가 왔소.$B$B이 투쟁에서 내가 당신의 동지가 되어주겠소. 우리의 자유, 우리에게 충성을 바칠 자들을 찾을 수 있는 자유를 위한 투쟁 말이오. 준비가 되면 내게 되돌아오시오. 그러면 내가 아는 것을 모두 가르쳐주겠소.'),
(3106, 'koKR', '그리고 또 눈에 띌 만한 것들이 있어, 알아 두라고 하는 말인데: 드워프들이 전투에서 소총 대신 마법을 쓰는 모습이라든가, 일부 인간들처럼 성스러운 빛을 숭배하는 몇몇 동포, 마지막으로 트로그도 있지. 트로그에 대해서는 나중에 더 알게 될 텐데, 지금 알아야 할 건 내가 자네를 도와주려고 여기 있다는 거야.$B$B자네에게 진짜 $c가 되는 법을 가르쳐 주려고 여기 있지. 훈련이 더 필요하다 싶을 때는 언제든 나한테 돌아와, 내가 어떻게든 해 줄 테니.'),
(3117, 'koKR', '그늘 협곡에서 배울 것들을 경험해 가면서 나를 찾아오게 — 자네의 역할이 $c로서 무엇인지, 자네가 무엇을 할 수 있는지 이해하도록 내가 도울 수 있을 걸세.$B$B위험한 시대일세, $N. 자네 야수들의 능력을 당연하게 여기지 말게. 이 세상에는 자네가 상상하는 것보다 더 위험한 것들이 있다네. 엘룬과 함께 가고, 다시 내게 돌아오게.'),
(3118, 'koKR', '그때까지 우리 같은 이들이 이 위태로운 시기에 그 어느 때보다 필요하다는 점을 알아 두시오. 다른 종족과의 평화는 언제든 깨질 수 있고, 호드의 일부가 불신의 씨앗을 더 크게 퍼뜨리려 한다는 이야기도 많이 들리오. 이 점을 기억하시오.$B$B힘을 얻고 준비가 되었다고 느껴지면 여기 있는 내게 돌아오시오. 훈련을 받을 수 있도록 알아봐 주겠소. 무엇보다 자신이 선택한 무기를 다루는 법을 아는 것이 중요하오.'),
(3376, 'koKR', '그대의 신속한 행동으로 오늘 정의가 실현되었소, $N. 이 일이 우리 터전을 위협하려는 모든 자들에게 경고가 되기를 바라오.$B$B그대는 여정에 도움이 될 이 보상을 받을 자격이 있소, 젊은 $c.'),
(3510, 'koKR', '드디어 이 아크코로크의 지혜를 받을 만한 자가 나타났군!'),
(3511, 'koKR', '담금질이 무기를 벼리는 데 필요한 황산을 더해 줄 것이다. 이제 무기를 만드는 단계가 하나 남았을 뿐이다.'),
(3602, 'koKR', '아즈샤라에서 자네의 할 일은 끝났네. 나는 이제부터 자네의 모험에 필요한 물건들을 제작해야겠네.'),
(3621, 'koKR', '맙소사. 이 재료들을 구하느라 얼마나 고생했을지 알 만하네. 아즈샤라에 들어갔다가 살아나오는 자는 거의 없는 것으로 알고 있지. 거인들과 반은 신과 같은 존재들과 대적하는 게 얼마나 힘들지는 두말 안 해도 알고말고!'),
(3627, 'koKR', '파멸자 라젤리크의 아뮬렛이 다시 결합했지만 그가 자신의 지배 체계에 문제가 생긴 것을 느끼고 있다오. 바로 당신이 자신을 처치하러 온다는 것을 알고 있소.'),
(3639, 'koKR', '자, 여기 당신의 첫 번째 고블린 기술자 회원권이오!$B$B이 회원권은 회비를 선불로 내고 14일 동안 사용할 수 있소. 모든 회원권은 발급 받은 지 2주 후에 기간이 만료되는데, 만기가 되면 어떤 고블린 전문 기술자에게나 다음번 회비를 내고 새 회원권을 받도록 하시오. 회원권이 없으면 회원 자격이 일시 정지되어 새로운 설계도를 볼 수가 없소이다.$B$B회원 자격이 정지되어도 당신이 이미 알고 있는 것에는 아무런 영향을 주지 않소. 한번 고블린 기술자는 영원한 고블린 기술자니까 말이오.'),
(3643, 'koKR', '자, 여기 당신의 첫 번째 노움 기술자 회원권이오!$B$B이 회원권은 회비를 선불로 내고 14일 동안 사용할 수 있소. 발급받은 지 2주 후에 만료되는 데, 만기가 되면 아무 노움 전문 기술자에게나 회비를 내고 새 회원권을 받을 수 있소. 회원권이 없으면 회원 자격이 일시 정지되어 새로운 설계도를 볼 수 없다오.$B$B하지만 당신이 이미 습득한 지식에는 아무런 영향을 주지 않소. 한번 노움 기술자는 영원한 노움 기술자니까!'),
(3644, 'koKR', '당신은 고블린 기술자이며 신용도도 양호하니, 2골드의 수수료로 만료된 회원권을 갱신해 드릴 수 있습니다. 수수료를 내시면 새 회원권을 재발급해 드립니다. 이 회원권이 있으면 적절한 전문가에게서 고블린 기술 설계도를 열람할 수 있습니다.$B$B이 회원권은 2주 동안 활동할 수 있으며, 그 기간이 끝나면 회비를 다시 내야 합니다! 설계도를 열람하려면 밀린 회비를 정리하셔야 합니다.'),
(3645, 'koKR', '당신은 노움 기술자이며 신용도도 양호하니, 2골드의 수수료로 만료된 회원권을 갱신해 드릴 수 있습니다. 수수료를 내시면 새 회원권을 재발급해 드립니다. 이 회원권이 있으면 적절한 전문가에게서 노움 기술 설계도를 열람할 수 있습니다.$B$B이 회원권은 2주 동안 활동할 수 있으며, 그 기간이 끝나면 회비를 다시 내야 합니다! 설계도를 열람하려면 밀린 회비를 정리하셔야 합니다.'),
(3646, 'koKR', '당신은 고블린 기술자이며 신용도도 양호하니, 2골드의 수수료로 만료된 회원권을 갱신해 드릴 수 있습니다. 수수료를 내시면 새 회원권을 재발급해 드립니다. 이 회원권이 있으면 적절한 전문가에게서 고블린 기술 설계도를 열람할 수 있습니다.$B$B이 회원권은 2주 동안 활동할 수 있으며, 그 기간이 끝나면 회비를 다시 내야 합니다! 설계도를 열람하려면 밀린 회비를 정리하셔야 합니다.'),
(3647, 'koKR', '당신은 노움 기술자이며 신용도도 양호하니, 2골드의 수수료로 만료된 회원권을 갱신해 드릴 수 있습니다. 수수료를 내시면 새 회원권을 재발급해 드립니다. 이 회원권이 있으면 적절한 전문가에게서 노움 기술 설계도를 열람할 수 있습니다.$B$B이 회원권은 2주 동안 활동할 수 있으며, 그 기간이 끝나면 회비를 다시 내야 합니다! 설계도를 열람하려면 밀린 회비를 정리하셔야 합니다.'),
(3761, 'koKR', '아, 그거야. 참, 일부러 이 흙더미 위에 퍼올리는 걸 도와줄 생각은 말라고! 고대의 영혼들께서 진정 원하시는 일이라면 기적적으로 퍼올려질 테니까 말이지.$B$B대$C 룬토템님께서 당신과 다시 얘기하고 싶어하시오. 하지만 다음 임무를 수행하려면 적어도 중급 정도의 약초학 지식은 갖추고 있는 게 좋을 거야. 혹시 그게 아니더라도 당신이 대$C님께 전혀 쓸모 없는 친구는 아닐테니 어서 가보라고.'),
(3762, 'koKR', '어서 오게. 우리 연구를 돕는 데 관심을 가져 줘서 기쁘구만. 할 일이 많을 뿐더러, 관련 작업들이 위험하지 않다고 하면 거짓말을 하는 게 될 거야. 겁부터 줘서 쫓아버리는 게 되진 않았으면 좋겠구만... 하지만 자네 모습을 보아하니 이전에 이미 위험한 일을 해 본 경험이 있는 것 같은데.'),
(3783, 'koKR', '이 모피면 딱 되겠어요, $N. 출발이 아주 좋은데요!'),
(3784, 'koKR', '어서 오게. 우리 연구를 돕는 데 관심을 가져 줘서 기쁘구만. 할 일이 많을 뿐더러, 관련 작업들이 위험하지 않다고 하면 거짓말을 하는 게 될 거야. 겁부터 줘서 쫓아버리는 게 되진 않았으면 좋겠구만... 하지만 자네 모습을 보아하니 이전에 이미 위험한 일을 해 본 경험이 있는 것 같은데.'),
(3786, 'koKR', '수고하셨어요. 대드루이드님이 필요로 하실 때 제가 꼭 가져다 드리도록 하겠어요. 그리고 세나리온 의회에서 드리는 감사의 표시로 이걸 받아 주세요.$B$B여명초는 앞으로도 계속 필요한 것이니 계속 우릴 돕고 싶다면 여명초를 더 재배하여 절 다시 찾아오세요.'),
(3842, 'koKR', '좋소. 이거면 될 거요. 재료를 섞을 동안 잠시만 기다리시오. 이 알이 얼마나 튼튼할지 곧 알게 될 테니까.'),
(3882, 'koKR', '아주 좋소. 이거면 될 거요. 그리고 잠깐만 실례를...$B$B이 뼈들을 땅에서 파내고 살아있는 스테고돈에 해를 전혀 입히지 않아 줘서 아주 고맙소이다!!!$B$B당신이 정말로 땅을 파서 가져왔든 그렇지 않았든 나는 알고 싶지 않소. 그냥 그렇게 비밀로 간직하도록 합시다. 어때 괜찮겠지? 자, 이거면 이번 일에 대해서 당신이 완전히 입을 다물어 줄 수 있을 거요. 여기서 살아서 빠져나갈 수만 있다면야!'),
(3902, 'koKR', '잘했어, 친구. 당신이 쓸모 있을 줄 알았다니까. 자, 지금까지 수집한 물건 중 그나마 괜찮은 걸 골라 놨으니 하나 골라 가지라고.'),
(3907, 'koKR', '<쿠르니아의 서판을 거머쥐는 썬더하트>$B$B라그나로스가... 이곳에...$B$B장로들이 검은바위 산에서 뿜어져 나오는 타락을 걱정한 것이 옳았습니다. 고대 신들의 장군이라니! 우리의 세계에!!! 우린 카르가스에서의 우리 입지를 다시 세워야 합니다. 여기에 남아서 싸울 것인가 아니면 새로운 세계의 분리를 두려워하여 도망칠 것인가 반드시 결정해야 하는 겁니다.$B$B검은바위 산으로 다시 탐험을 떠나게 되면 조심하도록 하시기 바랍니다. 이 세계에 현존하는'),
(4101, 'koKR', '이 핏빛 호박석은 악령의 숲의 타락을 정화할 방법을 연구하는데 사용할 거예요. 그대는 세나리온 의회를 위해서라면 어떤 일이라도 감수하겠다는 것을 입증해 보였어요. 이제 당신을 믿겠어요.$B$B정령을 해치는 것이 그대의 뜻을 증명해 보일 수 있는 방법이라는 게 이상했겠지만 수많은 생명체들을 구하려면 결국 우리가 선택한 방법이 최선이었다는 걸 알게 될 거예요. 드디어 고약을 만들어 그대와 함께 생명을 보존할 수 있겠군요.$B$B 이제 악령의 숲을 정화할 때가 온 거예요.'),
(4113, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4114, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4116, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4117, 'koKR', '채찍뿌리에 세나리온 식물 고약 3개를 바르자 채찍뿌리가 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4118, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4293, 'koKR', '아. 훌륭하군. 이 견본들이면 되겠소. 도와줘서 고맙소이다.$B$B진흙괴물의 견본을 모두 모았으니 더 많은 것을 알아낼 수 있을 거요. 실바나스 여왕님의 예감이 적중하기도 했지만 그분 자신조차도 예측하지 못할 만큼 깊은 식견이 있었던 게 아닌가 생각되오. 이 견본들은 아주 흥미롭군. 내 혼합물들에 반응하는 모양을 보니... 흠. 그래. 분명 더 조사해봐야겠소.'),
(4385, 'koKR', '탁자 위에 수정들을 늘어놓고 색깔을 조심스럽게 맞춥니다. 마지막 수정을 제자리에 밀어 넣자 빛이 번쩍이며 수정들이 하나로 융합됩니다.$B$B이제 완성된 조합이 당신의 것입니다.'),
(4386, 'koKR', '탁자 위에 수정들을 늘어놓고 색깔을 조심스럽게 맞춥니다. 마지막 수정을 제자리에 밀어 넣자 빛이 번쩍이며 수정들이 하나로 융합됩니다.$B$B이제 완성된 조합이 당신의 것입니다.'),
(4401, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4443, 'koKR', '채찍뿌리에 세나리온 식물 고약 3개를 바르자 채찍뿌리가 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4444, 'koKR', '채찍뿌리에 세나리온 식물 고약 3개를 바르자 채찍뿌리가 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4445, 'koKR', '채찍뿌리에 세나리온 식물 고약 3개를 바르자 채찍뿌리가 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4446, 'koKR', '채찍뿌리에 세나리온 식물 고약 3개를 바르자 채찍뿌리가 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4461, 'koKR', '채찍뿌리에 세나리온 식물 고약 3개를 바르자 채찍뿌리가 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4464, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4465, 'koKR', '세나리온 식물 고약을 노래꽃에 바르자 노래꽃이 곧바로 오염된 모습을 벗어 던지고 생기 넘치고 건강한 식물로 피어납니다.'),
(4484, 'koKR', '머리가... 지끈거린다... 우리 우주를 이루는 광대한 에너지가... 으아악!$B$B원하는 것을 가지고 떠나라!'),
(4642, 'koKR', '아. 정말 잘 됐군. 정말로 굉장하오.$B$B아주 재미있는 일이 벌어졌군그래. 이 둘이 그런 반응을 보일 줄이야... 이 생물들을 변화시키는 환경적 요인에 대해 좀 더 조사해봐야겠소.$B$B나는 당분간 연구를 계속할 것이오. 조만간 다시 얘기를 나눌 날이 오겠지. 그 때까지 몸조심하시오.'),
(4742, 'koKR', '<잠시 흐릿해지는 밸란의 형상>$B$B<지금까지 모았던 조각들이 사라졌습니다.>$B$B벼려지지 않은 승천의 인장이 준비되었다. 이제 마지막 단계를 행할 시간이도다.'),
(4781, 'koKR', '딱 이거면 되겠군. 그렇게 빨리 광부를 찾아 도움을 받을 수 있었다니 다행이군. 아니면 당신이 직접 한 건가? 어찌 됐든 아주 잘했어. 이거라면 실을 만드는 데 아주 안성맞춤이야.$B$B실을 만들려면 시간이 오래 걸리니 나중에 다시 와야 할 것 같네. 탑 안에 갇혀 금실만 잣고있는 어떤 공주에게 이 금괴를 보내야 하거든... 아... 진짜라니까, 진짜라고... 아! 알았네. 농담이었어.'),
(4784, 'koKR', '훌륭합니다, $N! 구성 요소가 모두 모였으니 준비가 끝났군요.$B$B마음에 드실 거라 믿어요.'),
(4801, 'koKR', '마우아리가 $N|1을;를; 위해 주술을 일으킬 수 있다, 몬... 마우아리의 부적을 사용해 자신이나 동료들에게 이 주술을 걸어라.'),
(4802, 'koKR', '마우아리가 $N|1을;를; 위해 주술을 일으킬 수 있다, 몬... 마우아리의 부적을 사용해 자신이나 동료들에게 이 주술을 걸어라.'),
(4803, 'koKR', '마우아리가 $N|1을;를; 위해 주술을 일으킬 수 있다, 몬... 마우아리의 부적을 사용해 자신이나 동료들에게 이 주술을 걸어라.'),
(4804, 'koKR', '마우아리가 $N|1을;를; 위해 주술을 일으킬 수 있다, 몬... 마우아리의 부적을 사용해 자신이나 동료들에게 이 주술을 걸어라.'),
(4805, 'koKR', '마우아리가 $N|1을;를; 위해 주술을 일으킬 수 있다, 몬... 마우아리의 부적을 사용해 자신이나 동료들에게 이 주술을 걸어라.'),
(4806, 'koKR', '마우아리가 $N|1을;를; 위해 주술을 일으킬 수 있다, 몬... 마우아리의 부적을 사용해 자신이나 동료들에게 이 주술을 걸어라.'),
(4807, 'koKR', '마우아리가 $N|1을;를; 위해 주술을 일으킬 수 있다, 몬... 마우아리의 부적을 사용해 자신이나 동료들에게 이 주술을 걸어라.'),
(4810, 'koKR', '가져왔군요! 좋아요! 바로 일을 시작해야겠네요! 백만 스물하나만큼 고마워요!$B$B당신은 정말 큰 도움이 되었어요. 나중에 이것보다 더 중요한 일을 맡게 될 거예요.'),
(4812, 'koKR', '신비한 수정과 다시 만나게 되었습니다. 시험관의 마개를 따고 그 안에 든 달샘의 물을 수정 위에 붓습니다. 달샘의 물이 수정에 흘러내리자, 흐릿한 표면이 투명하게 변합니다.'),
(5022, 'koKR', '엠마 펠스톤에게 보낸 소포라고 하셨습니까? 4년 전 마지막 주소가 스톰윈드라고요? 어디 한번 보지요...$B$B우리 기록에 의하면 4년 전에 엠마 펠스톤이라는 여성이 스톰윈드에서 살았군요. 제가 보고 있는 기록은 5년 전 것이라 확실하지는 않지만 도시를 떠난 기록은 없습니다. 그렇다고 해서 엠마 펠스톤이 반드시 이곳에 있다는 뜻은 아닙니다.$B$B잠깐... 혹시 이 소포가 올엠마의 것은 아닐까요?'),
(5023, 'koKR', '제레미어 펠스톤이라는 자에게 보내는 소포란 말인가? 마지막 주소가 로데론이었다라... 내가 도와줄 수 있겠군그래.$B$B제레미어 펠스톤은 로데론에 역병이 퍼지기 전에 살았군. 그러니까 전 제레미어 펠스톤이라고 해야 하나... 어떤 포세이큰은 살았을 때의 모습을 없애기 위해 성을 바꾸기도 했으니 말이야. 이 경우도 예외는 아닌 것 같군. 전 제레미어 펠스톤은 이제 제레미어 페이슨으로 이름을 변경했네.$B$B가만... 그 친구는 바퀴벌레 상인일 텐데?'),
(5046, 'koKR', '전쟁터로 나아가라, $R.'),
(5048, 'koKR', '그래요. 내 이름이 엠마 펠스톤이에요. 지난 몇 년 동안 날그렇게 부른 사람은 없었는데... 당신은... 누구죠?$B$B내... 여동생을 안다고 했나요? 동생은 아직 살아 있나요? 이런, 내가 무슨 정신 나간 소리를 하는 거지. 걔가 살아있을 리가 없는데... 로데론에 역병이 퍼졌을 때 모든 희망을 버리게 되었어요. 가족들은 모두 죽어갔고... 난 이렇게 미친 올엠마로 혼자 살아가고 있어요. 당신은 대체 누구에요? 다음 범행 대상을 물색하는 도굴꾼인가요?$B$B뭐라고요? 동생이 내게 보내는 소포를 가져왔다고요?'),
(5049, 'koKR', '그 이름을 안 쓴지는 벌써 몇 년이나 지났지만... 그렇습니다. 이 언데드의 삶을 살기 이전, 내 살아 생전에는 펠스톤, 그게 내 성이었습니다.$B$B당신은 내 여동생을 알았다고, 아니, 최근에 내 여동생과 얘기를 나누었다고 주장을 하는데 말입니다. 내 여동생은 죽었습니다.$B$B4년 전에 말입니다. 내 뼈가 이렇게 상하지만 않았어도 발로 당신 엉덩이를 차 주고 싶은 심정입니다. 사기꾼 같은 친구로군요.$B$B뭐...? 내 여동생이 보낸 소포라고요?'),
(5092, 'koKR', '임무 완료로군! 수고했소, 아주 수고했어.$B$B스톰윈드 국세에서 이번 임무에 대한 보상금을 지급해 주겠소. 그 돈으로 다음 임무에 필요한 장비를 구입해 두는 게 좋을 거요... 다음 임무를 수행하려면 안돌할의 폐허까지 직접 들어가야 하니까 말이지.$B$B준비를 단단히 하고 경계를 소홀히 하지 마시오!'),
(5125, 'koKR', '난 죽어가지만... 내 영혼이 구제되었소. 당신에게 뭐라 말로 표현할 수 없는 신세를 진 거요. 부디 이걸 받아주시오. 그리고 계속 싸우시오. 용맹한 $C|1이여;여;!'),
(5143, 'koKR', '그대가 가져온 야생 가죽 세공품들을 보니 곧 자연이 그대에게 순응하게 될 것 같군요. 내 수업이 끝나면 그대의 세공품에 자연의 힘이 깃들게 될 거예요.$B$B차후에 수업을 받으려면 언제든지 내게 오도록 하세요. 그러면 당신이 가진 지식을 실제로 이용하는 방법을 가르쳐 주겠어요.'),
(5144, 'koKR', '그대는 운명을 걸었고, 정령들이 그대를 받아들였네. 내 가르침이 끝나면 그대는 최고의 가죽 의복을 만들어 내는 의지를 다스리게 될 걸세.$B$B앞으로 이 기술을 더 수련하고 싶다면 내게 말을 걸게. 그대가 아직 익히지 못한 지식은 무엇이든 가르쳐 주겠네.'),
(5163, 'koKR', '헤헤! 두 번 다시는 저를 놀리지 못할 거예요!$B$B도와줘서 고맙습니다, $N. 당신 없이는 이렇게 큰 재미를 보지 못했을 거예요!'),
(5203, 'koKR', '아르코나린의 탈출을 도운 것이 바로 그대였다고요? 절 찾아 오셔서 정말 다행이로군요. 얼마 전 아르코나린이 다르나서스로 가는 길에 잠시 들렀어요. 힘겹게 라이트포지를 들고서 드루이드에게 치유를 받을 틈도 없이 서둘러 떠나더군요. 굉장히 급한 일이라면서 말이에요.$B$B그래도 트레이의 영혼과 만난 일은 얘기해 주었어요. 은빛성기사단의 훌륭한 기사가 그렇게 끔찍한 종말을 맞이하다니... 아르코나린은 내색을 하지 않았지만, 전 알아요. 그녀가 마음 속으로 너무나 아파하고 있다는 걸. 가장 가까운 친구를 하나 잃었으니까요.'),
(5214, 'koKR', '오오, 소중하고도 소중한 내 담배! 내가 얼마나 널 그리워했는지 아니...'),
(5216, 'koKR', '가마솥군주 창자아귀를 처치하고 얻은 열쇠가 꼭 들어맞습니다. 문을 열자 가마솥 안에 소용돌이치고 있는 알 수 없는 응축 조합물에서 지독한 악취가 납니다.$B$B아래 부분에 병이 들어맞는 작은 꼭지가 있어 서리바람 거점에 있는 대여$C 맥도널에게 가져다줄 견본을 뽑을 수 있습니다.'),
(5218, 'koKR', '가마솥에 시약을 넣자 솟아오르는 연기의 색과 질감이 변하기 시작합니다. 가마솥 가까이에 있던 스컬지들은 새로 섞여 든 성분에 움찔하며 뒷걸음질 칩니다.'),
(5219, 'koKR', '가마솥군주 말비니어스를 처치하고 얻은 소름 끼치게 생긴 열쇠가 열쇠 구멍에 쉽게 미끄러져 들어가더니 사라지고, 입구가 완전히 열립니다. 가마솥 받침대 안에서는 정제되지 않은 끈적끈적한 고름 같은 액체가 뒤틀린 관 속을 고동치며 흐르고 있습니다.$B$B아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 서리바람 거점에 있는 대여사제 맥도널에게 가져갈 견본을 뽑아 낼 수 있습니다.'),
(5221, 'koKR', '가마솥에 시약을 넣자 솟아오르는 연기의 색과 질감이 변하기 시작합니다. 가마솥 가까이에 있던 스컬지들은 새로 섞여 든 성분에 움찔하며 뒷걸음질 칩니다.'),
(5224, 'koKR', '가마솥에 시약을 넣자 솟아오르는 연기의 색과 질감이 변하기 시작합니다. 가마솥 가까이에 있던 스컬지들은 새로 섞여 든 성분에 움찔하며 뒷걸음질 칩니다.'),
(5227, 'koKR', '가마솥에 시약을 넣자 솟아오르는 연기의 색과 질감이 변하기 시작합니다. 가마솥 가까이에 있던 스컬지들은 새로 섞여 든 성분에 움찔하며 뒷걸음질 칩니다.'),
(5283, 'koKR', '$N, 다시 되돌릴 수 없는 선택이오. 장난감이나 만들고 싶다면... 그러니까 무기를 제작하고 싶다면 지금이라도 늦지 않았으니까 얘기하시오.$B$B당신이라면 현명한 결정을 내릴 거라고 믿소이다.'),
(5284, 'koKR', '제때 잘 끝냈군그래. 손님들이 벌써 그 물건들을 기다리고 있었거든.$B$B한 번 보여 주고 반응을 잘 살펴봐. 자, 이제 무기제작자로서 첫발을 내디딘 거야.'),
(5386, 'koKR', '오, 그대는 구세주로군요! 붉은복어가 날로 먹어도 될 만큼 신선하군요.$B$B<군침을 흘리는 나타카>$B$B이 중에서 하나를 고르세요. 붉은복어를 가져다주신 데 대한 보답입니다.'),
(5402, 'koKR', '축하합니다, $N. 은빛 여명회 명예 휘장을 수여하게 되어 기쁩니다!$B$B이 휘장은 두 가지 용도가 있습니다. 첫째, 은빛 여명회 내에서 당신의 평판을 높이는 데 쓸 수 있습니다. 평판이 오르면 우리가 명예롭게 여기고 존경하는 동지에게만 허락되는 선택지와 보상을 얻게 될 것입니다. 둘째, 보급 담당관에게 돈과 함께 건네면 여명회의 귀중한 물품을 얻는 대가로 쓸 수 있습니다.$B$B어느 쪽을 택하시든, 당신이 맡은 임무에 걸맞은 활약을 하고 있다는 것만은 알아 두십시오. 잘하셨습니다!'),
(5403, 'koKR', '축하합니다, $N. 은빛 여명회 명예 휘장을 수여하게 되어 기쁩니다!$B$B가치 있는 이에게 수여되는 명예 휘장 하나하나는 스컬지에 맞서 전세가 뒤바뀌고 있다는 증거입니다. 점점 더 많은 영웅이 각자의 땅에서 스컬지와 싸우고 있으니, 스컬지라는 궁극의 악과 전쟁을 벌일 때 은빛 여명회가 선봉에 서게 될 것입니다. 휘장을 얻기 위해 보여 주신 용기가 그때에도 승리를 가져다주기를 바랍니다!'),
(5404, 'koKR', '축하합니다, $N. 은빛 여명회 명예 휘장을 수여하게 되어 기쁩니다!$B$B이런 방식으로 명예 휘장을 얻었다는 것은 선을 위해 싸우는 진정한 영웅이라는 뜻입니다. 우리는 스컬지에 맞선 모든 노력을 소중히 여기지만, 그들의 지휘관 중 하나를 쓰러뜨리는 일은 진정으로 그들에게 통렬한 패배를 안기는 일입니다!$B$B여명을 위하여, $g형제:자매;여!'),
(5406, 'koKR', '축하합니다, $N. 은빛 여명회 명예 휘장을 수여하게 되어 기쁩니다!$B$B이런 방식으로 명예 휘장을 얻었다는 것은 선을 위해 싸우는 진정한 영웅이라는 뜻입니다. 우리는 스컬지에 맞선 모든 노력을 소중히 여기지만, 그들의 지휘관 중 하나를 쓰러뜨리는 일은 진정으로 그들에게 통렬한 패배를 안기는 일입니다!$B$B여명을 위하여, $g형제:자매;여!'),
(5407, 'koKR', '축하합니다, $N. 은빛 여명회 명예 휘장을 수여하게 되어 기쁩니다!$B$B가치 있는 이에게 수여되는 명예 휘장 하나하나는 스컬지에 맞서 전세가 뒤바뀌고 있다는 증거입니다. 점점 더 많은 영웅이 각자의 땅에서 스컬지와 싸우고 있으니, 스컬지라는 궁극의 악과 전쟁을 벌일 때 은빛 여명회가 선봉에 서게 될 것입니다. 휘장을 얻기 위해 보여 주신 용기가 그때에도 승리를 가져다주기를 바랍니다!'),
(5408, 'koKR', '축하합니다, $N. 은빛 여명회 명예 휘장을 수여하게 되어 기쁩니다!$B$B이 휘장은 두 가지 용도가 있습니다. 첫째, 은빛 여명회 내에서 당신의 평판을 높이는 데 쓸 수 있습니다. 평판이 오르면 우리가 명예롭게 여기고 존경하는 동지에게만 허락되는 선택지와 보상을 얻게 될 것입니다. 둘째, 보급 담당관에게 돈과 함께 건네면 여명회의 귀중한 물품을 얻는 대가로 쓸 수 있습니다.$B$B어느 쪽을 택하시든, 당신이 맡은 임무에 걸맞은 활약을 하고 있다는 것만은 알아 두십시오. 잘하셨습니다!'),
(5581, 'koKR', '잘했습니다. 그대의 노력은 악마의 위협에 맞서 싸우는 데 큰 도움이 되었으며 아제로스의 모든 것이 좀 더 안전해질 것입니다!'),
(5803, 'koKR', '그래, 바로 이것입니다! 정말... 당신의 영리함과 용기에 놀라지 않을 수가 없군요. 어둠의 군대를 이렇게 빨리 물리치다니 믿을 수가 없습니다.$B$B이제 내 역할을 할 차례로군요. 스카라베를 열쇠의 머리에 안전하게 붙일 수 있는 특수한 용매를 준비했습니다. 스칼로맨스의 잠긴 문 뒤쪽까지 닿도록 힘을 줘서 부으면 된답니다.$B$B그렇게 오래 걸리지 않을 겁니다...'),
(5845, 'koKR', '비록 상처투성이일지라도 이제는 내가 그리던, 동맹의 서약을 맺던 시절만큼이나 영광스럽군.$B$B탤런을 구원할 날도 그리 멀지 않은 것 같네.'),
(6026, 'koKR', '절반은 지금 지급하고 절반은 일이 끝나면 지급하겠네.'),
(6028, 'koKR', '그레고르는 참 수완이 좋군요. 스팀휘들 무역회사와 한동안 거래해 오면서 고블린식 협상의 \'기술\'에 도가 텄지요. 고블린의 최우선 충성 대상이 돈주머니가 가장 큰 쪽이라는 말은 사실이지만, 그들도 외교의 가치를 알고 존중합니다. 어쨌든 단골 고객이 생기는 셈이니까요...$B$B아무튼 은빛 여명회는 당신의 노고를 인정합니다. 우리의 감사의 표시로 이것을 받아 주십시오.'),
(6029, 'koKR', '인간치고는 수완이 좋군요, 그레고르는. 스팀휘들 무역회사와 한동안 거래해 오면서 고블린식 협상의 \'기술\'에 도가 텄지요. 고블린의 최우선 충성 대상이 돈주머니가 가장 큰 쪽이라는 말은 사실이지만, 그들도 외교의 가치를 알고 존중합니다. 어쨌든 단골 고객이 생기는 셈이니까요...$B$B아무튼 은빛 여명회는 당신의 노고를 인정합니다. 우리의 감사의 표시로 이것을 받아 주십시오.'),
(6127, 'koKR', '조상님들이시여, 물이 역겹구먼! 가젤들이 병들 만도 하군.$B$B무언가가 물을 오염시키고 있고, 그 때문에 북부 불모의 땅 생태계가 무너지기 시작하고 있어. 병든 가젤이 이곳 동서 도로 북쪽 전역에서 목격되었지. 이 물이 병을 퍼뜨리는 주된 원인일 가능성이 높지만, 그 밖에도 뭔가 작용하고 있는 게 있어.$B$B믿기 어렵겠지만 이 물이 치료제를 만드는 데 도움이 될 걸세. 내가 이 물을 연구하는 동안, 치료제를 만들 재료가 몇 가지 필요하네...'),
(6128, 'koKR', '$N, 잘했네. 연고를 만들기에 충분한 양이로군. 병든 가젤 몇 마리를 치료하기에는 충분하겠어.$B$B질병을 일으키는 독마다 정화할 치료제의 성분이 다르기 때문에, 치료제를 만드는 일은 무척 어렵지. 딱 알맞은 재료가 도대체 뭘까 고민하지 않고 마음 편히 병을 치유해 줄 수 있다면 얼마나 좋겠나!$B$B자, 이제 자네가 가져온 이 재료를 사용해 치료제를 만들어 봐야겠군!'),
(6142, 'koKR', '딱 됐네요. 의술사님이 두통이 나거든 이렇게 하라고 하셨어요. \"마이라힐. 가서 낚시를 해. 두통이 나아질 게야.\" 이렇게 말씀하시죠.$B$B벌써 두통이 가신 것 같아요. 정말 고마워요!'),
(6164, 'koKR', '아, 여기 있군! 맙소사! 얼마나 빽빽하게 써 놨었는지 잊고 있었군!$B$B오늘은 아주 멋진 날이야! 황홀하고 좋아서 미칠 것만 같은 날이라고!'),
(6393, 'koKR', '제 속의 물의 영혼들이 흥분의 거품을 터뜨리며 기쁨을 감추지 못하는군요. 해일의 심판장에 영광스러운 승전의 소식을 전할 수 있게 해주셔서 정말 감사 드립니다.'),
(6421, 'koKR', '바로 이거야! 리조나이트 수정에 토석인의 흔적이 남아 있군. 코볼트들이 토석인을 발견하려고 동굴을 샅샅이 파헤친 게 분명해.$B$B전설에 따르면 티탄들이 토석인을 창조했다지. 토석인을 이용해 우리가 지금 밟고 서 있는 이 땅을 창조했어. 그래, 이건 분명 그냥 지나칠 수 없는 위협이야.$B$B<고개를 끄덕이는 모르로갈>$B$B이 광석 표본에 마력을 부여하면 코볼트의 계략에 대항할 수 있을 거야.'),
(6442, 'koKR', '이 근처에 당신 같은 분이 더 있었으면 좋겠군요. 도와 주셔서 감사합니다.'),
(6462, 'koKR', '찾았군! 고맙네! 정말로 고마워, $N! 이게 얼마나 중요한 일인지 자네는 모를 거야.$B$B부적이 없는 트롤은 몸에 흉터가 하나도 없는 민숭민숭한 오크나 마찬가지야...$B$B그러니까... 아무짝에도 쓸모가 없단 얘기지.'),
(6571, 'koKR', '$N, 잘했네. 내 일을 정말 많이 덜어주었군.$B$B자네에게 진심으로 고마워하고 있다는 걸 알아주게.'),
(6801, 'koKR', '적들의 피가 뿌려졌구나. 이 피를 지금까지 모은 피와 섞겠다. 제물이 완성되면 얼음 군주께서 저 스톰파이크 개들에게 서리늑대 부족의 분노를 똑똑히 보여 주실 것이다!'),
(6825, 'koKR', '함대가 놈들의 살을 먹는다. 적을 집어삼킨다.$B$B곧 비상이다!'),
(6844, 'koKR', '이런 세상에! 이게 도대체 뭐죠? 뭐, 책 모양 비슷하게 생긴 것 같긴 한데... 내가 이 껍질을 한번 깨 보겠습니다.$B$B실리더스에서 라요가 보내서 왔다고요? 그곳에서 끔찍한 일이 일어나고 있다고 사람들이 비밀스럽게 속닥대는 걸 듣긴 했는데, 어떻게 보면 속닥거린 거라고 할 수 없을 것도 같고... 게다가 나는 벌레처럼 생긴 거라면 딱 질색인데, 당신이 별 희한한 걸 다 가져와서 나를 이곳에 머무르게 하는군요.'),
(7002, 'koKR', '잘했다, 병사. 가죽을 충분히 비축하면 알려 주겠다.$B$B계속 임무에 임하라!'),
(7162, 'koKR', '자, 스톰파이크의 긍지를 가지고 이 계급장을 착용하도록 하시오. 스톰파이크 경비대에서 계급이 올라가면 계급장도 같이 변경될 것이오. 스톰파이크에서 명예를 더 쌓게 되면 내게 돌아오시오. 당신의 계급장을 더욱 강력한 다른 계급장으로 바꿔주도록 하겠소.$B$B어쩌면 훗날 당신이 이 전장의 전설로 떠오르게 될지도 모르지. 그런 날이 오면 지휘의 눈을 받게 될지도 모르오.'),
(7385, 'koKR', '적들의 피가 뿌려졌구나. 이 피를 지금까지 모은 피와 섞겠다. 제물이 완성되면 얼음 군주께서 저 스톰파이크 개들에게 서리늑대 부족의 분노를 똑똑히 보여 주실 것이다!'),
(7441, 'koKR', '찾았군! 괘씸한 임프 녀석 같으니... 유감스럽지만 내가 가진 게 변변치 못해서 말이오. 내가 줄 수 있는 것 중에서 한 번 골라보도록 하시오.'),
(7507, 'koKR', '이 책을 암시장에 팔면 돈 좀 꽤 받았을 텐데... 더군다나 보호 인장이 깨져 필요한 지식을 가진 자라면 누구나 이 성스러운 책 안에 든 용 퇴치법을 읽을 수 있게 되었으니 말이오.$B$B아주 큰 보상을 해줘야 마땅하겠지... 뭐, 얻으려면 아주 큰 고생을 해야만 하는 그런 보상 말이오.$B$B<씩 웃는 리드로스>'),
(7603, 'koKR', '약속은 약속이지! 그럼, 내가 지닌 최고의 소환 마법을 가르쳐주지! 자, 얼른 받아 적으라고... 난 바쁜 몸이니까!'),
(7626, 'koKR', '아주 좋소! 이 비약들을 구하는 데 너무 고생하지는 않았길 바라오. 연금술사들은 가끔 자기 작품에 정말 인색하단 말이지...$B$B종은 내가 만들어서, 그대의 의식 준비가 끝날 때까지 보관하고 있겠소.'),
(7627, 'koKR', '거기 있었군! 검은무쇠 광석은 검은바위 산 깊은 곳에서만 나온다고 들었는데, 이 파편들도 구하기 쉽지 않았을 테지. 흑마법사들의 그 열정에는 늘 감탄하게 된다오. 그 모든 열정을 벌레 잡는 기술에 쏟는다면, 오... 얼마나 풍성한 만찬을 즐길 수 있겠소!$B$B미안하오, 잠깐 딴 길로 샜군. 바퀴는 내가 만들어서, 그대의 의식 준비가 끝날 때까지 보관해 두겠소.'),
(7628, 'koKR', '아, 아주 좋아. 양초의 불을 억제하려면 이것들이 필요할 거야. 이제 비늘이 생겼으니 양초를 만들어 자네가 대소환진 의식을 시작할 준비가 될 때까지 내가 지니고 있도록 하지.'),
(7637, 'koKR', '축복이 있기를, 친구 $c! 그대의 기부는 필요했던 것보다 훨씬 큰 것이오. 그대의 희생은 우리가 잃은 것을 되찾는 데 도움이 될 뿐 아니라, 이곳 아이언포지에서 가장 도움이 절실한 이들을 돕는 데에도 쓰일 것이오.$B$B이제 이 향로가 앞으로 그대에게 쓸모가 있도록 제대로 준비해 두겠소...'),
(7642, 'koKR', '이건... 정말 내가 필요하던 바로 그것이오. 그대는 참 수완이 좋은 $c이군요, 그렇지 않소?$B$B좋소, 그럼 이 말 갑옷을 마저 완성해 드리겠소!'),
(7643, 'koKR', '고대 준마의 영혼이 맛좋은 만나 사료를 제물로 받아들이고, 특별한 귀리와 곡식을 맛있게 먹으며 통에 코를 비빕니다. 조금 먹고 난 뒤, 당신이 가지고 있는 말 갑옷을 바라보더니 등 위에 올려 달라는 듯한 자세를 취합니다...'),
(7646, 'koKR', '훌륭한 표본들이오, $N. 마지막 조각들이 이제 모두 갖춰졌소. 드디어 그대의 때가 온 것이오!$B$B스칼로맨스의 대형 납골당 깊은 곳에는 수많은 존재의 해골 유해가 있소. 그중에는 한때 고귀했던 군마도 있지. 이 군마의 텅 빈 영혼은 이제 죽음의 기사 다크리버의 탈것이 되어 있소. 그대가 맞서게 될 자가 바로 그이며, 그대가 심판하게 될 것이 바로 이 군마요. 오직 그대, $N만이 그 영혼을 구원하고 예속의 고통에서 해방시킬 수 있소.'),
(7657, 'koKR', '거래는 잘했군, $N.$B$B그 불만스런 얼굴 좀 치워라. 보기만 해도 속이 쓰리다, 하하!'),
(7736, 'koKR', '불꽃 융해촉진제는 언제나 더 있어도 좋지, 애송이. 내가 그만하라고 할 때까지 계속 가져오라고.'),
(7737, 'koKR', '잔여물을 계속 쏟아부어라!'),
(7738, 'koKR', '아주 놀라운 걸 발견했군! 내가 본 것 중 가장 훌륭한 설인 가죽 견본인 것 같소!$B$B당연히, 이런 가죽은 제대로 값을 쳐 줘야지. 보통 가죽 하나에 이렇게 많은 돈을 지불하지는 않지만 분명 이 가죽으로 특별한 걸 만들 수 있을 거요. 이런 물건을 나한테 가져다줘서 고맙소이다!'),
(7787, 'koKR', '제발 해치지 마세요! 가져가세요! 칼을 가져가요! 데미트리안이 이 한심한 삶을 다시 꾸려 갈 수 있게 놔 주세요!'),
(7842, 'koKR', '이야, 이거 괜찮겠는데. 이제 한 단계만 더 거치면 와일드해머 드워프들이 감히 트롤족에게 함부로 덤벼선 안 된다는 걸 깨닫게 될 거야!'),
(7881, 'koKR', '고맙습니다, $N. 아주 잘 만들었군요. 솜씨가 최고입니다! 여기 다크문 축제 상품권입니다... 즐기십시오, 손님.'),
(7882, 'koKR', '아, 조끼를 가져오셨군요. 훌륭합니다. 어떤 동물의 가죽으로 만드셨는지 여쭤 봐도 될까요? 바느질이 아주 훌륭하고 가죽 질감에서도 거친 멋이 느껴지는군요. 솜씨 좋은 장인이신 게 분명합니다!$B$B감사합니다, $N. 여기 상품권입니다.'),
(7883, 'koKR', '어머, 꽤 크네요!! 이렇게 큰 옷이 딱 맞는 노움을 찾을 수 있을지는 모르겠지만, 걱정 마세요. 찾아낸 노움이 충분히 크지 않으면 의상을 고치면 되니까요.$B$B정말 고마워요, $N. 약속한 상품권입니다.'),
(7884, 'koKR', '좋아요, 만드셨군요! 이거면 되겠어요... 때가 되었을 때 악어 우리를 청소하는 사람이 제가 아니기만을 바랄 뿐이죠. 그 짐승들은 정말이지 짐승 같잖아요?$B$B여기 상품권입니다, $N. 잘 쓰시고, 다크문 축제에서 즐거운 시간 보내세요!'),
(7885, 'koKR', '아마 당신은 모르겠지만 다크문 축제를 순회하며 운영하는 데는 비용이 아주 많이 든다오! 모든 장비가 워낙 빨리 마모되다 보니 흑자를 낸다는 것 자체가 놀라울 정도지.$B$B이런 남모를 비용 때문에 우리는 늘 장비를 가능한 한 저렴한 비용으로 유지 관리할 수 있는 방법을 찾고 있소. 예를 들어, 천막은 자주 찢어지지만 가죽 방어구 키트를 사용하면 훌륭하게 수선할 수 있다오. 그래서 말인데, 방어구 키트를 좀 구해다 주지 않겠소? 그러면 엄청난 비용을 절'),
(7889, 'koKR', '좋아! 이거면 되겠어! 너무 무겁지도 가볍지도 않아. 근육을 키우기에 딱 좋겠군!$B$B정말 고마워요, $N. 여기 다크문 축제 상품권이에요!'),
(7890, 'koKR', '돌을 가져왔군요! 게다가 무겁군요! 벌써 근육이 커지는 게 느껴져요. 고마워요, $N!$B$B자, 이 상품권을 받으세요. 축제에서 단 음식은 너무 많이 먹지 마세요. 당신처럼 크고 강한 $c는 항상 전투에 맞는 몸을 유지해야 하니까요!'),
(7891, 'koKR', '정말 고마워요, $N. 여기 다크문 축제 상품권이에요!'),
(7892, 'koKR', '정말 고마워요, $N. 여기 다크문 축제 상품권이에요!'),
(7894, 'koKR', '아하! 변조기들이군요! 훌륭합니다!$B$B정확히 무엇을 만들고 있는지는 말씀드릴 수 없지만, 이것들은 제작에 꼭 필요한 물건입니다. 신세를 졌군요, $n. 감사의 표시로 다크문 축제 상품권을 받아 주십시오.'),
(7895, 'koKR', '장치들을 가져오셨군요! 훌륭해요! 지금도 윙윙, 웅웅거리는 그 소리가 머릿속에 들려요! 아, 이 전시장이 완성되면 세상의 불가사의가 될 거예요, 두고 보세요!$B$B여기 상품권이에요, $N. 그리고 축제에서 즐거운 시간 보내세요!'),
(7896, 'koKR', '폭죽을 가져오셨군요. 훌륭한 솜씨예요, $N! 어서 불을 붙여서 내 전시장이 준비되었다고 세상에 알리고 싶어요! 아직 한참 기다려야 하지만... 준비가 되면 되는 거죠, 그렇죠?$B$B여기 상품권이에요, $N. 즐겁게 보내세요!'),
(7897, 'koKR', '고마워요! 이제 수리를 시작할 수 있겠어요.$B$B모든 걸 제대로 돌아가게 하려면 수리 도구가 아주 많이 필요하고 밤샘도 많이 해야겠죠. 가끔은 뿌리로 돌아가 다시 머리 사냥꾼으로 일해 볼까 싶기도 하지만... 그래도 축제가 저에겐 잘해 줬어요.$B$B이 상품권을 받으세요, $N. 즐겁게 보내세요!'),
(7898, 'koKR', '아, 고맙습니다, $N! 예브가 이 장치들을 아주 좋아할 거예요. 어디에 쓸 계획인지는 모르겠지만, 예브는 영리한 꼬마 노움이거든요. 영리하고, 어쩌면 조금 음흉하기도 하죠....$B$B인간형 생물의 살맛만 좋아했다면... 훌륭한 트롤이 됐을 텐데!$B$B자, $N. 거래는 거래니까, 이 상품권은 당신 거예요.'),
(7899, 'koKR', '좋아, 가져왔군! 이걸로 장난감이랑 장신구를 만들 수 있어. 그러면 축제에 사람들이 더 많이 몰려오겠지!$B$B여기 상품권이야, $N. 받을 자격이 있어!'),
(7900, 'koKR', '멋진 가죽이군요, $N! 누구한테 부탁해서 이걸로 봉제 인형을 잔뜩 만들어야겠어요. 솜을 채우고 페인트를 칠하면 아제로스 전역의 아이들이 부러워할 거예요!$B$B상품권이요? 아, 맞다, 보수를 드려야지요!$B$B여기 있어요!'),
(7902, 'koKR', '아, 깃털! 정말 멋지지 않나요! 이런 아름다운 깃털이라면 상상력에 불을 지피는 건 어렵지 않겠어요!$B$B좋은 일을 하시는군요, $N. 공연을 보는 관객들의 웃는 얼굴만으로도 충분한 보상이지만, 이 상품권도 받아 주세요.'),
(8059, 'koKR', '잘했다... 필시 마력의 보물을 내놓기 전에 말도 못 할 고통을 겪었을 것이다. 이걸 받아라 — 악령술사의 손목띠다. 악령술사의 먹잇감을 불러내는 데 쓰이는 강력한 주술로 만들어진 것으로, 힘을 얻는 데 강력한 도구가 되어 줄 것이다.'),
(8076, 'koKR', '잘했다, $N. 줄구룹의 마력의 보물은 헛되이 쓰인 힘을 일깨워 줄 것이다. 구루바시는 전성기에 강력했지만 그 힘에 스스로 삼켜지고 말았다. 악령술사는 자신들이 벌이는 게임이 그와 크게 다르지 않다는 것을 안다. 하지만 풀려난 힘은 흔히 살아남기 위해 필요한 바로 그것이기도 하다.$B$B잔달라의 명예로운 동맹으로서 이 어깨보호대를 사용하라... 그대에게 도움이 될 것이다.'),
(8077, 'koKR', '인상적이군 — 줄구룹에서 거둔 그대의 승리 덕분에 우리는, 아니, 세상은 학카르가 이기지 못하리라는 걸 확신하게 되었소. 언젠가 피의 신과 직접 맞서야 할 때가 올지도 모르오... 그런 날이 온다면 그대에 대한 잔달라 부족의 존경은 변함없을 것이오.$B$B아, 그리고 이 간소한 예복도 도움이 될 것 같군.$B$B<알타빔이 알겠다는 듯 당신에게 윙크합니다.>'),
(8225, 'koKR', '*위잉*$B$B브로넬의 푸른줄무늬날치 식별 완료.$B$B보상 제공 가능합니다.$B$B*딸깍 딸깍* *지지지직*'),
(8319, 'koKR', '훌륭하오! 내 그대를 좋게 말해 두겠소.'),
(8321, 'koKR', '해냈군! 바이랄을 해치우다니! 이제 실리더스에서 황혼의망치단이 계획하고 있는 작전은 무산된 것이나 다름없소. 더 많은 이교도 놈들이 경계를 강화하려고 분주히 일하겠지만 오늘 당신에게 입은 타격을 쉽게 회복하지는 못할 것이오.'),
(8494, 'koKR', '이런, 이런, $N 아닌가. 해냈구나. 이제 널 눈여겨봐야겠는걸. 이런 말 하기 싫지만, 수고해 줘서 고맙다. 얼라이언스는 잊지 않을 거고, 나도 마찬가지다. 이제 나가서 모아야 할 다른 물건들을 구하러 뼈 빠지게 뛰어다녀라.'),
(8499, 'koKR', '노아른이 내 정찰 실력을 못 믿는다고? 왜 그럴까...'),
(8500, 'koKR', '훌륭하군요, $c! 일을 아주 잘해 주셨습니다. 이 주괴들은 팔레트에 실어서 우리 군대의 보급품을 만드느라 바쁜 대장장이와 기술자들에게 전달하도록 하겠습니다. 다시 한 번 감사드리며, 토륨 주괴를 더 구하시면 꼭 들러 주십시오.'),
(8503, 'koKR', '만세! 이걸로 스무 개 더 끝났네요. 당신이 최고예요. 시들기 전에 얼른 다 포장해 둬야겠어요. 갈래물풀은 많은데 시간은 너무 없네요!$B$B다시 한 번 고마워요, $c!'),
(8509, 'koKR', '잘했습니다, $c. 솔직히 놀랐군요. 도와주겠다며 찾아왔다가 다시는 돌아오지 않은 사람이 얼마나 많았는지 모릅니다. 이걸 상자에 담고 당신 이름으로 집계해 두겠습니다. 그런 다음 식물이 더 필요한지 다시 이야기하도록 하죠.'),
(8512, 'koKR', '아낌없는 기부, 정말 고마워요. 바로 이것들을 얇은 가죽 더미에 가져다 놓을 것이고 그러면 즉시 가죽들은 좋은 방어구와 가죽 조각이나 우리의 전쟁 준비에 쓰일 다른 것으로 바뀌게 될 겁니다. 얇은 가죽은 항상 부족한 것 같으니, 더 구하게 되면 돌아와서 다시 와 주세요.'),
(8513, 'koKR', '우와! 마치 자원 봉사하러 여기 오신 분 같습니다. 가죽을 기부해 주셔서 정말 감사합니다. 잘 포장한 다음 개수를 확인해야겠습니다. 당신은 동료를 기쁘게 하는 방법을 잘 알고 있는 분이시로군요.'),
(8514, 'koKR', '대단하시군요! 일반 가죽을 이렇게나 많이 구해 주시다니! 가져다주신 보급품 바로 옆에 적합한 용도로 쓰이도록 가져다 놓도록 하겠습니다. 도와주신 덕분에 필요한 양의 일반 가죽을 금방 확보할 수 있을 것 같군요!$B$B감사합니다!'),
(8515, 'koKR', '아, 해낼 수 있을 줄 알았어요, $c. 정말 알고 있었다고요! 최대한 빨리 적합한 이들의 손에 전달하겠습니다. 어디 보자... 흠, 집계가 꽤 잘 되어 가고 있군요. 세는 일이 끝나는 대로 곧 다시 와서 더 필요한지 확인해 보세요. 필요하다면 그걸 구해 올 사람은 바로 당신이었으면 하거든요!'),
(8516, 'koKR', '또 해냈군요! 이 가죽을 어디서 어떻게 구해서 여기로 가지고 올 수 있었는지 정말 놀라울 따름이에요. 당신이 얼마나 많은 도움을 줬는지 알게 된다면 거리에서 만나는 이들마다 사인해 달라고 아마 난리가 날 거예요!$B$B두꺼운 가죽을 아낌없이 기부해 줘서 다시 한 번 고마워요.'),
(8517, 'koKR', '오늘 당신이 보탠 도움은 수많은 병사에게 혜택이 될 것입니다, $c. 얼라이언스가 당신의 노고를 알 수 있도록 제가 직접 챙기겠습니다. 이 붕대들을 제대로 보관하고 수량을 갱신할 동안 잠시만 기다려 주세요. 그런 다음 제가 더 필요한지 다시 확인해 보세요.$B$B엘룬의 빛이 그대를 비추기를, $R!'),
(8518, 'koKR', '그대는 존경받아 마땅한 분입니다! 우리가 전시 상황이라는 것을 이용해 자기 호주머니나 채우려고 혈안이 된 작자들과는 다르게 그대는 얼라이언스, 아니 아제로스 전체에 희생 정신이 무엇인지 다시 한 번 보여 주셨습니다.$B$B엘룬의 가호가 늘 함께하기를!'),
(8521, 'koKR', '남을 배려하는 마음이 깊으신 분이군요. 군수 물자 확보에 도움을 주셔서 정말 감사합니다. 당신 같은 분들의 활약에 따라 안퀴라즈 전쟁의 승패가 결정될 겁니다. 이것으로 필요한 비단 붕대가 충분히 확보되었으면 좋겠군요.$B$B다시 한 번 감사 드립니다.'),
(8522, 'koKR', '이 임무를 끈기 있게 수행하신 것은 칭찬받아 마땅합니다, $c. 이 붕대들을 정리한 뒤, 룬매듭 붕대를 더 모아 주실 수 있을지 다시 이야기하고 싶군요.'),
(8523, 'koKR', '함께 걷는 길이 훌륭하군요, $N. 당신은 훌륭한 동료입니다. 얼라이언스 전체를 위한 당신의 노력에 다시 한 번 감사드립니다. 곧 다시 이야기합시다.'),
(8524, 'koKR', '둘은 얼라이언스에게, 하나는 나에게. 둘은 얼라이언스에게, 하나는 나에게. 이봐요, 생선 장수 양반, 훌륭한 솜씨네요. 당신은 우리 모임의 자랑이 되겠어요. 하지만 다랑어가 아마 더 필요할 것 같네요. 나가서 조금만 더 구해 오는 게 어때요? 벌써 뱃속에서 꼬르륵 소리가 들려요.'),
(8528, 'koKR', '이렇게 시기적절하게 선물을 가져다주셔서 감사합니다, $c. 우리 병사들이 먹을거리가 부족할 일은 없겠군요. 이 생선들을 제대로 보관해 둘 테니, 괜찮으시다면 두 번째 물량에 대해 이야기하시죠.'),
(8558, 'koKR', '좋아요, $C. 이 도끼는 걸작이군요... 완벽 하군요. $B$B무기를 가져가세요, $N. 자신 있게 휘둘러 적을 물리치세요!'),
(8575, 'koKR', '<나라인이 편지를 열심히 살펴봅니다.>$B$B대단하군요, $R! 이게 뭐죠? 난 용족 언어는 한 글자도 못 읽는데 말이에요.'),
(8585, 'koKR', '저 안심 살의 마블링 좀 봐요! 환상적이군요!$B$B그럼 이제 닭고기를... 흠, 어디 보자. 요리법을 짜려면 몇 분 걸리겠군요.'),
(8600, 'koKR', '음, 꽤 잘해 낸 것 같군요. 몇몇 가죽은 가장자리가 좀 거칠어 보이지만요. 어쨌든 임무는 완료되었고, 보상을 받을 자격이 있습니다. 또 튼튼한 가죽 뭉치를 구하게 되면 곧장 제게 가져다주세요.'),
(8601, 'koKR', '연습, 연습, 또 연습. 잘 갈린 칼과 그걸 쓰는 기술이 있으면 세상 어디서든 통하는 법이지, $N. 이번 가죽은 가장자리가 지난번보다 좋군. 새 칼이라도 샀나?$B$B어쨌든 노고에 감사하오. 기부는 기록해 두었고 틀림없이 요긴하게 쓰일 것이오. 튼튼한 가죽을 더 구하게 되면 다시 와서 말해 주시오. 아마 필요할 것이오.'),
(8615, 'koKR', '이곳의 전쟁 준비를 돕는 데 관심을 가져주어 고맙네, $C. 많은 이들이 사리사욕을 채우느라 우리의 필요를 그저 외면하곤 하지. 하지만 그들에게는 자네가 얻은 호드의 감사가 없다네. 이타적인 베에서 나오는 자부심으로 가득 찬 자네의 마음과 달리 그들의 마음은 텅 비어 있을 걸세.$B$B다시 한 번 고맙네. 준비가 완료되기 전에 우리를 더 도와줄 시간이 난다면 언제든 이곳에서 기다리고 있겠네.'),
(8729, 'koKR', '잘했소, $N. 이제 곧 흐르는 모래의 홀을 다시 만들 수 있을 것이오.'),
(8790, 'koKR', '그 물건을 잘 쓰도록 해라, $N. 놈들이 남에게 그토록 가하고 싶어 하는 고통을 직접 느끼게 해 줘라.'),
(8791, 'koKR', '그대에게 내가 할 수 있는 최고의 찬사와 강력한 힘을 가진 물건을 선택할 수 있는 기회를 주겠소. 그대는 칼림도어의 백성들을 위해 엄청난 일을 해낸 것이오.'),
(8921, 'koKR', '$N, 필요한 재료들을 정확히 가져왔군. 시간도 아주 잘 맞췄어!$B$B조금 있으면 추출기가 준비될 것이네! 우선 이걸 받게나. 날 도와준 데 대한 보상일세.'),
(8957, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(8961, 'koKR', '대단하군, $c. 하지만 지체할 시간이 없다. 다음 임무를 맡기겠다. 진행하려면 아직 몇 가지 중요한 구성 요소를 더 손에 넣어야 하니까.$B$B앞으로 닥칠 도전에 임할 준비가 되었다고 생각하면 다시 내게 말을 걸어라.'),
(9016, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(9017, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(9018, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(9019, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(9020, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(9021, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(9022, 'koKR', '이 저주는 고작 메달 하나 때문에 우리에게 내려졌소. 군주 발타라크는 확실히 원한을 품을 줄 아는 자요.$B$B남은 조각들도 찾도록 노력해 보겠소 — 내가 비명횡사하기 전에 찾을 수 있길 바라야지. 하지만 그 전에, 그대의 보상부터 챙겨 드리겠소.'),
(9194, 'koKR', '그러지 말았어야죠! 아니, 진짜로 그러지 말았어야지. 메츠가 무슨 생각인지는 모르겠지만 아무도 이 옷을 입고 낙스라마스로 갈 수는 없을 거에요. $B$B<스톤브루저 한숨을 쉰다>$B$B아, 또 다른 쓰레기 더미를 전선으로 옮겨야 하고 체임버스에게 또 다른 꾸지람을 들어야겠지.'),
(9203, 'koKR', '아무말 안할거에요.$B$B<스톤브루저가 당신을 노려본다.>$B$B노코멘트라고 했죠! 이제 내 앞에서 사라져 주세요!'),
(9205, 'koKR', '정말 이게 뭔지 모르시겠어요? $B$B<팩마스터 스톤브루저가 웃는다. >$B$B말해줄게요! '),
(9232, 'koKR', '<빌헬름이 이마의 땀을 닦아냅니다.>$B$B정말 고된 작업이었소! 바지를 가져가시오, $C. 최소한 이제는 깨끗한 바지를 입고 깔끔하게 죽을 수 있을 거요.'),
(9344, 'koKR', '<그레이그가 얼굴을 찡그리며 일어서는데......>$B나는 선견자 레굴쿠트의 조언에 따라 경호원을 기다렸어야 했어요. 그를 찾아 사람을 보내길 정말 다행이군요. 저 혼자서는 스랄마로 돌아갈 수 없었을 겁니다야. 이 다리를 위해 최선을 다하고 있지만 보급품이 없다면 전망이 어둡습니다.'),
(9373, 'koKR', '이 물건을 가져다줘서 고맙습니다,$C. 저는 오랫동안 원정대의 소식을 듣지못해 궁금한 참이였거든요. 저는 이 물건이 얼마나 멀리서 왔는지 또 누구에게서 온건지 궁금하군요.$B$B당신의 노력에 작은 금액이라도 드리고 싶군요.'),
(9434, 'koKR', '아주 좋습니다, 이제 모든 것이 다 준비 되었군요. 이제 제가 해야 할 일은 모든 것을 한데 섞어 한 번 시도해 보는 것입니다. 만약 이 강장제가 제 연구가 보여준 대로만 된다면, 제가 사람들의 마법 중독의 영향을 줄일 수 있는 방법을 찾은 것일지도 모르겠군요. $B$B당신은 곧 역사를 목격하게 될 것입니다. 당신의 도움이 없었다면, 이런 일은 불가능했을 거라구요.'),
(9439, 'koKR', '당신은 기적의 은인입니다, $N! 내 평생 이렇게 옷을 갈아입고 싶었던 적은 없었어요. $B$B그리고 내 레이피어! 장비가 없으니 벌거벗은 기분이 들었지 뭡니까. $B$B당신께는 고마움과 보상을 드려야 합니다. 사로파스가 자신을 도와준 작은 사람들을 인정하지 않았다는 말은 절대 하지 마세요!'),
(9446, 'koKR', '우서경의 영혼이 당신 앞에 나타났다고요?  정말 대단해요!  그리고 이 모든 것이 우서경에 대한 당신의 헌신적인 도움으로 가능했습니다. $B$B 신화의 절반만 믿어도 우서경은 대단한 사람이었어요.  그리고 그와 마찬가지로 당신도 아제로스의 모든 선량한 사람들에게 진정한 영웅입니다, $N!'),
(9488, 'koKR', '마법의 로브를 만드는 세부 사항은 신경 쓸 필요 없습니다, $B, 당신은 나에게 무엇을 가져와야 하는지만 알면 돼요.$B$B 솔직히 말해서, 당신은 로브 몇 벌을 만들 수 있을 만큼 가져오긴 했어요. 하지만 저도 좀 수입이 있어야지 당신에게 만들어 주지 않겠습니까. 덕분에 고맙군요!'),
(9524, 'koKR', '고맙습니다, $N. 구조대가 올 줄은 몰랐습니다. $B$B제가 나머지 포로들도 구해서 명예의 요새로 데려갈 겁니다.'),
(9711, 'koKR', '삼두연합행정부에서는 즉시 마티스를 재판에 넘기기로 결정했네. 자네는 오늘 악질 범죄자에게 정의의 심판을 내렸네.$B$B젊은 드레나이여, 이제 세 명 중 두 명의 임무를 훌륭하게 해 냈으니 이제 아에솜에게 가 보게.'),
(9774, 'koKR', '$N, 고맙소. 지금은 동전 한 닢도 도움이 되는 시기요.$B$B아직 갈 길이 멀지만 한 번 부딪쳐 봐야지. 내가 순찰대 틈에서 달리 할 일이 무엇이 있겠소?'),
(9883, 'koKR', '$N, 수정 조각을 계속 가져와. 그 도둑들이 우리 재산을 마음대로 가져가게 놔둬선 안 돼.$B$B비록 아직은 우리 것이 아니라도. 물론 절차상의 문제일 뿐.'),
(10101, 'koKR', '<부드러운 선율의 목소리가 마음을 가득 채웁니다.>$B$B나는 대모 카슈르다. 넌 내 고대 함선의 심장부에 서 있구나. $B$B오슈군은 오크들이 명명한 대로 드레나이들을 이 세상에 처음 데려온 함선이다. 수백 년 전 하늘에서 떨어져 이곳에 추락했지만, 나의 약해진 에너지는 이 잔해 속에 갇혀 있다. 유감스럽게도 내가 오크 영혼들의 고통의 근원이다.'),
(10172, 'koKR', '<게야 할머니의 얼굴에 눈물이 흐른다>$B$B족장에게 전하게. 내가 여기서 기다린다고....'),
(10205, 'koKR', '드디어 그 쓰레기를 처리했다니 안심이 되는군요. 잘하셨습니다, $N... 이름을 부르면 실례인가요?$B$B원하신다면 맡아주실 임무가 더 있습니다. 매우 중요한 일인데 당신처럼 능력이 뛰어난 분이라면 간단하게 처리할 수 있을 겁니다.'),
(10267, 'koKR', '이 보잘것없는 거래가 끝나서 매우 기쁘군. 그 예의 없고 신뢰할 수 없는 놈들과 우리 무역연합이 언제 거래를 했었나 싶소.$B$B하지만, 당신은 아주 신뢰가 가는군! $N, 내 부탁 하나만 더 들어줄 수 있겠소?'),
(10528, 'koKR', '수정 열쇠를 악마의 수정 아랫부분에 있는 빈 홈에 밀어넣습니다.'),
(10623, 'koKR', '<무기 조각을 건네받는 그로콤>$B$B지난 수년간 이걸 본 적이 없었는데... $N, 이것은 희귀한 광물로 만들어진 것이며 평범한 무기에 사용하는 것이 아닐세.$B$B그리고 이 룬들은 검에 악마를 제압할 힘을 칼날에 불어넣어 준다네. 불타는 군단이 병사들에게 악마 사냥용 무기를 무장시킬 작정인 게야. 일리단에 대한 놈들의 증오심이 정말 큰 것 같군. 이걸 우리가 이용할 수도 있을 걸세.'),
(10653, 'koKR', '불타는 군단의 악마들과 그들을 추종하는 미치광이 광신도를 상대하는 것은 결코 만만한 일이 아닙니다. $N, 당신은 대단한 희생정신과 용기를 보여주셨습니다. 계속 노력해 주신다면 알도르 사제회에서 당신의 명성이 드높아질 겁니다.'),
(11877, 'koKR', '<계획서를 받아들고 살펴보는 토르보스 경>$B$B공격대에 큰 보탬이 되었소, 페라돌이$C. 하지만 마음을 놓아서는 안 되오. 적이 다시는 못된 계획을 세우지 못하도록 몰아세워야 하니까.'),
(11911, 'koKR', '대단합니다!\r\n\r\n당신 말을 들으니 녀석들은 난폭하기까지 한 모양이군요. 어쩌면 이 조작을 배후에서 조종하는 두뇌가 있는지도 모르겠습니다. 자연스러운 현상이 아닐지도 몰라요...\r\n\r\n자, $N 님, 당신의 수고에 대한 보답으로 이걸 받아주셨으면 합니다. 당신의 활약은 달라란에도 전해질 겁니다.'),
(12697, 'koKR', '착취자의 세계에 들어오려 애썼다고... 기다려라.$B$B<자신이 적어놓은 것을 읽어 보는 고딕>$B$B기다리게 해서 미안하다, $R. 습관일 뿐이니 괘념치 마라.$B$B발라나르가 그대를 보냈단 말인가? 어느 정도는 실력이 있다고 믿겠다.$B$B내게 붉은십자군의 개들에게 줄 선물이 있다. 이 선물을 받으면 놈들이 광산에서 일하는 속도가 확실히 빨라질 테지.'),
(14107, 'koKR', '전사한 형제들을 위해 아주 값진 일을 해주었소. 당신은 우리에게 전장에서 그들과 맞설 용기를 북돋아주었소. 스컬지와의 전쟁이 계속됨에 따라 나는 내 운명에 대해서도 생각하지 않을 수 없다오.$B$B내가 죽거든 $N, 당신 같은 이가 오늘 전사한 영웅들에게 한 것처럼 내 영혼에 안식을 찾아주었으면 좋겠소. 형제들이 나를 죽이고 또 죽여야만 하는 상황은...정말 생각만으로도 끔찍하오.');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) VALUES
(8, 'koKR', '어서 오세요, 손님. 무슨 일이신지요?$B$B수중에서 숨을 쉬지 않아도 되는 종족치고는 식욕이 엄청나시군요. 내 집처럼 편하게... 푹 쉬세요. 제 이름은 리니입니다. 필요한 게 있으면 언제든지 불러주세요.'),
(10, 'koKR', '그래, 무슨 소식을 갖고 왔소? 보아하니 꽤 힘이 들었나 본데... 슈생크는 살아 있소?'),
(20, 'koKR', '오크들을 처치하고 왔는가, $N? 그렇다면 증거를 보여 주게.'),
(21, 'koKR', '힘든 임무인 줄은 알고 있지만 노스샤이어의 안전을 위해서는 불가피한 일일세. 그래, 보고할 준비는 됐나?'),
(24, 'koKR', '$N, 다시 만나서 반갑습니다! 공훈의 증거를 보여 주려고 왔습니까?'),
(32, 'koKR', '미안하지만, 난 당신을 모르는 것 같은데... 하지만 당신은 나에 대해 뭔가 들어 본 것 같구먼. 그래, 내가 도와줄 일이라도 있소? 내게 뭘 가져온 거요?'),
(36, 'koKR', '하나둘씩 여길 떠나더니 이제 베르나가 떠난다고 하더군요. 아, 베르나가 무척 보고싶어질 거예요. 혹시 이곳으로 오는 길에 그녀를 만난 건 아니겠죠?'),
(50, 'koKR', '다시 불러 달라고? 물론이지, 친구!$B$B녹이고 녹여, 섞고 또 섞어$B아무도 모를 우리만의 비법$B튼튼한 금속으로 증류기를 만드세$B진은을 구해 주오. 이 노래를 마칠 수 있도록'),
(53, 'koKR', '물론, 기꺼이 다시 불러 주지, 친구!$B$B감미로운 액체는 아기 눈물처럼 맑고$B여러 해가 지나면 길고 아름다운 황색이 되네$B하지만 이 숲에 흠뻑 취하기 전에$B참나무 숲으로 맥주통을 만들어야지'),
(54, 'koKR', '맥브라이드로부터 소식을 가져왔소? 엘윈 숲에 비하면 노스샤이어는 천국이라고 할 수 있지. 음, 치안대장 맥브라이드가 보고할 일이란 게 무언지 궁금하군.$B$B자, 그의 보고서를 보여 주시오...'),
(56, 'koKR', '돌아왔군. 어둠의 순찰대의 임무에 도움이 된다는 것을 증명하려면, 해골 전사 8마리와 해골 마법사 6마리를 처치한 후 다시 내게 돌아오시오.'),
(61, 'koKR', '오, 동생의 물건을 가지고 오셨다구요? 멋지군요! 오늘은 운이 좋은 날입니다. 하하!'),
(68, 'koKR', '아, 당신이군요. 스탈반에 대해 물었던 분이죠? 원하던 정보는 찾으셨나요?'),
(71, 'koKR', '어서 오십시오, $N. 롤프와 말라카이가 어떻게 됐는지 알아냈습니까?'),
(74, 'koKR', '거기, 자네 뭘 가지고 있는 건가? 난 안 보이는군. 눈이 너무 나빠서 말일세. 그걸 내게 좀 줘 보게.'),
(77, 'koKR', '아마 당신이 우리 야영지에 온 건 임무에 중요한 리플을 전달하기 위해서겠지, 안 그렇소?'),
(78, 'koKR', '치안대장 해거드씨가 보냈다고 했습니까? 진작 그렇게 말했어야지요.$B$B아, 그분은 참 좋은 분이죠. 그런데 이제 곧 완전히 눈이 멀 거라니 불쌍하기도 하지... 어쨌든, 뭔지 한번 봅시다.'),
(79, 'koKR', '물론 좋은 소식이겠지, $C? 자, 뭘 찾아냈는지 한번 보도록 하지. 그리고 빛의 이름으로, 직접 설명해 주기 바라오. 물론, 설명은 짧게 끝대로고 하시오. 내 주된 임무는 다크샤이어를 지키는 것이니 시간 낭비할 겨를이 없소.'),
(84, 'koKR', '아... 배고파 죽겠어요! 혹시 제게 줄 파이는 가져오셨나요, $N?'),
(86, 'koKR', '내 목걸이를 훔쳐 간 녀석에게 먹을 것까지 해 줘야 하다니 정말 말도 안되는 일이지만, 그래도 목걸이를 되찾기 위해서라면 어쩔 수 없군요!$B$B멧돼지 고기는 가져왔나요?'),
(87, 'koKR', '어서오세요, $N. 내 목걸이를 찾았나요?'),
(92, 'koKR', '아직도 질긴 독수리 고기 5개, 큰 뿔엄니멧돼지 주둥이 5개, 파삭파삭한 거미 고기 5개가 필요해요.'),
(97, 'koKR', '그래, 무슨 일인가?'),
(98, 'koKR', '그래, 무슨 일인가?'),
(101, 'koKR', '내게 구울 송곳니 10개와 해골 손가락 10개, 거미 독액이 든 약병 5개를 가져아야 해. 내 마법의 힘으로 그대를 해하려는 자들을 막아 줄 시련의 토템을 만들어 주겠네.'),
(105, 'koKR', '난 이미 자네에게 임무를 준 것으로 기억하네만, 임무를 완료한 증거로 리치의 성물함 조각을 가져왔나?'),
(106, 'koKR', '뭘 가지고 왔다고요?? 오, 메이벨 내 사랑! 내 무미 건조한 인생에 메이벨은 빛과 같은 존재랍니다. 어서, 그녀의 편지를 이리 주세요!'),
(107, 'koKR', '스톤필드 할머님의 쪽지를 가지고 왔다고 했나요? 밀드레드 할머님을 못 뵌지도 몇 년이 지났군요! 흠, 내게 무슨 할 말이 있으신 건지...'),
(113, 'koKR', '아, 후임측량사 $N이로군. 페슬저그, 그 친구가 보고서를 준비했습디까?'),
(116, 'koKR', '서부 몰락지대 언덕의 그림부즈 썬더브루에게서 썬더브루 맥주통과 스톰윈드에서 멀롯 술통, 다크샤이어에서 문샤인 병, 골드샤이어에서 향기로운 럼주 주머니를 가져다 주세요. 제 부탁을 들어주시면 꼭 보답하겠습니다.'),
(117, 'koKR', '서두르게 친구여, 어서 서둘러$b맛 좋은 맥주를$b스튜같지 않고 진한 맥주로 만들려면$b홉 열매를 넣어서 맥주를 만드세'),
(124, 'koKR', '내 말들이 아직도 저 저주받은 늑대 울음소리에 놀라고 있습니다. 제발, 저 놀들을 어떻게 좀 해주세요!'),
(129, 'koKR', '달시가 점심을 보낸 거로군요? 정말 마음씨 고운 아가씨군. 자, 어서 이리 주십시오!'),
(132, 'koKR', '어서 오게. 그래, 와일리가 뭐라고 했지?'),
(144, 'koKR', '그래, 백성의 민병대의 도움을 곧 받을 수 있을 것 같소? 스타우트맨틀 경에게서 좋은 소식을 얻어 왔소?'),
(145, 'koKR', '먼길을 여행한 듯 보이오만, 이곳 다크샤이어에는 무슨 일인가?'),
(146, 'koKR', '오, 다시 봐서 반갑군. 다크샤이어로부터 어둠의 순찰대가 오고 있다는 기쁜 소식을 치안대장에게 알려도 되겠소?'),
(154, 'koKR', '그대에게서 눈 먼 매리의 기운이 느껴지는 군. 그래, 빗은 도로 가져왔고...?'),
(156, 'koKR', '어서 오세요. 자, 시든 꽃들은 다 구하셨나요?'),
(161, 'koKR', '뭐라고? 윙윙거리는 소리말고는 하나도 안 들려서 말이야. 크게 말해 보라고, 그런데 그건 대체 뭐지?'),
(164, 'koKR', '오, 아주 강한 $C인것 같군요. 우리와 함께 싸우러 왔습니까?'),
(171, 'koKR', '다시 뵙게 돼서 반갑군요, $N씨. 어린이 주간 동안 해 주기로 하신 일은 다 하셨나요?'),
(177, 'koKR', '코그에게 우리의 별 관측 기계의 제작 과정을 보여 주었소. 시작 단계일 뿐이지만 꽤 인상적이었던 모양이오. 그건 그렇고, 반사면은 찾았소?'),
(184, 'koKR', '땅문서를 가져 오셨다고요? 정말 반가운 소식이군요! 며칠 전 불한당 같은 놈들한테 땅문서를 빼앗겼었지요. 영영 못 찾을 줄 알았답니다!$B$B그 문서를 제게 주시겠습니까? 우리 가족은 서부 몰락지대를 떠나 가까운 시일 내에는 돌아오지 않을 생각입니다만, 혹시라도 돌아온다면 이 땅문서가 필요할 것입니다.'),
(189, 'koKR', '임무는 완수했습니까? 그 지독한 트롤 놈들이 여기저기에서 출몰하고 있다고요.$B$B으, 생각하니 또 화가 치미는군! 어서 동료들에게 도움을 청하도록 하십시오. 도움이 많이 필요합니다.'),
(208, 'koKR', '다시 돌아온 건가, 친구? 야수왕 뱅갈라시 때문에 나도 몇 번이나 야영지로 돌아왔었지. 자네는 한번 끝까지 해보도록 하게.'),
(209, 'koKR', '상대하기에 너무 사나운 놈들이었나요? 흠, 구해 오기는 한 겁니까? 재촉하는 것 같아서 미안하긴 하지만, 우린 시간이 별로 없습니다. 아시겠어요?'),
(232, 'koKR', '안녕하시오. 무슨 일로 오셨소? 왕립 연금술 학회 일로 오셨소, 아니면 그저 날 기쁘게 해 주러 온 것이오?'),
(238, 'koKR', '네, 맞아요. 나도 당신처럼 루카를 별로 탐탁히 여기지 않는답니다. 뭐, 중요한 문제는 아니고 휴대용 분석 도구를 이리 주세요. 적합한 기본 재료에 대한 조사를 하려면 약간의 개조가 필요하답니다.'),
(252, 'koKR', '그래, 편지는 번역됐나? 어디 한번 보세...'),
(255, 'koKR', '어떤가, 성과가 좀 있었소?'),
(256, 'koKR', '그래, 내가 도와줄 일이 있나?'),
(258, 'koKR', '세상엔 당신보다 뛰어난 사람이 많소. 그러나 너무 풀이 죽어 있을 필요는 없지... 너무 소심할 필요는 없지.$B$B흠, 당신 이름이 $N 맞던가?'),
(264, 'koKR', '묘비는 만지기에는 차갑지만 분명히 누군가 함부로 사용해 온 것 같습니다. 주변에는 쓰레기가 어지럽게 널려 있고 관 위에 양각된 조각은 흠집이 나고 갈라져 있습니다. 그리고 무덤 주위의 나뭇잎이 우거져 무덤 위를 덮기 시작했습니다.$B$B이곳에 누가 묻혀 있는지 신경쓰는 이는 아무도 없습니다. 특히, 역병의 희생자들은...'),
(265, 'koKR', '안녕하십니까. 저는 학자와 마법사, 혹은 일기를 쓰려는 사람들에게 백지로 된 책을 종종 팔고 있답니다.$B$B최근 몇 달간 책을 사 간 사람들은 충분히 기억할 수 있습니다만...'),
(266, 'koKR', '진홍 까마귀 선술집은 예전만큼 장사가 잘 되지는 않지만, 그래도 여전히 지나가는 여행자들이 투숙을 하곤 하지요.$B$B찾고 있는 분의 인상착의를 설명해 보시면 기억해 낼 수도 있을 겁니다.'),
(269, 'koKR', '편히 쉬시오, $G형제:자매;여. 먼 길을 여행하고 무거운 책임을 지고 있는게 보이는구려. 저 어두운 그림자가 무슨 염려를 끼치고 있는지 말해 주시겠소?'),
(271, 'koKR', '아, 당신이군! 또 왔습니까? 사냥을 나갔다 왔나 보군요. 뭐, 지금 실력이 모자란다고 너무 낙담하지는 말라니까요. 계속 노력하다 보면 점점 나아질 겁니다.$B$B어쨌든 지금보다 실력이 나쁠 수는 없지 않나요?'),
(288, 'koKR', '아, 목이 너무 마른 걸. 이 가슴 아픈 이야기의 주인공에게 술을 한 잔 사지 않겠나?'),
(291, 'koKR', '이런, 이런... 경비병들이 탄원서를 올리로 오는 이들에게 관대해지는가 보군. 아무 제제 없이 여기까지 들어오게 하다니... 흠, 그나저나 무슨 일로 왔나? 빨리 말하게. 난 바쁜 몸일세.'),
(292, 'koKR', '그 주정뱅이 피츠시몬즈가 자넬 보냈다고? 흠, 그자에게 내겐 더 이상 맥주가 없다고 전해 주게. 맥주는 이제 다른 사람에게 얻어먹으라고 말이야.'),
(298, 'koKR', '오, 현장의 상황 보고서로구먼. 고맙소.'),
(299, 'koKR', '네 개의 석판 조각은 찾았나? 아도스, 모드르, 골름, 그리고 네루 말일세.'),
(301, 'koKR', '난 사소한 일까지 신경 쓸 만큼 한가하지 않네, $C. 내 귀중한 시간을 빼앗을 만큼 중요한 소식을 가져 온 겐가?'),
(304, 'koKR', '불한당 발가라스를 찾았나, $C 친구? 녀석은 꽤 오랫동안 우릴 잘도 피해 다니고 있다네.'),
(313, 'koKR', '이봐, 은빛 동굴에는 갔다 왔나? 웬디고들은 꽤 사나워서 갈기 얻기가 쉽진 않을 거야.'),
(315, 'koKR', '내가 말한 쉼머우드는 가지고 왔나? 지금 스타우트 맥주 한 통을 만들 준비가 거의 다 됐는데, 거기다가 쉼머위드를 한번 넣어 보고 싶거든.'),
(322, 'koKR', '내 솜씨로 도울 일이 있소, $C 친구?'),
(339, 'koKR', '1, 4, 6, 8 쪽을 찾지 못한 것 같군요? 이 네 쪽이 있어야 1장을 다시 완성할 텐데...'),
(340, 'koKR', '10, 11, 14, 16 쪽이 있어야만 2장을 완성할 수 있습니다.'),
(341, 'koKR', '18, 20, 21, 24 쪽은 찾으셨나요? 이쪽들만 찾으면 3장의 원고는 모두 되찾게 되는 겁니다.'),
(342, 'koKR', '세 쪽만 있으면 4장을 완성할 수 있습니다. 25, 26, 27 쪽을 찾으셨나요?'),
(378, 'koKR', '바보 같은 인간들의 관료주의를 드워프 문제에까지 끼어들게 할 수는 없지. 캄 딥퓨리가 탄돌 교각 공격을 계획한 것이 만천하에 밝혀졌고, 딥퓨리의 책략으로 마그니 폐하의 선량한 국민들이 목숨을 잃었소. 인간들은 딥퓨리가 지하감옥에서 썩는 걸로 만족할지 모르지만, 나는 딥퓨리를 처치하기 전까진 두 발 뻗고 편히 잘 수 없을 것 같소.'),
(379, 'koKR', '그래, 그 유목민 녀석들이 \"자발적으로\" 물주머니를 내놓던가?'),
(383, 'koKR', '그래, 무슨 일인가?'),
(393, 'koKR', '반갑네. 내가 도와줄 일이 있나, $C 친구?'),
(396, 'koKR', '오, 그대로군? 바로스 알렉스턴에게서 그대가 올 것이라는 얘기를 들었노라. 짐은 그대의 말에 매우 관심있으니 경청하도록 하겠으니 어서 얘기하도록 하라.'),
(407, 'koKR', '이 사악하고 불결한 괴물, 저리 물러서라! 신이시여, 저를 지켜주소서! 붉은십자군이 아제로스에서 네놈들을 완전히 몰아낼 날이...$B$B...잠깐, 혹시 내게 줄 음식인가? 배가 너무 고파...'),
(413, 'koKR', '이봐, $C 양반! 여긴 무슨 일로 왔소? 뭔가 흥미진진한 좋은 소식이라도 가져 온 거요?$B$B한동안 변변한 싸움도 없었고 맥주도 거의 바닥이 나서 지루하던 참이었거든.'),
(414, 'koKR', '반갑소, $C 친구. 텔사마에 온 것을 환영하오!'),
(418, 'koKR', '요리를 시작할 준비가 다 됐는데, 재료는 가져왔나요?'),
(420, 'koKR', '새로운 친구, 반갑네. 한잔 할 텐가? 추위엔 맥주가 제격이지.'),
(429, 'koKR', '난 시간이 별로 없네, $C. 어둠의 여왕께서 중요한 임무를 내리셨네.'),
(439, 'koKR', '오, 돌아왔군 그래. 조사 결과 뭔가 소득이 있었나?'),
(445, 'koKR', '내게 무슨 볼일이 있나, $C 친구?'),
(447, 'koKR', '어서 오게. 그래, 왕립 연금술 학회에는 무슨 일이신가?'),
(451, 'koKR', '그래, 이번에는 무얼 가져왔나?'),
(459, 'koKR', '내 짐작이 맞는지 증명해 주세요, $N. 악마의 이끼 8개를 가져오세요.'),
(485, 'koKR', '로봇의 잔해를 찾은 것 같은데 닭... 모양을 하고 있습니다. 알 속에서 다시 목소리가 들려옵니다.$B$B\"잘했소! 그것이 바로 내 유도 로봇이오. 다시 무법항으로 보내 수리를 하려면 급속 시동을 걸어야 할 것 같소. 이 탐지기를 로봇에 넣으시오. 나머지는 탐지기가 알아서 할 테니까!\"'),
(488, 'koKR', '그래, 부지런히 재료는 구했나? 필요한 재료를 구해 오기를 기다리고 있었네.'),
(501, 'koKR', '다, 당신이로군. 내 마지막 비약 만드는 걸 도와주기로 하지 않았소? 힐스브래드에 거주하는 놈들에게 내가 특별히 제조한 고통을 선사하려면 그 피가 꼭 필요하오.'),
(503, 'koKR', '날 구하러 온 겐가? 그럼 열쇠를 가져다주시게, $C 친구. 그럼 내가 직접 자물쇠를 열도록 하지.'),
(513, 'koKR', '내가 지금 바쁘게 일하는 게 안 보이나, $C? 어둠의 여왕님께서 스컬지가 노스랜드로부터 우릴 공격해 오기 전에 새로운 역병을 개발하라고 재촉하고 계시네. 게다가 남쪽에선 인간들이 압박해 오고 있으니 지금 내겐 시간이 금쪽같아. 그러니 중요한 일이 아니라면 돌아가게!'),
(515, 'koKR', '잘 다녀왔소, $N?. 당신이 없는 동안 무료해서 죽을 지경이었소. 움피에게 독과 병균을 주입했다가 다시 소생시키는 것 외에는 소일거리가 전혀 없으니... 계속 그것만 반복하고 있었소.$B$B언더시티로 간 일은 어떻게 됐소? 가는 길에 운 좋게도 우연히 인간을 처치할 기회는 없었소?'),
(517, 'koKR', '나는 이곳 타렌 밀농장에서의 생활이 너무 따분하게 느껴질 때면 포름알데히드 병을 열어 그 기분 좋은 향기를 공기 중에 퍼뜨리곤 한다오. 그럴 때면 움피는 잔뜩 겁을 먹지.$B$B그건 그렇고, 드워프들에게서 맥주통은 훔쳐 왔소? 이 치명적인 비약을 아무에게도 사용해 보지 못하고, 하루라도 더 기다려야 한다면 난 비명을 지르게 될 게야.'),
(520, 'koKR', '머리 세 개는 손에 넣었고, 이제 네 번째 머리가 필요합니다. 무그톨의 머리를 가져오지 않으면 네 번째 머리의 주인공은 당신이 될 거라 내 약속하죠!'),
(522, 'koKR', '숨을 헐떡이는 걸 보니 꽤 급한 일인가 보군. 그래, 뭔가 보고할 거라도 있나?'),
(527, 'koKR', '자네는 바리스마트라스님과 어둠의 여왕님의 직속 부관이며 타렌 밀농장의 고위 집행관인 나의 명령을 따라야 하네.$B$B자네 혹시 얼라이언스와의 전쟁을 장난으로 여기는 건 아니겠지? 만에 하나 그게 사실이라면 지금 당장 자넬 처형할 수밖에 없어! 자, 명령대로 서쪽 힐스브래드 마을로 가서 인간을 상대하도록, 이상!'),
(529, 'koKR', '명령을 완수했나, $C? 베링턴과 그의 조무래기들은 처치한 겐가? 그리고 철괴 상자는 어디 있나?'),
(536, 'koKR', '여기 에일 한 잔 더 주게. 마지막 잔이 여기 있었는데 어디로 사라졌지? 아, 대체 이런 촌구석에 얼마나 더 틀어박혀 있어야 하는 거야?$B$B오, 당신이었군. 멀록은 아직 처치하지 못했소?'),
(541, 'koKR', '던 가록 공격이 자네에겐 무리인가, $C? 힐스브래드에서 보여준 용맹한 모습은 인상 깊었지만...$B$B이번 임무가 자네 힘에 부친다면 다른 적합한 이를 찾아보도록 하지. 어둠의 여왕님께 티리스팔 숲에서 무덤 파는 일꾼이 더 필요할지 모르니까 거기에나 지원해 보는 것은 어떨까. 그게 싫다면 다시 던 가록 공격을 다시 시도하던가...'),
(546, 'koKR', '행운아 $N께서 돌아오셨군요? 자, 오늘은 얼마나 많은 인간을 처치했습니까? 수백 명은 되겠죠? 내게 줄 해골은 가지고 왔나요?'),
(551, 'koKR', '오, 내게 뭐 보여 줄 거라도 있소? 산 위에서 새로운 무엇이라도 찾아 온 거라면 좋겠소만...'),
(554, 'koKR', '또 누가 날 방해하는 것이오?$B$B아, 양피지는 매우 난해하면서도 정교하게 짜 맞춰진 주문들로 가득하군. 물론 해독할 수는 있지만, 시간이 좀 걸릴 거요. 내게 시간은 금쪽보다도 귀하오이다...$B$B아마도 당신에게 시간을 벌어야겠군?'),
(555, 'koKR', '재료는 다 구해 오신 건가요? 이 곳은 더 이상 예전처럼 평화로운 곳이 아니니 조심해야 할 겁니다. 아, 이렇게 상황이 불안하지만 않았어도...'),
(559, 'koKR', '$N, 멀록의 머리를 가져왔습니까?'),
(565, 'koKR', '오, 이 위대한 바르톨로를 다시 찾아온 걸 보니, 설인 모피 망토를 만들 재료를 다 구해 왔나 보구려? 아니면 나, 바르톨로의 위대함에 매료된 것이겠군!'),
(566, 'koKR', '아, 바르두스 남작의 머리에 걸린 보상금을 받으려고 온 건가?'),
(571, 'koKR', '그래, 잘 돼가고 있소? 덩치큰 고릴라의 힘줄을 구해온 것이오?'),
(572, 'koKR', '그래, 깃털은 모아 왔나?'),
(576, 'koKR', '이보시오, 친구! 내 비록 볼 수는 없지만 당신이 항구 건너 중간쯤에 갔다는 건 냄새로 알 수 있소.$B$B내 눈은 되찾아 주지 않을 거요? 내 눈이 저 비열한 붉은해적단 놈들 손에 있다는 걸 알면 선장이 나를 수장시켜 버릴 거란 말이오.$B$B장님인 망보는 자가 무슨 소용이겠소? 저 까마귀 둥지가 바로 내 자리였었소. 더 이상 선실 하나 없는 신세가 될 텐데. 배 밑바닥에서라도 지낼 수 있다면 다행이겠군.'),
(577, 'koKR', '최고의 품질, 100% 고급 악어 가죽으로 만든 드리즐릭의 익셀시어 가죽 장화! 이보다 더 좋을 순 없다!$B$B이보다 더 멋진 광고 문구는 없을 거예요.$B$B가죽은 구해 오셨나요?'),
(581, 'koKR', '이보시오, $C 친구. 붉은머리부족들은 처치했소? 그렇다면 전리품을 보여 주시오.'),
(587, 'koKR', '물건은 찾았나, 친구?'),
(591, 'koKR', '어서 오시오. 정글의 영혼들이 당신의 용기를 찬양하는 노래를 부르고 있소. 하지만 마이조스를 상대하는 임무에 대해서는 해줄 얘기가 없다는군.$B$B그래, 마음의 눈은 가져왔소?'),
(592, 'koKR', '킨윌레이가 말하길, 당신이 예니쿠의 영혼을 붙잡으러 갔다고 하던데...$B$B사실이오? 그렇다면 그의 영혼을 가져왔소?'),
(604, 'koKR', '이봐, 그래. 남쪽의 붉은해적단 야영지에 대해 뭔가 소식을 가져왔나?'),
(606, 'koKR', '이보세요! 왜 그렇게 쳐다보는 거에요, $G선생:부인;.'),
(614, 'koKR', '이보게! 그래, 고를라쉬는 찾았나? 그 상자는 내가 가장 좋아하는 거였다네. 게다가 그 안에는 내가 가장 아끼는 보물들이 들어 있는 숨겨진 칸이 있지!'),
(619, 'koKR', '버려진 구명정입니다. 보트 옆에는 긁히고 빛 바랜 페인트로 다음과 같이 쓰여 있습니다.$B$B\"스모츠의 복수\"'),
(622, 'koKR', '어서 오십시오, $N. 무법항에는 다녀온 겁니까? 크라젝이 내 냄비를 고쳐 주었나요?'),
(627, 'koKR', '안녕하세요, $N. 내게 저급 혈석 광물을 가져왔나요?'),
(628, 'koKR', '바다악어가 점차 멸종돼 가고 있다는 기사를 읽은 적이 있었는데... 제겐 정말 안 좋은 소식이죠.$B$B어쨌든, 덩치큰 바다악어 가죽은 가져왔나요?'),
(640, 'koKR', '트롬카, $C 친구. 젠구에게 들었는데 내 도움이 필요하다고?'),
(651, 'koKR', '내부 봉인석입니다. 봉인석 중에서 가장 강력한 돌이며, 이 돌을 빼내면 나머지도 모두 열립니다.'),
(654, 'koKR', '그래, 필요한 건 다 모았나? 다 모으지 못했는데 동력이 다 떨어지면 안에 든 자료가 모두 파괴돼 버려 새로 시작해야만 한다고.$B$B이거, 나한테 동정을 구할 생각은 말라고. 나는 가젯잔 수자원개발회사의 수익을 올리는 데만 관심이 있으니까 말이야. 그러기 위해 던모로의 얼음 샘에서 물을 수입해 올 수 있을 때까지 당신에게 동력원을 팔아야만 한다면 그렇게 할 거라고!'),
(666, 'koKR', '고글은 어떻게 됐지? 모든 기능이 제대로 작동하나? 필요하다면 손을 좀 볼 수도 있소.$B$B참, 그리고 일을 마친 후에 고글을 돌려주는 것 잊지 말라고. 나중에 오브린 선장이 여러 가지로 유용하게 사용할 수 있을 테니까 말이야.'),
(668, 'koKR', '여어, $C 친구. 무슨 일로 왔지?'),
(669, 'koKR', '무법항에는 무슨 일인가, $C?'),
(683, 'koKR', '그래, 그대가 그 유명한 $C인가? 얼라이언스를 위해 세운 업적은 실로 모르는 사람이 없을 만큼 널리 퍼져 있더군.$B$B그래, 오늘은 무슨 일로 짐을 찾아왔는가?'),
(691, 'koKR', '일은 잘 돼 가십니까?$B$B<크리텐이 일지에 글을 적는 동시에 읽어 주며>$B$B제가 조사한 내용이 정확하다면 어금니는 마른나무껍질 트롤에게서 구할 수 있습니다. 약초 주머니는 마른나무껍질부족 의술사에게서 구할 수 있고, 어둠사냥꾼 나이프는 마른나무껍질부족 어둠사냥꾼 중 통과의례를 통과한 가장 강력한 녀석이 가지고 다닙니다. 전투를 시작하기 전에는 어떤 어둠사냥꾼에게 나이프가 있는지는 알 수 없답니다.'),
(699, 'koKR', '좋은 벌꿀 술과 따뜻한 불, 우리 부대 동료들, 무기로 가득 찬 무기고... 이곳 해안가에서 우리가 정말 필요로 하는 것은 이게 다지. 스토나드를 지키기 위해 이곳에 와 있는 걸 후회하지는 않지만, 언젠가 은신처나 탑이라도 하나 갖게 되면 좋겠군.'),
(712, 'koKR', '당신이 가져다 준 돌조각은 정말 완벽하군요. 여기서 실험이 끝나면 루시앙이 나머지 돌조각을 카라노스로 다시 가져갈 거에요. 그러면 그들이 이 돌의 유용성을 다시 증명할 수 있겠죠.$B$B예를 들면, 고성능의 폭약을 여러 방면으로 연구해서 이 돌조각들을 이용한다면 보다 좋은 보금자리를 지을 수 있는 좋은 기초를 만들 수 있을 거에요.$B$B<로트윌이 다시 실험을 하기 위해 돌아가면서 목소리가 서서히 사라진다.>'),
(714, 'koKR', '아, 그래요, 그래, 잠시만...<계속 어떤 장치를 만드느라 여념이 없는 로트윌>'),
(728, 'koKR', '아, 열정적인 $C|1이로군;로군;. 내 소장품을 공부하고 싶어서 왔소? 좋소!$B$B하지만 경고해 두는데, 지식은 강한 자들에게 힘을 주기도 하지만, 약한 자들을 미치게 만들기도 한다오.'),
(741, 'koKR', '무슨 일이오, $R?'),
(750, 'koKR', '부족을 위해 가죽을 구해 준다면 내 아버지, 족장 호크윈드께 당신의 공로를 전해 주겠소.'),
(757, 'koKR', '힘의 의식은 완수했는가? 우리 부족의 적, 뾰족털일족 놈들에게 맞서 싸울만한 용기가 있다는 걸 보여줄 증거가 필요한데...'),
(763, 'koKR', '우리 마을엔 어쩐 일이신가, $C?'),
(768, 'koKR', '다시 왔군. 사냥은 했소? 그럼, 가죽은 가져왔겠지?'),
(777, 'koKR', '<팔찌를 쳐다보지 않게 하기 위해서 손을 뻗어 저으며 조급한 목소리로...>$B$B기어, 기어가 필요해!'),
(790, 'koKR', '아버지는 항상 내가 위대한 영웅은 절대로 되지 못할 거라고 말씀하셨는데, 이렇게 나무 밑에서 죽음을 기다리고 있자니 그 말씀이 옳았따는 생각이 드는구려.$B$B하지만 죽기 전에 적어도 내 원수가 없어졌다는 걸 확인하고 싶소.'),
(816, 'koKR', '크론이 무사히 돌아오기만을 기도하고 있지만, 그 아이에게 나쁜 일이 생긴 것 같은 느낌을 지울 수가 없군요.'),
(822, 'koKR', '재료는 열심히 찾고 있소, $N?'),
(824, 'koKR', '오, 안녕하신가. 나는 물뿐 아니라 모든 원소들을 연구하면서 많은 시간을 보내는데, 한번 빠지면 무아지경에 이를 정도라 때로는 주위에 누가 있는 것도 알아차리지 못할 때가 있지...$B$B내가 도와줄 일이라도 있나?'),
(826, 'koKR', '잘라제인은 처치했나, $N?'),
(830, 'koKR', '표정을 보니 뭔가 걱정거리가 있는 것 같은데. 그래, 무슨 일이지?'),
(840, 'koKR', '무슨 일이오, 젊은이? 신병으로 지원하러 온 게 아니라면 괜히 시간 빼앗지 말고 가보라고.'),
(842, 'koKR', '이런, 이런, 이건 또 누구신가? 카르갈이 내가 병사가 필요로 한다고 생각한 모양이군?'),
(848, 'koKR', '포자를 가지고 왔나? 썬더 블러프에 있는 동료에게 조제약을 보내 주어야 하는데, 그걸 조제하려면 포자가 필요하네...'),
(864, 'koKR', '돌아왔군요. 봉인된 분석 도구를 갖고 돌아왔다면 환영해요. 그게 아니라면, 당신의 무능함을 모른 체하고 주어진 임무를 완수할 때까지 화를 참도록 하죠.'),
(879, 'koKR', '$R, 일은 잘 되가고 있나? <킁킁>$B$B로크는 누가 일족을 약탈하는지 안다고 생각하지만, <킁킁> 자네가 성공한다면 그도 자기가 틀렸음을 깨닫게 되겠지.$B$B비록 뻐드렁니는 이 감옥 안에서 죽어갈 운명이지만 자네가 나 대신 그 놈들을 처치해주었으면 후회는 없을 것 같네. <킁킁>'),
(880, 'koKR', '그래, 일은 어떻게 돼 가나? 등껍질을 다 모았나?'),
(884, 'koKR', '자네 눈 너머에서 새로운 힘이 느껴지네. 이미 오와탄카를 만난 게로군, 그렇지?'),
(892, 'koKR', '음, 디지위그가 뭐라고 하던가?'),
(893, 'koKR', '나 또한 미개한 서슬갈기 일족이 그 정도 수준의 기술을 가지고 있다는 것이 믿어지진 않지만, 대족장님 말씀대로 서슬갈기 일족에게서라도 배울 점이 있다면 배울 거요.$B$B아무리 구차한 일이라도 우리 오크족을 돕는 일이라면 발 벗고 나설 것이오.'),
(902, 'koKR', '오, 돌아왔구먼! 사모플랜지는 가져왔나?'),
(919, 'koKR', '그래, 물가에서 나무괴물 씨눈들을 발견했소?'),
(921, 'koKR', '달샘의 물은 사실 영원의 샘에서 온 것입니다. 그 샘은 우리 세계에 수많은 비극을 불러왔던 고대 마법의 원천이지요.$B$B드루이드들은 그 물의 특성을 이용하고 있고 센티널에서는 그 샘을 엘룬의 제단으로 신성시하고 있지만, 그 물 안에 담긴 마법은 아직 그 누구에게도 알려지지 않았소.'),
(928, 'koKR', '어서 오시오, $C. 무슨 일로 이렇게 날 찾아왔는지 말해 주시겠소?'),
(929, 'koKR', '다시 만나 반갑소, $N. 임무는 완수했소?'),
(934, 'koKR', '우리 드루이드들은 대드루이드님, 그리고 신탁의 나무와 함께 텔드랏실의 성장을 지켜봐 왔소. 하지만 새로운 고향에 둥지를 틀었음에도 아직 우리는 불사의 생명을 회복하지 못 하고 있소.'),
(950, 'koKR', '돌아왔구나, $N.'),
(956, 'koKR', '이 제단의 기둥은 마치 날 가두고 있는 감옥의 빗장과 같은 거라네. 내 힘으로는 그걸 부술 수도 없고 마법으로도 파괴할 수 없지.$B$B수천 년 동안 나는 저 기둥들을 쳐다보면서 저 돌처럼 오랜 시간을 이런 모습으로 남게 되는 게 아닌가, 다시 자유로울 수 있을까... 이런 생각을 해왔다네. 아니면 날 가두고 있는 보이지 않는 빗장이 있는 건 아닐까...'),
(964, 'koKR', '죽여. 다 죽여 버리게, $C|1이여;여;. 열쇠를 만들려면 온전한 뼈조각이 꽤 많이 필요하다고. 왜 세상에 많고 많은 이름을 놔두고 해골 열쇠라고 부르겠나?'),
(992, 'koKR', '어서 오시오, 후임측량사! 벌써 임무를 완수했소?'),
(1003, 'koKR', '버즈박스 525에서노랫소리가 들려 옵니다.$B$B\"게 와인은 달콤하고, 트레샤돈 맥주는 훌륭하고, 달표범 위스키는 근사하지. 하지만 엉겅퀴곰 맥주만큼 좋은 건 없다네. 그리고 난 곧 이 술을 맛보게 되리!\"$B$B노래는 계속 반복되고 버즈박스의 입구는 불곰 가죽 4개를 기다리는 듯 열려 있습니다.'),
(1016, 'koKR', '정령들을 처치하려면 족쇄를 부숴야 하기 때문에 예언의 두루마리를 예언된 두루마리로 바꾸는 데 필요한 정보를 가지고 있는 족쇄를 찾기가 쉽지 않을 겁니다. 다른 이와 족쇄를 교환해서 필요한 족쇄를 모을 수도 있습니다만, 혹시 이미 비밀을 밝혀 낸 것인가요?'),
(1023, 'koKR', '아, 돌아왔군요.'),
(1046, 'koKR', '센티널이 이곳 잿빛 골짜기를 지키기 위해 최선을 다하고 있긴 하지만, 그대와 같은 나이트 엘프들이 있었기에 우리가 지금의 터전을 갖추게 되었답니다.'),
(1065, 'koKR', '음, 내게 새로운 실험 과제라도 가져온 건가?'),
(1074, 'koKR', '어이, 멋진 친구. 돌아왔구먼.'),
(1077, 'koKR', '하하, 돌아왔군! 부탁한 건 가져왔소? 마법 주문 말이오.'),
(1106, 'koKR', '흠, 용케 날 찾아냈군. 좋아.$B$B가스일조그를 주려고 만든 도끼를 구하러 온 건가? 아니면 공작부인 파페이의 명예를 되찾으러 온 건가?$B$B사실, 무슨 일로 왔든 나야 상관 없지만... 싸우러 온 건가? 그럼 바로 시작하지...'),
(1111, 'koKR', '좀 큰 소리로 말하라고! 도대체 물건을 보내러 온 건가, 아니면 찾으러 온 건가?'),
(1114, 'koKR', '내게 뭐 줄 거라도 있소? 아, 잘 됐군! 어디 한번 봅시다!'),
(1118, 'koKR', '하하, 안녕하신가요! 귀하신 $R께서 무법항엔 어쩐 일이신지요?'),
(1119, 'koKR', '그래, 피즐버브가 도움을 주었소?'),
(1126, 'koKR', '그래, 됐습니까? 무사한 걸 보니 다행입니다만 뭔가 찾아낸 거라도 있습니까?'),
(1148, 'koKR', '아, 오랜만이군. 오늘은 무슨 일이오? 방금 전투를 치르고 온 것 같아 보이는데... 호드를 위해서나 당신 자신을 위해서나 좋은 일이지... 전투를 많이 치를수록 더 큰 명성과 힘을 얻게 될 테니까 말이오.'),
(1150, 'koKR', '앞으로 남아 있는 시험을 통과하려면 영혼과 신체, 그리고 마음의 무장을 단단히 해야 하네.$B$B우리는 때때로 아무 준비도 없이 무모하게 달려드는 경우가 있지. 호드의 모든 종족을 막론하고 모든 젊은이들이 집을 떠나 부딪히게 될 역경을 잘 극복할 수 있도록 지도하는 것이 내 사명이라 여기고 있네.'),
(1160, 'koKR', '책을 훔쳐내기 전에 붉은십자군을 좀 처치해 주길 바라네.$B$B그들을 보는 내 눈은 틀리지 않아. 한 때 붉은십자군이 정의를 따르는 자들이었는지는 모르지만 지금은 그들의 신앙을 따르지 않는 이들은 전부 해치고 있어. 놈들은 언데드와 표세이큰을 비롯한 모든 다른 종족들을 반드시 정화해야 할 대상으로 여기고 있네. 게다가 그들의 땅으로 들어오는 자는 모두 제정신이 아니거나 언데드의 강력한 마법에 조종당하고 있다고 생각하지. 바보들, 전부 정말 바보 멍청이'),
(1166, 'koKR', '나 그로그주 마시고 싶다. 내 코담배도 그립고. 내 금고는 어디 있는 거야? 나, 대군주 모크모로크에게 그것들을 가져와라.$B$B남쪽으로 우리 일족의 옛 고향을 찾아 가라. 난 오우거들을 다스리느라 너무 바빠서 직접 가지 못한다.'),
(1176, 'koKR', '뼈는 구해 왔소? 막 조종 장치의 하중을 줄이는 작업을 시작하려던 참이었는데, 필요한 부품을 구하기 전까지는 차체를 분해하고 싶지 않다오.'),
(1193, 'koKR', '커다란 부서진 함정이 앞에 놓여 있습니다. 겉으로 보아하니 오우거들이 수리를 하려다 실패한 것 같습니다. 옆에는 서둘러 적은 듯한 메모가 있는데, 기묘하게도 함정을 수리하는 데 필요한 것이 정확히 무엇인지 쓰여있습니다. 수리하려면 토륨 부품과 냉기 오일이 필요하며, 다 고치면 오우거가 지나가다가 걸릴 수도 있으니 조심해야 한다고 적혀있습니다.$B$B글을 읽을 줄 아는 오우거는 몇 되지 않는다는 사실은 확실히 큰 행운입니다.$B$B확실히 말입니다.'),
(1200, 'koKR', '시간은 소중한 거요, $C|1이여;여;.$B$B이곳 다르나서스에서의 내 역할은 은빛 여명회가 번성하고 칼림도어를 침략해 오는 악의 무리들을 막아내도록 하는 것.$B$B어서 용건을 얘기하든지 아니면 어서 가 보시오.'),
(1202, 'koKR', '서류는 찾았나? 그 서류에는 얼라이언스의 안전에 매우 치명적이고, 따라서 나아가 호드의 안전에도 매우 중요한 정보가 들어 있다네.'),
(1218, 'koKR', '향료라... 누구든 삶에 향료 같은 게 조금씩은 필요하지, 안 그렇소?'),
(1241, 'koKR', '흠, 당신 내가 고기 잡는 걸 방해할 정도로 중요한 일이라도 있는 거요. 난 거지뿐 아니라 행상인에게도 친절을 베풀어 본 적이 없는 사람이오.'),
(1243, 'koKR', '숲 속을 돌아다니는 것은 위험합니다. 조심하도록 하시고 의심스러운 일이나 위험한 것을 보면 즉시 순찰대원에게 알리는 것이 좋습니다. 혼자서 해결하려고 하지 마시고요. 당신에게 끔찍한 일이 일어나더라도 우린 책임이 없으니까요.$B$B그러나 당신이 내 말을 무시하고 어둠 속에서 나타나는 것이라면 그것이 무엇이든 맞서 싸우리라는 것을 우리 모두 알고 있지요. 내 말이 틀렸습니까? 하하, 그래요. 당신은 모험가 같이 보이니까...'),
(1244, 'koKR', '조심하십시오. 트리아스가 보낸 이라고 해도 숲속에 숨어 있는 것들로 인해 화를 당하지 말라는 법은 없으니까요. 특히, 당신처럼 데피아즈단을 조사할 때는 더욱 그렇습니다.'),
(1245, 'koKR', '어디 한 군데 다친 데 없이 무사히 돌아오셨군요. 당신이 치즈를 사러 온 게 아니라는 건 자명하니까, 농담은 그만두기로 하고... 바커스가 좀 도움이 되던가요? 아니면 아직 그늘숲으로 떠나지도 않은 건가요?'),
(1321, 'koKR', '볼일이 있나, $C?'),
(1395, 'koKR', '안녕하십니까! 이곳의 소란스러움에 마음쓰지 마십시오. 네더가드 요새에서는 늘상 있는 일이니까요.$B$B그런데, 저에게 뭔가 전해주실 게 있으신가요?'),
(1424, 'koKR', '아탈학카르 신전 내에서 어떤 사악한 음모가 진행되고 있는지는 아무도 모르지만, 거대하고 강력한 마법의 힘이 사용된 것만은 분명하오.$B$B그 마법에 대해 가능한 많은 정보를 얻어야 하오. 어쩌면 아탈라이의 마법 주문이 호드에게 도움이 될 것 같군.$B$B우선 당신이 눈물의 연못 주위에서 아탈라이 유물을 충분히 모아 오면 도대체 그 트롤 녀석들이 무엇을 하려는 것인지, 또 뭐가 그렇게 크게 잘못된 것인지 조금씩 알아낼 수 있게 될 것이오.'),
(1429, 'koKR', '여기까지 오다니 용기가 가상하군. 용감한 것이든가, 아니면 어리석은 것이겠지...'),
(1481, 'koKR', '내게 제대로 된 가죽을 가져와야 하오, $C. 조그만 실수에도 우리는 죽음을 당할 수 있소. 악마 군주가 그에게 수정점을 치려는 이들을 처치하려다가 실수로 자신의 수하에게 치명적인 주문을 걸었을 수도 있단 말이지.$B$B운명은 이미 내게 충분한 고통을 주었소. 더 이상은 원하지 않아.'),
(1482, 'koKR', '예언의 수정구를 사용할 준비를 해두었소, $C. 제왕 아즈레토크를 찾아 처치한다면 대족장님께서 우리 둘 모두에게 큰 상을 내리시겠지. 우리가 힘을 합쳐 신속히 일을 처리한다면 분명 대족장님의 신임을 얻게 될 거요.'),
(1485, 'koKR', '마법으로 소환한 존재들을 통제할 수 있는 방법을 깨우치는 것이 무엇보다 중요하지. 요즘은 흑마법사의 길을 가려는 이들이 너무 적으니, 자네가 아직 준비가 덜 되었다고 해도 일단 가르칠 수밖에 없네. 자네의 목숨이 위험할지도 모르지만...'),
(1486, 'koKR', '이 동굴에 출몰하고 있는 기이한 짐승들의 가죽을 조사해 보고 싶소. 그래, 가죽을 좀 모아 왔소?'),
(1492, 'koKR', '다음 배에 승선하려는 건가, 아니면 실어 보낼 물건이 있는 거야?'),
(1536, 'koKR', '그 마을에 순수한 우물이 남아있다니 어릴 적에 들은 이야기가 하나 생각나는군요. 아무리 큰 고통과 슬픔이 닥쳐와도 실낱 같은 희망만 있다면, 딛고 일어설 수 있어요. 오크족이 스랄을 높이 평가하는 이유도 그 때문이죠. 아주 불리한 조건 속에서도 살아남아 타에 모범을 보이며 우리 종족을 이끌어 갈 강인한 지도자로 일어섰으니까요.$B$B스랄만큼 힘들게 살아온 오크가 또 있을까 싶네요. 또 한편으로 생각해 보니 그만큼 강한 오크도 없는 것 같아요.'),
(1654, 'koKR', '찾고 있는 물건들을 구하기는 어려울 것이지만, 제가 만들어 드릴 무기는 대단히 가치가 높을 것이라는 걸 장담하죠.$B$B분명 제 생애에 최고의 무기가 될 것입니다. 당신이 저를 위해 해 준 수고에 대한 보답으로 기꺼이 드리고 싶습니다.'),
(1656, 'koKR', '이 카우스에게 무슨 일이신가요, 젊은 모험가분?$B$B어떤 이들은 붉은 구름 구원에서 여기까지 오는 길을 무척이나 부담스럽게 여기지만, 어떤 이들은 오히려 좋은 경치구경이라 생각을 한답니다. 젊은 모험가께서는 어떻게 생각하시는지 궁금하군요.'),
(1665, 'koKR', '바틀비와 싸우는 건 잘 봤네. 잘했어! 그래, 술잔은 가져왔나?'),
(1707, 'koKR', '우리가 필요로 하는 사막유랑단 물주머니 5개는 가져왔소? 가져왔다면 가젯잔 수자원개발회사 선물세트, 모델 103-XB는 당신 것이오!'),
(1796, 'koKR', '로브를 찾는 일은 어떻게 돼가고 있나요, $N? 직접 만들었나요? 직접 만든 물건은 마법 부여가 더 잘 되는 것 같아요. 성취감도 더 크고요. 하지만 더 간편한 길을 택해서 다른 이에게 시켰다고 하더라도... 더 빨리 강해지고 싶은 당신의 야망은 이해합니다.'),
(1882, 'koKR', '금어초를 가져왔나요? 그 화종은 마법력을 워낙 잘 흡수하기 때문에 오염지대 가까이 있는 금어초를 조사하면 티리스팔 숲에 역병이 침투했는지 알 수 있어요.'),
(1918, 'koKR', '그래, 무슨 일로 왔나?'),
(1940, 'koKR', '아, 오셨군요. 마법사의 성소의 마법사들이 당신이 올 거라고 하더군요. 거미줄은 가져오셨나요?'),
(1945, 'koKR', '오, 반갑습니다. 다이노께서 당신이 미소띤 자매의 머리카락을 가지고 올 거라고 하시더군요. 자, 좀 보여주시겠습니까?'),
(1951, 'koKR', '오, 돌아왔군요? 책은 찾았나요?'),
(2160, 'koKR', '어서 오십시오, 손님! 불 옆에 앉아 따뜻한 차나 한 잔 드시면서 몸을 좀 녹이시기 바랍니다.'),
(2203, 'koKR', '요술 유리병으로 내가 필요로 하는 화염의 수호비룡 피를 모아 왔나? 그래, 위험한 임무라는 것은 나도 아네... 하지만 내 치유 물약 조제법이 자네가 성공하길 기다리고 있다네. 고생 끝에 낙이 온다네, 친구... 고생 끝에 낙이...'),
(2280, 'koKR', '어서오세, 젊은이. 천막으로 걸어 들어오는 모습을 보니 걸음걸이에 힘이 넘치는군... 목적에 대한 결의 말일세. 호드에게 극히 중대한 문제로 내 조언을 들으러 온 것일 테지? 자네 앞에 밝혀진 우주의 수수께끼를 알고 싶은 건가?'),
(2340, 'koKR', '아니, 이게 누군가! 신수가 훤해졌군. 여기까지 오면서 무슨 기분 좋은 일이라도 있었나 보지?! 희소식을 가져 왔길 바라오. 부탁한 물건들을 모두 가져오기 전까지는 돈을 주지 않을 테니까. 분명히 말해두는데 두 번이고 세 번이고 확인해볼 거요!'),
(2438, 'koKR', '서둘러 주시오. 펄볼그가 에메랄드의 꿈 흡입기에 손대지 않았기만 바랄 뿐이오.$B$B아직 찾아오지 못했소, $N?'),
(2440, 'koKR', '안녕하세요! 연금술 훈련을 받으러 오셨나요, 아니면 다른 이유로 오셨나요?'),
(2605, 'koKR', '그래, 이슬먹는 괴물들은 찾았소?'),
(2661, 'koKR', '아, 드디어 돌아왔군. 뭘 가져온 게요?'),
(2746, 'koKR', '난 2주째 라스코발을 지켜보고 있었소. 트리아스는 절대 라스코발 녀석을 믿지 않았지만, 우리는 녀석이 데피아즈 결사단과 관계가 있을거라고는 생각해 보지도 못했지. 우리는 녀석과 황혼의 망치단과의 관계에 대한 단서를 추적하고 있었거든. 어쨌든 녀석은 이 도시의 힘으로 처리할 수 없을 만큼 큰 위협이 되어버렸소. 바로 우리가 나서야 할 때지.$B$B그 물건들을 가져오면 내 계획을 실행하도록 하지.'),
(2782, 'koKR', '흠, 어디 보자. 이건 뭐죠?'),
(2860, 'koKR', '만나서 반갑습니다. 보아하니 당신도 나처럼 가죽세공사인 것 같군요. 내 기술을 배우러 왔나요, 아니면 혹시 나에게 다른 볼일이 있는 건가요?'),
(2873, 'koKR', '내 럼주가 든 뱃짐은 찾았소, $N?'),
(2933, 'koKR', '안녕하시오, $C 양반. 하루 종일 애써 봤지만 하나도 성공한 실험이 없구려... 당신이 즐거운 소식을 가져온 거라면 좋겠소.'),
(2947, 'koKR', '좀 진정하시라니까. 난 신용 있는 사업가란 말이오! 임대료를 부친 게 좀 지연이 되고 있을 뿐이... 잠깐, 당신은 우리 집주인이 아닌데...$B$B이런, 정말로 아니군. 내가 바보 같은 소릴 했군! 저주받은 물건 따위는 절대로 만들지 않는 아이언포지 최고의 보석 세공인을 찾아온 손님이시군 그래!$B$B음... 무엇이 필요하신 게요?'),
(2972, 'koKR', '엘룬께 영광을. 이 신전에 그대처럼 강한 모험가가 찾아오니 기쁘군요. 혹시 시간이 있다면 더 젊은 모험가들에게 모험담 한두 가지 들려 주지 않겠어요? 그들이 그대의 지혜에서 많은 것을 배울 수 있을 겁니다.$B$B이런, 미안합니다. 내가 너무 무례하게 구는군요. 달의 신전으로 우리의 도움을 받으러 온 것일 텐데 이런 부탁이나 하고 있으니... 용서하세요. 빛의 신하인 우리가 도와드릴 일이 있으면 어서 말씀하세요.'),
(2974, 'koKR', '내 말을 새겨들으시소. 그림토템부족은 사악하기 그지없는 놈들이오.녀석들의 소재를 파악했다면, 그곳으로 돌아가서 선제공격을 가해야 하오. 놈들이 쳐들어와 마을을 불사르고 우리 영토를 빼앗기 전에... 모두 당신에게 달렸소.'),
(2976, 'koKR', '어서 얘기하게, $C. 오늘 할 일이 아주 많거든.'),
(3103, 'koKR', '아, 드디어 왔군요. 날 찾아올 줄 알고 있었습니다. 성스러운 빛이 당신과 당신이 선택한 길을 비추고 있답니다. 이 시대는 가혹합니다. 아직도 불타는 군단의 세력이 아제로스에 남아 있고 칼림도어 전체가 그 자신의 시련으로부터 자신을 보호할 새로운 방법을 찾고 있어요. 그리고 가능한 많은 이들을 돕는 것은 당신의 소임입니다.'),
(3106, 'koKR', '지독하게 추운 날씨로군, 안 그렇소? 세상이 끝나도 이놈의 눈은 그칠 것 같지 않다니까...$B$B벌써 알아차렸겠지만 노움족도 우리 도시에 살고 있소. 그 친구들 스스로 고향을 폭파시키고 떠나왔지 이 얘기는 함부로 하고 다니지 마시오. 그런데 노움들을 어리석다고만은 할 수 없을 것 같단 말이야. 나라도 내 고향 아이언포지에 검은무쇠단 드워프 녀석들이 득실거리면 폭탄을 터뜨렸을 걸.'),
(3117, 'koKR', '드디어 도착했군요. 그늘 협곡에 오신 걸 환영합니다. 그대의 몸과 마음이 모두 평안하실 것으로 믿습니다. 전에도 말했듯이, 여기서 저는 짐승을 길들여 전투에 이용하는 법, 한치의 오차도 없이 활을 쏘는 법, 우리가 고향이라고 부르는 이 땅과 이 너머에 있는 땅을 존중하는 법 등 사냥꾼으로서 갖추어야 할 기술을 그대에게 가르칠 것입니다.'),
(3118, 'koKR', '안녕하시오. 제대로 찾아와서 다행이군. 혹시 오다가 길을 잃은 건 아닌가 걱정하고 있었소.$B$B당신에게 내 도장을 보낸 이후 그늘 협곡에 별다른 문제는 없었지만, 당신에게 이곳에 퍼진 소문을 물색하는 임무를 맡기겠소. 시간이 난다면 알드랏실에 사는 모든 주민들과 대화해 보시오.'),
(3119, 'koKR', '이렇게 빨리 와주시다니 기쁘군요. 잘 오셨습니다.$B$B이미 들으셨겠지만 수많은 여행자가 오가는 통에 텔드랏실이 분주해지고 있어요. 이곳에서 앞으로의 모험을 준비하는 나이트 엘프들 뿐만 아니라, 얼라이언스 모든 일원들을 만날 수 있게 됐답니다.'),
(3361, 'koKR', '정말 이 마을은 깔끔한 내겐 어울리지 않는다니까... 여기는 더럽고 냄새 나는 놈들이 침략해 우글우글거리던 시절의 놈리건이랑 거의 비슷한 수준이라오!$B$B$N, 내 물건들을 찾아 온 거요? 아직까지 그 무식한 트롤 녀석들의 손에 있다면 성하지는 못할 텐데...'),
(3364, 'koKR', '내가 바로 두르난 퍼커터가 맞는데, 뭘 가지고 온거요?'),
(3376, 'koKR', '당신이 뾰족어금니를 처치했다는 증거를 가져오면 녀석이 더 이상 우리를 괴롭히는 일은 없게 될 겁니다. 내가 원하는 것은 녀석의 머리입니다.$B$B우리 타우렌은 사냥을 위해 삽니다. 되려 우리를 사냥할 수 있을 정도로 영리한 상대를 사냥하는 것보다 더 위대한 사냥은 없습니다. 젊은 $R|1이여;여;, 이 임무를 완수하게 되면 내 말의 의미를 알게 될 겁니다.'),
(3449, 'koKR', '이런, 이런, 이런, 여기까지 무사히 온 걸 보니 반갑군. 티모르씨에게 배달할 탁본은 가져왔소?$B$B이곳이 위험하다고는 해도 해안에서는 별다른 일이 없었소이다. 아마 나가들이 물 밑에서 헤엄치고 있기 때문이겠지만, 그거야 내가 신경 쓸 일이 아니지... 나는 하늘을 정찰하니까 말이오.'),
(3511, 'koKR', '돌아왔군! 놀랐네, $R|1이여;여;. 악마의 진짜 이름은 알아냈는가?'),
(3541, 'koKR', '그래, 뭣 때문엔 온 거지? 그렇지 않아도 오늘 할 일이 많은데 자네는 오늘 일정에 없는 걸. 날 자꾸 귀찮게 하면 가만두지 않겠네.'),
(3562, 'koKR', '그래, 마가타가 뭐라든가요? 그 늙은 대모... 분명 거만하게 굴었겠지.'),
(3601, 'koKR', '돼 먹지 못한 블러드 엘프 놈들 같으니, 내가 당신만큼 강했어도 지금 당장 달려가서 톡톡히 본때를 보여 줬을 거요! 하지만 당신에게 대신 처리해 달라고 하는 수밖엔 없겠네요.'),
(3643, 'koKR', '내가 검토할 수 있도록, 당신이 만든 기계공학 물건들을 주면 당신에게 정품 노움 기술자 회원권을 주겠소! 그 회원권의 유효 기간 동안은 세계 어디에서든 노움 전문 기술자를 무제한으로 만날 수 있소.'),
(3823, 'koKR', '제복에 묻은 피를 보니 녀석들을 충분히 없애지 못한 것 같군, 병사!'),
(3841, 'koKR', '안녕하시오, $C 친구.$B$B여기 경주를 구경하러 온 게 아니니 오해하지 마시오. 뭐, 경주가 재미있기는 하지만 말이외다.$B$B난 이 땅의  구제 가치를 알아보려고 갖은 조사를 하러 버섯구름 봉우리에 온 것이오. 이 지역을 활력이 넘치고 비옥한 땅으로 되살리는 건 내게 일종의 신성한 임무가 되어 버렸소. 어쩌면 근처에서 수자원을 발견할지도 모르는 일이지.$B$B페랄라스와 버섯구름 봉우리 사이의 변화가 얼마나 기이한지 보지 않았소? 이런 일이 발생했'),
(3922, 'koKR', '용접용 철괴를 가져오셨나요, $N? 이 사모플랜지를 계속 쳐다보고 있으려니 얼른 고치고 싶어서 안달이 나네요.'),
(4105, 'koKR', '숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있소. 그 식물은 악령의 숲이 타락해서 생긴 부산물이오. 난 이곳에서 일하다가 지옥덩굴을 정화용 시약이로 만드는 방법을 알게 되었소. 지금 그 약은 세나리온 식물 고약이라는 이름으로 불리고 있지.$B$B세나리온 등불을 들고 악령의 숲에서 약초를 모으다 보면, 지옥덩굴을 찾게 될 거요. 충분히 모아서 가지고 오면 미리 만들어둔 세나리온 식물 고약을 나눠드리겠소이다.'),
(4110, 'koKR', '숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있소. 그 식물은 악령의 숲이 타락해서 생긴 부산물이오. 난 이곳에서 일하다가 지옥덩굴을 정화용 시약이로 만드는 방법을 알게 되었소. 지금 그 약은 세나리온 식물 고약이라는 이름으로 불리고 있지.$B$B세나리온 등불을 들고 악령의 숲에서 약초를 모으다 보면, 지옥덩굴을 찾게 될 거요. 충분히 모아서 가지고 오면 미리 만들어둔 세나리온 식물 고약을 나눠드리겠소이다.'),
(4161, 'koKR', '늘 자연의 균형을 기억하며 살아가십시오, $N. 숲을 살아있는 생명체로 이해하는 마음의 자세와 강한 영감을 키우시길 바라겠습니다.'),
(4283, 'koKR', '<꽤 큼직하게 절단된 오우거 귀에다 대고 말하는 랄리우스>$B$B여기는 불타는 평원. 본부 나와라, 오버.'),
(4294, 'koKR', '그래, 실험은 어떻게 되어가오?'),
(4297, 'koKR', '고기는 찾아 온 건가? 자네의 작은 알은 이제 부화할 때가 거의 다 됐네. 처음 먹는 음식을 좋은 것으로 먹이지 않으면 한 주도 넘기지 못할지 모르네. 그런 일이 일어나서는 안 되지.$B$B음, 더 이상 거짓말하지 않겠네. 난 애초에 당신이 이 알을 손에 넣었다는 것부터가 부럽네. 자네를 이렇게 도와 준 걸 후회하지 않도록 해 주게나.'),
(4450, 'koKR', '오, 음? 무슨 일이지, $R 친구? 손님이 워낙 밀려서 엄청나게 바쁘단 말이야. 당신만 아니면 일을 더 빨리 끝낼 수 있을 것 같은데 말이지. 기분 나쁘게 할 생각은 아니지만 지금 내 일을 다 마칠 시간도 없는 판이라고.'),
(4509, 'koKR', '그 자들은 정말 한심해요, $N! 주변에 더 큰 위협이 있는지 찾아볼 생각도 하지 않는다니까요. 얼라이언스의 맹목적인 증오 때문에 결국엔 우리 모두 끝장나고 말 거예요. 실리시드 소굴로 데리고 가서 직접 확인시켜 주는 것 말고는 달리 어떻게 실리시드의 위협을 알려야 할지 모르겠어요!$B$B아, 죄송합니다. 제게 무슨 소식을 가져온건가요?'),
(4781, 'koKR', '금괴라... 그렇지, 좋소. 금괴 하나를 내게 주면 실을 만들어 주겠네. 그리고 내 말을 잘 들어 두게. 아주 힘겨운 시험들이 기다리고 있으니... 그때까지 자신을 더 강하게 만드는 데 주력해야 하네. 지금 자신이 얼마나 강하다고 생각하든, 나중에 준비를 좀 더 철저히 해둘 걸 하고 후회할 날이 분명 있을 테니까.'),
(4784, 'koKR', '곧 완성돼요! $N, 약속하죠. 그 로브는 기대 이상으로 우수하기 때문에 어떤 전투에서든지 승산을 높여 줄 거예요.'),
(4883, 'koKR', '무슨 일이신가요, $N?'),
(4972, 'koKR', '내가 찾는 시간의 장식품은 단순한 장치랍니다. 주로 시계인데, 안돌할에 처음 역병이 들이닥쳤을 때 시계 침이 멎어버린 것들이지요.$B$B시간은 결코 멈추지 않고, 당신이 가져오는 시계들은 모두 제 집으로 되돌아가게 될 겁니다. 물론 이곳의 소동이 계속된다면 말이지만...'),
(5041, 'koKR', '보급품 수색은 어떻게 진행되고 있나, $N? 자네의 힘이라면 가시멧돼지들은 여지없이 나가떨어질 거라고 믿네.'),
(5042, 'koKR', '아감마간님의 힘을 얻으려면 4개의 혈석 파편이 필요하네, $R. 이 힘을 얻는다면 적들이 자네를 가장 두려워 하게 될 걸세. <킁킁>$B$B서슬갈기 일족의 용맹한 전사들은 모두 이런 힘을 가지고 있네!'),
(5050, 'koKR', '존, 여보... 당신인가요? 갑자기 추워졌어요...'),
(5051, 'koKR', '존, 구울을 조심하세요... 절 혼자 두지 마세요... 고약한 구울들... 부적만 잇으면 안전할 거예요.'),
(5052, 'koKR', '우리 일족은 불모의 땅 전역에 걸쳐서 가시 덩쿨이 많은 장소에 모여 살고 있다네. <킁킁> 왜냐하면 우리에게는 성역이기 때문이지. 그중에서도 가시덤불을 가장 신성한 장소로 꼽는다네. 아감마간님의 성체로 만들어졌기 때문에 더더욱 중요하지. <킁킁> 그곳에서 경비가 가장 삼엄한 곳은, 구릉으로 입구가 아감마간님의 입으로 만들어졌지! <킁킁> 아감마간님께 충성하지 않는 자들을 삼키고 뼈를 뱉어낸다네! <킁킁>$B$B아감마간께서는 우리를 지키기 위해서 그 분'),
(5059, 'koKR', '변소로 통하는 문은 계속해서 억지로 열려고 한 듯, 가장자리가 쪼개지기 시작했습니다. 지금은 밖에서 단단히 잠겨 있습니다.$B$B문을 흔들어 보니 안에서 누군가 쉰 목소리로 신음하는 소리가 들립니다! 안에 있는 것이 무엇이든 간에 사나운 것 같습니다.'),
(5088, 'koKR', '$N, 악독한 독사 아리카라를 처치하셨습니까?'),
(5122, 'koKR', '난 이 교회의 힘으로 내 가슴 속의 타락에 저항하고 있소. 내가 이곳을 떠나면 죽음의 기사로 변해 버리게 될 거요. 하지만 신념의 메달만 있으면 내가 이곳을 떠날 수 있는 힘을 줄 거요.$B$B부탁이니 그 메달을 가져다주시오. 그 메달은 광신자 말로가 지키고 있는데, 이 미친 녀석은 스트라솔름 서쪽에 있는 붉은십자군 성채에 사는 붉은십자군 일원이라오.'),
(5159, 'koKR', '아, 돌아왔군요, $N. 불모의 땅에서 이슬렌을 찾을 수 있었나요? 아니면 다른 방법으로 물을 정화하셨나요?'),
(5214, 'koKR', '난 더 이상 참을 수 없네! 제발 날 도와주게! 오, 난 죽어가고 있어!'),
(5232, 'koKR', '각 가마솥에서는 여러 가지 다른 종류의 재료가 섞여 역병을 뿜어내는 고유의 독이 만들어진다고 알고 있습니다. 마찬가지로, 우리는 각 가마솥별로 고유한 반작용 물질을 개발해야 하는 것입니다. 당신이 달슨의 눈물에서 가져온 견본은 그 가마솥 특유의 필요한 재료를 알아 내는 열쇠가 될 겁니다.'),
(5243, 'koKR', '도시가 파괴되어 남아 있는 보급품들이 그다지 많지 않을 테니까 조심하게! 스컬지는 성수에 손 댈 수 없지만, 성수도 독으로부터 자네를 지킬 수는 없을 것일세.'),
(5246, 'koKR', '귀족의 성서가 있어야 그대를 도와드릴 수 있는지, 없는지 결정할 수 있습니다.'),
(5252, 'koKR', '오랜만에 다시 만나게 되는구려, $N. 그동안 무사하셨소?'),
(5253, 'koKR', '어쩐 일인가, $R?'),
(5283, 'koKR', '아, 대장간에서 그을린 이 영광의 흔적 좀 봐주시오. 이보다 더 뿌듯한 건 없지... 작업복의 이 기름때만 봐도 누가 더 훌륭한 장인인지 알 수 있을 거야.'),
(5341, 'koKR', '내 앞에서는 고개를 숙이라고, $R. 나는 고상한 신분이고 그쪽은 결국 땡전 한푼 없는 천한 신분 아닌가?'),
(5343, 'koKR', '그쪽이 내 미래를 보장해 준다면 나도 그쪽의 미래를 보장하겠습니다.'),
(5361, 'koKR', '$C, 무슨 소식이라도 가지고 온 것이오? 아! 형이 보낸 전갈이라고요? 당장 그 보고서 좀 봅시다!'),
(5385, 'koKR', '자에데나르에서의 일은 잘 됐습니까, $N?'),
(5402, 'koKR', '앞잡이의 스컬지석은 스컬지 사병들의 표장입니다. 이 표장은 역병지대에 배치된 부대들 중 좀 약한 무리들에게서 종종 찾을 수 있습니다. 하지만 \"좀 약하다\"고 해서 녀석들을 얕잡아봐서는 절대 안 됩니다. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대랍니다.$B$B현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나씩을 지급하고 있습니다. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 드리도록 하겠습니다.'),
(5403, 'koKR', '침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장이죠. 역병지대에 배치된 부대들 중에서도 좀 더 강한 녀석들에게서 종종 찾을 수 있습니다. 이러한 녀석을 처치하는 것이 사실 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겨야 할 임무라고 할 수 있습니다.$B$B은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 주고 있습니다. 내게 그 표장들을 가져오시면 형제님께서 마땅히 받아야 할 보상을 반드시 지급하도록 하겠습니다'),
(5407, 'koKR', '침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장이죠. 역병지대에 배치된 부대들 중에서도 좀 더 강한 녀석들에게서 종종 찾을 수 있습니다. 이러한 녀석을 처치하는 것이 사실 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겨야 할 임무라고 할 수 있습니다.$B$B은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 주고 있습니다. 내게 그 표장들을 가져오시면 형제님께서 마땅히 받아야 할 보상을 반드시 지급하도록 하겠습니다'),
(5408, 'koKR', '앞잡이의 스컬지석은 스컬지 사병들의 표장입니다. 이 표장은 역병지대에 배치된 부대들 중 좀 약한 무리들에게서 종종 찾을 수 있습니다. 하지만 \"좀 약하다\"고 해서 녀석들을 얕잡아봐서는 절대 안 됩니다. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대랍니다.$B$B현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나씩을 지급하고 있습니다. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 드리도록 하겠습니다.'),
(5514, 'koKR', '그래, 당신이 누군지, 여기 왜 왔는지 알고 있지. 당신이 도착하기 전에 알빙턴에게 전갈을 받았다고. 자, 서론은 집어치우고 본론으로 들어가자고. 거래하겠나?$B$B나한테 해골 열쇠를 만드는 데 필요한 거푸집이 있는데 말이야. 가격은 선불로 15골드. 흥정은 없다고, 친구. 뼈조각을 거푸집에 넣어 주고 말이야. 그리고 대장기술에 대한 지식 없이 열쇠의 자루를 만드는 방법을 공짜로 가르쳐 주지.$B$B이 정도면 아주 훌륭한 조건이라고!'),
(5525, 'koKR', '그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데. 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지...$B$B아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!'),
(5526, 'koKR', '봉인된 정화의 성물함을 손에 넣으면 이 세계에서 타락의 위협을 하나 제거할 수 있을 뿐만 아니라, 우리가 신중히 관리하면서 연구할 수도 있을 거요. 어쩌면 아제로스를 위협하는 타락한 존재에 맞설 방법을 알아낼 수 있을지도 모르지.$B$B밀리도 그걸 바라고 있었을 거요...'),
(5527, 'koKR', '정화의 성물함은 그 자체만으로도 유물의 가치를 지니고 있소. 원래 몇 개밖에 만들어지지 않았고, 그나마 대부분 시간이 흐르면서 분실된 것으로 알고 있소.$B$B그 중 하나가 마파람 마을에 있었다는 것을 안지는 꽤 됐다는 건 인정하겠소. 사실 실리더스에서 혼란이 점점 커지기에 그대로 비밀로 간직하려고 했었지. 이리저리 기웃거리다 보면 분명 적들의 의심을 살 테니 말이오.$B$B안타깝게도 이제 나 홀로 지켜온 평화의 시간은 이제 끝난 것 같소. 엘드레탈라'),
(5534, 'koKR', '그래, $N, 룬은 어디 있소? 당신은 일을 도우러 온 훌륭한 일꾼이지 않소?$B$B까딱 잘못하다간 우리가 합의한 보수에 대해 다시 생각해 보는 수가 있지. 뭐라고? 아무 것도 합의를 본 게 없었다고? 맙소사... 그렇다면 느긋하게 찾아오도록 하시오. 대신, 시간을 오래 끌면 끌수록 보수가 많이 줄어들 거라는 것만 알아 두고.'),
(5544, 'koKR', '그 고기 맛도 참을 만해지게 될 걸세, $R 친구.'),
(5545, 'koKR', '이행 시한이 점점 다가오고 있어요, $C님. 제발 서둘러 그 장작 더미를 가져와 주세요.'),
(5582, 'koKR', '음, 내게 뭔가 보여 줄 게 있나요?'),
(5725, 'koKR', '처리할 일이 너무나 많다, $C. 주문서는 가져왔나?'),
(5763, 'koKR', '앉게나, $C. 함께 밀림으로 사냥을 떠나세.'),
(5802, 'koKR', '해골 열쇠는 거의 다 완성하셨나? 미안하지만, 그 거푸집의 가격은 더 이상 깎아드릴 수가 없네. 우린 스컬지를 상대할 수 있도록, 맡은바 소임에 충실할 뿐이지. 불완전한 해골 열쇠를 가져왔다면, 자네에게 마지막으로 남은 일을 알려주지. 열쇠를 완성하려면 그 물건이 반드시 있어야 해.$B$B쉽지는 않겠지만, 안돌할 공격이라는 어마어마한 작전을 준비한 장본인이니, 그만한 대가는 치를 준비가 되있겠지. 차차 알게 될 거야.'),
(5803, 'koKR', '고생스러울 테지만, 소환사 아라즈의 육체적 형태를 부수는 것 만이 열쇠의 완성을 의미하네. 아라즈의 스카라베를 무슨 수를 써서라도 구해서 나에게 가져다 주면, 내가 열쇠의 머리 부분으로 용해를 시켜 주겠네.'),
(5884, 'koKR', '숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있소. 그 식물은 악령의 숲이 타락해서 생긴 부산물이오. 난 이곳에서 일하다가 지옥덩굴을 정화용 시약이로 만드는 방법을 알게 되었소. 지금 그 약은 세나리온 식물 고약이라는 이름으로 불리고 있지.$B$B세나리온 등불을 들고 악령의 숲에서 약초를 모으다 보면, 지옥덩굴을 찾게 될 거요. 충분히 모아서 가지고 오면 미리 만들어둔 세나리온 식물 고약을 나눠드리겠소이다.'),
(5889, 'koKR', '숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있소. 그 식물은 악령의 숲이 타락해서 생긴 부산물이오. 난 이곳에서 일하다가 지옥덩굴을 정화용 시약이로 만드는 방법을 알게 되었소. 지금 그 약은 세나리온 식물 고약이라는 이름으로 불리고 있지.$B$B세나리온 등불을 들고 악령의 숲에서 약초를 모으다 보면, 지옥덩굴을 찾게 될 거요. 충분히 모아서 가지고 오면 미리 만들어둔 세나리온 식물 고약을 나눠드리겠소이다.'),
(5941, 'koKR', '나는 당신의 친구인 카를린과 서로 소식을 전하고 있답니다. 그는 자기 고향이 몰락해 버린 일을 무척이나 괴로워하고 있지만 당신을 높이 평가하며 당신이야말로 모든 것을 바로잡을 수 있는 능력이 있다고 하더군요.$B$B아, 이야기가 옆길로 빠졌군요. 부탁한 유물은 갖고 있나요?'),
(6026, 'koKR', '나, 스모키를 믿게나. 자네는 반드시 합당한 보상을 받을 걸세. 은빛 여명회는 반드시 대가를 지불한다네.'),
(6028, 'koKR', '$C|1이여;여;, 어서 오세요. 은빛 여명회를 대신해 당신이 이곳 서리바람 거점에 머무르는 동안 안전한 숙소를 제공하겠어요. 그리고 일거리도 좀 주고 싶은데...'),
(6029, 'koKR', '$C|1이여;여;, 어서 오게나. 은빛 여명회를 대신해 자네가 이곳 보루에 머무르는 동안 안전한 숙소를 제공하겠네. 그리고 가치 있는 일을 위해 싸울 기회도 마련해 주겠네.'),
(6133, 'koKR', '날 기다리게 하지 말라고, $C 친구.'),
(6135, 'koKR', '이 일을 혼자 하는 건 좋지 않아, $C 친구.'),
(6146, 'koKR', '이런 건 허용되지 않는다, 병사!'),
(6162, 'koKR', '$N, 그 괴물은 처치했나? 녀석은 자기가 저지른 죄에 대한 대가를 치르게 될 거야. 녀석이 정말로 타락했든, 단지 그런 암울한 숲에 사는 바람에 사나워진 것뿐이든 상관없어. 내 가족에게 그런 죄를 저지르고도 살아남을 펄볼그는 없으니까!'),
(6163, 'koKR', '실바나스 여왕님께서 날 해방해주신 후, 나는 그 괴물을 추적해 이 황무지를 몇 달 동안이나 돌아다녔지. 녀석은 안전한 스트라솔름으로 피신해 갔어. 더러운 녀석 같으니...'),
(6442, 'koKR', '$N, 나가들의 수가 늘어나고 있습니다. 부디 절 위해 이 임무를 완수해 주십시오.'),
(6502, 'koKR', '시간의 흐름이란 멈추지도, 늦추어지지도 않는 것입니다. 내 생은 영원하나, 그대의 생은 그렇지 못하니 주어진 시간을 낭비하지 않도록 하십시오...'),
(6543, 'koKR', '서두르게, $N. 급한 일이니 어서 보고서를 전달해주게.'),
(6546, 'koKR', '$N, 이쪽은 매우 위험한 지역이에요. 여기 머무르는 동안에는 이 사실을 잊지 마세요. 얼라이언스의 위협이 시시각각 다가오고 있으니까요.$B$B여긴 사방이 적이에요. 잿빛 골짜기 동부는 사티로스의 세력이 만만치 않고요. 그리고 아즈샤라의 많은 지역을 나가가 차지하고 있지요.$B$B그래도 이렇게 당신이 오는 걸 보니 우리의 병력 보강은 원활하게 이루어지고 있군요. 정말 다행이에요. 언제나 유비무환이 최고죠.'),
(6547, 'koKR', '$N, 항상 주위를 잘 살피세요. 엘프들은 종종 밤의 그림자 속으로 숨어 버리거든요.$B$B늘 경계를 게을리해서는 안 돼요. 우리는 나이트 엘프들이 호시탐탐 노리고 있는 이 땅을 지키기 위해 최선을 다하고 있어요.$B$B참, 카드라크가 제게 어떤 명령을 내렸나요?'),
(6561, 'koKR', '$N, 항상 대지모신께서 당신과 함께하시기를.$B$B이 땅에서 대지모신의 후손들이 언제까지나 평화롭게 지내는 것이 우리의 목표입니다. 대지모신께서는 자연에 대해 위대한 계획을 가지고 계십니다. 그리고 우리 모두는 그 안에서 각자의 역할이 있는 것입니다.'),
(6581, 'koKR', '네, 있어요. 톱니항에서 바로 공수해온 전쟁노래부족 톱날이라고요!$B$B그런데 맨입으로 가져갈 수는 없죠. 저도 일하느라 바쁜 몸이라고요! 대가로 뭘 줄 건가요?$B$B사실 쓸만한 총이 하나 필요해요. 여자는 스스로 자신을 지킬 줄 알아야 한다고요. 참, 갖고 싶은 총이 하나 있는데... 만들기도 그리 어렵지 않대요.$B$B정교한 나팔총을 가져오면 대신 전쟁노래부족 톱날을 드릴게요. 어때요?'),
(6621, 'koKR', '$N, 족장 머구트를 물리쳤소? 썩은나무일족 토템은 가져왔고?'),
(6801, 'koKR', '나는 썬더 블러프에서 왔소, $R. 이 험난한 시기에 서리늑대부족을 도와주라면서 케른님이 몸소 보내셨지.$B$B하지만 시간 낭비는 그만두도록 하지. 당신은 우리 적을 물리치고 녀석들의 피를 가져와야 하오. 피를 충분히 모으면 소환 의식을 거행할 수 있소.$B$B정령의 군주를 소환해 스톰파이크 군대를 치면 반드시 승리할 거요.'),
(6844, 'koKR', '어이, 안녕하쇼! 허엄...$B$B솔직히 말하는 건데, 당신한테서는... 좀 노인네 냄새 같은 게 나는구만! 그러니까 불쾌한 냄새가 난단 말이야. 뭐, 인신 공격을 하려는 건 아니오. 그저... 앞으로는 밖에서 들어올 때 좀 깨끗이 씻고 오라는 거요. 첫인상이 썩 괜찮아질 테니까 말이지!$B$B그나저나... 무슨 일로 왔소?'),
(7068, 'koKR', '아직 수정을 발견하지 못했습니까? 마력의 의식, 강력한 마력은 모든 비전 마법에 대단히 큰 도움이 될 것입니다.'),
(7161, 'koKR', '정신 차리게, 정신을! 이건 꿈이 아니야. 지금 자네는 치열한 전투의 한복판에 서 있는 거란 말일세!'),
(7383, 'koKR', '우리 드루이드들은 대드루이드님, 그리고 신탁의 나무와 함께 텔드랏실의 성장을 지켜봐 왔소. 하지만 새로운 고향에 둥지를 틀었음에도 아직 우리는 불사의 생명을 회복하지 못 하고 있소.'),
(7385, 'koKR', '적에게서 더 많은 피를 제물로 바칠 수도 있습니다. 당신이 원한다면... $N, 한 사발 정도라면 흡족하겠습니다.'),
(7441, 'koKR', '후회는 하지 않소, 이방인 친구. 여왕님께서 떠나신지도 오래되었고 센드랄라의 업적은 토르텔드린 왕자의 광기로 훼손돼버렸지. 이제 내가 바라는 것은 오직 자유... 탈출 뿐이라오...'),
(7507, 'koKR', '아, 우리가 편찬한 최고의 작품 중 하나로군. 아주 오랫동안 분실돼 있던 책이오.'),
(7563, 'koKR', '광란에 휩싸인 올빼미 야수를 본 적 있습니까? 그 생물들의 마법은 강력하고 그 마법은 녀석들의 고통 받는 육체를 흐르는 피에 응축되고 있지요.'),
(7583, 'koKR', '그래, 어찌 됐소?'),
(7626, 'koKR', '비약은 가져왔나? 데스무라의 종이 필요하다고 모르줄님이 그러시던데, 그 종 하나를 만드는 데는 상당한 암흑의 힘이 필요하다고!'),
(7642, 'koKR', '아, $C 친구. 내가 말한 물건이 없으면 마갑을 완성할 수 없소. 내가 말한 물건을 모두 가지고 왔소?'),
(7703, 'koKR', '하하, 못 찾았지, 왕? 옛날 얘기가 거짓말일지도 모른다... 기분 나쁜 엘프가 고르독 왕에게서 훔치다니 말도 안돼!'),
(7732, 'koKR', '어서 오게, 친구... 아주 급한 용무로 온 것 같은데, 내가 도와 줄 일이라도 있나?'),
(7736, 'koKR', '잡담이나 하면서 더 이상 귀한 시간 낭비하진 말자고, $C 친구. 지금은 줄어들고 있는 불꽃 융해촉진제 재고를 보충하는 데 힘을 기울여야 할 때일세.$B$B자네가 가져와야 할 건 이렇다네.$B$B*인센도사우르스 비늘 2개$B*왕꽃잎풀 4개$B*석탄$B$B자네가 가져오는 건 모조리 다 받도록 하지! 토륨대장조합에서 평판을 높이려면 빨리 가져오는 게 좋을 거야.'),
(7795, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았습니다. 하지만 아직도 재고를 보충하기위해 애쓰는 중이라서요. 제일 부족한게 룬무늬 옷감입니다. 이 상황에서 우리를 다시 도와 줬으면 합니다.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주십시오. 처음이니까60개 받는 걸로 시작하죠.'),
(7800, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았습니다. 하지만 아직도 재고를 보충하기위해 애쓰는 중이라서요. 제일 부족한게 룬무늬 옷감입니다. 이 상황에서 우리를 다시 도와 줬으면 합니다.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주십시오. 처음이니까60개 받는 걸로 시작하죠.'),
(7805, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았습니다. 하지만 아직도 재고를 보충하기위해 애쓰는 중이라서요. 제일 부족한게 룬무늬 옷감입니다. 이 상황에서 우리를 다시 도와 줬으면 합니다.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주십시오. 처음이니까60개 받는 걸로 시작하죠.'),
(7811, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았습니다. 하지만 아직도 재고를 보충하기위해 애쓰는 중이라서요. 제일 부족한게 룬무늬 옷감입니다. 이 상황에서 우리를 다시 도와 줬으면 합니다.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주십시오. 처음이니까60개 받는 걸로 시작하죠.'),
(7818, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았네. 하지만 아직도 재고를 보충하기위해 애쓰는 중이네. 제일 부족한게 룬무늬 옷감입니다. 이 상황에서 우리를 다시 도와 줬으면 하네.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주게나. 처음이니까60개 받는 걸로 시작세.'),
(7823, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았네. 하지만 아직도 재고를 보충하기위해 애쓰는 중이라서요. 제일 부족한게 룬무늬 옷감이라네. 이 상황에서 우리를 다시 도와 줬으면 합네.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주게나. 처음이니까60개 받는 걸로 시작하세.'),
(7824, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았네. 하지만 아직도 재고를 보충하기위해 애쓰는 중이라서요. 제일 부족한게 룬무늬 옷감이라네. 이 상황에서 우리를 다시 도와 줬으면 합네.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주게나. 처음이니까60개 받는 걸로 시작하세.'),
(7836, 'koKR', '$N, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많았네. 하지만 아직도 재고를 보충하기위해 애쓰는 중이라서요. 제일 부족한게 룬무늬 옷감이라네. 이 상황에서 우리를 다시 도와 줬으면 합네.$B$B생각이 있다면 남는 룬무늬 옷감을 기부해 주게나. 처음이니까60개 받는 걸로 시작하세.'),
(7881, 'koKR', '다크문 유랑단에서 일하려면 많이 걸어야 하오. 이곳에서 저곳으로 계속 옮겨다녀야 하니까... 사실, 앉아서 일하는 경우가 전혀 없소! 그러니까 장화가 쉽게 닳아 버리는 것도 놀랄 일은 아니지! 그래서 우리는 질기면서도 멋진 장화가 필요하오. 새김무늬 가죽 장화가 바로 그런 괜찮은 장화지.$B$B참, 당신! 당신은 가죽세공사가 아니오? 새김무늬 가죽 장화를 만들어 주시오. 그러면 그 대가로 다크문 축제 상품권을 주겠소.'),
(7883, 'koKR', '예브 네블기어는 자신의 쇼에 더 많은 볼거리를 추가하려 하고 있소. 그래서 세계에서 제일 큰 노움을 백방으로 찾고 있다오! 혹시 그만한 키의 노움을 알고 있소?$B$B하여간 네블기어가 그런 노움을 찾기 전에 의상부터 준비해 놓길 원하고 있소. 야만전사의 멜빵이라면 기본적인 의상으로 괜찮을 것 같은데, 당신이 멜빵을 좀 만들어서 가져다주지 않겠소? 그러면 보답으로 다크문 축제 상품권을 여러 장 주겠소...'),
(7885, 'koKR', '아마 당신은 모르겠지만 다크문 축제를 순회하며 운영하는 데는 비용이 아주 많이 든다오! 모든 장비가 워낙 빨리 마모되다 보니 흑자를 낸다는 것 자체가 놀라울 정도지.$B$B이런 남모를 비용 때문에 우리는 늘 장비를 가능한 한 저렴한 비용으로 유지 관리할 수 있는 방법을 찾고 있소. 예를 들어, 천막은 자주 찢어지지만 가죽 방어구 키트를 사용하면 훌륭하게 수선할 수 있다오. 그래서 말인데, 방어구 키트를 좀 구해다 주지 않겠소? 그러면 엄청난 비용을 '),
(7891, 'koKR', '이 세상에서 가장 힘센 여자로서 저만의 전시장을 갖게 될 때에 대해 전 지금 새로 착용할 장비들을 마련하고 있어요! 지금은 제가 쓸 만한 팔보호구를 찾고 있답니다. 사람들에게 내 근육을 보여 줘야 하기 때문에 팔을 너무 덮어서는 안 되지만 어느 정도의 치장도 필요하거든요. 무슨 말인지 아시죠?$B$B녹색 철제 팔보호구는 어떨까요? 당신이녹색 철제 팔보호구를 만들어 주실 수 있나요? 그러면 답례로 다크문 축제 상품권 한 묶음을 드릴게요.'),
(7893, 'koKR', '전 이 세상에 가장 힘센 여자가 되기 위해 전 세계를 여행하면서 외딴 곳에 사는 몸 만들기 전문가와 몸짱 선생님, 고대 비전서를 찾아다니며 근육을 단련하는 여러 가지 비전을 익혔어요. 그래서 이제 약자의 목숨을 빼앗고 초보자를 불구로 만들 수 있을 정도로 위험한, 금지된 의식을 알게 되었죠!$B$B힘과 조절 능력이 필요한 이 의식을 실행하려면 가장 강도 높은 연마석이 있어야 해요. 연마석을 몇 개 만들거나 구해서 제게 가져다 주시겠어요? 그럼 다크문 '),
(7895, 'koKR', '이번에 새로 꾸밀 내 전시장은 정말 볼 만한 걸세! 몇몇 운 좋은 사람들은 눈으로 보는 것뿐 아니라... 직접 만져 볼 수도 있지!$B$B손님들이 내 전시장에 들어와서 실력을 테스트해 볼 때 청동 회전 장치가 기계적인 환희의 노래를 부르게 된다네. 아, 벌써 그 소리가 들리는 듯하군!$B$B아 그런데... 이제 내가 구상한 대로 꾸미려면 바로 그 청동 회전 장치가 필요하다네. 제발 청동 회전 장치 좀 구해다 주게. 그러면 다크문 축제 상품권을 주겠네!'),
(7896, 'koKR', '마침내 이 전시장이 완성되어 운영할 수 있게 되면 홍보를 해야 할 거야! 폭죽만큼 사람들의 이목을 쉽게 끌 수 있는 게 어디 있겠는가?$B$B물론, 멧돼지를 가마솥에 푹 삶아서 그 달콤한 냄새로 사람들을 끌어 모으는 게 더 효과적이긴 하겠지만... 고기를 싫어하는 친구들도 있어서 말이야. 그래서 사람들 눈길을 끄는 덴 폭죽이 딱이라네!$B$B녹색 폭죽을 가져다주면 다크문 축제 상품권 한뭉치를 두둑하게 주도록 하지.'),
(7901, 'koKR', '사람들이 무엇을 가치있게 여기는지를 보면 정말 놀라워요! 자, 예를 들어 나무 막대기에 텁수룩한 꼬리를 붙였다고 쳐요. 그럼, 당신이나 나 같으면 그런 건 별로 가치가 없다고 생각하겠죠? 하지만 그런 보잘것없는 물건에 \"\"천년 묵은 구미호 꼬리\"\"처럼 그럴 듯한 이름을 붙이고 예쁜 상자에 포장하면 사람들은 그걸 가치있게 여긴다고요. 쓰레기가 보물이 되는 거죠!$B$B잊혀진 땅과 황야의 땅에 사는 늑대에게서 텁수룩한 꼬리를 가져오세요. 그러면 그'),
(7902, 'koKR', '사람의 상상력이란 정말 놀라워요. 상상 속에서는 아주 작은 언덕도 제일 큰 산처럼 만들 수도 있고, 아무것도 아닌 그림자가 끔찍한 악몽 속에 나오는 괴물처럼 보이게 할 수도 있으니까요!$B$B다크문 유랑단에서는 방문객이 상상의 나래를 펼칠 수 있도록 해 주죠! 하지만 상상력을 펼칠 수 있도록 하기 위해서는... 때때로 우리 나름의 작전이 필요하답니다.$B$B그래서 말인데, 흩날리는 솜깃털이 필요해요. 아제로스 대륙에서 좀 위험한 지역에 사는 새들에게서'),
(7903, 'koKR', '혹시 모험을 찾아 밤 늦게 동굴 속을 돌아다녀본 적이 있나요? 있다고요? 정말인가요? 그럼, 분명 천장에 매달려서 당신을 노려보고 있는 박쥐의 섬뜩한 눈을 본 적이 있겠군요. 언제든지 틈을 봐서 공격하고 피를 빨아 먹으려고 노리고 있는 그 눈 말이에요!$B$B생각만 해도 소름 끼치는 일 아닌가요? 박쥐 눈은 확실히 무섭다니까요!$B$B더러운 박쥐 눈을 좀 구해다 주시겠어요? 그게... 요즘 구상 중인 시설에 필요하거든요. 뭔가 섬뜩하게 무서운 걸 만들'),
(7930, 'koKR', '어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!'),
